"use strict";(globalThis.webpackChunkistqb_quiz=globalThis.webpackChunkistqb_quiz||[]).push([[752],{752(e){e.exports=JSON.parse('[{"id":250,"chapter":1,"topic":"Fundamentos del Testing","question":"Qual das seguintes afirma\xe7\xf5es descreve um objetivo de teste v\xe1lido?","options":["A) Provar que n\xe3o h\xe1 defeitos","B) Provar que n\xe3o haver\xe1 falhas em produ\xe7\xe3o","C) Reduzir o n\xedvel de risco e criar confian\xe7a","D) Verificar que n\xe3o h\xe1 combina\xe7\xf5es n\xe3o testadas"],"correctAnswer":2,"explanation":"A op\xe7\xe3o C) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra A, Q#1, LO: FL-1.1.1). Justificativa: Reduzir o n\xedvel de risco do objeto de teste e gerar confian\xe7a no n\xedvel de qualidade D) Verificar que n\xe3o h\xe1 combina\xe7\xf5es de entradas sem testar","source":"Official Sample Exam A Q#1"},{"id":251,"chapter":1,"topic":"Fundamentos del Testing","question":"Qual das seguintes op\xe7\xf5es mostra um exemplo de atividades de teste que contribuem para o sucesso?","options":["A) Envolver os testadores durante diversas atividades","B) N\xe3o incomodar os desenvolvedores","C) Colaborar com os usu\xe1rios finais","D) Testar todo o c\xf3digo do sistema com ferramentas"],"correctAnswer":0,"explanation":"A op\xe7\xe3o A) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra A, Q#2, LO: FL-1.2.1). Justificativa: Envolver os testadores durante diversas atividades do ciclo de vida de desenvolvimento de software (SDLC) ajudar\xe1 a detectar defeitos nos produtos de trabalho.","source":"Official Sample Exam A Q#2"},{"id":252,"chapter":1,"topic":"Fundamentos del Testing","question":"Voc\xea foi designado como testador em uma equipe que produz um novo sistema de forma incremental. Voc\xea notou que nenhuma mudan\xe7a foi feita nos casos de teste de regress\xe3o existentes durante v\xe1rias itera\xe7\xf5es e nenhum novo defeito de regress\xe3o foi identificado. Seu gerente est\xe1 feliz, mas voc\xea n\xe3o. Qual princ\xedpio de teste explica o seu ceticismo?","options":["A) Os testes se desgastam","B) Fal\xe1cia da aus\xeancia de defeitos","C) Os defeitos se agrupam","D) Testes exaustivos s\xe3o imposs\xedveis"],"correctAnswer":0,"explanation":"A op\xe7\xe3o A) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra A, Q#3, LO: FL-1.3.1). Justificativa: Os testes se desgastam.","source":"Official Sample Exam A Q#3"},{"id":253,"chapter":1,"topic":"Fundamentos del Testing","question":"Voc\xea trabalha em uma equipe que desenvolve um aplicativo m\xf3vel para pedir comida. Na itera\xe7\xe3o atual, a equipe decidiu implementar a funcionalidade de pagamento. Qual das seguintes atividades faz parte da an\xe1lise de teste?","options":["A) Estimar que testar a integra\xe7\xe3o com o servi\xe7o de pagamento levar\xe1 8 pessoas-dia","B) Decidir que a equipe deve testar se \xe9 poss\xedvel dividir o pagamento adequadamente entre muitos usu\xe1rios","C) Usar a an\xe1lise de valor limite (BVA) para derivar os dados de teste para os casos de teste que verificam o processamento correto do pagamento para o valor m\xednimo permitido a pagar","D) Analisar a discrep\xe2ncia entre o resultado real e o resultado esperado ap\xf3s executar um caso de teste que verifica o processo de pagamento com cart\xe3o de cr\xe9dito, e relatar um defeito"],"correctAnswer":1,"explanation":"A op\xe7\xe3o B) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra A, Q#4, LO: FL-1.4.1). Justificativa: Decidir que a equipe deve testar se \xe9 poss\xedvel dividir o pagamento adequadamente entre muitos usu\xe1rios.","source":"Official Sample Exam A Q#4"},{"id":254,"chapter":1,"topic":"Fundamentos del Testing","question":"Quais dos seguintes fatores t\xeam uma influ\xeancia SIGNIFICATIVA na abordagem de teste?\\n\\ni. O SDLC\\n\\nii. O n\xfamero de defeitos detectados em projetos anteriores\\n\\niii. Os riscos de produto identificados\\n\\niv. Novos requisitos regulat\xf3rios que obrigam a realizar testes formais de caixa branca\\n\\nv. A configura\xe7\xe3o do ambiente de teste","options":["A) i, ii t\xeam uma influ\xeancia significativa","B) i, iii, iv t\xeam uma influ\xeancia significativa","C) ii, iv, v t\xeam uma influ\xeancia significativa","D) iii, v t\xeam uma influ\xeancia significativa"],"correctAnswer":1,"explanation":"A op\xe7\xe3o B) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra A, Q#5, LO: FL-1.4.2). Justificativa: i, iii, iv t\xeam uma influ\xeancia significativa.","source":"Official Sample Exam A Q#5"},{"id":255,"chapter":1,"topic":"Fundamentos del Testing","question":"Quais das seguintes tarefas pertencem PRINCIPALMENTE a um papel de testes?","options":["A) Configurar ambientes e Analisar a base de teste","B) Manter o backlog e Projetar solu\xe7\xf5es","C) Projetar solu\xe7\xf5es e Criar o plano de teste","D) Manter o backlog e Configurar ambientes"],"correctAnswer":0,"explanation":"A op\xe7\xe3o A) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra A, Q#6, LO: FL-1.4.5). Justificativa: Configurar ambientes de teste.","source":"Official Sample Exam A Q#6"},{"id":256,"chapter":1,"topic":"Fundamentos del Testing","question":"Quais das seguintes habilidades (i-v) s\xe3o as MAIS importantes para um testador?\\n\\ni. Ter conhecimento do dom\xednio\\n\\nii. Criar uma vis\xe3o do produto\\n\\niii. Ser um bom membro de equipe\\n\\niv. Planejar e organizar o trabalho da equipe\\n\\nv. Pensamento cr\xedtico","options":["A) ii e iv s\xe3o importantes","B) i, iii e v s\xe3o importantes","C) i, ii e v s\xe3o importantes","D) iii e iv s\xe3o importantes"],"correctAnswer":1,"explanation":"A op\xe7\xe3o B) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra A, Q#7, LO: FL-1.5.1). Justificativa: i, iii e v s\xe3o importantes.","source":"Official Sample Exam A Q#7"},{"id":257,"chapter":1,"topic":"Fundamentos del Testing","question":"Como a abordagem de toda a equipe (whole-team approach) est\xe1 presente nas intera\xe7\xf5es entre os testadores e os representantes do neg\xf3cio?","options":["A) Os representantes do neg\xf3cio decidem as abordagens de automa\xe7\xe3o de testes","B) Os testadores ajudam os representantes do neg\xf3cio a definir uma estrat\xe9gia de teste","C) Os representantes do neg\xf3cio n\xe3o fazem parte da abordagem de toda a equipe","D) Os testadores ajudam os representantes do neg\xf3cio a criar testes de aceita\xe7\xe3o adequados"],"correctAnswer":3,"explanation":"A op\xe7\xe3o D) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra A, Q#8, LO: FL-1.5.2). Justificativa: Os testadores ajudam os representantes do neg\xf3cio a criar testes de aceita\xe7\xe3o adequados.","source":"Official Sample Exam A Q#8"},{"id":258,"chapter":2,"topic":"Testing a lo largo del SDLC","question":"Considere a seguinte regra: \\"para cada atividade do SDLC h\xe1 uma atividade de teste correspondente\\". Em quais modelos do SDLC essa regra se aplica?","options":["A) Apenas nos modelos de desenvolvimento sequenciais","B) Apenas nos modelos de desenvolvimento iterativos","C) Apenas nos modelos de desenvolvimento iterativos e incrementais","D) Nos modelos de desenvolvimento sequenciais, incrementais e iterativos"],"correctAnswer":3,"explanation":"A op\xe7\xe3o D) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra A, Q#9, LO: FL-2.1.2). Justificativa: Nos modelos de desenvolvimento sequenciais, incrementais e iterativos.","source":"Official Sample Exam A Q#9"},{"id":259,"chapter":2,"topic":"Testing a lo largo del SDLC","question":"Qual das seguintes afirma\xe7\xf5es descreve MELHOR a abordagem de desenvolvimento orientado a testes de aceita\xe7\xe3o (ATDD)?","options":["A) Em ATDD, os crit\xe9rios de aceita\xe7\xe3o geralmente s\xe3o criados com base no formato dado/quando/ent\xe3o (given/when/then)","B) Em ATDD, os casos de teste s\xe3o criados principalmente nos testes de componente e s\xe3o orientados ao c\xf3digo","C) Em ATDD, os testes s\xe3o criados com base nos crit\xe9rios de aceita\xe7\xe3o para orientar o desenvolvimento do software relacionado","D) Em ATDD, os testes s\xe3o baseados no comportamento desejado do software, o que facilita o entendimento pelos membros da equipe"],"correctAnswer":2,"explanation":"A op\xe7\xe3o C) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra A, Q#10, LO: FL-2.1.3). Justificativa: Em ATDD, os testes s\xe3o criados com base nos crit\xe9rios de aceita\xe7\xe3o para orientar o desenvolvimento do software relacionado.","source":"Official Sample Exam A Q#10"},{"id":260,"chapter":2,"topic":"Testing a lo largo del SDLC","question":"Qual dos seguintes N\xc3O \xe9 um exemplo da abordagem shift-left?","options":["A) Revisar os requisitos do usu\xe1rio antes de serem aceitos formalmente pelos stakeholders","B) Escrever um teste de componente antes que o c\xf3digo correspondente seja escrito","C) Executar um teste de efici\xeancia de desempenho para um componente durante os testes de componente","D) Escrever um script de teste antes de configurar o processo de gerenciamento de configura\xe7\xe3o"],"correctAnswer":3,"explanation":"A op\xe7\xe3o D) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra A, Q#11, LO: FL-2.1.5). Justificativa: Escrever um script de teste antes de configurar o processo de gerenciamento de configura\xe7\xe3o.","source":"Official Sample Exam A Q#11"},{"id":261,"chapter":2,"topic":"Testing a lo largo del SDLC","question":"Qual dos seguintes argumentos voc\xea usaria para convencer o seu gerente a organizar retrospectivas?","options":["A) As retrospectivas s\xe3o muito populares hoje em dia e os clientes apreciariam se as adicion\xe1ssemos aos nossos processos","B) Organizar retrospectivas economizar\xe1 dinheiro para a organiza\xe7\xe3o porque sem elas os representantes dos usu\xe1rios finais n\xe3o fornecem feedback imediato sobre o produto","C) As fraquezas do processo identificadas durante a retrospectiva podem ser analisadas e servir como uma lista de pend\xeancias para o programa de melhoria cont\xednua de processos da organiza\xe7\xe3o","D) As retrospectivas englobam cinco valores que incluem a coragem e o respeito, os quais s\xe3o cruciais para manter a melhoria cont\xednua na organiza\xe7\xe3o"],"correctAnswer":2,"explanation":"A op\xe7\xe3o C) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra A, Q#12, LO: FL-2.1.6). Justificativa: As fraquezas do processo identificadas durante a retrospectiva podem ser analisadas e servir como uma lista de pend\xeancias para o programa de melhoria cont\xednua de processos da organiza\xe7\xe3o.","source":"Official Sample Exam A Q#12"},{"id":262,"chapter":2,"topic":"Testing a lo largo del SDLC","question":"Quais tipos de falhas (1-4) MELHOR se ajustam a quais n\xedveis de teste (A-D)?\\n\\n1. Falhas no comportamento do sistema ao desviar-se das necessidades de neg\xf3cios do usu\xe1rio\\n2. Falhas na comunica\xe7\xe3o entre componentes\\n3. Falhas na l\xf3gica do c\xf3digo\\n4. Falhas devido a regras de neg\xf3cios implementadas incorretamente\\n\\nA. Testes de componente\\nB. Testes de integra\xe7\xe3o de componentes\\nC. Testes de sistema\\nD. Testes de aceita\xe7\xe3o","options":["A) 1D, 2B, 3A, 4C","B) 1D, 2B, 3C, 4A","C) 1B, 2A, 3D, 4C","D) 1C, 2B, 3A, 4D"],"correctAnswer":0,"explanation":"A op\xe7\xe3o A) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra A, Q#13, LO: FL-2.2.1). Justificativa: 1D, 2B, 3A, 4C.","source":"Official Sample Exam A Q#13"},{"id":263,"chapter":2,"topic":"Testing a lo largo del SDLC","question":"Voc\xea est\xe1 testando uma hist\xf3ria de usu\xe1rio com tr\xeas crit\xe9rios de aceita\xe7\xe3o: AC1, AC2 e AC3. AC1 est\xe1 coberto pelo caso de teste TC1, AC2 pelo TC2, e AC3 pelo TC3. O hist\xf3rico de execu\xe7\xe3o de testes teve tr\xeas rodadas de testes em tr\xeas vers\xf5es consecutivas do software da seguinte forma:\\n\\n| | Execu\xe7\xe3o 1 | Execu\xe7\xe3o 2 | Execu\xe7\xe3o 3 |\\n|---|---|---|---|\\n| TC1 (1) | Falhou (4) | Passou (7) | Passou |\\n| TC2 (2) | Passou (5) | Falhou (8) | Passou |\\n| TC3 (3) | Falhou (6) | Falhou (9) | Passou |\\n\\nOs testes s\xe3o repetidos uma vez que se informa que todos os defeitos encontrados na rodada de testes foram corrigidos e h\xe1 uma nova vers\xe3o do software dispon\xedvel. Quais dos testes acima s\xe3o executados como testes de regress\xe3o?","options":["A) Apenas 4, 7, 8, 9","B) Apenas 5, 7","C) Apenas 4, 6, 8, 9","D) Apenas 5, 6"],"correctAnswer":1,"explanation":"A op\xe7\xe3o B) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra A, Q#14, LO: FL-2.2.3). Justificativa: Apenas 5, 7.","source":"Official Sample Exam A Q#14"},{"id":264,"chapter":3,"topic":"Pruebas Est\xe1ticas","question":"Qual dos seguintes N\xc3O \xe9 um benef\xedcio dos testes est\xe1ticos?","options":["A) Ter uma gest\xe3o de defeitos menos custosa devido \xe0 facilidade de detectar defeitos mais tarde no SDLC","B) Corrigir defeitos encontrados durante os testes est\xe1ticos geralmente \xe9 muito menos custoso do que corrigir defeitos encontrados durante os testes din\xe2micos","C) Encontrar defeitos de codifica\xe7\xe3o que poderiam n\xe3o ter sido encontrados realizando apenas testes din\xe2micos","D) Detectar lacunas e inconsist\xeancias nos requisitos"],"correctAnswer":0,"explanation":"A op\xe7\xe3o A) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra A, Q#15, LO: FL-3.1.2). Justificativa: Ter uma gest\xe3o de defeitos menos custosa devido \xe0 facilidade de detectar defeitos mais tarde no SDLC.","source":"Official Sample Exam A Q#15"},{"id":265,"chapter":3,"topic":"Pruebas Est\xe1ticas","question":"Qual dos seguintes \xe9 um benef\xedcio do feedback antecipado e frequente?","options":["A) Melhora o processo de teste para projetos futuros","B) Obriga os clientes a priorizar seus requisitos com base nos riscos acordados","C) Fornece uma medida para a qualidade das mudan\xe7as","D) Ajuda a evitar mal-entendidos nos requisitos"],"correctAnswer":3,"explanation":"A op\xe7\xe3o D) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra A, Q#16, LO: FL-3.2.1). Justificativa: Ajuda a evitar mal-entendidos nos requisitos.","source":"Official Sample Exam A Q#16"},{"id":266,"chapter":3,"topic":"Pruebas Est\xe1ticas","question":"As revis\xf5es que est\xe3o sendo usadas em sua organiza\xe7\xe3o t\xeam os seguintes atributos: \u2022 Existe o papel de um escriba \u2022 O objetivo principal \xe9 avaliar a qualidade \u2022 A reuni\xe3o \xe9 conduzida pelo autor do produto de trabalho \u2022 H\xe1 prepara\xe7\xe3o individual \u2022 \xc9 produzido um relat\xf3rio de revis\xe3o. Qual dos seguintes tipos de revis\xe3o \xe9 MAIS prov\xe1vel que esteja sendo utilizado?","options":["A) Revis\xe3o informal","B) Walkthrough (Passagem passo a passo)","C) Revis\xe3o t\xe9cnica","D) Inspe\xe7\xe3o"],"correctAnswer":1,"explanation":"A op\xe7\xe3o B) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra A, Q#17, LO: FL-3.2.4). Justificativa: Walkthrough.","source":"Official Sample Exam A Q#17"},{"id":267,"chapter":3,"topic":"Pruebas Est\xe1ticas","question":"Qual destas afirma\xe7\xf5es N\xc3O \xe9 um fator que contribui para o sucesso das revis\xf5es?","options":["A) Os participantes devem dedicar tempo adequado para a revis\xe3o","B) Dividir os produtos de trabalho grandes em partes pequenas para que o esfor\xe7o necess\xe1rio seja menos intenso","C) Os participantes devem evitar comportamentos que possam indicar t\xe9dio, exaspera\xe7\xe3o ou hostilidade em rela\xe7\xe3o aos outros participantes","D) As falhas encontradas devem ser reconhecidas, apreciadas e gerenciadas de forma objetiva"],"correctAnswer":3,"explanation":"A op\xe7\xe3o D) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra A, Q#18, LO: FL-3.2.5). Justificativa: As falhas encontradas devem ser reconhecidas, apreciadas e gerenciadas objetivamente.","source":"Official Sample Exam A Q#18"},{"id":268,"chapter":4,"topic":"T\xe9cnicas de An\xe1lisis y Dise\xf1o de Pruebas","question":"Qual das seguintes \xe9 uma caracter\xedstica das t\xe9cnicas de teste baseadas na experi\xeancia?","options":["A) Os casos de teste s\xe3o criados com base em informa\xe7\xf5es detalhadas de design","B) Os itens testados dentro da se\xe7\xe3o de c\xf3digo da interface s\xe3o usados para medir a cobertura","C) As t\xe9cnicas de teste dependem fortemente do conhecimento do testador sobre o software e o dom\xednio de neg\xf3cios","D) Os casos de teste s\xe3o usados para identificar desvios dos requisitos"],"correctAnswer":2,"explanation":"A op\xe7\xe3o C) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra A, Q#19, LO: FL-4.1.1). Justificativa: As t\xe9cnicas de teste dependem fortemente do conhecimento do testador sobre o software e o dom\xednio de neg\xf3cios.","source":"Official Sample Exam A Q#19"},{"id":269,"chapter":4,"topic":"T\xe9cnicas de An\xe1lisis y Dise\xf1o de Pruebas","question":"Voc\xea est\xe1 testando um formul\xe1rio simplificado de busca de apartamentos que tem apenas dois crit\xe9rios de busca: \u2022 andar (com tr\xeas op\xe7\xf5es poss\xedveis: t\xe9rreo; primeiro andar; segundo andar ou superior) \u2022 tipo de jardim (com tr\xeas op\xe7\xf5es poss\xedveis: sem jardim; jardim pequeno; jardim grande). Todos os apartamentos no t\xe9rreo t\xeam jardim, os apartamentos nos andares superiores n\xe3o t\xeam. O formul\xe1rio tem um mecanismo de valida\xe7\xe3o incorporado que n\xe3o permitir\xe1 usar crit\xe9rios de busca que violem esta regra. Cada teste tem dois valores de entrada: andar e tipo de jardim. Voc\xea deseja aplicar o particionamento de equival\xeancia (EP) para cobrir cada andar e cada tipo de jardim em seus testes. Qual \xe9 o n\xfamero m\xednimo de casos de teste para alcan\xe7ar uma cobertura EP de 100% para as parti\xe7\xf5es v\xe1lidas?","options":["A) 3","B) 4","C) 5","D) 6"],"correctAnswer":1,"explanation":"A op\xe7\xe3o B) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra A, Q#20, LO: FL-4.2.1). Justificativa: 4.","source":"Official Sample Exam A Q#20"},{"id":270,"chapter":4,"topic":"T\xe9cnicas de An\xe1lisis y Dise\xf1o de Pruebas","question":"Voc\xea est\xe1 testando um sistema que calcula a nota final do curso para um determinado aluno. A nota final \xe9 atribu\xedda com base no resultado final, de acordo com as seguintes regras:\\n- 0 \u2013 50 pontos: reprovado\\n- 51 \u2013 60 pontos: suficiente\\n- 61 \u2013 70 pontos: satisfat\xf3rio\\n- 71 \u2013 80 pontos: bom\\n- 81 \u2013 90 pontos: muito bom\\n- 91 \u2013 100 pontos: excelente\\n\\nVoc\xea preparou o seguinte conjunto de casos de teste:\\n\\n| TC | Resultado final | Nota final |\\n|---|---|---|\\n| TC1 | 91 | excelente |\\n| TC2 | 50 | reprovado |\\n| TC3 | 81 | muito bom |\\n| TC4 | 60 | suficiente |\\n| TC5 | 70 | satisfat\xf3rio |\\n| TC6 | 80 | bom |\\n\\nQual \xe9 a cobertura de an\xe1lise de valor limite (BVA) de 2 valores para o resultado final que \xe9 alcan\xe7ada com os casos de teste existentes?","options":["A) 50%","B) 60%","C) 33.3%","D) 100%"],"correctAnswer":0,"explanation":"A op\xe7\xe3o A) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra A, Q#21, LO: FL-4.2.2). Justificativa: 50%.","source":"Official Sample Exam A Q#21"},{"id":271,"chapter":4,"topic":"T\xe9cnicas de An\xe1lisis y Dise\xf1o de Pruebas","question":"Sua loja de aluguel di\xe1rio de bicicletas favorita acabou de introduzir um novo sistema de gest\xe3o de relacionamento com o cliente (CRM) e pediu a voc\xea, um de seus membros mais leais, para test\xe1-lo. As caracter\xedsticas implementadas s\xe3o as seguintes: \u2022 Qualquer pessoa pode alugar uma bicicleta, mas os membros recebem um desconto de 20% \u2022 No entanto, se o prazo de devolu\xe7\xe3o n\xe3o for cumprido, o desconto n\xe3o estar\xe1 mais dispon\xedvel \u2022 Ap\xf3s 15 alugu\xe9is, os membros recebem um presente: uma camiseta. A tabela de decis\xe3o que descreve as caracter\xedsticas implementadas se parece com isto:\\nCondi\xe7\xf5es R1 R2 R3 R4 R5 R6 R7 R8\\nSer um membro T T T T F F F F\\nPrazo descumprido T F T F T F F T\\n15\xba aluguel F F T T F F T T\\nA\xe7\xf5es\\n20% desconto X X\\nPresente Camiseta X X X\\nCom base APENAS na descri\xe7\xe3o das caracter\xedsticas do sistema CRM, qual das regras acima descreve uma situa\xe7\xe3o imposs\xedvel?","options":["A) R4","B) R2","C) R6","D) R8"],"correctAnswer":3,"explanation":"A op\xe7\xe3o D) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra A, Q#22, LO: FL-4.2.3). Justificativa: R8.","source":"Official Sample Exam A Q#22"},{"id":272,"chapter":4,"topic":"T\xe9cnicas de An\xe1lisis y Dise\xf1o de Pruebas","question":"Voc\xea testa um sistema cujo ciclo de vida \xe9 modelado pelo diagrama de transi\xe7\xe3o de estado mostrado abaixo. O sistema come\xe7a no estado INIT e termina sua opera\xe7\xe3o no estado OFF. Qual \xe9 o n\xfamero M\xcdNIMO de casos de teste para alcan\xe7ar a cobertura de transi\xe7\xf5es v\xe1lidas?","options":["A) 4","B) 2","C) 7","D) 3"],"correctAnswer":3,"explanation":"A op\xe7\xe3o D) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra A, Q#23, LO: FL-4.2.4). Justificativa: 3.","source":"Official Sample Exam A Q#23"},{"id":273,"chapter":4,"topic":"T\xe9cnicas de An\xe1lisis y Dise\xf1o de Pruebas","question":"Sua su\xedte de testes alcan\xe7ou uma cobertura de comandos (statement coverage) de 100%. Qual \xe9 a consequ\xeancia desse fato?","options":["A) Cada instru\xe7\xe3o no c\xf3digo que cont\xe9m um defeito foi executada pelo menos uma vez","B) Qualquer su\xedte de testes que contenha mais casos de teste que sua su\xedte de testes tamb\xe9m alcan\xe7ar\xe1 uma cobertura de comandos de 100%","C) Cada caminho no c\xf3digo foi executado pelo menos uma vez","D) Cada combina\xe7\xe3o de valores de entrada foi testada pelo menos uma vez"],"correctAnswer":0,"explanation":"A op\xe7\xe3o A) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra A, Q#24, LO: FL-4.3.1). Justificativa: Cada instru\xe7\xe3o no c\xf3digo que cont\xe9m um defeito foi executada pelo menos uma vez.","source":"Official Sample Exam A Q#24"},{"id":274,"chapter":4,"topic":"T\xe9cnicas de An\xe1lisis y Dise\xf1o de Pruebas","question":"Qual das seguintes afirma\xe7\xf5es N\xc3O \xe9 verdadeira para os testes de caixa branca?","options":["A) Durante os testes de caixa branca, toda a implementa\xe7\xe3o do software \xe9 considerada","B) As m\xe9tricas de cobertura de caixa branca podem ajudar a identificar testes adicionais para aumentar a cobertura do c\xf3digo","C) As t\xe9cnicas de teste de caixa branca podem ser utilizadas nos testes est\xe1ticos","D) Os testes de caixa branca podem ajudar a identificar lacunas na implementa\xe7\xe3o dos requisitos"],"correctAnswer":3,"explanation":"A op\xe7\xe3o D) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra A, Q#25, LO: FL-4.3.3). Justificativa: Os testes de caixa branca podem ajudar a identificar lacunas na implementa\xe7\xe3o dos requisitos.","source":"Official Sample Exam A Q#25"},{"id":275,"chapter":4,"topic":"T\xe9cnicas de An\xe1lisis y Dise\xf1o de Pruebas","question":"Qual das op\xe7\xf5es a seguir descreve MELHOR o conceito por tr\xe1s da suposi\xe7\xe3o de erros (error guessing)?","options":["A) A suposi\xe7\xe3o de erros envolve usar seu conhecimento e experi\xeancia sobre defeitos encontrados no passado e os erros t\xedpicos cometidos pelos desenvolvedores","B) A suposi\xe7\xe3o de erros envolve usar sua experi\xeancia pessoal em desenvolvimento e os erros que voc\xea cometeu como desenvolvedor","C) A suposi\xe7\xe3o de erros exige que voc\xea imagine que \xe9 o usu\xe1rio do objeto de teste e adivinhe os erros que o usu\xe1rio poderia cometer interagindo com ele","D) A suposi\xe7\xe3o de erros exige que voc\xea duplique rapidamente a tarefa de desenvolvimento para identificar o tipo de erros que um desenvolvedor poderia cometer"],"correctAnswer":0,"explanation":"A op\xe7\xe3o A) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra A, Q#26, LO: FL-4.4.1). Justificativa: A suposi\xe7\xe3o de erros envolve usar seu conhecimento e experi\xeancia sobre defeitos encontrados no passado e os erros t\xedpicos cometidos pelos desenvolvedores.","source":"Official Sample Exam A Q#26"},{"id":276,"chapter":4,"topic":"T\xe9cnicas de An\xe1lisis y Dise\xf1o de Pruebas","question":"Voc\xea come\xe7ou tarde, mas possui um conhecimento do dom\xednio muito detalhado e boas habilidades anal\xedticas. A lista completa de requisitos ainda n\xe3o foi compartilhada com a equipe, mas a ger\xeancia est\xe1 pedindo que alguns resultados de testes sejam apresentados. Qual t\xe9cnica de teste se ajusta MELHOR a esta situa\xe7\xe3o?","options":["A) Teste baseado em checklist","B) Suposi\xe7\xe3o de erros","C) Teste explorat\xf3rio","D) Teste de ramifica\xe7\xe3o (branch testing)"],"correctAnswer":2,"explanation":"A op\xe7\xe3o C) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra A, Q#27, LO: FL-4.4.2). Justificativa: Testes explorat\xf3rios.","source":"Official Sample Exam A Q#27"},{"id":277,"chapter":4,"topic":"T\xe9cnicas de An\xe1lisis y Dise\xf1o de Pruebas","question":"Qual das seguintes descreve MELHOR a forma como os crit\xe9rios de aceita\xe7\xe3o podem ser documentados?","options":["A) Realizando retrospectivas para determinar as necessidades reais dos stakeholders em rela\xe7\xe3o a uma determinada hist\xf3ria de usu\xe1rio","B) Usando o formato dado/quando/ent\xe3o (given/when/then) para descrever uma condi\xe7\xe3o de teste de exemplo relacionada a uma determinada hist\xf3ria de usu\xe1rio","C) Usando comunica\xe7\xe3o verbal para reduzir o risco de que outros interpretem mal os crit\xe9rios de aceita\xe7\xe3o","D) Documentando os riscos relacionados a uma determinada hist\xf3ria de usu\xe1rio em um plano de teste para facilitar os testes baseados em risco de uma determinada hist\xf3ria de usu\xe1rio"],"correctAnswer":1,"explanation":"A op\xe7\xe3o B) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra A, Q#28, LO: FL-4.5.2). Justificativa: Usando o formato dado/quando/ent\xe3o (given/when/then) para descrever uma condi\xe7\xe3o de teste de exemplo relacionada a uma determinada hist\xf3ria de usu\xe1rio.","source":"Official Sample Exam A Q#28"},{"id":278,"chapter":4,"topic":"T\xe9cnicas de An\xe1lisis y Dise\xf1o de Pruebas","question":"Considere a seguinte hist\xf3ria de usu\xe1rio: Como Editor, quero revisar o conte\xfado antes de ser publicado para garantir que a gram\xe1tica esteja correta, e seus crit\xe9rios de aceita\xe7\xe3o: \u2022 O usu\xe1rio pode fazer login no sistema de gerenciamento de conte\xfado com a fun\xe7\xe3o de \\"Editor\\" \u2022 O editor pode visualizar as p\xe1ginas de conte\xfado existentes \u2022 O editor pode editar o conte\xfado da p\xe1gina \u2022 O editor pode adicionar coment\xe1rios de marca\xe7\xe3o \u2022 O editor pode salvar as altera\xe7\xf5es \u2022 O editor pode reatribuir o papel a um \\"propriet\xe1rio do conte\xfado\\" para fazer atualiza\xe7\xf5es. Qual dos seguintes \xe9 o MELHOR exemplo de um teste ATDD para esta hist\xf3ria de usu\xe1rio?","options":["A) Testar se o editor pode salvar o documento ap\xf3s editar o conte\xfado da p\xe1gina","B) Testar se o propriet\xe1rio do conte\xfado pode fazer login e realizar atualiza\xe7\xf5es no conte\xfado","C) Testar se o editor pode agendar o conte\xfado editado para publica\xe7\xe3o","D) Testar se o editor pode reatribuir a outro editor para realizar atualiza\xe7\xf5es"],"correctAnswer":0,"explanation":"A op\xe7\xe3o A) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra A, Q#29, LO: FL-4.5.3). Justificativa: Testar se o editor pode salvar o documento ap\xf3s editar o conte\xfado da p\xe1gina.","source":"Official Sample Exam A Q#29"},{"id":279,"chapter":5,"topic":"Gesti\xf3n de las Actividades de Prueba","question":"Qual das seguintes op\xe7\xf5es \xe9 um crit\xe9rio de sa\xedda t\xedpico para testar um sistema?","options":["A) Prepara\xe7\xe3o do ambiente de teste","B) Capacidade de fazer login","C) A densidade de defeitos estimada \xe9 alcan\xe7ada","D) Requisitos traduzidos para o formato given/when/then"],"correctAnswer":2,"explanation":"A op\xe7\xe3o C) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra A, Q#31, LO: FL-5.1.3). Justificativa: A densidade de defeitos estimada \xe9 alcan\xe7ada.","source":"Official Sample Exam A Q#31"},{"id":280,"chapter":5,"topic":"Gesti\xf3n de las Actividades de Prueba","question":"Sua equipe usa a t\xe9cnica de estimativa de tr\xeas pontos para estimar o esfor\xe7o de teste de uma nova funcionalidade de alto risco. As seguintes estimativas foram feitas: \u2022 Estimativa mais otimista: 2 pessoas-hora \u2022 Estimativa mais prov\xe1vel: 11 pessoas-hora \u2022 Estimativa mais pessimista: 14 pessoas-hora. Qual \xe9 a estimativa final?","options":["A) 9 pessoas-hora","B) 14 pessoas-hora","C) 11 pessoas-hora","D) 10 pessoas-hora"],"correctAnswer":3,"explanation":"A op\xe7\xe3o D) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra A, Q#32, LO: FL-5.1.4). Justificativa: 10 pessoas-hora.","source":"Official Sample Exam A Q#32"},{"id":281,"chapter":5,"topic":"Gesti\xf3n de las Actividades de Prueba","question":"Voc\xea est\xe1 testando um aplicativo m\xf3vel que permite aos usu\xe1rios encontrar um restaurante pr\xf3ximo com base no tipo de comida que desejam comer. Considere a seguinte lista de casos de teste, prioridades (ou seja, um n\xfamero menor significa uma prioridade maior) e depend\xeancias l\xf3gicas:\\nN\xfamero do caso de teste | Condi\xe7\xe3o de teste coberta | Prioridade | Depend\xeancia l\xf3gica\\nTC 001 | Selecionar tipo de comida | 3 | nenhuma\\nTC 002 | Selecionar restaurante | 2 | TC 001\\nTC 003 | Obter dire\xe7\xf5es | 1 | TC 002\\nTC 004 | Ligar para o restaurante | 2 | TC 002\\nTC 005 | Fazer uma reserva | 3 | TC 002\\nQual dos seguintes casos de teste deve ser executado em terceiro lugar?","options":["A) TC 003","B) TC 005","C) TC 002","D) TC 001"],"correctAnswer":0,"explanation":"A op\xe7\xe3o A) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra A, Q#33, LO: FL-5.1.5). Justificativa: TC 003.","source":"Official Sample Exam A Q#33"},{"id":282,"chapter":5,"topic":"Gesti\xf3n de las Actividades de Prueba","question":"Considere as seguintes categorias de teste (1-4) e os quadrantes de teste \xe1gil (A-D):\\nComo as seguintes categorias de teste mapeiam para os quadrantes de teste \xe1gil?\\n\\n1. Teste de usabilidade\\n2. Teste de componente\\n3. Teste funcional\\n4. Teste de confiabilidade\\n\\nA. Quadrante de teste \xe1gil Q1: voltado para a tecnologia, apoiando a equipe de desenvolvimento\\nB. Quadrante de teste \xe1gil Q2: voltado para o neg\xf3cio, apoiando a equipe de desenvolvimento\\nC. Quadrante de teste \xe1gil Q3: voltado para o neg\xf3cio, criticando o produto\\nD. Quadrante de teste \xe1gil Q4: voltado para a tecnologia, criticando o produto","options":["A) 1C, 2A, 3B, 4D","B) 1D, 2A, 3C, 4B","C) 1C, 2B, 3D, 4A","D) 1D, 2B, 3C, 4A"],"correctAnswer":0,"explanation":"A op\xe7\xe3o A) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra A, Q#34, LO: FL-5.1.7). Justificativa: 1C, 2A, 3B, 4D.","source":"Official Sample Exam A Q#34"},{"id":283,"chapter":5,"topic":"Gesti\xf3n de las Actividades de Prueba","question":"Durante uma an\xe1lise de riscos, o seguinte risco foi identificado e avaliado: \u2022 Risco: O tempo de resposta \xe9 muito longo para gerar um relat\xf3rio \u2022 Probabilidade do risco: m\xe9dia; impacto do risco: alto \u2022 Resposta ao risco:\\n  o Uma equipe de testes independente realiza testes de efici\xeancia de desempenho durante os testes de sistema\\n  o Uma amostra selecionada de usu\xe1rios finais realiza testes alfa e testes beta antes do lan\xe7amento\\nQual medida prop\xf5e-se tomar em resposta a este risco analisado?","options":["A) Aceita\xe7\xe3o do risco","B) Plano de conting\xeancia","C) Mitiga\xe7\xe3o do risco","D) Transfer\xeancia do risco"],"correctAnswer":2,"explanation":"A op\xe7\xe3o C) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra A, Q#35, LO: FL-5.2.4). Justificativa: Mitiga\xe7\xe3o do risco.","source":"Official Sample Exam A Q#35"},{"id":284,"chapter":5,"topic":"Gesti\xf3n de las Actividades de Prueba","question":"Qual produto de trabalho uma equipe \xe1gil pode usar para mostrar a quantidade de trabalho que foi conclu\xedda e a quantidade total de trabalho restante para uma determinada itera\xe7\xe3o?","options":["A) Crit\xe9rios de aceita\xe7\xe3o","B) Relat\xf3rio de defeito","C) Relat\xf3rio de conclus\xe3o de teste","D) Gr\xe1fico de burndown (Burndown chart)"],"correctAnswer":3,"explanation":"A op\xe7\xe3o D) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra A, Q#36, LO: FL-5.3.3). Justificativa: Gr\xe1fico de burndown (Burndown chart).","source":"Official Sample Exam A Q#36"},{"id":285,"chapter":5,"topic":"Gesti\xf3n de las Actividades de Prueba","question":"Voc\xea precisa atualizar um dos scripts de teste automatizados para alinh\xe1-lo a um novo requisito. Qual processo indica que voc\xea deve criar uma nova vers\xe3o do script de teste no reposit\xf3rio de testes?","options":["A) Gerenciamento de rastreabilidade","B) Teste de manuten\xe7\xe3o","C) Gerenciamento de configura\xe7\xe3o","D) Engenharia de requisitos"],"correctAnswer":2,"explanation":"A op\xe7\xe3o C) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra A, Q#37, LO: FL-5.4.1). Justificativa: Gerenciamento de configura\xe7\xe3o.","source":"Official Sample Exam A Q#37"},{"id":286,"chapter":5,"topic":"Gesti\xf3n de las Actividades de Prueba","question":"Voc\xea recebeu o seguinte relat\xf3rio de defeito dos desenvolvedores indicando que a anomalia descrita neste relat\xf3rio de teste n\xe3o \xe9 reprodut\xedvel. A aplica\xe7\xe3o congela 2022-May-03 \u2013 John Doe \u2013 Rejeitado. A aplica\xe7\xe3o congela ap\xf3s inserir \\"Entrada de teste: $\xe4\\" no campo Nome na tela de cria\xe7\xe3o de novo usu\xe1rio. Tentei fazer logout, fazer login com a conta test_admin01, mesmo problema. Tentei com outras contas de administra\xe7\xe3o de teste, mesmo problema. Nenhuma mensagem de erro foi recebida; o log (ver anexo) cont\xe9m uma notifica\xe7\xe3o de erro fatal. Com base no caso de teste TC-1305, o aplicativo deve aceitar a entrada fornecida e criar o usu\xe1rio. Por favor, corrija com alta prioridade, esta funcionalidade est\xe1 relacionada ao REQ-0012, que \xe9 um novo requisito cr\xedtico de neg\xf3cios. Qual informa\xe7\xe3o cr\xedtica EST\xc1 FALTANDO neste relat\xf3rio de teste que teria sido \xfatil para os desenvolvedores?","options":["A) Resultado esperado e resultado real","B) Refer\xeancias e status do defeito","C) Ambiente de teste e item de teste","D) Prioridade e severidade"],"correctAnswer":2,"explanation":"A op\xe7\xe3o C) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra A, Q#38, LO: FL-5.5.1). Justificativa: Ambiente de teste e item de teste.","source":"Official Sample Exam A Q#38"},{"id":287,"chapter":6,"topic":"Herramientas de Prueba","question":"Qual atividade de teste uma ferramenta de prepara\xe7\xe3o de dados suporta?","options":["A) Monitoramento de teste e controle de teste","B) An\xe1lise de teste","C) Modelagem de teste e implementa\xe7\xe3o de teste","D) Conclus\xe3o de teste"],"correctAnswer":2,"explanation":"A op\xe7\xe3o C) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra A, Q#39, LO: FL-6.1.1). Justificativa: Modelagem de teste e implementa\xe7\xe3o de teste.","source":"Official Sample Exam A Q#39"},{"id":288,"chapter":6,"topic":"Herramientas de Prueba","question":"Qual item identifica corretamente um risco potencial da automa\xe7\xe3o de testes?","options":["A) Impedimentos para os testes","B) Cobertura de ramifica\xe7\xe3o alcan\xe7ada","C) Progresso dos testes","D) Novos riscos dentro do ciclo de teste"],"correctAnswer":1,"explanation":"A op\xe7\xe3o B) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra A, Q#40, LO: FL-6.2.1). Justificativa: Cobertura de ramifica\xe7\xe3o alcan\xe7ada.","source":"Official Sample Exam A Q#40"},{"id":289,"chapter":1,"topic":"Fundamentos del Testing","question":"Qual dos seguintes \xe9 um exemplo de por que \xe9 necess\xe1rio realizar testes?","options":["A) Os testes din\xe2micos aumentam a qualidade ao fazer com que os objetos de teste falhem de maneiras que os usu\xe1rios nunca poderiam alcan\xe7ar","B) Os testes est\xe1ticos s\xe3o usados pelos desenvolvedores para identificar falhas em seu c\xf3digo mais cedo do que pode ser alcan\xe7ado por meio de testes din\xe2micos","C) A an\xe1lise est\xe1tica fornece evid\xeancias aos clientes de que os elementos do sistema que n\xe3o geram sa\xeddas est\xe3o aptos para lan\xe7amento","D) As revis\xf5es aumentam a qualidade das especifica\xe7\xf5es de requisitos e fazem com que menos altera\xe7\xf5es sejam necess\xe1rias nos produtos de trabalho derivados"],"correctAnswer":3,"explanation":"A op\xe7\xe3o D) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra B, Q#1, LO: FL-1.2.1). Justificativa: As revis\xf5es aumentam a qualidade das especifica\xe7\xf5es de requisitos e fazem com que menos altera\xe7\xf5es sejam necess\xe1rias nos produtos de trabalho derivados.","source":"Official Sample Exam B Q#1"},{"id":290,"chapter":1,"topic":"Fundamentos del Testing","question":"Qual das seguintes afirma\xe7\xf5es sobre a garantia da qualidade (QA) e/ou controle da qualidade (QC) est\xe1 correta?  ","options":["A) A QA \xe9 realizada como parte dos testes","B) Os testes s\xe3o realizados como parte do QC","C) Testes \xe9 outro termo para QC","D) Os testes s\xe3o realizados como parte da QA"],"correctAnswer":1,"explanation":"A op\xe7\xe3o B) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra B, Q#2, LO: FL-1.2.2). Justificativa: Os testes s\xe3o realizados como parte do QC","source":"Official Sample Exam B Q#2"},{"id":291,"chapter":1,"topic":"Fundamentos del Testing","question":"Um dos \'princ\xedpios de teste\' estabelece que os testes exaustivos s\xe3o imposs\xedveis. Qual dos seguintes \xe9 um exemplo de como abordar este princ\xedpio na pr\xe1tica?  ","options":["A) Criar casos de teste que cubram cada sa\xedda poss\xedvel especificada","B) Documentar todas as poss\xedveis varia\xe7\xf5es de entrada de teste e prioriz\xe1-las de acordo com a sua import\xe2ncia","C) Come\xe7ar os testes o mais cedo poss\xedvel com revis\xf5es e outras abordagens de testes est\xe1ticos","D) Usar o particionamento de equival\xeancia e a an\xe1lise de valor limite para gerar casos de teste"],"correctAnswer":3,"explanation":"A op\xe7\xe3o D) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra B, Q#3, LO: FL-1.3.1). Justificativa: Usar o particionamento de equival\xeancia e a an\xe1lise de valor limite para gerar casos de teste","source":"Official Sample Exam B Q#3"},{"id":292,"chapter":1,"topic":"Fundamentos del Testing","question":"Qual atividade de teste envolve trabalhar com os requisitos de dados de teste, as condi\xe7\xf5es de teste, os requisitos do ambiente de teste e os casos de teste?  ","options":["A) Modelagem de teste","B) Execu\xe7\xe3o de teste","C) An\xe1lise de teste","D) Implementa\xe7\xe3o de teste"],"correctAnswer":0,"explanation":"A op\xe7\xe3o A) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra B, Q#4, LO: FL-1.4.1). Justificativa: Modelagem de teste","source":"Official Sample Exam B Q#4"},{"id":293,"chapter":1,"topic":"Fundamentos del Testing","question":"Qual dos seguintes \xe9 MAIS prov\xe1vel de impactar a forma como os testes s\xe3o realizados para um determinado objeto de teste?  ","options":["A) O n\xedvel m\xe9dio de experi\xeancia da equipe de marketing da organiza\xe7\xe3o","B) O conhecimento dos usu\xe1rios de que um novo sistema est\xe1 sendo desenvolvido para eles","C) O n\xfamero de anos de experi\xeancia dos membros da equipe de teste","D) A estrutura organizacional do usu\xe1rio final para um aplicativo comercial de streaming de m\xfasica"],"correctAnswer":2,"explanation":"A op\xe7\xe3o C) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra B, Q#5, LO: FL-1.4.2). Justificativa: O n\xfamero de anos de experi\xeancia dos membros da equipe de teste","source":"Official Sample Exam B Q#5"},{"id":294,"chapter":1,"topic":"Fundamentos del Testing","question":"Qual das seguintes afirma\xe7\xf5es \xe9 um exemplo CORRETO do valor da rastreabilidade?  ","options":["A) A rastreabilidade entre os riscos mitigados e os casos de teste que passaram fornece um meio de determinar o n\xedvel de risco residual","B) A rastreabilidade entre os requisitos do usu\xe1rio e os resultados dos testes fornece um meio de medir o progresso do projeto em rela\xe7\xe3o aos objetivos de neg\xf3cio","C) A rastreabilidade entre os testadores e os casos de teste que falharam fornece um meio de determinar o n\xedvel de habilidade dos testadores","D) A rastreabilidade entre os riscos identificados e as condi\xe7\xf5es de teste escritas fornece um meio de determinar quais riscos valem a pena ser testados"],"correctAnswer":1,"explanation":"A op\xe7\xe3o B) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra B, Q#6, LO: FL-1.4.4). Justificativa: A rastreabilidade entre os requisitos do usu\xe1rio e os resultados dos testes fornece um meio de medir o progresso do projeto em rela\xe7\xe3o aos objetivos de neg\xf3cio","source":"Official Sample Exam B Q#6"},{"id":295,"chapter":1,"topic":"Fundamentos del Testing","question":"Qual dos seguintes \xe9 MAIS prov\xe1vel que seja um exemplo de um testador utilizando uma habilidade gen\xe9rica ao testar?  ","options":["A) O profundo conhecimento do testador sobre uma variedade de jogos de computador significou que ele se deu bem com um dos desenvolvedores que tamb\xe9m era f\xe3 de videogames","B) O testador era um ex-piloto e foi mais capaz de entender os crit\xe9rios de aceite para o sistema de controle do helic\xf3ptero","C) O testador trabalhou anteriormente como programador e usou as suas habilidades nessa \xe1rea para se comunicar melhor com os analistas de neg\xf3cios","D) O testador teve muito cuidado para n\xe3o cometer erros quando gerou metodicamente casos de teste antes de come\xe7ar a sua sess\xe3o de testes explorat\xf3rios"],"correctAnswer":1,"explanation":"A op\xe7\xe3o B) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra B, Q#7, LO: FL-1.5.1). Justificativa: O testador era um ex-piloto e foi mais capaz de entender os crit\xe9rios de aceite para o sistema de controle do helic\xf3ptero","source":"Official Sample Exam B Q#7"},{"id":296,"chapter":1,"topic":"Fundamentos del Testing","question":"Qual das seguintes \xe9 uma vantagem da abordagem de equipe completa (whole-team approach)?  ","options":["A) Permite aos membros da equipe assumir qualquer papel a qualquer momento","B) Precisa apenas de uma \xfanica equipe para dar suporte ao projeto de desenvolvimento completo","C) Integra os representantes de neg\xf3cios junto com os desenvolvedores na mesma equipe","D) Gera uma sinergia de equipe que beneficia a todo o projeto"],"correctAnswer":3,"explanation":"A op\xe7\xe3o D) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra B, Q#8, LO: FL-1.5.2). Justificativa: A abordagem de equipe completa gera uma sinergia que beneficia a todo o projeto.","source":"Official Sample Exam B Q#8"},{"id":297,"chapter":2,"topic":"Testing a lo largo del SDLC","question":"Qual das seguintes afirma\xe7\xf5es sobre o ciclo de vida de desenvolvimento de software escolhido \xe9 CORRETA?  ","options":["A) Se o desenvolvimento \xe1gil de software for usado, a automa\xe7\xe3o dos testes de sistema substitui a necessidade de testes de regress\xe3o","B) Se um modelo de desenvolvimento sequencial for usado, os testes din\xe2micos geralmente ficam restritos a est\xe1gios mais avan\xe7ados do ciclo de vida","C) Se um modelo de desenvolvimento iterativo for usado, os testes de componente s\xe3o geralmente realizados manualmente pelos desenvolvedores","D) Se um modelo de desenvolvimento incremental for usado, os testes est\xe1ticos s\xe3o realizados nos primeiros incrementos e os din\xe2micos nos \xfaltimos"],"correctAnswer":1,"explanation":"A op\xe7\xe3o B) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra B, Q#9, LO: FL-2.1.1). Justificativa: Em um modelo de desenvolvimento sequencial, os testes din\xe2micos geralmente s\xe3o restritos \xe0s fases finais do ciclo de vida.","source":"Official Sample Exam B Q#9"},{"id":298,"chapter":2,"topic":"Testing a lo largo del SDLC","question":"Qual das seguintes \xe9 uma boa pr\xe1tica de teste aplic\xe1vel a todos os ciclos de vida de desenvolvimento de software?  ","options":["A) Os testadores devem revisar os produtos de trabalho como parte da pr\xf3xima fase de desenvolvimento","B) Os testadores devem revisar os produtos de trabalho assim que os rascunhos estiverem dispon\xedveis","C) Os testadores devem revisar os produtos de trabalho antes do in\xedcio da an\xe1lise e da modelagem de testes","D) Os testadores devem revisar os produtos de trabalho imediatamente ap\xf3s a sua publica\xe7\xe3o"],"correctAnswer":1,"explanation":"A op\xe7\xe3o B) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra B, Q#10, LO: FL-2.1.2). Justificativa: Os testadores devem revisar os produtos de trabalho assim que os rascunhos estiverem dispon\xedveis.","source":"Official Sample Exam B Q#10"},{"id":299,"chapter":2,"topic":"Testing a lo largo del SDLC","question":"Qual das seguintes \xe9 um exemplo de abordagem de desenvolvimento de teste primeiro (test-first)?  ","options":["A) Desenvolvimento Orientado a Testes (TDD)","B) Desenvolvimento Orientado a Cobertura","C) Desenvolvimento Orientado a Qualidade","D) Desenvolvimento Orientado a Funcionalidades"],"correctAnswer":0,"explanation":"A op\xe7\xe3o A) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra B, Q#11, LO: FL-2.1.3). Justificativa: O Desenvolvimento Orientado a Testes (TDD) \xe9 o exemplo cl\xe1ssico da abordagem de teste primeiro.","source":"Official Sample Exam B Q#11"},{"id":300,"chapter":2,"topic":"Testing a lo largo del SDLC","question":"Qual das seguintes atividades \xe9 MAIS PROV\xc1VEL de ser realizada como parte dos testes de sistema?  ","options":["A) Testes de seguran\xe7a de um sistema de gest\xe3o de cr\xe9ditos realizado por uma equipe de testes independente","B) Testes da interface de um sistema de c\xe2mbio com um sistema banc\xe1rio externo","C) Testes beta de um sistema de aprendizado remoto realizados pelos desenvolvedores do software","D) Testes das intera\xe7\xf5es entre a interface do usu\xe1rio e o banco de dados de um sistema de recursos humanos"],"correctAnswer":0,"explanation":"A op\xe7\xe3o A) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra B, Q#13, LO: FL-2.2.1). Justificativa: Os testes de seguran\xe7a realizados por uma equipe independente s\xe3o caracter\xedsticas dos testes de sistema.","source":"Official Sample Exam B Q#13"},{"id":301,"chapter":2,"topic":"Testing a lo largo del SDLC","question":"Qual das seguintes afirma\xe7\xf5es \xe9 CORRETA?  ","options":["A) Os testes de regress\xe3o aumentam em n\xfamero \xe0 medida que o projeto avan\xe7a, enquanto os testes de confirma\xe7\xe3o diminuem","B) Os testes de regress\xe3o s\xe3o criados e executados quando o objeto de teste \xe9 corrigido, enquanto os de confirma\xe7\xe3o s\xe3o executados quando o objeto de teste \xe9 aprimorado","C) Os testes de regress\xe3o verificam se o ambiente operacional permanece inalterado, enquanto os de confirma\xe7\xe3o testam as mudan\xe7as no objeto de teste","D) Os testes de regress\xe3o verificam os efeitos adversos no c\xf3digo n\xe3o alterado, enquanto os de confirma\xe7\xe3o testam o c\xf3digo modificado"],"correctAnswer":3,"explanation":"A op\xe7\xe3o D) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra B, Q#14, LO: FL-2.2.3). Justificativa: Os testes de regress\xe3o lidam com os efeitos adversos no c\xf3digo n\xe3o alterado, enquanto os testes de confirma\xe7\xe3o lidam com o c\xf3digo modificado.","source":"Official Sample Exam B Q#14"},{"id":302,"chapter":3,"topic":"Pruebas Est\xe1ticas","question":"Qual dos seguintes \xe9 um exemplo de defeito que pode ser encontrado atrav\xe9s de testes est\xe1ticos, mas N\xc3O atrav\xe9s de testes din\xe2micos?  ","options":["A) Falta de usabilidade na interface do usu\xe1rio","B) C\xf3digo que n\xe3o \xe9 alcan\xe7ado por nenhum caminho de execu\xe7\xe3o (c\xf3digo morto)","C) Tempos de resposta deficientes para a maioria dos usu\xe1rios esperados","D) Funcionalidades exigidas que n\xe3o est\xe3o implementadas no c\xf3digo"],"correctAnswer":1,"explanation":"A op\xe7\xe3o B) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra B, Q#15, LO: FL-3.1.3). Justificativa: O c\xf3digo inalcan\xe7\xe1vel (c\xf3digo morto) s\xf3 pode ser detectado atrav\xe9s de an\xe1lise est\xe1tica, uma vez que nunca \xe9 executado.","source":"Official Sample Exam B Q#15"},{"id":303,"chapter":3,"topic":"Pruebas Est\xe1ticas","question":"Qual das seguintes \xe9 uma vantagem do feedback inicial e frequente das partes interessadas?  ","options":["A) Os gerentes sabem quais desenvolvedores s\xe3o menos produtivos","B) Permite aos gerentes de projeto priorizarem suas intera\xe7\xf5es com as partes interessadas","C) Facilita a comunica\xe7\xe3o antecipada de poss\xedveis problemas de qualidade","D) Os usu\xe1rios finais entendem melhor por que a entrega do produto de trabalho est\xe1 atrasada"],"correctAnswer":2,"explanation":"A op\xe7\xe3o C) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra B, Q#16, LO: FL-3.2.1). Justificativa: O feedback inicial facilita a comunica\xe7\xe3o antecipada de poss\xedveis problemas de qualidade.","source":"Official Sample Exam B Q#16"},{"id":304,"chapter":3,"topic":"Pruebas Est\xe1ticas","question":"Dadas as seguintes descri\xe7\xf5es de tarefas: Qual das seguintes op\xe7\xf5es estabelece a MELHOR correspond\xeancia entre as descri\xe7\xf5es de tarefas e as atividades?\\n\\n1. As caracter\xedsticas de qualidade a serem avaliadas e os crit\xe9rios de sa\xedda s\xe3o selecionados\\n2. Todos t\xeam acesso ao produto de trabalho\\n3. Anomalias s\xe3o identificadas no produto de trabalho\\n4. As anomalias s\xe3o debatidas\\n\\nA. Revis\xe3o individual  \\nB. In\xedcio da revis\xe3o  \\nC. Planejamento  \\nD. Comunica\xe7\xe3o e an\xe1lise","options":["A) 1B, 2C, 3D, 4A","B) 1B, 2D, 3C, 4A","C) 1C, 2A, 3B, 4D","D) 1C, 2B, 3A, 4D"],"correctAnswer":3,"explanation":"A op\xe7\xe3o D) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra B, Q#17, LO: FL-3.2.2). Justificativa: O planejamento define crit\xe9rios (1C), o in\xedcio d\xe1 acesso ao documento (2B), a revis\xe3o individual identifica anomalias (3A) e a comunica\xe7\xe3o e an\xe1lise as debate (4D).","source":"Official Sample Exam B Q#17"},{"id":305,"chapter":3,"topic":"Pruebas Est\xe1ticas","question":"Dados os seguintes pap\xe9is nas revis\xf5es: Qual das seguintes op\xe7\xf5es estabelece a MELHOR correspond\xeancia entre os pap\xe9is e as responsabilidades?\\n\\n1. Escriba (Relator)\\n2. L\xedder da revis\xe3o\\n3. Facilitador\\n4. Gerente\\n\\nA. Garante o funcionamento eficaz das reuni\xf5es de revis\xe3o e estabelece um ambiente seguro  \\nB. Registra as informa\xe7\xf5es da revis\xe3o, como decis\xf5es e novas anomalias encontradas  \\nC. Decide o que ser\xe1 revisado e fornece recursos como pessoal e tempo  \\nD. Assume a responsabilidade geral pela revis\xe3o: quando e onde ocorrer\xe1","options":["A) 1A, 2B, 3D, 4C","B) 1A, 2C, 3B, 4D","C) 1B, 2D, 3A, 4C","D) 1B, 2D, 3C, 4A"],"correctAnswer":2,"explanation":"A op\xe7\xe3o C) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra B, Q#18, LO: FL-3.2.3). Justificativa: O Escriba registra (1B), o L\xedder organiza a revis\xe3o (2D), o Facilitador gerencia a reuni\xe3o (3A) e o Gerente decide os recursos (4C).","source":"Official Sample Exam B Q#18"},{"id":306,"chapter":4,"topic":"T\xe9cnicas de An\xe1lisis y Dise\xf1o de Pruebas","question":"Qual das seguintes afirma\xe7\xf5es descreve MELHOR a diferen\xe7a entre os testes de tabela de decis\xe3o e os testes de ramo?  ","options":["A) Nos testes de tabela de decis\xe3o, os casos de teste s\xe3o derivados das instru\xe7\xf5es de decis\xe3o do c\xf3digo. Nos testes de ramo, os casos de teste s\xe3o derivados do conhecimento do fluxo de controle do objeto de teste.","B) Nos testes de tabela de decis\xe3o, os casos de teste s\xe3o derivados da especifica\xe7\xe3o que descreve a l\xf3gica de neg\xf3cios. Nos testes de ramo, os casos baseiam-se na antecipa\xe7\xe3o de poss\xedveis defeitos no c\xf3digo-fonte.","C) Nos testes de tabela de decis\xe3o, os casos de teste s\xe3o derivados do conhecimento do fluxo de controle do objeto de teste. Nos testes de ramo, os casos s\xe3o derivados da especifica\xe7\xe3o que descreve a l\xf3gica de neg\xf3cios.","D) Nos testes de tabela de decis\xe3o, os casos de teste s\xe3o independentes da forma como o software \xe9 implementado. Nos testes de ramo, os casos de teste s\xf3 podem ser criados ap\xf3s a modelagem ou a implementa\xe7\xe3o do c\xf3digo."],"correctAnswer":3,"explanation":"A op\xe7\xe3o D) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra B, Q#19, LO: FL-4.1.1). Justificativa: As tabelas de decis\xe3o s\xe3o independentes da implementa\xe7\xe3o (caixa preta), enquanto os testes de ramo exigem o conhecimento do c\xf3digo (caixa branca).","source":"Official Sample Exam B Q#19"},{"id":307,"chapter":4,"topic":"T\xe9cnicas de An\xe1lisis y Dise\xf1o de Pruebas","question":"Os clientes da rede de lavagem de carros TestWash t\xeam cart\xf5es com o n\xfamero de lavagens que compraram. O valor inicial \xe9 0. Ao entrar no lava-r\xe1pido, o sistema incrementa o n\xfamero no cart\xe3o em um. Este valor representa o n\xfamero da lavagem atual. Com base neste n\xfamero, o sistema decide o desconto: cada d\xe9cima lavagem d\xe1 10% de desconto e cada vig\xe9sima lavagem d\xe1 40% adicional (ou seja, 50% no total). Qual dos seguintes conjuntos de dados de entrada (entendidos como os n\xfameros da lavagem atual) alcan\xe7a a maior cobertura de particionamento de equival\xeancia?  ","options":["A) 19, 20, 30","B) 11, 12, 20","C) 1, 10, 50","D) 10, 29, 30, 31"],"correctAnswer":0,"explanation":"A op\xe7\xe3o A) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra B, Q#20, LO: FL-4.2.1). Justificativa: As parti\xe7\xf5es s\xe3o: sem desconto (n\xe3o m\xfaltiplo de 10), 10% (m\xfaltiplo de 10, mas n\xe3o de 20) e 50% (m\xfaltiplo de 20). 19 (sem desconto), 20 (50%) e 30 (10%) cobrem 3 parti\xe7\xf5es distintas.","source":"Official Sample Exam B Q#20"},{"id":308,"chapter":4,"topic":"T\xe9cnicas de An\xe1lisis y Dise\xf1o de Pruebas","question":"Voc\xea est\xe1 testando um formul\xe1rio que verifica se o comprimento da senha inserida est\xe1 correto. O formul\xe1rio aceita senhas com o comprimento correto e rejeita aquelas que s\xe3o curtas ou longas demais. O comprimento est\xe1 correto se tiver entre 6 e 12 caracteres, inclusive. O formul\xe1rio est\xe1 inicialmente vazio (comprimento = 0). Voc\xea aplica a an\xe1lise de valor limite \xe0 vari\xe1vel \'comprimento da senha\'. Seu conjunto de casos de teste atinge 100% de cobertura de valor limite de 2 valores. A equipe decide que, devido ao alto risco do componente, casos devem ser adicionados para atingir 100% de cobertura de valor limite de 3 valores. Quais comprimentos de senha adicionais devem ser testados?  ","options":["A) 4, 5, 13, 14","B) 7, 11","C) 1, 5, 13","D) 1, 4, 7, 11, 14"],"correctAnswer":3,"explanation":"A op\xe7\xe3o D) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra B, Q#21, LO: FL-4.2.2). Justificativa: Com 2 valores j\xe1 temos 0, 6, 12 e um valor fora do intervalo superior. Com 3 valores tamb\xe9m precisamos dos vizinhos: 5, 7, 11, 13 e o valor 1 para o limite inferior esquerdo.","source":"Official Sample Exam B Q#21"},{"id":309,"chapter":4,"topic":"T\xe9cnicas de An\xe1lisis y Dise\xf1o de Pruebas","question":"A tabela de decis\xe3o a seguir cont\xe9m as regras para determinar o risco de arteriosclerose.  \\n  \\n| | Regra 1 | Regra 2 | Regra 3 | Regra 4 | Regra 5 |  \\n|---|---|---|---|---|---|  \\n| Colesterol (mg/dl) | \u2264124 | \u2264124 | 125\u2013200 | 125\u2013200 | \u2265201 |  \\n| Press\xe3o arterial (mm Hg) | \u2264140 | >140 | \u2264140 | >140 | \u2013 |  \\n| N\xedvel de risco | muito baixo | baixo | m\xe9dio | alto | muito alto |  \\n  \\nVoc\xea projetou os seguintes casos de teste:  \\n- TC1: Colesterol=125, PA=141  \\n- TC2: Colesterol=200, PA=201  \\n- TC3: Colesterol=124, PA=201  \\n- TC4: Colesterol=109, PA=200  \\n- TC5: Colesterol=201, PA=140  \\n  \\nQual cobertura de tabela de decis\xe3o esses casos de teste alcan\xe7am?  ","options":["A) 40%","B) 60%","C) 80%","D) 100%"],"correctAnswer":1,"explanation":"A op\xe7\xe3o B) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra B, Q#22, LO: FL-4.2.3). Justificativa: A tabela possui 5 regras. Os casos de teste cobrem as regras 2 (TC1), 4 (TC2 \u2013 n\xe3o se aplica exatamente), 1 (TC4) e 5 (TC5). Apenas 3 de 5 regras s\xe3o cobertas corretamente, o que d\xe1 60%.","source":"Official Sample Exam B Q#22"},{"id":310,"chapter":4,"topic":"T\xe9cnicas de An\xe1lisis y Dise\xf1o de Pruebas","question":"Um sistema de armazenamento pode guardar at\xe9 tr\xeas itens e \xe9 modelado pelo diagrama de transi\xe7\xe3o de estado a seguir. A vari\xe1vel N representa o n\xfamero de itens armazenados no momento. Qual dos seguintes casos de teste, representados como sequ\xeancias de eventos, alcan\xe7a o n\xedvel mais alto de cobertura de transi\xe7\xe3o v\xe1lida?  ","options":["A) Adicionar, Remover, Adicionar, Adicionar, Adicionar","B) Adicionar, Adicionar, Adicionar, Adicionar, Remover, Remover","C) Adicionar, Adicionar, Adicionar, Remover, Remover","D) Adicionar, Adicionar, Adicionar, Remover, Adicionar"],"correctAnswer":2,"explanation":"A op\xe7\xe3o C) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra B, Q#23, LO: FL-4.2.4). Justificativa: A sequ\xeancia Adicionar\xd73, Remover\xd72 percorre todas as transi\xe7\xf5es v\xe1lidas do diagrama de estados.","source":"Official Sample Exam B Q#23"},{"id":311,"chapter":4,"topic":"T\xe9cnicas de An\xe1lisis y Dise\xf1o de Pruebas","question":"Voc\xea executa dois casos de teste, T1 e T2, sobre o mesmo c\xf3digo. T1 alcan\xe7a 40% de cobertura de instru\xe7\xe3o e T2 alcan\xe7a 65%. Qual das seguintes afirma\xe7\xf5es \xe9 necessariamente verdadeira?  ","options":["A) O conjunto de testes T1+T2 alcan\xe7a 105% de cobertura de instru\xe7\xe3o","B) Existe pelo menos uma instru\xe7\xe3o que foi executada tanto por T1 quanto por T2","C) Pelo menos 5% das instru\xe7\xf5es do c\xf3digo testado n\xe3o s\xe3o execut\xe1veis","D) O conjunto de testes T1+T2 alcan\xe7a cobertura total de ramo"],"correctAnswer":1,"explanation":"A op\xe7\xe3o B) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra B, Q#24, LO: FL-4.3.1). Justificativa: Se T1 cobre 40% e T2 cobre 65%, e a cobertura total n\xe3o pode exceder 100%, necessariamente existe uma sobreposi\xe7\xe3o: ambos executaram pelo menos alguma instru\xe7\xe3o em comum.","source":"Official Sample Exam B Q#24"},{"id":312,"chapter":4,"topic":"T\xe9cnicas de An\xe1lisis y Dise\xf1o de Pruebas","question":"A m\xe9trica de cobertura de ramo \xe9 definida como: BCov = (X / Y) \xd7 100%. O que X e Y representam nesta f\xf3rmula?  ","options":["A) X = n\xfamero de resultados de decis\xe3o exercitados pelos casos de teste. Y = n\xfamero total de resultados de decis\xe3o no c\xf3digo","B) X = n\xfamero de ramos condicionais exercitados pelos casos de teste. Y = n\xfamero total de ramos no c\xf3digo","C) X = n\xfamero de ramos exercitados pelos casos de teste. Y = n\xfamero total de ramos no c\xf3digo","D) X = n\xfamero de ramos condicionais exercitados pelos casos de teste. Y = n\xfamero total de resultados de decis\xe3o no c\xf3digo"],"correctAnswer":2,"explanation":"A op\xe7\xe3o C) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra B, Q#25, LO: FL-4.3.2). Justificativa: X \xe9 o n\xfamero de ramos exercitados e Y o n\xfamero total de ramos no c\xf3digo.","source":"Official Sample Exam B Q#25"},{"id":313,"chapter":4,"topic":"T\xe9cnicas de An\xe1lisis y Dise\xf1o de Pruebas","question":"O que MELHOR justifica o uso de testes explorat\xf3rios?","options":["A) Pouco tempo para modelagem e testadores experientes","B) Uso de t\xe9cnicas formais de caixa preta requeridas","C) Especifica\xe7\xe3o em linguagem formal","D) Testadores com boas habilidades de programa\xe7\xe3o"],"correctAnswer":0,"explanation":"A op\xe7\xe3o A) e E) s\xe3o as respostas corretas de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra B, Q#26, LO: FL-4.4.2). Justificativa: Os testes explorat\xf3rios s\xe3o ideais quando h\xe1 pouco tempo para a modelagem formal (A) e quando o testador tem experi\xeancia no dom\xednio (E).","source":"Official Sample Exam B Q#26"},{"id":314,"chapter":4,"topic":"T\xe9cnicas de An\xe1lisis y Dise\xf1o de Pruebas","question":"Qual das seguintes op\xe7\xf5es MELHOR se encaixa como um item de uma lista de verifica\xe7\xe3o (checklist) nos testes baseados em checklist?  ","options":["A) \'O desenvolvedor cometeu um erro ao implementar o c\xf3digo\'","B) \'A cobertura de instru\xe7\xe3o alcan\xe7ada supera os 85%\'","C) \'O programa funciona corretamente em rela\xe7\xe3o aos requisitos funcionais e n\xe3o funcionais\'","D) \'As mensagens de erro s\xe3o escritas em uma linguagem compreens\xedvel para o usu\xe1rio\'"],"correctAnswer":3,"explanation":"A op\xe7\xe3o D) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra B, Q#27, LO: FL-4.4.3). Justificativa: Os itens de um checklist devem ser verific\xe1veis por observa\xe7\xe3o, como verificar se as mensagens s\xe3o compreens\xedveis para o usu\xe1rio.","source":"Official Sample Exam B Q#27"},{"id":315,"chapter":4,"topic":"T\xe9cnicas de An\xe1lisis y Dise\xf1o de Pruebas","question":"Considere o seguinte crit\xe9rio de aceite para uma hist\xf3ria de usu\xe1rio escrita sob a perspectiva do propriet\xe1rio de uma loja online. DADO QUE o usu\xe1rio fez login e est\xe1 na p\xe1gina inicial, QUANDO o usu\xe1rio clica no bot\xe3o \'Adicionar item\', ENT\xc3O o formul\xe1rio \'Criar item\' deve aparecer, E o usu\xe1rio deve ser capaz de inserir um nome e um pre\xe7o para o novo item. Em que formato este crit\xe9rio de aceite est\xe1 escrito?  ","options":["A) Orientado a regras","B) Orientado a cen\xe1rios","C) Orientado ao produto","D) Orientado ao processo"],"correctAnswer":1,"explanation":"A op\xe7\xe3o B) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra B, Q#28, LO: FL-4.5.2). Justificativa: O formato DADO QUE/QUANDO/ENT\xc3O (Given/When/Then) \xe9 o formato orientado a cen\xe1rios, t\xedpico do BDD.","source":"Official Sample Exam B Q#28"},{"id":316,"chapter":4,"topic":"T\xe9cnicas de An\xe1lisis y Dise\xf1o de Pruebas","question":"A sua equipe analisa a seguinte hist\xf3ria de usu\xe1rio para definir os crit\xe9rios de aceite: \'Como cliente registrado, quero poder visualizar meus pedidos anteriores no site da empresa, para poder acompanhar minhas compras.\' Qual dos seguintes casos de teste N\xc3O ser\xe1 relevante para esta hist\xf3ria de usu\xe1rio?  ","options":["A) Entrada: o cliente faz login e clica em \'ver hist\xf3rico de pedidos\'. Resultado esperado: o sistema mostra uma lista de todos os pedidos anteriores com data, n\xfamero do pedido e custo total","B) Entrada: o cliente clica em um pedido da lista. Resultado esperado: o sistema mostra os itens individuais comprados com seus pre\xe7os e quantidades","C) Entrada: o cliente clica em \'Ordenar de forma crescente\' na tela de hist\xf3rico de pedidos. Resultado esperado: o sistema mostra o hist\xf3rico ordenado pelo n\xfamero do pedido em ordem crescente","D) Entrada: um cliente n\xe3o registrado se cadastra como um novo cliente com um e-mail v\xe1lido que n\xe3o existe no banco de dados. Resultado esperado: o sistema aceita o cadastro e cria a conta"],"correctAnswer":3,"explanation":"A op\xe7\xe3o D) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra B, Q#29, LO: FL-4.5.3). Justificativa: A hist\xf3ria de usu\xe1rio trata da visualiza\xe7\xe3o de pedidos anteriores (cliente j\xe1 registrado), e n\xe3o sobre o processo de cadastro de novos clientes.","source":"Official Sample Exam B Q#29"},{"id":317,"chapter":5,"topic":"Gesti\xf3n de las Actividades de Prueba","question":"Sua equipe segue um processo que usa o pipeline de entrega do DevOps. Os tr\xeas primeiros passos s\xe3o: (1) Desenvolvimento de c\xf3digo (2) Enviar o c\xf3digo para o sistema de controle de vers\xe3o e mescl\xe1-lo com o branch \'test\' (3) Executar os testes de componente do c\xf3digo enviado. Qual das alternativas a seguir \xe9 a MELHOR op\xe7\xe3o como crit\xe9rio de entrada para o passo (2) deste pipeline?  ","options":["A) A an\xe1lise est\xe1tica n\xe3o retorna avisos de alta severidade para o c\xf3digo enviado","B) O sistema de controle de vers\xe3o n\xe3o relata conflitos ao mesclar o c\xf3digo com o branch \'test\'","C) Os testes de componente est\xe3o compilados e prontos para serem executados","D) A cobertura de instru\xe7\xe3o \xe9 de pelo menos 80%"],"correctAnswer":0,"explanation":"A op\xe7\xe3o A) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra B, Q#30, LO: FL-5.1.3). Justificativa: A an\xe1lise est\xe1tica sem avisos graves \xe9 o crit\xe9rio de entrada mais adequado antes de enviar o c\xf3digo para o sistema de controle de vers\xe3o.","source":"Official Sample Exam B Q#30"},{"id":318,"chapter":5,"topic":"Gesti\xf3n de las Actividades de Prueba","question":"Voc\xea deseja estimar o esfor\xe7o de teste para um novo projeto usando estimativas baseadas em propor\xe7\xf5es. Voc\xea calcula a propor\xe7\xe3o esfor\xe7o de teste/esfor\xe7o de desenvolvimento usando dados m\xe9dios de quatro projetos hist\xf3ricos semelhantes. A tabela mostra: P1: Desenvolvimento $800.000, Testes $40.000 | P2: $1.200.000 / $130.000 | P3: $600.000 / $70.000 | P4: $1.000.000 / $120.000. O esfor\xe7o de desenvolvimento estimado para o novo projeto \xe9 de $800.000. Qual \xe9 a sua estimativa de esfor\xe7o de teste?  ","options":["A) $40.000","B) $80.000","C) $81.250","D) $82.500"],"correctAnswer":1,"explanation":"A op\xe7\xe3o B) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra B, Q#31, LO: FL-5.1.4). Justificativa: A propor\xe7\xe3o m\xe9dia \xe9 (40+130+70+120)/(800+1200+600+1000) = 360/3600 = 10%. Os 10% de $800.000 = $80.000.","source":"Official Sample Exam B Q#31"},{"id":319,"chapter":5,"topic":"Gesti\xf3n de las Actividades de Prueba","question":"Voc\xea est\xe1 testando um aplicativo web que permite aos usu\xe1rios BUSCAR produtos, VER detalhes, ADICIONAR ao carrinho e FAZER um pedido. Voc\xea tem 7 casos de teste com estas prioridades (1=maior):  \\n- TC1: BUSCAR produto A (4)  \\n- TC2: BUSCAR produto B (4)  \\n- TC3: VER detalhes A (3)  \\n- TC4: VER detalhes B (2)  \\n- TC5: ADICIONAR produto A (3)  \\n- TC6: ADICIONAR produto B (1)  \\n- TC7: FAZER PEDIDO (5)  \\n  \\nDepend\xeancias: BUSCAR deve ser testado antes de VER, VER antes de ADICIONAR, e ADICIONAR antes de PEDIDO. Qual caso de teste deve ser executado em quarto lugar?  ","options":["A) TC3","B) TC1","C) TC7","D) TC2"],"correctAnswer":1,"explanation":"A op\xe7\xe3o B) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra B, Q#32, LO: FL-5.1.5). Justificativa: Respeitando depend\xeancias e prioridade: 1\xba TC6 (p1), 2\xba TC4 (p2), 3\xba TC5 ou TC3 (p3), 4\xba TC1 (p4 ap\xf3s cumprir as depend\xeancias).","source":"Official Sample Exam B Q#32"},{"id":320,"chapter":5,"topic":"Gesti\xf3n de las Actividades de Prueba","question":"De acordo com o modelo de quadrantes de teste, qual dos seguintes se enquadra no quadrante Q1 (\'orientado \xe0 tecnologia\' e \'d\xe1 suporte \xe0 equipe\')?  ","options":["A) Testes de usabilidade","B) Testes funcionais","C) Testes de aceite do usu\xe1rio","D) Testes de integra\xe7\xe3o de componentes"],"correctAnswer":3,"explanation":"A op\xe7\xe3o D) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra B, Q#33, LO: FL-5.1.7). Justificativa: Os testes de integra\xe7\xe3o de componentes s\xe3o t\xe9cnicos e d\xe3o suporte \xe0 equipe de desenvolvimento, por isso pertencem ao quadrante Q1.","source":"Official Sample Exam B Q#33"},{"id":321,"chapter":5,"topic":"Gesti\xf3n de las Actividades de Prueba","question":"Dados os seguintes riscos: Qual das seguintes op\xe7\xf5es estabelece a MELHOR correspond\xeancia entre os riscos e as atividades de mitiga\xe7\xe3o?\\n\\n1. Uma implementa\xe7\xe3o ineficaz de loops causa respostas lentas do sistema\\n2. Os consumidores mudam as suas prefer\xeancias\\n3. Inunda\xe7\xe3o da sala de servidores\\n4. Pacientes acima de uma certa idade recebem relat\xf3rios incorretos\\n\\nA. Aceita\xe7\xe3o do risco  \\nB. Testes de efici\xeancia de desempenho  \\nC. Uso da an\xe1lise de valor limite como t\xe9cnica  \\nD. Transfer\xeancia do risco","options":["A) 1C, 2D, 3A, 4B","B) 1B, 2D, 3A, 4C","C) 1B, 2A, 3D, 4C","D) 1C, 2A, 3D, 4B"],"correctAnswer":2,"explanation":"A op\xe7\xe3o C) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra B, Q#34, LO: FL-5.2.4). Justificativa: Risco de desempenho\u2192testes de desempenho (1B), risco de mercado\u2192aceita\xe7\xe3o (2A), risco de inunda\xe7\xe3o\u2192transfer\xeancia/seguro (3D), risco de precis\xe3o\u2192valores limite (4C).","source":"Official Sample Exam B Q#34"},{"id":322,"chapter":5,"topic":"Gesti\xf3n de las Actividades de Prueba","question":"Qual das seguintes \xe9 uma m\xe9trica de qualidade do produto?  ","options":["A) Tempo m\xe9dio at\xe9 a falha (MTTF)","B) N\xfamero de defeitos encontrados","C) Cobertura de requisitos","D) Porcentagem de detec\xe7\xe3o de defeitos"],"correctAnswer":0,"explanation":"A op\xe7\xe3o A) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra B, Q#35, LO: FL-5.3.1). Justificativa: O MTTF (tempo m\xe9dio at\xe9 a falha) mede a confiabilidade do produto em produ\xe7\xe3o, sendo, portanto, uma m\xe9trica de qualidade do produto.","source":"Official Sample Exam B Q#35"},{"id":323,"chapter":5,"topic":"Gesti\xf3n de las Actividades de Prueba","question":"Voc\xea \xe9 membro de uma equipe de testes localizada na Am\xe9rica do Norte, desenvolvendo um produto para um cliente na Europa. A equipe \xe9 \xe1gil, segue pr\xe1ticas DevOps e usa um pipeline de CI/CD. Qual das seguintes \xe9 a forma MENOS eficaz de comunicar o progresso dos testes ao cliente?  ","options":["A) Frente a frente (presencialmente)","B) Pain\xe9is de controle (Dashboards)","C) E-mail","D) Videoconfer\xeancia"],"correctAnswer":0,"explanation":"A op\xe7\xe3o A) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra B, Q#36, LO: FL-5.3.3). Justificativa: Com a equipe na Am\xe9rica do Norte e o cliente na Europa, a comunica\xe7\xe3o presencial \xe9 invi\xe1vel e \xe9 a op\xe7\xe3o menos eficaz.","source":"Official Sample Exam B Q#36"},{"id":324,"chapter":5,"topic":"Gesti\xf3n de las Actividades de Prueba","question":"Qual das op\xe7\xf5es a seguir descreve MELHOR um exemplo de como o gerenciamento de configura\xe7\xe3o (CM) d\xe1 suporte aos testes?  ","options":["A) Com o n\xfamero da vers\xe3o do ambiente, a ferramenta de CM pode recuperar os n\xfameros de vers\xe3o das bibliotecas, stubs e drivers utilizados nesse ambiente","B) Com um registro dos valores das entradas, a ferramenta de CM pode executar os casos de teste para essas configura\xe7\xf5es e calcular a cobertura","C) Com dados sobre a data de compra de uma licen\xe7a de software, a ferramenta de CM gera automaticamente informa\xe7\xf5es sobre a proximidade do fim da licen\xe7a","D) Com o n\xfamero de vers\xe3o do caso de teste, a ferramenta de CM pode gerar dados de teste automaticamente para esse caso"],"correctAnswer":0,"explanation":"A op\xe7\xe3o A) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra B, Q#37, LO: FL-5.4.1). Justificativa: O CM permite vincular vers\xf5es do ambiente a vers\xf5es espec\xedficas de bibliotecas, stubs e drivers, garantindo a reprodutibilidade dos ambientes de teste.","source":"Official Sample Exam B Q#37"},{"id":325,"chapter":5,"topic":"Gesti\xf3n de las Actividades de Prueba","question":"Voc\xea est\xe1 testando uma fun\xe7\xe3o de ordena\xe7\xe3o que recebe um conjunto de n\xfameros e os retorna em ordem crescente. O log de execu\xe7\xe3o \xe9:  \\n  \\n- TC1: Entrada: `3`. Sa\xedda: `3`. Resultado: passou  \\n- TC2: Entrada: `3 11 6 5`. Sa\xedda: `3 5 6 11`. Resultado: passou  \\n- TC3: Entrada: `8 7 3 7 1`. Sa\xedda: `1 3 7 8`. Resultado: falhou  \\n- TC4: Entrada: `-2 -2 -2 -3 -3`. Sa\xedda: `-3 -2`. Resultado: falhou  \\n- TC5: Entrada: `0 -2 0 3 4 4`. Sa\xedda: `-2 0 3 4`. Resultado: falhou  \\n  \\nQual das alternativas a seguir fornece a MELHOR descri\xe7\xe3o da falha para usar em um relat\xf3rio de defeito?  ","options":["A) O sistema falha em ordenar v\xe1rios conjuntos de n\xfameros. Refer\xeancia: TC3, TC4, TC5.","B) O sistema parece ignorar as duplicatas ao ordenar. Refer\xeancia: TC3, TC4, TC5.","C) O sistema falha em ordenar n\xfameros negativos. Refer\xeancia: TC4, TC5.","D) TC3, TC4 e TC5 t\xeam defeitos (dados de entrada duplicados) e devem ser corrigidos."],"correctAnswer":1,"explanation":"A op\xe7\xe3o B) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra B, Q#38, LO: FL-5.5.1). Justificativa: O padr\xe3o comum nas tr\xeas falhas \xe9 que a fun\xe7\xe3o ignora os elementos duplicados ao ordenar, o que \xe9 a descri\xe7\xe3o mais precisa do defeito.","source":"Official Sample Exam B Q#38"},{"id":326,"chapter":6,"topic":"Herramientas de Prueba","question":"Dadas as seguintes descri\xe7\xf5es: Qual das seguintes op\xe7\xf5es estabelece a MELHOR correspond\xeancia entre as descri\xe7\xf5es e as categorias?\\n\\n1. D\xe3o suporte ao acompanhamento do fluxo de trabalho\\n2. Facilitam a comunica\xe7\xe3o\\n3. M\xe1quinas virtuais\\n4. D\xe3o suporte \xe0s revis\xf5es\\n\\nA. Ferramentas de testes est\xe1ticos  \\nB. Ferramentas que apoiam a escalabilidade e a padroniza\xe7\xe3o da implanta\xe7\xe3o  \\nC. Ferramentas DevOps  \\nD. Ferramentas de colabora\xe7\xe3o","options":["A) 1A, 2B, 3C, 4D","B) 1B, 2D, 3C, 4A","C) 1C, 2D, 3B, 4A","D) 1D, 2C, 3A, 4B"],"correctAnswer":2,"explanation":"A op\xe7\xe3o C) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra B, Q#39, LO: FL-6.1.1). Justificativa: DevOps\u2192acompanhamento de fluxo (1C), Colabora\xe7\xe3o\u2192comunica\xe7\xe3o (2D), Escalabilidade\u2192m\xe1quinas virtuais (3B), Est\xe1ticas\u2192revis\xf5es (4A).","source":"Official Sample Exam B Q#39"},{"id":327,"chapter":6,"topic":"Herramientas de Prueba","question":"Qual das seguintes \xe9 MAIS PROV\xc1VEL de ser uma vantagem da automa\xe7\xe3o de testes?  ","options":["A) Fornece medidas de cobertura muito complicadas para que os humanos as obtenham manualmente","B) Compartilha a responsabilidade dos testes com o fornecedor da ferramenta","C) Elimina a necessidade de pensamento cr\xedtico ao analisar os resultados dos testes","D) Gera casos de teste a partir da an\xe1lise do c\xf3digo do programa"],"correctAnswer":0,"explanation":"A op\xe7\xe3o A) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra B, Q#40, LO: FL-6.2.1). Justificativa: A automa\xe7\xe3o permite obter m\xe9tricas de cobertura complexas que seriam impratic\xe1veis de serem calculadas manualmente.","source":"Official Sample Exam B Q#40"},{"id":328,"chapter":1,"topic":"Fundamentos del Testing","question":"Qual dos seguintes \xe9 um objetivo t\xedpico dos testes?  ","options":["A) Validar se os requisitos documentados s\xe3o atendidos","B) Provocar falhas e identificar defeitos","C) Iniciar erros e identificar as causas ra\xedzes","D) Verificar se o objeto de teste atende \xe0s expectativas do usu\xe1rio"],"correctAnswer":1,"explanation":"A op\xe7\xe3o B) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra C, Q#1, LO: FL-1.1.1). Justificativa: Um objetivo t\xedpico dos testes \xe9 provocar falhas para identificar defeitos no software.","source":"Official Sample Exam C Q#1"},{"id":329,"chapter":1,"topic":"Fundamentos del Testing","question":"Qual das seguintes afirma\xe7\xf5es descreve MELHOR a diferen\xe7a entre os testes e a depura\xe7\xe3o (debugging)?  ","options":["A) Os testes provocam falhas, enquanto a depura\xe7\xe3o as corrige","B) Os testes s\xe3o uma atividade negativa, enquanto a depura\xe7\xe3o \xe9 positiva","C) Os testes determinam que existem defeitos, enquanto a depura\xe7\xe3o os elimina","D) Os testes encontram a causa dos defeitos, enquanto a depura\xe7\xe3o os corrige"],"correctAnswer":2,"explanation":"A op\xe7\xe3o C) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra C, Q#2, LO: FL-1.1.2). Justificativa: Os testes determinam a exist\xeancia de defeitos (atrav\xe9s das falhas); a depura\xe7\xe3o localiza a causa raiz e a elimina.","source":"Official Sample Exam C Q#2"},{"id":330,"chapter":1,"topic":"Fundamentos del Testing","question":"A \'fal\xe1cia da aus\xeancia de defeitos\' \xe9 um dos princ\xedpios de teste. Qual das seguintes op\xe7\xf5es \xe9 um exemplo de como abordar esse princ\xedpio na pr\xe1tica?","options":["A) Explicar que n\xe3o \xe9 poss\xedvel que os testes demonstrem a aus\xeancia de defeitos","B) Apoiar os usu\xe1rios finais na realiza\xe7\xe3o de testes de aceite","C) Garantir que n\xe3o reste nenhum defeito de implementa\xe7\xe3o no sistema entregue","D) Modificar os testes que n\xe3o causam falhas para garantir que restem poucos defeitos"],"correctAnswer":1,"explanation":"A op\xe7\xe3o B) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra C, Q#3, LO: FL-1.3.1). Justificativa: Apoiar os usu\xe1rios finais nos testes de aceite garante que o sistema satisfa\xe7a suas necessidades reais, abordando a fal\xe1cia de que \'sem defeitos = sistema correto\'.","source":"Official Sample Exam C Q#3"},{"id":331,"chapter":1,"topic":"Fundamentos del Testing","question":"Quais atividades de teste s\xe3o MAIS PROV\xc1VEIS de envolver a aplica\xe7\xe3o da an\xe1lise de valor limite e parti\xe7\xe3o de equival\xeancia?","options":["A) Implementa\xe7\xe3o de teste","B) Modelagem de teste","C) Execu\xe7\xe3o de teste","D) Monitoramento de teste"],"correctAnswer":1,"explanation":"A op\xe7\xe3o B) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra C, Q#4, LO: FL-1.4.1). Justificativa: As t\xe9cnicas de modelagem de teste, como a an\xe1lise de valor limite e a parti\xe7\xe3o de equival\xeancia, s\xe3o aplicadas durante a modelagem de teste.","source":"Official Sample Exam C Q#4"},{"id":332,"chapter":1,"topic":"Fundamentos del Testing","question":"Dado o seguinte testware: Qual das seguintes op\xe7\xf5es indica MELHOR o testware produzido por cada atividade?\\n\\n1. Itens de cobertura\\n2. Solicita\xe7\xf5es de mudan\xe7a\\n3. Cronograma de execu\xe7\xe3o de teste\\n4. Condi\xe7\xf5es de teste priorizadas\\n\\nA. An\xe1lise de teste\\nB. Modelagem de teste\\nC. Implementa\xe7\xe3o de teste\\nD. Conclus\xe3o de teste","options":["A) 1B, 2D, 3C, 4A","B) 1B, 2D, 3A, 4C","C) 1D, 2C, 3A, 4B","D) 1D, 2C, 3B, 4A"],"correctAnswer":0,"explanation":"A op\xe7\xe3o A) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra C, Q#5, LO: FL-1.4.3). Justificativa: Os itens de cobertura s\xe3o produzidos na modelagem (1B), as solicita\xe7\xf5es de mudan\xe7a na conclus\xe3o (2D), o cronograma na implementa\xe7\xe3o (3C) e as condi\xe7\xf5es priorizadas na an\xe1lise (4A).","source":"Official Sample Exam C Q#5"},{"id":333,"chapter":1,"topic":"Fundamentos del Testing","question":"Qual das seguintes afirma\xe7\xf5es sobre os diferentes pap\xe9is de teste \xe9 MAIS PROVAVELMENTE CORRETA?","options":["A) No desenvolvimento de software \xe1gil, o papel de gerenciamento de teste \xe9 responsabilidade principal da equipe, enquanto o papel de teste \xe9 responsabilidade de um \xfanico indiv\xedduo externo","B) O papel de teste \xe9 principalmente respons\xe1vel pelo monitoramento e controle de teste, enquanto o papel de gerenciamento \xe9 respons\xe1vel pelo planejamento e conclus\xe3o","C) No desenvolvimento de software \xe1gil, as atividades de gerenciamento de teste que abrangem v\xe1rias equipes s\xe3o gerenciadas por um gerente de teste externo, enquanto algumas tarefas de gerenciamento s\xe3o assumidas pela pr\xf3pria equipe","D) O papel de gerenciamento de teste \xe9 principalmente respons\xe1vel pela an\xe1lise e modelagem de teste, enquanto o papel de teste \xe9 respons\xe1vel pela implementa\xe7\xe3o e execu\xe7\xe3o"],"correctAnswer":2,"explanation":"A op\xe7\xe3o C) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra C, Q#6, LO: FL-1.4.5). Justificativa: No \xc1gil, as atividades de gerenciamento que afetam v\xe1rias equipes s\xe3o coordenadas por um gerente externo, enquanto a equipe gerencia suas pr\xf3prias atividades de teste internamente.","source":"Official Sample Exam C Q#6"},{"id":334,"chapter":1,"topic":"Fundamentos del Testing","question":"Qual das seguintes afirma\xe7\xf5es sobre a independ\xeancia dos testes \xe9 CORRETA?","options":["A) Testadores independentes encontrar\xe3o defeitos gra\xe7as \xe0 sua perspectiva t\xe9cnica diferente da dos desenvolvedores, embora sua independ\xeancia possa gerar uma rela\xe7\xe3o conflituosa","B) A familiaridade dos desenvolvedores com seu pr\xf3prio c\xf3digo faz com que encontrem apenas alguns defeitos; no entanto, sua forma\xe7\xe3o semelhante \xe0 dos testadores faz com que estes tamb\xe9m os encontrariam","C) Testes independentes requerem testadores fora da equipe de desenvolvimento e idealmente de fora da organiza\xe7\xe3o, embora essas pessoas tenham dificuldade para entender o dom\xednio da aplica\xe7\xe3o","D) Testadores de fora da equipe do desenvolvedor s\xe3o mais independentes, mas os de dentro da equipe t\xeam maior probabilidade de serem culpados por atrasos na entrega"],"correctAnswer":0,"explanation":"A op\xe7\xe3o A) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra C, Q#8, LO: FL-1.5.3). Justificativa: A independ\xeancia traz uma perspectiva diferente que ajuda a encontrar mais defeitos, mas pode criar tens\xf5es com a equipe de desenvolvimento.","source":"Official Sample Exam C Q#8"},{"id":335,"chapter":2,"topic":"Testing a lo largo del SDLC","question":"Qual das seguintes op\xe7\xf5es fornece a MELHOR descri\xe7\xe3o do conceito de \'shift-left\' (deslocamento \xe0 esquerda)?","options":["A) Quando os desenvolvedores concordam, as atividades manuais do lado esquerdo do processo de teste s\xe3o automatizadas para apoiar o princ\xedpio de \'testes iniciais economizam tempo e dinheiro\'","B) Quando \xe9 rent\xe1vel, as atividades de teste s\xe3o antecipadas no SDLC para reduzir o custo total da qualidade, diminuindo o n\xfamero de defeitos encontrados nas fases finais","C) Quando t\xeam tempo livre, os testadores devem automatizar testes de regress\xe3o, come\xe7ando pelos testes de componente e de integra\xe7\xe3o de componentes","D) Quando est\xe3o dispon\xedveis, os testadores recebem treinamento para realizar tarefas no in\xedcio do SDLC e, assim, permitir a automa\xe7\xe3o de mais atividades de teste nas fases posteriores"],"correctAnswer":1,"explanation":"A op\xe7\xe3o B) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra C, Q#11, LO: FL-2.1.5). Justificativa: Shift-left envolve antecipar as atividades de teste no in\xedcio do ciclo de vida para detectar defeitos mais cedo, quando s\xe3o mais baratos para corrigir.","source":"Official Sample Exam C Q#11"},{"id":336,"chapter":2,"topic":"Testing a lo largo del SDLC","question":"Qual das seguintes op\xe7\xf5es \xe9 a que MENOS PROVAVELMENTE ocorrer\xe1 como resultado de uma retrospectiva?","options":["A) A qualidade dos futuros objetos de teste melhora ao identificar melhorias nas pr\xe1ticas de desenvolvimento","B) A efici\xeancia dos testes melhora ao agilizar a configura\xe7\xe3o dos ambientes de teste por meio de automa\xe7\xe3o","C) A compreens\xe3o dos usu\xe1rios finais sobre os processos de desenvolvimento e teste melhora","D) Os scripts de teste automatizados s\xe3o melhorados gra\xe7as ao feedback dos desenvolvedores"],"correctAnswer":2,"explanation":"A op\xe7\xe3o C) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra C, Q#12, LO: FL-2.1.6). Justificativa: As retrospectivas s\xe3o reuni\xf5es internas da equipe; n\xe3o t\xeam como objetivo melhorar a compreens\xe3o dos usu\xe1rios finais sobre os processos.","source":"Official Sample Exam C Q#12"},{"id":337,"chapter":2,"topic":"Testing a lo largo del SDLC","question":"Qual n\xedvel de teste MAIS PROVAVELMENTE est\xe1 sendo realizado se os testes est\xe3o focados na valida\xe7\xe3o e n\xe3o s\xe3o executados por testadores?","options":["A) Teste de componente","B) Teste de integra\xe7\xe3o de componentes","C) Teste de integra\xe7\xe3o de sistemas","D) Teste de aceite"],"correctAnswer":3,"explanation":"A op\xe7\xe3o D) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra C, Q#13, LO: FL-2.2.1). Justificativa: Os testes de aceite s\xe3o orientados \xe0 valida\xe7\xe3o (o sistema est\xe1 correto?) e geralmente s\xe3o realizados pelos usu\xe1rios ou clientes, n\xe3o por testadores.","source":"Official Sample Exam C Q#13"},{"id":338,"chapter":2,"topic":"Testing a lo largo del SDLC","question":"O software de um sistema de navega\xe7\xe3o foi atualizado porque sugeria rotas que infringiam as leis de tr\xe2nsito, como dirigir na contram\xe3o em ruas de sentido \xfanico. Qual das seguintes op\xe7\xf5es descreve MELHOR os testes que ser\xe3o realizados?","options":["A) Apenas testes de confirma\xe7\xe3o","B) Testes de confirma\xe7\xe3o e depois testes de regress\xe3o","C) Apenas testes de regress\xe3o","D) Testes de regress\xe3o e depois testes de confirma\xe7\xe3o"],"correctAnswer":1,"explanation":"A op\xe7\xe3o B) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra C, Q#14, LO: FL-2.2.3). Justificativa: Primeiro, faz-se o teste de confirma\xe7\xe3o para verificar se o defeito foi corrigido e, em seguida, os testes de regress\xe3o para comprovar que a corre\xe7\xe3o n\xe3o introduziu novos defeitos.","source":"Official Sample Exam C Q#14"},{"id":339,"chapter":3,"topic":"Pruebas Est\xe1ticas","question":"Dados os seguintes exemplos de defeitos:\\n\\ni. Duas partes distintas da especifica\xe7\xe3o de modelagem se contradizem devido \xe0 complexidade da modelagem\\n\\nii. Um tempo de resposta \xe9 muito longo e faz com que os usu\xe1rios percam a paci\xeancia\\n\\niii. Um caminho no c\xf3digo n\xe3o pode ser alcan\xe7ado durante a execu\xe7\xe3o\\n\\niv. Uma vari\xe1vel \xe9 declarada, mas nunca \xe9 usada no programa\\n\\nv. A quantidade de mem\xf3ria que o programa precisa para gerar um relat\xf3rio \xe9 excessiva. Qual das seguintes op\xe7\xf5es identifica MELHOR os defeitos que poderiam ser encontrados por meio de testes est\xe1ticos (em vez de din\xe2micos)?","options":["A) ii, v","B) iii, v","C) i, ii, iv","D) i, iii, iv"],"correctAnswer":3,"explanation":"A op\xe7\xe3o D) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra C, Q#15, LO: FL-3.1.3). Justificativa: Contradi\xe7\xf5es na especifica\xe7\xe3o (i), c\xf3digo inacess\xedvel (iii) e vari\xe1veis n\xe3o utilizadas (iv) s\xe3o detectados por meio de revis\xe3o ou an\xe1lise est\xe1tica sem executar o c\xf3digo.","source":"Official Sample Exam C Q#15"},{"id":340,"chapter":3,"topic":"Pruebas Est\xe1ticas","question":"Dados os seguintes tipos de revis\xe3o: Qual das seguintes op\xe7\xf5es estabelece a MELHOR correspond\xeancia?\\n\\n1. Revis\xe3o t\xe9cnica\\n2. Revis\xe3o informal\\n3. Inspe\xe7\xe3o\\n4. Walkthrough\\n\\nA. Inclui objetivos como alcan\xe7ar consenso, gerar novas ideias e motivar os autores a melhorar\\nB. Inclui objetivos como treinar os revisores, alcan\xe7ar consenso, gerar novas ideias e detectar poss\xedveis defeitos\\nC. O objetivo principal \xe9 detectar poss\xedveis defeitos e requer coleta de m\xe9tricas para a melhoria do processo\\nD. O objetivo principal \xe9 detectar poss\xedveis defeitos e n\xe3o gera documenta\xe7\xe3o formal de sa\xedda","options":["A) 1A, 2B, 3C, 4D","B) 1A, 2D, 3C, 4B","C) 1B, 2C, 3D, 4A","D) 1C, 2D, 3A, 4B"],"correctAnswer":1,"explanation":"A op\xe7\xe3o B) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra C, Q#16, LO: FL-3.2.1). Justificativa: Revis\xe3o t\xe9cnica \u2192 consenso e novas ideias (1A), Informal \u2192 sem documenta\xe7\xe3o formal (2D), Inspe\xe7\xe3o \u2192 m\xe9tricas (3C), Walkthrough \u2192 treina revisores e gera ideias (4B).","source":"Official Sample Exam C Q#17"},{"id":341,"chapter":3,"topic":"Pruebas Est\xe1ticas","question":"Qual dos seguintes \xe9 um fator que contribui para uma revis\xe3o bem-sucedida?","options":["A) Os revisores s\xe3o especialistas no dom\xednio do objeto a ser revisado","B) Os revisores fazem suas revis\xf5es em voz alta durante a reuni\xe3o de revis\xe3o","C) O autor n\xe3o participa do planejamento da revis\xe3o","D) Os participantes fazem as revis\xf5es de seus pr\xf3prios produtos de trabalho"],"correctAnswer":0,"explanation":"A op\xe7\xe3o A) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra C, Q#17, LO: FL-3.2.4). Justificativa: O fato dos revisores serem especialistas no dom\xednio garante que possam detectar defeitos relevantes.","source":"Official Sample Exam C Q#18"},{"id":342,"chapter":4,"topic":"T\xe9cnicas de An\xe1lisis y Dise\xf1o de Pruebas","question":"Qual \xe9 a PRINCIPAL diferen\xe7a entre as t\xe9cnicas de teste caixa-preta e as t\xe9cnicas baseadas em experi\xeancia?","options":["A) As t\xe9cnicas de caixa-preta usam modelos formais; as t\xe9cnicas baseadas em experi\xeancia usam o conhecimento dos testadores","B) As t\xe9cnicas de caixa-preta usam a especifica\xe7\xe3o do sistema; as t\xe9cnicas baseadas em experi\xeancia usam o conhecimento e a intui\xe7\xe3o dos testadores","C) As t\xe9cnicas de caixa-preta s\xe3o derivadas do c\xf3digo; as t\xe9cnicas baseadas em experi\xeancia s\xe3o derivadas da especifica\xe7\xe3o","D) As t\xe9cnicas de caixa-preta incluem testes explorat\xf3rios; as t\xe9cnicas baseadas em experi\xeancia incluem testes de parti\xe7\xe3o de equival\xeancia"],"correctAnswer":1,"explanation":"A op\xe7\xe3o B) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra C, Q#18, LO: FL-4.1.1). Justificativa: As t\xe9cnicas de caixa-preta s\xe3o baseadas na especifica\xe7\xe3o do sistema; as baseadas em experi\xeancia s\xe3o fundamentadas no conhecimento e na intui\xe7\xe3o do testador.","source":"Official Sample Exam C Q#19"},{"id":343,"chapter":4,"topic":"T\xe9cnicas de An\xe1lisis y Dise\xf1o de Pruebas","question":"Voc\xea est\xe1 testando um validador de PIN que aceita PINs v\xe1lidos e rejeita os inv\xe1lidos. Um PIN \xe9 uma sequ\xeancia de 4 d\xedgitos, onde cada d\xedgito est\xe1 entre 0 e 9. Voc\xea aplica a parti\xe7\xe3o de equival\xeancia ao campo \'n\xfamero de d\xedgitos do PIN\'. Quantas parti\xe7\xf5es existem no total (incluindo as v\xe1lidas e inv\xe1lidas)?","options":["A) 2","B) 3","C) 4","D) 5"],"correctAnswer":1,"explanation":"A op\xe7\xe3o B) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra C, Q#19, LO: FL-4.2.1). Justificativa: Existem 3 parti\xe7\xf5es: comprimento menor que 4 (inv\xe1lida), exatamente 4 d\xedgitos (v\xe1lida) e mais de 4 d\xedgitos (inv\xe1lida).","source":"Official Sample Exam C Q#20"},{"id":344,"chapter":4,"topic":"T\xe9cnicas de An\xe1lisis y Dise\xf1o de Pruebas","question":"Foi solicitado a um desenvolvedor que implementasse a seguinte regra de neg\xf3cio: ENTRADA: valor (n\xfamero inteiro). SE (valor > 0) E (valor \u2264 10) \u2192 A\xe7\xe3o A. SE (valor > 10) E (valor \u2264 20) \u2192 A\xe7\xe3o B. SE (valor > 20) \u2192 A\xe7\xe3o C. Quantos casos de teste s\xe3o necess\xe1rios, no m\xednimo, para atingir 100% de cobertura de desvios (branch coverage)?","options":["A) 2","B) 3","C) 4","D) 6"],"correctAnswer":2,"explanation":"A op\xe7\xe3o C) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra C, Q#20, LO: FL-4.2.2). Justificativa: S\xe3o necess\xe1rios 4 casos de teste para cobrir todos os desvios: um valor \u2264 0 (nenhuma condi\xe7\xe3o), um entre 1-10 (A\xe7\xe3o A), um entre 11-20 (A\xe7\xe3o B) e um > 20 (A\xe7\xe3o C).","source":"Official Sample Exam C Q#21"},{"id":345,"chapter":4,"topic":"T\xe9cnicas de An\xe1lisis y Dise\xf1o de Pruebas","question":"Voc\xea est\xe1 trabalhando em um projeto para desenvolver um sistema de an\xe1lise de resultados de exames de dire\xe7\xe3o. Foi solicitado que voc\xea modele casos de teste usando o teste de tabela de decis\xe3o para a seguinte regra: Um candidato \xe9 APROVADO se obtiver pelo menos 43 de 50 respostas corretas E n\xe3o cometer nenhuma falha grave. Um candidato \xe9 REPROVADO em qualquer outro caso. Quantas regras (colunas) a tabela de decis\xe3o completa ter\xe1?","options":["A) 2","B) 3","C) 4","D) 6"],"correctAnswer":2,"explanation":"A op\xe7\xe3o C) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra C, Q#21, LO: FL-4.2.3). Justificativa: Existem 2 condi\xe7\xf5es com 2 valores cada (\u2265 43/n\xe3o, sem falha grave/com falha grave), o que resulta em 4 combina\xe7\xf5es (regras).","source":"Official Sample Exam C Q#22"},{"id":346,"chapter":4,"topic":"T\xe9cnicas de An\xe1lisis y Dise\xf1o de Pruebas","question":"Voc\xea est\xe1 modelando casos de teste baseando-se em um diagrama de transi\xe7\xe3o de estados. Qual \xe9 o n\xfamero M\xcdNIMO de casos de teste necess\xe1rios para alcan\xe7ar a cobertura de todas as transi\xe7\xf5es v\xe1lidas (100%)?","options":["A) 2","B) 3","C) 4","D) 5"],"correctAnswer":1,"explanation":"A op\xe7\xe3o B) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra C, Q#23, LO: FL-4.2.4). Justificativa: O n\xfamero m\xednimo de casos de teste para cobertura das transi\xe7\xf5es v\xe1lidas depende do diagrama; neste caso, 3 casos cobrem todas as transi\xe7\xf5es.","source":"Official Sample Exam C Q#23"},{"id":347,"chapter":4,"topic":"T\xe9cnicas de An\xe1lisis y Dise\xf1o de Pruebas","question":"Voc\xea deseja aplicar testes de desvios ao c\xf3digo representado pelo seguinte grafo de fluxo de controle. Quantos casos de teste s\xe3o necess\xe1rios, no M\xcdNIMO, para atingir 100% de cobertura de desvios?","options":["A) 1","B) 2","C) 3","D) 4"],"correctAnswer":1,"explanation":"A op\xe7\xe3o B) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra C, Q#25, LO: FL-4.3.2). Justificativa: Para o grafo de fluxo de controle fornecido, s\xe3o necess\xe1rios 2 casos de teste para cobrir todos os desvios (TRUE e FALSE de cada decis\xe3o).","source":"Official Sample Exam C Q#24"},{"id":348,"chapter":4,"topic":"T\xe9cnicas de An\xe1lisis y Dise\xf1o de Pruebas","question":"Como os testes de caixa-branca podem ser \xfateis como suporte para os testes de caixa-preta?","options":["A) Podem ser usados para verificar se todos os requisitos est\xe3o implementados no c\xf3digo","B) Podem ser usados para criar casos de teste que cubram o c\xf3digo que os casos de caixa-preta n\xe3o executam","C) Podem ser usados para avaliar se a especifica\xe7\xe3o reflete corretamente a l\xf3gica de neg\xf3cio do sistema","D) Podem ser usados para evitar a cria\xe7\xe3o de casos de teste redundantes com os de caixa-preta"],"correctAnswer":1,"explanation":"A op\xe7\xe3o B) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra C, Q#26, LO: FL-4.3.2). Justificativa: Os testes de caixa-branca podem identificar e cobrir c\xf3digos que os casos de caixa-preta n\xe3o exercitam, complementando assim a cobertura.","source":"Official Sample Exam C Q#25"},{"id":349,"chapter":4,"topic":"T\xe9cnicas de An\xe1lisis y Dise\xf1o de Pruebas","question":"Considere a seguinte lista de poss\xedveis defeitos: \u2022 Entrada correta n\xe3o aceita \u2022 Entrada incorreta aceita \u2022 Sa\xedda incorreta produzida \u2022 Funcionalidade omitida. Qual das seguintes t\xe9cnicas de teste foi projetada ESPECIFICAMENTE para detectar todos esses tipos de defeitos?","options":["A) Testes de parti\xe7\xe3o de equival\xeancia","B) Testes de tabela de decis\xe3o","C) Testes de transi\xe7\xe3o de estados","D) Testes de an\xe1lise de valor limite"],"correctAnswer":0,"explanation":"A op\xe7\xe3o A) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra C, Q#27, LO: FL-4.4.1). Justificativa: A parti\xe7\xe3o de equival\xeancia \xe9 especificamente projetada para detectar esses tipos de defeitos, testando valores representativos de cada parti\xe7\xe3o.","source":"Official Sample Exam C Q#26"},{"id":350,"chapter":4,"topic":"T\xe9cnicas de An\xe1lisis y Dise\xf1o de Pruebas","question":"Qual das seguintes op\xe7\xf5es descreve MELHOR como o uso de testes baseados em checklist pode resultar em uma maior cobertura em compara\xe7\xe3o com os testes de especifica\xe7\xe3o sem checklist?","options":["A) Os checklists incluem itens baseados na experi\xeancia de defeitos do passado, o que ajuda a detectar mais defeitos","B) Os checklists s\xe3o documentos formais gerados automaticamente por ferramentas de an\xe1lise est\xe1tica","C) Os checklists permitem que o testador cubra mais condi\xe7\xf5es de teste sem necessidade de especifica\xe7\xe3o","D) Os checklists garantem 100% de cobertura de desvios do c\xf3digo"],"correctAnswer":0,"explanation":"A op\xe7\xe3o A) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra C, Q#28, LO: FL-4.4.3). Justificativa: Os checklists incorporam experi\xeancia de projetos anteriores, o que permite detectar defeitos que as especifica\xe7\xf5es formais n\xe3o contemplam explicitamente.","source":"Official Sample Exam C Q#27"},{"id":351,"chapter":4,"topic":"T\xe9cnicas de An\xe1lisis y Dise\xf1o de Pruebas","question":"Qual das seguintes op\xe7\xf5es fornece o MELHOR exemplo de um crit\xe9rio de aceite orientado a cen\xe1rio?","options":["A) O sistema deve exibir uma mensagem de erro se o nome de usu\xe1rio exceder 50 caracteres","B) DADO QUE um cliente fez login, QUANDO ele clica em \'Realizar pedido\', ENT\xc3O o sistema exibe uma confirma\xe7\xe3o do pedido","C) O tempo de resposta do sistema n\xe3o deve exceder 2 segundos em 95% das solicita\xe7\xf5es","D) O campo de senha deve aceitar entre 8 e 20 caracteres alfanum\xe9ricos"],"correctAnswer":1,"explanation":"A op\xe7\xe3o B) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra C, Q#29, LO: FL-4.5.2). Justificativa: O formato DADO/QUANDO/ENT\xc3O (Given/When/Then) \xe9 o formato orientado a cen\xe1rios t\xedpico de BDD (Desenvolvimento Orientado a Comportamento).","source":"Official Sample Exam C Q#28"},{"id":352,"chapter":4,"topic":"T\xe9cnicas de An\xe1lisis y Dise\xf1o de Pruebas","question":"Voc\xea est\xe1 usando o desenvolvimento orientado a testes de aceite (ATDD) e modelando casos de teste com base na seguinte hist\xf3ria de usu\xe1rio: \'Como um usu\xe1rio registrado, quero poder alterar minha senha para manter minha conta segura.\' Qual dos seguintes casos de teste N\xc3O \xe9 relevante para esta hist\xf3ria de usu\xe1rio?","options":["A) Verificar se o usu\xe1rio pode alterar sua senha inserindo a senha atual correta e uma nova senha v\xe1lida","B) Verificar se o sistema rejeita a altera\xe7\xe3o se a senha atual inserida estiver incorreta","C) Verificar se o sistema envia um e-mail de confirma\xe7\xe3o ao usu\xe1rio ap\xf3s a altera\xe7\xe3o da senha","D) Verificar se um usu\xe1rio n\xe3o registrado pode redefinir sua senha atrav\xe9s do link \'esqueci minha senha\'"],"correctAnswer":3,"explanation":"A op\xe7\xe3o D) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra C, Q#30, LO: FL-4.5.3). Justificativa: A hist\xf3ria de usu\xe1rio trata da altera\xe7\xe3o da senha de um usu\xe1rio J\xc1 registrado, n\xe3o da redefini\xe7\xe3o de senhas de usu\xe1rios n\xe3o registrados.","source":"Official Sample Exam C Q#29"},{"id":353,"chapter":5,"topic":"Gesti\xf3n de las Actividades de Prueba","question":"Qual das seguintes op\xe7\xf5es N\xc3O \xe9 uma finalidade de um plano de teste?","options":["A) Documentar os meios e o cronograma das atividades de teste","B) Servir como meio de comunica\xe7\xe3o entre os membros da equipe de teste","C) Registrar os defeitos encontrados durante a execu\xe7\xe3o dos testes","D) Documentar os riscos e as abordagens de mitiga\xe7\xe3o"],"correctAnswer":2,"explanation":"A op\xe7\xe3o C) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra D, Q#1, LO: FL-5.1.1). Justificativa: O registro de defeitos \xe9 responsabilidade do sistema de gerenciamento de defeitos, n\xe3o do plano de teste.","source":"Official Sample Exam C Q#30"},{"id":354,"chapter":5,"topic":"Gesti\xf3n de las Actividades de Prueba","question":"No in\xedcio de cada itera\xe7\xe3o, a equipe estima a quantidade de trabalho (em pessoas-dia) que pode concluir durante aquela itera\xe7\xe3o. Ao final da itera\xe7\xe3o, o trabalho real conclu\xeddo \xe9 medido. Com o tempo, os dados hist\xf3ricos mostram que a equipe conclui, em m\xe9dia, 80% do trabalho estimado. Se na pr\xf3xima itera\xe7\xe3o a equipe estimar 50 pessoas-dia de trabalho, quantos pessoas-dia o gerente de teste deve planejar como esfor\xe7o real?","options":["A) 40","B) 50","C) 62","D) 63"],"correctAnswer":0,"explanation":"A op\xe7\xe3o A) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra D, Q#2, LO: FL-5.1.4). Justificativa: Se historicamente conclui-se 80% da estimativa, a estimativa real seria de 50 \xd7 0,80 = 40 pessoas-dia.","source":"Official Sample Exam C Q#31"},{"id":355,"chapter":5,"topic":"Gesti\xf3n de las Actividades de Prueba","question":"Voc\xea est\xe1 preparando um cronograma de execu\xe7\xe3o de testes para 7 casos de teste (TC1-TC7).\\n\\nAs depend\xeancias s\xe3o:\\n- TC2 depende de TC1\\n- TC4 depende de TC2 e TC3\\n- TC5 depende de TC3\\n- TC6 depende de TC4 e TC5\\n- TC7 depende de TC6\\n\\nAs prioridades (1=maior) s\xe3o: TC1-p3, TC2-p5, TC3-p1, TC4-p4, TC5-p2, TC6-p6, TC7-p7.\\n\\nQual \xe9 a ordem correta de execu\xe7\xe3o respeitando as depend\xeancias e prioridades?","options":["A) TC3, TC5, TC1, TC2, TC4, TC6, TC7","B) TC1, TC2, TC3, TC4, TC5, TC6, TC7","C) TC3, TC1, TC5, TC2, TC4, TC6, TC7","D) TC1, TC3, TC2, TC5, TC4, TC6, TC7"],"correctAnswer":2,"explanation":"A op\xe7\xe3o C) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra D, Q#3, LO: FL-5.1.5). Justificativa: TC3 tem a maior prioridade (p1) e n\xe3o possui depend\xeancias, portanto, \xe9 o primeiro. Em seguida, TC1 (p3, sem depend\xeancias), depois TC5 (depende de TC3), etc.","source":"Official Sample Exam C Q#32"},{"id":356,"chapter":5,"topic":"Gesti\xf3n de las Actividades de Prueba","question":"O que o modelo da pir\xe2mide de teste demonstra?","options":["A) Os diferentes n\xedveis de teste e os tipos de defeitos mais prov\xe1veis em cada n\xedvel","B) O n\xfamero relativo de testes recomendados em cada n\xedvel de teste, com mais testes nos n\xedveis inferiores","C) O custo relativo de encontrar e corrigir defeitos em cada n\xedvel de teste","D) A sequ\xeancia recomendada em que os diferentes n\xedveis de teste devem ser executados"],"correctAnswer":1,"explanation":"A op\xe7\xe3o B) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra D, Q#4, LO: FL-5.1.7). Justificativa: A pir\xe2mide de teste mostra que deve haver muitos testes de componente (base) e poucos testes de sistema ou E2E (topo), pois os n\xedveis inferiores s\xe3o mais r\xe1pidos e baratos.","source":"Official Sample Exam C Q#33"},{"id":357,"chapter":5,"topic":"Gesti\xf3n de las Actividades de Prueba","question":"Qual \xe9 a rela\xe7\xe3o entre os quadrantes de teste, os n\xedveis de teste e os tipos de teste?","options":["A) Os quadrantes de teste incluem os n\xedveis de teste; os tipos de teste ajudam a identificar quais quadrantes de teste se aplicam a cada n\xedvel","B) Os tipos de teste ajudam a identificar quais quadrantes de teste se aplicam; os quadrantes de teste ajudam a identificar quais n\xedveis de teste devem ser usados","C) Os quadrantes de teste ajudam a identificar quais tipos de teste se aplicam a cada n\xedvel; os tipos de teste podem abranger v\xe1rios n\xedveis","D) Os n\xedveis de teste s\xe3o subconjuntos dos quadrantes de teste; os quadrantes de teste s\xe3o subconjuntos dos tipos de teste"],"correctAnswer":2,"explanation":"A op\xe7\xe3o C) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra D, Q#5, LO: FL-5.1.7). Justificativa: Os quadrantes de teste ajudam a identificar quais tipos de teste (funcional, n\xe3o funcional, caixa-branca, etc.) s\xe3o aplic\xe1veis em cada n\xedvel de teste.","source":"Official Sample Exam C Q#34"},{"id":358,"chapter":5,"topic":"Gesti\xf3n de las Actividades de Prueba","question":"Qual das seguintes op\xe7\xf5es \xe9 um exemplo de como a an\xe1lise de risco de produto pode influenciar a abrang\xeancia e o foco dos testes?","options":["A) Aumentar a cobertura de testes das funcionalidades de maior risco","B) Priorizar os testes das funcionalidades implementadas recentemente em vez das mais antigas","C) Executar primeiro os testes de menor dura\xe7\xe3o para obter resultados r\xe1pidos","D) Concentrar o esfor\xe7o de teste nos componentes desenvolvidos por testadores menos experientes"],"correctAnswer":0,"explanation":"A op\xe7\xe3o A) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra D, Q#6, LO: FL-5.2.3). Justificativa: A an\xe1lise de risco direciona o esfor\xe7o de teste para as \xe1reas de maior risco, aumentando sua cobertura.","source":"Official Sample Exam C Q#35"},{"id":359,"chapter":5,"topic":"Gesti\xf3n de las Actividades de Prueba","question":"Qual das seguintes atividades do processo de teste faz MAIOR USO dos relat\xf3rios de progresso do teste?","options":["A) Planejamento de teste","B) Monitoramento e controle de teste","C) An\xe1lise de teste","D) Modelagem de teste"],"correctAnswer":1,"explanation":"A op\xe7\xe3o B) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra D, Q#7, LO: FL-5.3.2). Justificativa: O monitoramento e o controle de teste utilizam os relat\xf3rios de progresso para comparar o avan\xe7o real com o planejado e tomar decis\xf5es corretivas.","source":"Official Sample Exam C Q#36"},{"id":360,"chapter":5,"topic":"Gesti\xf3n de las Actividades de Prueba","question":"Qual das seguintes op\xe7\xf5es N\xc3O \xe9 um exemplo de como a ger\xeancia de configura\xe7\xe3o (CM) apoia os testes?","options":["A) Manter um registro dos itens de configura\xe7\xe3o que comp\xf5em o ambiente de teste","B) Gerar automaticamente casos de teste adicionais quando s\xe3o detectados defeitos no software","C) Permitir a rastreabilidade entre os casos de teste e os itens de trabalho que eles testam","D) Garantir que todos os membros da equipe utilizem a mesma vers\xe3o dos casos de teste"],"correctAnswer":1,"explanation":"A op\xe7\xe3o B) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra D, Q#8, LO: FL-5.4.1). Justificativa: A gera\xe7\xe3o autom\xe1tica de casos de teste n\xe3o \xe9 uma fun\xe7\xe3o da ger\xeancia de configura\xe7\xe3o.","source":"Official Sample Exam C Q#37"},{"id":361,"chapter":5,"topic":"Gesti\xf3n de las Actividades de Prueba","question":"Considere o seguinte relat\xf3rio de defeito para uma aplica\xe7\xe3o web de compras: Aplica\xe7\xe3o: WebShop v0.9.1. M\xf3dulo: Carrinho de compras. Resumo: \'O bot\xe3o Remover do carrinho n\xe3o funciona quando h\xe1 exatamente 1 item\'. Passos:\\n\\n1) Fazer login\\n\\n2) Adicionar 1 item ao carrinho\\n\\n3) Clicar em Remover. Resultado esperado: O item \xe9 removido e o carrinho fica vazio. Resultado real: Nada acontece. Qual dos seguintes elementos est\xe1 AUSENTE neste relat\xf3rio de defeito?","options":["A) O identificador do caso de teste que revelou o defeito","B) Os dados de ambiente/configura\xe7\xe3o do sistema","C) A severidade do defeito","D) A prioridade do defeito"],"correctAnswer":1,"explanation":"A op\xe7\xe3o B) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra D, Q#9, LO: FL-5.5.1). Justificativa: O relat\xf3rio n\xe3o especifica a vers\xe3o do sistema operacional, navegador ou outros dados do ambiente necess\xe1rios para reproduzir o defeito.","source":"Official Sample Exam C Q#38"},{"id":362,"chapter":6,"topic":"Herramientas de Prueba","question":"Ferramentas de qual categoria ajudam a organizar os casos de teste, os defeitos encontrados e os resultados dos testes?","options":["A) Ferramentas de gerenciamento de teste","B) Ferramentas de an\xe1lise est\xe1tica","C) Ferramentas de execu\xe7\xe3o de teste","D) Ferramentas de automa\xe7\xe3o de teste"],"correctAnswer":0,"explanation":"A op\xe7\xe3o A) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra D, Q#10, LO: FL-6.1.1). Justificativa: As ferramentas de gerenciamento de teste (como Jira, TestRail) organizam e rastreiam casos de teste, defeitos e resultados.","source":"Official Sample Exam C Q#39"},{"id":363,"chapter":1,"topic":"Fundamentos del Testing","question":"Um designer documenta uma modelagem para uma interface de usu\xe1rio que n\xe3o atende adequadamente usu\xe1rios com defici\xeancia visual porque ele n\xe3o estava ciente dos requisitos de acessibilidade. Como isso \xe9 classificado segundo a terminologia do ISTQB?","options":["A) O designer cometeu uma falha que introduziu um erro na modelagem","B) O designer cometeu um erro (engano) que introduziu um defeito na modelagem","C) O designer cometeu um defeito que resultou em uma falha na modelagem","D) O designer cometeu um erro (engano) que introduziu uma falha na modelagem"],"correctAnswer":1,"explanation":"A op\xe7\xe3o B) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra D, Q#1, LO: FL-1.2.2). Justificativa: O desconhecimento do designer (erro humano) resulta em um defeito no documento de modelagem. Terminologia: Erro \u2192 Defeito \u2192 Falha.","source":"Official Sample Exam D Q#2"},{"id":364,"chapter":1,"topic":"Fundamentos del Testing","question":"Os testadores usam condi\xe7\xf5es de teste para derivar casos de teste e executar testes. Embora as condi\xe7\xf5es de teste permane\xe7am as mesmas, os casos de teste variam a cada ocasi\xe3o. Qual dos \'princ\xedpios de teste\' est\xe1 sendo aplicado atrav\xe9s da varia\xe7\xe3o dos casos de teste?","options":["A) Os testes se desgastam (paradoxo do pesticida)","B) A fal\xe1cia da aus\xeancia de defeitos","C) Testes iniciais economizam tempo e dinheiro","D) Os defeitos se agrupam"],"correctAnswer":0,"explanation":"A op\xe7\xe3o A) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra D, Q#3, LO: FL-1.3.1). Justificativa: O paradoxo do pesticida (ou \'os testes se desgastam\') indica que repetir os mesmos casos de teste deixa de detectar novos defeitos, e por isso \xe9 necess\xe1rio vari\xe1-los.","source":"Official Sample Exam D Q#3"},{"id":365,"chapter":1,"topic":"Fundamentos del Testing","question":"Dado o seguinte testware:\\n\\ni. Relat\xf3rio de conclus\xe3o de teste\\n\\nii. Dados em um banco de dados usados como entradas e resultados esperados\\n\\niii. Lista de itens necess\xe1rios para construir o ambiente de teste\\n\\niv. Sequ\xeancias documentadas de casos de teste em ordem de execu\xe7\xe3o\\n\\nv. Casos de teste. Qual das seguintes op\xe7\xf5es indica MELHOR o testware produzido como resultado da realiza\xe7\xe3o da implementa\xe7\xe3o de teste?","options":["A) ii, iv","B) iii, v","C) i, ii, v","D) i, iii, iv"],"correctAnswer":0,"explanation":"A op\xe7\xe3o A) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra D, Q#5, LO: FL-1.4.3). Justificativa: Durante a implementa\xe7\xe3o de teste s\xe3o criados os dados de teste (ii) e as sequ\xeancias de execu\xe7\xe3o/su\xedtes de teste (iv).","source":"Official Sample Exam D Q#5"},{"id":366,"chapter":1,"topic":"Fundamentos del Testing","question":"Qual das seguintes op\xe7\xf5es descreve MAIS PROVAVELMENTE uma tarefa realizada por algu\xe9m em um papel de gerenciamento de teste?","options":["A) Avaliar a base de teste e o objeto de teste","B) Definir os requisitos do ambiente de teste","C) Avaliar a testabilidade do objeto de teste","D) Criar o relat\xf3rio de conclus\xe3o de teste"],"correctAnswer":3,"explanation":"A op\xe7\xe3o D) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra D, Q#6, LO: FL-1.4.5). Justificativa: Criar o relat\xf3rio de conclus\xe3o de teste \xe9 uma tarefa de encerramento do processo, tipicamente responsabilidade do gerente de teste.","source":"Official Sample Exam D Q#6"},{"id":367,"chapter":1,"topic":"Fundamentos del Testing","question":"Qual das seguintes \xe9 uma vantagem da abordagem de equipe inteira (whole-team approach)?","options":["A) Melhora a comunica\xe7\xe3o entre os membros da equipe","B) Diminui a responsabilidade individual pela qualidade","C) Acelera a implanta\xe7\xe3o de entreg\xe1veis para os usu\xe1rios finais","D) Reduz a colabora\xe7\xe3o com usu\xe1rios de neg\xf3cios externos"],"correctAnswer":0,"explanation":"A op\xe7\xe3o A) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra D, Q#7, LO: FL-1.5.2). Justificativa: A abordagem de equipe inteira promove a colabora\xe7\xe3o entre todos os membros da equipe, melhorando a comunica\xe7\xe3o.","source":"Official Sample Exam D Q#7"},{"id":368,"chapter":1,"topic":"Fundamentos del Testing","question":"Dados os seguintes benef\xedcios e desvantagens da independ\xeancia dos testes:\\n\\ni. Os testadores trabalham em um local diferente dos desenvolvedores\\n\\nii. Os testadores questionam as suposi\xe7\xf5es que os programadores fazem ao escrever o c\xf3digo\\n\\niii. Estabeleceu-se uma din\xe2mica de confronto entre testadores e desenvolvedores\\n\\niv. Os desenvolvedores se convenceram de que os testadores s\xe3o os principais respons\xe1veis pela qualidade\\n\\nv. Os testadores t\xeam vieses diferentes dos desenvolvedores. Quais s\xe3o MAIS PROVAVELMENTE considerados benef\xedcios?","options":["A) i, iv","B) ii, v","C) i, iii, iv","D) ii, iii, v"],"correctAnswer":1,"explanation":"A op\xe7\xe3o B) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra D, Q#8, LO: FL-1.5.3). Justificativa: Questionar as suposi\xe7\xf5es (ii) e ter vieses distintos (v) s\xe3o benef\xedcios da independ\xeancia; os demais s\xe3o desvantagens ou consequ\xeancias negativas.","source":"Official Sample Exam D Q#8"},{"id":369,"chapter":2,"topic":"Testing a lo largo del SDLC","question":"Qual das seguintes op\xe7\xf5es \xe9 MAIS PROVAVELMENTE um desafio ao implementar DevOps?","options":["A) Garantir que as caracter\xedsticas de qualidade n\xe3o funcionais n\xe3o sejam negligenciadas","B) Gerenciar ambientes de teste que mudam continuamente","C) A necessidade de mais testadores manuais com experi\xeancia adequada","D) Configurar a automa\xe7\xe3o de testes como parte do pipeline de entrega"],"correctAnswer":3,"explanation":"A op\xe7\xe3o D) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra D, Q#11, LO: FL-2.1.4). Justificativa: Configurar e integrar a automa\xe7\xe3o de testes no pipeline de entrega cont\xednua \xe9 um dos maiores desafios ao adotar DevOps.","source":"Official Sample Exam D Q#11"},{"id":370,"chapter":2,"topic":"Testing a lo largo del SDLC","question":"Qual das seguintes alternativas descreve MELHOR as retrospectivas?","options":["A) As retrospectivas permitem aos membros da equipe identificar outros membros que n\xe3o contribu\xedram suficientemente para a qualidade de acordo com a abordagem de toda a equipe (whole team)","B) As retrospectivas d\xe3o aos testadores a oportunidade de identificar atividades que foram bem-sucedidas para mant\xea-las quando melhorias forem feitas no futuro","C) As retrospectivas s\xe3o onde os membros da equipe \xe1gil podem expressar suas preocupa\xe7\xf5es sobre a gest\xe3o e os clientes em um ambiente sem culpa","D) As retrospectivas d\xe3o aos membros da equipe \xe1gil um f\xf3rum para debater o plano e as decis\xf5es t\xe9cnicas da pr\xf3xima itera\xe7\xe3o"],"correctAnswer":1,"explanation":"A op\xe7\xe3o B) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra D, Q#12, LO: FL-2.1.6). Justificativa: As retrospectivas servem para identificar o que funcionou bem (para mant\xea-lo) e o que pode ser melhorado no pr\xf3ximo ciclo.","source":"Official Sample Exam D Q#12"},{"id":371,"chapter":2,"topic":"Testing a lo largo del SDLC","question":"Qual dos seguintes testes \xe9 MAIS PROV\xc1VEL de ser realizado como parte dos testes funcionais?","options":["A) O teste verifica se a fun\xe7\xe3o de ordena\xe7\xe3o coloca os elementos da lista em ordem crescente","B) O teste verifica se a fun\xe7\xe3o de ordena\xe7\xe3o conclui o processo em menos de um segundo","C) O teste verifica com que facilidade a fun\xe7\xe3o de ordena\xe7\xe3o pode ser alterada de crescente para decrescente","D) O teste verifica se a fun\xe7\xe3o de ordena\xe7\xe3o continua funcionando corretamente ao migrar de uma arquitetura de 32 para 64 bits"],"correctAnswer":0,"explanation":"A op\xe7\xe3o A) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra D, Q#13, LO: FL-2.2.2). Justificativa: Verificar se a fun\xe7\xe3o de ordena\xe7\xe3o faz o que deve fazer (ordenar corretamente) \xe9 um teste funcional; as outras op\xe7\xf5es s\xe3o n\xe3o funcionais.","source":"Official Sample Exam D Q#13"},{"id":372,"chapter":2,"topic":"Testing a lo largo del SDLC","question":"Qual dos seguintes \xe9 MAIS PROV\xc1VEL de ser o gatilho que leva \xe0 realiza\xe7\xe3o de testes de manuten\xe7\xe3o em um sistema de c\xe2mbio de moedas?","options":["A) Os desenvolvedores relataram que modificar o sistema era dif\xedcil e os testadores decidiram verificar se isso era verdade","B) A op\xe7\xe3o de reembolso foi removida do sistema porque nem sempre devolvia o valor correto aos clientes","C) A equipe \xe1gil come\xe7ou a desenvolver uma hist\xf3ria de usu\xe1rio que adiciona uma funcionalidade de fidelidade do cliente","D) A op\xe7\xe3o de suporte a idiomas do sistema foi usada para habilitar transa\xe7\xf5es em ingl\xeas e no idioma local"],"correctAnswer":1,"explanation":"A op\xe7\xe3o B) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra D, Q#14, LO: FL-2.3.1). Justificativa: Remover uma funcionalidade defeituosa do sistema em produ\xe7\xe3o \xe9 um gatilho cl\xe1ssico para testes de manuten\xe7\xe3o.","source":"Official Sample Exam D Q#14"},{"id":373,"chapter":3,"topic":"Pruebas Est\xe1ticas","question":"Qual dos seguintes N\xc3O pode ser examinado por meio de testes est\xe1ticos?","options":["A) Contrato","B) Plano de teste","C) C\xf3digo criptografado","D) Carta de teste (test charter)"],"correctAnswer":2,"explanation":"A op\xe7\xe3o C) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra D, Q#15, LO: FL-3.1.1). Justificativa: O c\xf3digo criptografado n\xe3o pode ser analisado estaticamente porque seu conte\xfado \xe9 ileg\xedvel para ferramentas de an\xe1lise est\xe1tica e revisores.","source":"Official Sample Exam D Q#15"},{"id":374,"chapter":3,"topic":"Pruebas Est\xe1ticas","question":"Qual das seguintes afirma\xe7\xf5es sobre o valor dos testes est\xe1ticos \xe9 CORRETA?","options":["A) Os tipos de defeitos que os testes est\xe1ticos encontram s\xe3o diferentes daqueles que os testes din\xe2micos podem encontrar","B) Os testes din\xe2micos podem detectar os tipos de defeitos que os testes est\xe1ticos encontram, mais alguns adicionais","C) Os testes din\xe2micos podem identificar alguns dos defeitos que os testes est\xe1ticos encontram, mas n\xe3o todos","D) Os testes est\xe1ticos podem identificar os tipos de defeitos que os testes din\xe2micos encontram, al\xe9m de alguns adicionais"],"correctAnswer":2,"explanation":"A op\xe7\xe3o C) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra D, Q#16, LO: FL-3.1.2). Justificativa: Os testes din\xe2micos n\xe3o podem encontrar defeitos como c\xf3digo inating\xedvel, vari\xe1veis n\xe3o utilizadas ou inconsist\xeancias na documenta\xe7\xe3o que apenas os testes est\xe1ticos detectam.","source":"Official Sample Exam D Q#16"},{"id":375,"chapter":3,"topic":"Pruebas Est\xe1ticas","question":"Dadas as seguintes descri\xe7\xf5es de atividades de revis\xe3o:  \\n  \\n1. As anomalias detectadas s\xe3o debatidas e decis\xf5es s\xe3o tomadas sobre seu status, propriet\xe1rio e pr\xf3ximos passos  \\n  \\n2. Os defeitos s\xe3o registrados e as atualiza\xe7\xf5es necess\xe1rias s\xe3o tratadas antes da aceita\xe7\xe3o do produto de trabalho  \\n  \\n3. Os revisores empregam t\xe9cnicas para gerar sugest\xf5es e perguntas sobre o produto de trabalho e identificar anomalias  \\n  \\n4. O objetivo da revis\xe3o e seu cronograma s\xe3o estabelecidos para garantir uma revis\xe3o focada e eficiente  \\n  \\n5. Os participantes recebem acesso ao item a ser revisado. Qual \xe9 a sequ\xeancia CORRETA das atividades do processo de revis\xe3o?","options":["A) 4 \u2013 3 \u2013 5 \u2013 2 \u2013 1","B) 4 \u2013 5 \u2013 3 \u2013 1 \u2013 2","C) 5 \u2013 4 \u2013 1 \u2013 3 \u2013 2","D) 5 \u2013 4 \u2013 3 \u2013 2 \u2013 1"],"correctAnswer":1,"explanation":"A op\xe7\xe3o B) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra D, Q#17, LO: FL-3.2.2). Justificativa: Sequ\xeancia correta: Planejamento (4) \u2192 In\xedcio da revis\xe3o/acesso (5) \u2192 Revis\xe3o individual (3) \u2192 Comunica\xe7\xe3o e an\xe1lise (1) \u2192 Corre\xe7\xe3o e relat\xf3rio (2).","source":"Official Sample Exam D Q#17"},{"id":376,"chapter":3,"topic":"Pruebas Est\xe1ticas","question":"Qual participante no processo de revis\xe3o \xe9 respons\xe1vel por garantir que as reuni\xf5es de revis\xe3o ocorram de forma eficaz e que todos possam expressar suas opini\xf5es livremente?","options":["A) Gerente","B) Moderador","C) Presidente (Chairman)","D) L\xedder de Revis\xe3o"],"correctAnswer":1,"explanation":"A op\xe7\xe3o B) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra D, Q#18, LO: FL-3.2.3). Justificativa: Moderador","source":"Official Sample Exam D Q#18"},{"id":377,"chapter":4,"topic":"T\xe9cnicas de An\xe1lisis y Dise\xf1o de Pruebas","question":"Voc\xea realiza testes de sistema em uma aplica\xe7\xe3o web de com\xe9rcio eletr\xf4nico e \xe9 fornecido o seguinte requisito: REQ 05-017. Se o custo total das compras exceder US$ 100, o cliente obt\xe9m um desconto de 5% em compras subsequentes. Caso contr\xe1rio, o cliente n\xe3o recebe nenhum desconto. Quais t\xe9cnicas de teste ser\xe3o MAIS \xfateis para projetar casos de teste com base neste requisito?","options":["A) T\xe9cnicas de teste de caixa branca","B) T\xe9cnicas de teste de caixa preta","C) T\xe9cnicas baseadas na experi\xeancia","D) T\xe9cnicas de teste baseadas em risco"],"correctAnswer":1,"explanation":"A op\xe7\xe3o B) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra D, Q#19, LO: FL-4.1.1). Justificativa: T\xe9cnicas de teste de caixa preta","source":"Official Sample Exam D Q#19"},{"id":378,"chapter":4,"topic":"T\xe9cnicas de An\xe1lisis y Dise\xf1o de Pruebas","question":"O sistema de venda de ingressos de cinema calcula o tipo de desconto com base no ano de nascimento (AN) do cliente e no ano atual (AA) da seguinte forma: Seja D a diferen\xe7a entre AA e AN, ou seja, D = AA \u2013 AN. \u2022 Se D < 0, exibe o erro \'o ano de nascimento n\xe3o pode ser maior que o ano atual\'. \u2022 Se 0 \u2264 D < 18, aplica o desconto de estudante. \u2022 Se 18 \u2264 D < 65, n\xe3o aplica nenhum desconto. \u2022 Se D \u2265 65, aplica o desconto de idoso. Seu conjunto de testes j\xe1 cont\xe9m dois casos: \u2022 AN = 1990, AA = 2020, resultado esperado: nenhum desconto. \u2022 AN = 2030, AA = 2029, resultado esperado: exibir erro. Qual dos seguintes conjuntos de dados de teste deve ser adicionado para obter uma cobertura completa de parti\xe7\xe3o de equival\xeancia v\xe1lida para o tipo de desconto?","options":["A) AN = 2001, AA = 2065","B) AN = 1900, AA = 1965","C) AN = 1965, AA = 1900","D) AN = 2011, AA = 2029"],"correctAnswer":1,"explanation":"A op\xe7\xe3o B) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra D, Q#20, LO: FL-4.2.1). Justificativa: AN = 1900, AA = 1965","source":"Official Sample Exam D Q#20"},{"id":379,"chapter":4,"topic":"T\xe9cnicas de An\xe1lisis y Dise\xf1o de Pruebas","question":"Voc\xea est\xe1 testando um sistema de controle de temperatura para uma instala\xe7\xe3o de armazenamento a frio. O sistema recebe a temperatura (em graus Celsius inteiros) como entrada. Se a temperatura estiver entre 0 e 2 graus inclusive, exibe \'temperatura OK\'. Para temperaturas mais baixas, exibe \'temperatura muito baixa\' e para mais altas \'temperatura muito alta\'. Usando a an\xe1lise de valores limite de dois valores, qual dos seguintes conjuntos fornece o maior n\xedvel de cobertura de valores limite?","options":["A) \u20131, 3","B) 0, 2","C) \u20131, 0, 2, 3","D) \u20132, 0, 2, 4"],"correctAnswer":2,"explanation":"A op\xe7\xe3o C) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra D, Q#21, LO: FL-4.2.2). Justificativa: \u20131, 0, 2, 3","source":"Official Sample Exam D Q#21"},{"id":380,"chapter":4,"topic":"T\xe9cnicas de An\xe1lisis y Dise\xf1o de Pruebas","question":"Voc\xea est\xe1 projetando casos de teste com base em uma tabela de decis\xe3o de idades e experi\xeancia. At\xe9 agora, voc\xea projetou 4 casos de teste. Qual dos seguintes casos de teste, quando adicionado ao conjunto existente, aumentar\xe1 a cobertura da tabela de decis\xe3o?","options":["A) Homem de 66 anos, n\xe3o registrado, sem experi\xeancia; resultado esperado: categoria B","B) Mulher de 55 anos, n\xe3o registrada, com 2 anos de experi\xeancia; resultado esperado: categoria A","C) Mulher de 19 anos, registrada, com 5 anos de experi\xeancia; resultado esperado: categoria D","D) Nenhum caso adicional pode aumentar a cobertura alcan\xe7ada"],"correctAnswer":0,"explanation":"A op\xe7\xe3o A) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra D, Q#22, LO: FL-4.2.3). Justificativa: Homem de 66 anos, n\xe3o registrado, sem experi\xeancia; resultado esperado: categoria B","source":"Official Sample Exam D Q#22"},{"id":381,"chapter":4,"topic":"T\xe9cnicas de An\xe1lisis y Dise\xf1o de Pruebas","question":"Voc\xea est\xe1 aplicando testes de transi\xe7\xe3o de estado a um sistema de reserva de quartos de hotel. Supondo que todos os casos de teste comecem no estado \'Solicitando\' (Requesting), qual dos seguintes casos de teste, representados como sequ\xeancias de eventos, alcan\xe7a a maior cobertura de transi\xe7\xf5es v\xe1lidas?","options":["A) NotAvailable, Available, ChangeRoom, NotAvailable, Cancel","B) Available, ChangeRoom, NotAvailable, Available, Pay","C) Available, ChangeRoom, Available, ChangeRoom, NotAvailable","D) NotAvailable, Cancel, ChangeRoom, Available, Pay"],"correctAnswer":1,"explanation":"A op\xe7\xe3o B) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra D, Q#23, LO: FL-4.2.4). Justificativa: Available, ChangeRoom, NotAvailable, Available, Pay","source":"Official Sample Exam D Q#23"},{"id":382,"chapter":4,"topic":"T\xe9cnicas de An\xe1lisis y Dise\xf1o de Pruebas","question":"Seu conjunto de testes S para um programa P alcan\xe7a 100% de cobertura de comandos. Ele consiste em tr\xeas casos de teste, cada um dos quais alcan\xe7a 50% de cobertura de comandos. Qual das seguintes afirma\xe7\xf5es \xe9 CORRETA?","options":["A) Executar S causar\xe1 todas as falhas poss\xedveis em P","B) S alcan\xe7a 100% de cobertura de ramos (branch coverage) para P","C) Cada comando execut\xe1vel em P que cont\xe9m um defeito foi executado pelo menos uma vez durante a execu\xe7\xe3o de S","D) Ap\xf3s remover um caso de teste de S, os dois restantes ainda alcan\xe7ar\xe3o 100% de cobertura de comandos"],"correctAnswer":2,"explanation":"A op\xe7\xe3o C) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra D, Q#24, LO: FL-4.3.1). Justificativa: Cada comando execut\xe1vel em P que cont\xe9m um defeito foi executado pelo menos uma vez durante a execu\xe7\xe3o de S","source":"Official Sample Exam D Q#24"},{"id":383,"chapter":4,"topic":"T\xe9cnicas de An\xe1lisis y Dise\xf1o de Pruebas","question":"Por que os testes de caixa branca facilitam a detec\xe7\xe3o de defeitos mesmo quando a especifica\xe7\xe3o do software \xe9 vaga, desatualizada ou incompleta?","options":["A) Os casos de teste s\xe3o projetados com base na estrutura do objeto de teste em vez da especifica\xe7\xe3o","B) Para cada t\xe9cnica de caixa branca, a cobertura pode ser bem definida e facilmente medida","C) As t\xe9cnicas de caixa branca s\xe3o muito bem projetadas para detectar omiss\xf5es nos requisitos","D) As t\xe9cnicas de caixa branca podem ser usadas tanto em testes est\xe1ticos quanto din\xe2micos"],"correctAnswer":0,"explanation":"A op\xe7\xe3o A) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra D, Q#25, LO: FL-4.3.3). Justificativa: Os casos de teste s\xe3o projetados com base na estrutura do objeto de teste em vez da especifica\xe7\xe3o","source":"Official Sample Exam D Q#25"},{"id":384,"chapter":4,"topic":"T\xe9cnicas de An\xe1lisis y Dise\xf1o de Pruebas","question":"Qual das seguintes situa\xe7\xf5es N\xc3O \xe9 antecipada pelo testador ao aplicar a t\xe9cnica de suposi\xe7\xe3o de erros (error guessing)?","options":["A) O desenvolvedor interpretou mal a f\xf3rmula na hist\xf3ria de usu\xe1rio para calcular os juros","B) O desenvolvedor escreveu \'FA = A*(1+IR^N)\' em vez de \'FA = A*(1+IR)^N\' no c\xf3digo","C) O desenvolvedor faltou ao semin\xe1rio sobre a nova legisla\xe7\xe3o de taxas de juros compostos","D) A precis\xe3o dos juros calculados pelo sistema n\xe3o \xe9 suficientemente exata"],"correctAnswer":2,"explanation":"A op\xe7\xe3o C) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra D, Q#26, LO: FL-4.4.1). Justificativa: O desenvolvedor faltou ao semin\xe1rio sobre a nova legisla\xe7\xe3o de taxas de juros compostos","source":"Official Sample Exam D Q#26"},{"id":385,"chapter":4,"topic":"T\xe9cnicas de An\xe1lisis y Dise\xf1o de Pruebas","question":"Qual das seguintes afirma\xe7\xf5es \xe9 verdadeira sobre os testes explorat\xf3rios?","options":["A) Os casos de teste s\xe3o projetados antes do in\xedcio da sess\xe3o de testes explorat\xf3rios","B) O testador pode executar testes, mas n\xe3o pode projet\xe1-los","C) Os resultados dos testes explorat\xf3rios s\xe3o bons preditores do n\xfamero de defeitos restantes","D) Durante os testes explorat\xf3rios, o testador pode usar t\xe9cnicas de caixa preta"],"correctAnswer":3,"explanation":"A op\xe7\xe3o D) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra D, Q#27, LO: FL-4.4.2). Justificativa: Durante os testes explorat\xf3rios, o testador pode usar t\xe9cnicas de caixa preta","source":"Official Sample Exam D Q#27"},{"id":386,"chapter":4,"topic":"T\xe9cnicas de An\xe1lisis y Dise\xf1o de Pruebas","question":"Qual pr\xe1tica colaborativa para escrever hist\xf3rias de usu\xe1rio permite \xe0 equipe alcan\xe7ar uma compreens\xe3o coletiva do que precisa ser entregue?","options":["A) Planning poker, para chegar a um consenso sobre o esfor\xe7o","B) Revis\xf5es, para detectar inconsist\xeancias e contradi\xe7\xf5es","C) Planejamento da itera\xe7\xe3o, para priorizar hist\xf3rias de maior valor","D) Conversa\xe7\xe3o, para que os membros da equipe entendam como o software ser\xe1 usado"],"correctAnswer":3,"explanation":"A op\xe7\xe3o D) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra D, Q#28, LO: FL-4.5.1). Justificativa: Conversa\xe7\xe3o, para que os membros da equipe entendam como o software ser\xe1 usado","source":"Official Sample Exam D Q#28"},{"id":387,"chapter":4,"topic":"T\xe9cnicas de An\xe1lisis y Dise\xf1o de Pruebas","question":"Voc\xea est\xe1 projetando casos de teste para uma hist\xf3ria de usu\xe1rio onde o cliente deseja filtrar produtos por faixa de pre\xe7o. Pr\xe9-condi\xe7\xe3o: h\xe1 apenas dois produtos dispon\xedveis, A (US$ 100) e B (US$ 110). Qual \xe9 o MELHOR exemplo de caso de teste para esta hist\xf3ria de usu\xe1rio?","options":["A) Entrar no site e definir o filtro entre US$ 90 e US$ 100. Resultado: mostra apenas A. Alterar o m\xe1ximo para US$ 110. Resultado: mostra A e B.","B) Entrar no site. Adicionar produto C com pre\xe7o de US$ 120. Atualizar a p\xe1gina. Resultado: o pre\xe7o m\xe1ximo padr\xe3o muda para US$ 120.","C) Entrar no site e definir o filtro entre US$ 90 e US$ 115. Resultado: mostra A e B. Alterar a moeda para EUR. Resultado: o filtro muda para valores em EUR.","D) Entrar no site com Edge, Chrome e Opera. Em cada um, definir o filtro entre US$ 90 e US$ 110. Resultado: mostram A e B com o mesmo design em todos."],"correctAnswer":0,"explanation":"A op\xe7\xe3o A) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra D, Q#29, LO: FL-4.5.3). Justificativa: Entrar no site e definir o filtro entre US$ 90 e US$ 100. Resultado: mostra apenas A. Alterar o m\xe1ximo para US$ 110. Resultado: mostra A e B.","source":"Official Sample Exam D Q#29"},{"id":388,"chapter":5,"topic":"Gesti\xf3n de las Actividades de Prueba","question":"Qual dos seguintes define MELHOR os crit\xe9rios de sa\xedda (EXIT criteria) em um projeto de testes?","options":["A) O or\xe7amento \xe9 aprovado","B) O or\xe7amento se esgota","C) A base de teste est\xe1 dispon\xedvel","D) Os casos de teste alcan\xe7aram pelo menos 80% de cobertura de comandos"],"correctAnswer":1,"explanation":"A op\xe7\xe3o B) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra D, Q#30, LO: FL-5.1.3). Justificativa: O or\xe7amento se esgota","source":"Official Sample Exam D Q#30"},{"id":389,"chapter":5,"topic":"Gesti\xf3n de las Actividades de Prueba","question":"A equipe deseja estimar o tempo para executar quatro casos de teste. As medidas para um caso s\xe3o: Melhor cen\xe1rio: 1h, Pior cen\xe1rio: 8h, Mais prov\xe1vel: 3h. Usando a t\xe9cnica de estimativa de tr\xeas pontos, qual \xe9 a estimativa final para os QUATRO casos de teste?","options":["A) 14 horas","B) 3.5 horas","C) 16 horas","D) 12 horas"],"correctAnswer":0,"explanation":"A op\xe7\xe3o A) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra D, Q#31, LO: FL-5.1.4). Justificativa: 14 horas","source":"Official Sample Exam D Q#31"},{"id":390,"chapter":5,"topic":"Gesti\xf3n de las Actividades de Prueba","question":"Voc\xea tem uma matriz de rastreabilidade e deseja priorizar os casos de teste seguindo a t\xe9cnica de cobertura adicional (additional coverage prioritization). Voc\xea executar\xe1 quatro casos de teste. De acordo com as t\xe9cnicas padr\xe3o, qual caso de teste deve ser executado por \xdaLTIMO?","options":["A) TC1","B) TC2","C) TC3","D) TC4"],"correctAnswer":1,"explanation":"A op\xe7\xe3o B) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra D, Q#32, LO: FL-5.1.5). Justificativa: TC2","source":"Official Sample Exam D Q#32"},{"id":391,"chapter":5,"topic":"Gesti\xf3n de las Actividades de Prueba","question":"Como os quadrantes de teste (testing quadrants) podem ser ben\xe9ficos?","options":["A) Ajudam a planejar dividindo em quatro fases: componente, integra\xe7\xe3o, sistema, aceita\xe7\xe3o","B) Ajudam a avaliar a cobertura de alto n\xedvel com base na de baixo n\xedvel","C) Ajudam os stakeholders n\xe3o t\xe9cnicos a entender os diferentes tipos de testes e sua relev\xe2ncia por n\xedveis","D) Ajudam as equipes \xe1geis a se comunicarem de acordo com perfis psicol\xf3gicos"],"correctAnswer":2,"explanation":"A op\xe7\xe3o C) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra D, Q#33, LO: FL-5.1.7). Justificativa: Ajudam os stakeholders n\xe3o t\xe9cnicos a entender os diferentes tipos de testes e sua relev\xe2ncia por n\xedveis","source":"Official Sample Exam D Q#33"},{"id":392,"chapter":5,"topic":"Gesti\xf3n de las Actividades de Prueba","question":"Para um determinado risco, o n\xedvel de risco \xe9 de US$ 1.000 e sua probabilidade \xe9 estimada em 50%. Qual \xe9 o impacto do risco?","options":["A) US$ 500","B) US$ 2.000","C) US$ 50.000","D) US$ 200"],"correctAnswer":1,"explanation":"A op\xe7\xe3o B) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra D, Q#34, LO: FL-5.2.1). Justificativa: US$ 2.000","source":"Official Sample Exam D Q#34"},{"id":393,"chapter":5,"topic":"Gesti\xf3n de las Actividades de Prueba","question":"Qual dos seguintes \xe9 um risco de produto?","options":["A) Corrup\xe7\xe3o de escopo (scope creep)","B) Arquitetura deficiente","C) Corte de custos","D) Falta de suporte de ferramentas"],"correctAnswer":1,"explanation":"A op\xe7\xe3o B) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra D, Q#35, LO: FL-5.2.2). Justificativa: Arquitetura deficiente (Poor architecture)","source":"Official Sample Exam D Q#35"},{"id":394,"chapter":5,"topic":"Gesti\xf3n de las Actividades de Prueba","question":"Qual dos seguintes N\xc3O \xe9 um prop\xf3sito v\xe1lido para um relat\xf3rio de testes?","options":["A) Acompanhamento do progresso e identifica\xe7\xe3o de \xe1reas de aten\xe7\xe3o","B) Fornecer informa\xe7\xf5es sobre os testes executados, resultados e defeitos","C) Fornecer informa\xe7\xf5es passo a passo sobre como reproduzir cada defeito","D) Fornecer informa\xe7\xf5es sobre os testes planejados para o pr\xf3ximo per\xedodo"],"correctAnswer":2,"explanation":"A op\xe7\xe3o C) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra D, Q#36, LO: FL-5.3.2). Justificativa: Fornecer informa\xe7\xf5es passo a passo sobre como reproduzir cada defeito","source":"Official Sample Exam D Q#36"},{"id":395,"chapter":5,"topic":"Gesti\xf3n de las Actividades de Prueba","question":"Um usu\xe1rio relatou uma falha. O suporte pediu a vers\xe3o do software. Com essa vers\xe3o, a equipe reconstruiu os arquivos da vers\xe3o de lan\xe7amento, o que permitiu ao desenvolvedor analisar e corrigir o defeito. Qual processo permitiu a realiza\xe7\xe3o dessa atividade?","options":["A) Gerenciamento de riscos","B) Monitoramento e controle de testes","C) Abordagem de toda a equipe (Whole team)","D) Gerenciamento de configura\xe7\xe3o"],"correctAnswer":3,"explanation":"A op\xe7\xe3o D) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra D, Q#37, LO: FL-5.4.1). Justificativa: Gerenciamento de configura\xe7\xe3o","source":"Official Sample Exam D Q#37"},{"id":396,"chapter":5,"topic":"Gesti\xf3n de las Actividades de Prueba","question":"Considere um relat\xf3rio de defeito de um Sistema de Empr\xe9stimo de Livros. Qual das seguintes a\xe7\xf5es ajudaria MAIS o desenvolvedor a reproduzir a falha rapidamente?","options":["A) Adicionar informa\xe7\xf5es sobre quais usu\xe1rios e quais livros foram afetados na se\xe7\xe3o \'Descri\xe7\xe3o\'","B) Preencher o valor ausente do campo \'Prioridade\'","C) Adicionar dumps de mem\xf3ria (memory dumps) ap\xf3s cada etapa na se\xe7\xe3o \'Anexos\'","D) Repetir o caso de teste para diferentes ambientes e criar um relat\xf3rio separado para cada um"],"correctAnswer":0,"explanation":"A op\xe7\xe3o A) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra D, Q#38, LO: FL-5.5.1). Justificativa: Adicionar informa\xe7\xf5es sobre quais usu\xe1rios e quais livros foram afetados na se\xe7\xe3o \'Descri\xe7\xe3o\'","source":"Official Sample Exam D Q#38"},{"id":397,"chapter":6,"topic":"Herramientas de Prueba","question":"Dadas as categorias de ferramentas de teste (i. Colabora\xe7\xe3o,  \\n  \\nii. DevOps,  \\n  \\niii. Gest\xe3o,  \\n  \\niv. N\xe3o funcionais,  \\n  \\nv. Design/Implementa\xe7\xe3o). Ferramentas de quais categorias s\xe3o MAIS propensas a facilitar a execu\xe7\xe3o de testes?","options":["A) i, v","B) ii, iv","C) i, iii, v","D) ii, iii, iv"],"correctAnswer":1,"explanation":"A op\xe7\xe3o B) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra D, Q#39, LO: FL-6.1.1). Justificativa: ii, iv (DevOps, N\xe3o funcionais)","source":"Official Sample Exam D Q#39"},{"id":398,"chapter":6,"topic":"Herramientas de Prueba","question":"Qual dos seguintes \xe9 MAIS prov\xe1vel de ser um risco da automa\xe7\xe3o de testes?","options":["A) Detec\xe7\xe3o de defeitos adicionais de alta severidade","B) Fornecer m\xe9tricas muito complicadas para os humanos","C) Incompatibilidade com a plataforma de desenvolvimento","D) Redu\xe7\xe3o substancial do tempo de execu\xe7\xe3o"],"correctAnswer":2,"explanation":"A op\xe7\xe3o C) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra D, Q#40, LO: FL-6.2.1). Justificativa: Incompatibilidade com a plataforma de desenvolvimento","source":"Official Sample Exam D Q#40"},{"id":399,"chapter":1,"topic":"Fundamentos del Testing","question":"Dadas as seguintes tarefas de teste: Qual \xe9 o MELHOR pareamento?\\n\\n1. Derivar casos de teste a partir de condi\xe7\xf5es\\n2. Identificar testware reutiliz\xe1vel\\n3. Organizar casos em procedimentos\\n4. Avaliar a base de teste\\n\\nA. An\xe1lise  \\nB. Modelagem (Design)  \\nC. Implementa\xe7\xe3o  \\nD. Conclus\xe3o","options":["A) 1B, 2A, 3D, 4C","B) 1B, 2D, 3C, 4A","C) 1C, 2A, 3B, 4D","D) 1C, 2D, 3A, 4B"],"correctAnswer":1,"explanation":"A op\xe7\xe3o B) \xe9 a resposta correta de acordo com o Exame Oficial ISTQB CTFL v4.0 (Amostra D, Q#4, LO: FL-1.4.1). Justificativa: 1B, 2D, 3C, 4A","source":"Official Sample Exam D Q#4"},{"chapter":4,"topic":"T\xe9cnicas de An\xe1lisis y Dise\xf1o de Pruebas","question":"Voc\xea \xe9 um testador de um sistema banc\xe1rio. O campo \'valor da transfer\xeancia\' aceita valores entre 1\u20ac e 10.000\u20ac. Aplicando a An\xe1lise de Valor Limite (BVA) de 3 valores por limite, qual conjunto de valores de teste \xe9 o correto?","options":["A) 0, 1, 2, 9999, 10000, 10001","B) 1, 10000","C) 0, 1, 5000, 10000, 10001","D) -1, 0, 1, 9999, 10000, 10001"],"correctAnswer":0,"explanation":"A BVA de 3 valores por limite inclui: pouco fora do limite (0), no limite (1), pouco dentro (2) para o limite inferior; e pouco dentro (9999), no limite (10000), pouco fora (10001) para o limite superior.","id":400},{"chapter":4,"topic":"T\xe9cnicas de An\xe1lisis y Dise\xf1o de Pruebas","question":"Um sistema de descontos aplica: 0% se compra < 100\u20ac, 5% se 100\u20ac \u2264 compra < 500\u20ac, 10% se 500\u20ac \u2264 compra < 1000\u20ac, 15% se compra \u2265 1000\u20ac. Usando a parti\xe7\xe3o de equival\xeancia, quantas classes de equival\xeancia v\xe1lidas existem?","options":["A) 2","B) 3","C) 4","D) 5"],"correctAnswer":2,"explanation":"Existem 4 classes de equival\xeancia v\xe1lidas: [0-99\u20ac], [100-499\u20ac], [500-999\u20ac], [\u22651000\u20ac], uma para cada faixa de desconto diferente.","id":401},{"chapter":4,"topic":"T\xe9cnicas de An\xe1lisis y Dise\xf1o de Pruebas","question":"Voc\xea est\xe1 projetando uma tabela de decis\xe3o para um sistema de empr\xe9stimos com 3 condi\xe7\xf5es booleanas (renda suficiente, bom hist\xf3rico de cr\xe9dito, garantia fornecida). Quantas colunas de regras a tabela completa ter\xe1?","options":["A) 3","B) 6","C) 8","D) 9"],"correctAnswer":2,"explanation":"Com 3 condi\xe7\xf5es booleanas (V/F cada), o n\xfamero de combina\xe7\xf5es poss\xedveis \xe9 2\xb3 = 8 regras/colunas.","id":402},{"chapter":4,"topic":"T\xe9cnicas de An\xe1lisis y Dise\xf1o de Pruebas","question":"Um caixa eletr\xf4nico tem os estados: Inativo, Aguardando PIN, Verificando, Dispensando, Bloqueado. Se voc\xea inserir 3 PINs incorretos consecutivos, a transi\xe7\xe3o vai para \'Bloqueado\'. Qual t\xe9cnica de modelagem de teste \xe9 MAIS adequada para modelar e verificar esse comportamento?","options":["A) Parti\xe7\xe3o de equival\xeancia","B) An\xe1lise de valor limite","C) Teste de transi\xe7\xe3o de estado","D) Tabela de decis\xe3o"],"correctAnswer":2,"explanation":"Os testes de transi\xe7\xe3o de estado modelam o comportamento do sistema quando ele passa de um estado para outro com base em eventos ou condi\xe7\xf5es, ideais para sistemas com estados como um caixa eletr\xf4nico (ATM).","id":403},{"chapter":4,"topic":"T\xe9cnicas de An\xe1lisis y Dise\xf1o de Pruebas","question":"Voc\xea tem o seguinte c\xf3digo: IF (a > 0 AND b > 0) THEN resultado = a + b ELSE resultado = 0. Para atingir 100% de cobertura de decis\xe3o, quantos casos de teste s\xe3o necess\xe1rios no m\xednimo?","options":["A) 1","B) 2","C) 3","D) 4"],"correctAnswer":1,"explanation":"Para obter 100% de cobertura de decis\xe3o, voc\xea precisa de pelo menos 2 casos: um que torne a condi\xe7\xe3o verdadeira (ex: a=1, b=1) e outro que a torne falsa (ex: a=-1, b=1).","id":404},{"chapter":4,"topic":"T\xe9cnicas de An\xe1lisis y Dise\xf1o de Pruebas","question":"Voc\xea trabalha em um aplicativo de reserva de voos. Voc\xea est\xe1 aplicando o m\xe9todo de \'casos de uso\' para projetar testes. Qual fluxo voc\xea DEVE testar para encontrar os defeitos mais cr\xedticos no fluxo de reserva?","options":["A) Apenas o fluxo b\xe1sico (caminho feliz)","B) Apenas os fluxos alternativos de erro","C) O fluxo b\xe1sico e todos os fluxos alternativos e de exce\xe7\xe3o","D) Apenas os fluxos que t\xeam a maior probabilidade de ocorrer"],"correctAnswer":2,"explanation":"Os testes baseados em casos de uso devem cobrir o fluxo b\xe1sico (caminho feliz) E todos os fluxos alternativos e de exce\xe7\xe3o para garantir a cobertura completa do comportamento especificado.","id":405},{"chapter":4,"topic":"T\xe9cnicas de An\xe1lisis y Dise\xf1o de Pruebas","question":"Para um m\xf3dulo com 5 condi\xe7\xf5es independentes em uma tabela de decis\xe3o, quantas regras a tabela completa teria e quantas seriam obtidas com \'colapso\' eliminando condi\xe7\xf5es irrelevantes se houver apenas 3 a\xe7\xf5es distintas?","options":["A) 32 completa; 3 colapsada","B) 10 completa; 3 colapsada","C) 32 completa; pode ser menos de 32 colapsada","D) 16 completa; 3 colapsada"],"correctAnswer":2,"explanation":"Com 5 condi\xe7\xf5es booleanas: 2\u2075 = 32 regras completas. O colapso reduz regras combinando aquelas onde alguma condi\xe7\xe3o \xe9 irrelevante (\'don\'t care\'), resultando em menos de 32.","id":406},{"chapter":1,"topic":"Fundamentos del Testing","question":"Sua equipe detectou 45 defeitos no m\xf3dulo A (5.000 linhas de c\xf3digo) e 12 defeitos no m\xf3dulo B (8.000 linhas). De acordo com o princ\xedpio de \'agrupamento de defeitos\' (defect clustering), qual conclus\xe3o \xe9 a MAIS correta?","options":["A) O m\xf3dulo B apresenta mais riscos por ter mais c\xf3digo","B) O m\xf3dulo A tem maior densidade de defeitos e deve receber mais esfor\xe7o de teste","C) Ambos os m\xf3dulos t\xeam o mesmo n\xedvel de risco","D) Os defeitos s\xe3o distribu\xeddos uniformemente entre os dois m\xf3dulos"],"correctAnswer":1,"explanation":"O m\xf3dulo A tem densidade 45/5000 = 0,009 defeitos/linha vs B com 12/8000 = 0,0015. O princ\xedpio de agrupamento indica que os defeitos se concentram em um pequeno n\xfamero de m\xf3dulos; A merece maior esfor\xe7o de teste.","id":407},{"chapter":1,"topic":"Fundamentos del Testing","question":"Um testador executa o mesmo conjunto de testes de regress\xe3o por 6 sprints consecutivos sem modifica\xe7\xf5es. De acordo com os princ\xedpios do ISTQB, que problema surge e qual \xe9 a solu\xe7\xe3o?","options":["A) N\xe3o h\xe1 problema; os testes de regress\xe3o devem ser est\xe1veis","B) Paradoxo do pesticida: os testes deixam de encontrar novos defeitos; revisar e atualizar o conjunto de testes","C) Fal\xe1cia da aus\xeancia de defeitos: o software n\xe3o tem mais bugs","D) Os testes antecipados geram falsos positivos acumulados"],"correctAnswer":1,"explanation":"O paradoxo do pesticida afirma que, se os mesmos testes forem repetidos sem altera\xe7\xf5es, eles eventualmente deixar\xe3o de encontrar novos defeitos. A solu\xe7\xe3o \xe9 revisar e atualizar os testes periodicamente.","id":408},{"chapter":2,"topic":"Testing a lo largo del SDLC","question":"Em um projeto com modelo em V, a equipe recebe os requisitos do sistema no dia 1. Em que momento eles devem come\xe7ar a projetar os testes de sistema?","options":["A) Quando o c\xf3digo do sistema estiver completamente desenvolvido","B) Ap\xf3s a conclus\xe3o dos testes de integra\xe7\xe3o","C) Em paralelo com o design do sistema, assim que os requisitos estiverem dispon\xedveis","D) Somente ap\xf3s os requisitos serem aprovados formalmente pelo cliente"],"correctAnswer":2,"explanation":"A abordagem \'shift-left\' e o modelo em V estabelecem que o design de testes de sistema deve ocorrer em paralelo com o design do sistema, e n\xe3o ap\xf3s o desenvolvimento, aproveitando os requisitos iniciais.","id":409},{"chapter":2,"topic":"Testing a lo largo del SDLC","question":"Sua equipe trabalha com Scrum em sprints de 2 semanas. No in\xedcio da sprint, a equipe tem 8 hist\xf3rias de usu\xe1rio. Quando os testadores devem come\xe7ar a trabalhar nessas hist\xf3rias?","options":["A) No \xfaltimo dia da sprint, durante a demo","B) Desde o primeiro dia, colaborando na defini\xe7\xe3o dos crit\xe9rios de aceite e casos de teste","C) Na metade da sprint, quando o desenvolvimento estiver em 50%","D) Na sprint seguinte, fazendo testes de regress\xe3o"],"correctAnswer":1,"explanation":"No Agile/Scrum, os testadores participam desde o in\xedcio da sprint no refinamento, na defini\xe7\xe3o de crit\xe9rios de aceite e no projeto de testes, integrando os testes continuamente (abordagem de toda a equipe).","id":410},{"chapter":3,"topic":"Pruebas Est\xe1ticas","question":"Durante uma inspe\xe7\xe3o de requisitos, o moderador encontra a frase: \'O sistema deve ser r\xe1pido\'. Que tipo de defeito de requisito esta afirma\xe7\xe3o representa?","options":["A) Requisito duplicado","B) Requisito amb\xedguo e n\xe3o verific\xe1vel","C) Requisito conflitante","D) Requisito fora de escopo"],"correctAnswer":1,"explanation":"\'R\xe1pido\' \xe9 amb\xedguo e n\xe3o verific\xe1vel porque n\xe3o especifica um crit\xe9rio mensur\xe1vel. Um requisito correto diria, por exemplo, \'O sistema deve responder em menos de 2 segundos para 95% das solicita\xe7\xf5es\'.","id":411},{"chapter":3,"topic":"Pruebas Est\xe1ticas","question":"Uma ferramenta de an\xe1lise est\xe1tica relata: \'Vari\xe1vel x declarada mas nunca utilizada na fun\xe7\xe3o calcularTotal()\'. Como essa descoberta \xe9 classificada na terminologia do ISTQB?","options":["A) Failure (falha)","B) Error (erro/engano)","C) Defect (defeito/bug)","D) Incident (incidente)"],"correctAnswer":2,"explanation":"A an\xe1lise est\xe1tica encontra defeitos (bugs/falhas) no c\xf3digo sem execut\xe1-lo. Uma vari\xe1vel declarada sem uso \xe9 um defeito de c\xf3digo detectado estaticamente.","id":412},{"chapter":5,"topic":"Gesti\xf3n de las Actividades de Prueba","question":"Voc\xea \xe9 gerente de teste e deve estimar o esfor\xe7o de teste para um novo projeto. Voc\xea tem dados hist\xf3ricos de 5 projetos semelhantes. Qual abordagem de estimativa voc\xea usaria PRINCIPALMENTE?","options":["A) Exclusivamente Delphi Banda Larga (Wideband Delphi)","B) Estimativa baseada em m\xe9tricas usando dados hist\xf3ricos de projetos semelhantes","C) Planning Poker com a equipe de desenvolvimento","D) Estimativa por pontos de fun\xe7\xe3o sem dados hist\xf3ricos"],"correctAnswer":1,"explanation":"A estimativa baseada em m\xe9tricas utiliza dados hist\xf3ricos de projetos anteriores semelhantes para calcular o esfor\xe7o. Com 5 projetos hist\xf3ricos dispon\xedveis, esta abordagem \xe9 a mais s\xf3lida e objetiva.","id":413},{"chapter":5,"topic":"Gesti\xf3n de las Actividades de Prueba","question":"Seu plano de teste indica 200 casos de teste planejados para a semana. No final da semana, voc\xea executou 140 e encontrou 25 defeitos, dos quais 8 s\xe3o cr\xedticos e ainda n\xe3o foram corrigidos. Qual informa\xe7\xe3o \xe9 a MAIS relevante para decidir se o software deve ser liberado?","options":["A) Apenas a porcentagem de execu\xe7\xe3o (70%)","B) Apenas o n\xfamero total de defeitos (25)","C) A densidade de defeitos cr\xedticos n\xe3o resolvidos e os crit\xe9rios de sa\xedda definidos no plano","D) O n\xfamero de testes pendentes (60)"],"correctAnswer":2,"explanation":"Os crit\xe9rios de sa\xedda (exit criteria) do plano de teste definem as condi\xe7\xf5es para a libera\xe7\xe3o (release). Os defeitos cr\xedticos n\xe3o resolvidos s\xe3o o fator mais relevante para a decis\xe3o de libera\xe7\xe3o.","id":414},{"chapter":5,"topic":"Gesti\xf3n de las Actividades de Prueba","question":"Um defeito tem severidade \'cr\xedtica\' (o sistema trava) mas prioridade \'baixa\' atribu\xedda pelo product owner. Qual \xe9 a explica\xe7\xe3o MAIS prov\xe1vel?","options":["A) \xc9 um erro; severidade e prioridade devem sempre coincidir","B) O defeito afeta uma funcionalidade raramente usada ou n\xe3o cr\xedtica para o neg\xf3cio neste momento","C) O product owner n\xe3o entende a severidade t\xe9cnica","D) A prioridade \xe9 sempre mais importante do que a severidade no Agile"],"correctAnswer":1,"explanation":"Severidade (impacto t\xe9cnico) e prioridade (urg\xeancia de neg\xf3cio) s\xe3o conceitos independentes. Um travamento (crash) em uma fun\xe7\xe3o pouco usada pode ter alta severidade t\xe9cnica, mas baixa prioridade de neg\xf3cio.","id":415},{"chapter":5,"topic":"Gesti\xf3n de las Actividades de Prueba","question":"Voc\xea trabalha em um projeto com um risco de produto identificado: \'O m\xf3dulo de pagamentos pode falhar sob alta carga\'. Que tipo de teste voc\xea deve priorizar para mitigar esse risco?","options":["A) Testes de regress\xe3o do m\xf3dulo de pagamentos","B) Testes de desempenho/carga no m\xf3dulo de pagamentos","C) Revis\xe3o est\xe1tica do c\xf3digo do m\xf3dulo de pagamentos","D) Testes de aceite do usu\xe1rio do m\xf3dulo de pagamentos"],"correctAnswer":1,"explanation":"O risco identificado \xe9 de desempenho sob carga, portanto os testes de desempenho/carga s\xe3o os mais indicados para validar e mitigar esse risco de produto espec\xedfico.","id":416},{"chapter":6,"topic":"Herramientas de Prueba","question":"Sua organiza\xe7\xe3o deseja implementar uma ferramenta de automa\xe7\xe3o de testes de GUI. Qual dos seguintes fatores representa o MAIOR risco a longo prazo?","options":["A) O custo inicial da licen\xe7a da ferramenta","B) A fragilidade dos scripts quando a interface de usu\xe1rio muda frequentemente","C) O tempo de aprendizado inicial da equipe","D) A incompatibilidade com a linguagem de programa\xe7\xe3o do sistema"],"correctAnswer":1,"explanation":"Os scripts de automa\xe7\xe3o de GUI s\xe3o muito fr\xe1geis a mudan\xe7as de interface (localizadores, IDs, posi\xe7\xf5es). Em projetos com interface de usu\xe1rio que evolui rapidamente, a manuten\xe7\xe3o pode superar o benef\xedcio da automa\xe7\xe3o.","id":417},{"chapter":6,"topic":"Herramientas de Prueba","question":"Qual \xe9 a principal diferen\xe7a entre uma ferramenta de execu\xe7\xe3o de testes e uma ferramenta de gerenciamento de testes?","options":["A) N\xe3o h\xe1 diferen\xe7a, s\xe3o a mesma ferramenta","B) A de execu\xe7\xe3o automatiza a execu\xe7\xe3o dos scripts; a de gerenciamento organiza, planeja e registra o progresso e os resultados dos testes","C) A de gerenciamento serve apenas para testes manuais; a de execu\xe7\xe3o para automatizados","D) A de execu\xe7\xe3o gera relat\xf3rios; a de gerenciamento executa os casos de teste"],"correctAnswer":1,"explanation":"As ferramentas de execu\xe7\xe3o (ex. Selenium, JUnit) rodam os testes automaticamente. As de gerenciamento (ex. TestRail, Zephyr) organizam casos, planos, ciclos de teste e rastreiam resultados e cobertura.","id":418},{"chapter":1,"topic":"Fundamentos del Testing","question":"Qual dos itens a seguir \xe9 um exemplo de teste N\xc3O funcional?","options":["A) Verificar se o login rejeita senhas incorretas","B) Comprovar que a p\xe1gina inicial carrega em menos de 3 segundos com 500 usu\xe1rios simult\xe2neos","C) Validar se o c\xe1lculo do imposto \xe9 correto","D) Confirmar que o bot\xe3o \'Salvar\' armazena os dados no banco de dados"],"correctAnswer":1,"explanation":"Os testes n\xe3o funcionais avaliam atributos de qualidade como desempenho, usabilidade e seguran\xe7a. A op\xe7\xe3o B \xe9 um teste de desempenho (carga), que \xe9 n\xe3o funcional.","id":419},{"chapter":2,"topic":"Testing a lo largo del SDLC","question":"Qual \xe9 a diferen\xe7a entre testes de confirma\xe7\xe3o (reteste) e testes de regress\xe3o?","options":["A) S\xe3o a mesma coisa, apenas nomes diferentes","B) A confirma\xe7\xe3o verifica se um defeito espec\xedfico foi corrigido; a regress\xe3o verifica se as altera\xe7\xf5es n\xe3o quebraram mais nada","C) A regress\xe3o \xe9 feita apenas pelos desenvolvedores; a confirma\xe7\xe3o pelos testadores","D) A confirma\xe7\xe3o \xe9 feita antes do desenvolvimento; a regress\xe3o depois"],"correctAnswer":1,"explanation":"O reteste (confirma\xe7\xe3o) executa o caso de teste que falhou para verificar se o defeito espec\xedfico foi corrigido. O teste de regress\xe3o verifica se a altera\xe7\xe3o n\xe3o introduziu novas falhas em outras \xe1reas.","id":420},{"chapter":3,"topic":"Pruebas Est\xe1ticas","question":"Qual dos seguintes documentos pode ser objeto de revis\xe3o est\xe1tica?","options":["A) Apenas o c\xf3digo-fonte","B) Apenas os requisitos","C) Qualquer produto de trabalho: requisitos, design, c\xf3digo, casos de teste, planos","D) Apenas os documentos entregues ao cliente"],"correctAnswer":2,"explanation":"Os testes est\xe1ticos podem ser aplicados a qualquer produto de trabalho escrito: requisitos, especifica\xe7\xf5es de design, c\xf3digo-fonte, casos de teste, planos de teste, contratos, etc.","id":421},{"chapter":4,"topic":"T\xe9cnicas de An\xe1lisis y Dise\xf1o de Pruebas","question":"Um campo de formul\xe1rio aceita valores de idade entre 18 e 65 anos. Usando parti\xe7\xe3o de equival\xeancia, quantas classes s\xe3o identificadas (v\xe1lidas + inv\xe1lidas)?","options":["A) 2","B) 3","C) 4","D) 5"],"correctAnswer":1,"explanation":"S\xe3o identificadas 3 classes: inv\xe1lida (<18), v\xe1lida (18 a 65), inv\xe1lida (>65). H\xe1 1 classe v\xe1lida e 2 inv\xe1lidas = 3 classes no total.","id":422},{"chapter":5,"topic":"Gesti\xf3n de las Actividades de Prueba","question":"Qual documento descreve o escopo, a abordagem, os recursos, o cronograma e os objetivos das atividades de teste para um projeto espec\xedfico?","options":["A) Estrat\xe9gia de teste","B) Plano de teste","C) Especifica\xe7\xe3o de caso de teste","D) Relat\xf3rio de resumo de teste"],"correctAnswer":1,"explanation":"O Plano de Teste (Test Plan) descreve para um projeto espec\xedfico: escopo, objetivos, abordagem, crit\xe9rios de entrada/sa\xedda, recursos, riscos e o cronograma das atividades de teste.","id":423},{"chapter":4,"topic":"T\xe9cnicas de An\xe1lisis y Dise\xf1o de Pruebas","question":"Analise o seguinte diagrama de fluxo: START \u2192 A \u2192 IF X THEN B ELSE C \u2192 IF Y THEN D ELSE E \u2192 END. Quantos casos de teste s\xe3o necess\xe1rios para alcan\xe7ar 100% de cobertura de comandos (senten\xe7as)?","options":["A) 1","B) 2","C) 3","D) 4"],"correctAnswer":1,"explanation":"Para executar todos os comandos (A, B ou C, D ou E) voc\xea precisa de pelo menos 2 casos: um em que X=true, Y=true (executa A, B, D) e outro em que X=false, Y=false (executa A, C, E). Com 2 casos voc\xea cobre todos os comandos.","id":424},{"chapter":4,"topic":"T\xe9cnicas de An\xe1lisis y Dise\xf1o de Pruebas","question":"Voc\xea tem uma fun\xe7\xe3o com 4 condi\xe7\xf5es independentes em uma express\xe3o AND: (A AND B AND C AND D). Para atingir 100% de cobertura de condi\xe7\xe3o modificada/decis\xe3o (MC/DC), quantos casos de teste s\xe3o necess\xe1rios no m\xednimo?","options":["A) 2","B) 4","C) 5","D) 16"],"correctAnswer":2,"explanation":"O MC/DC requer N+1 casos de teste para N condi\xe7\xf5es independentes. Com 4 condi\xe7\xf5es: 4+1=5 casos no m\xednimo. O MC/DC demonstra que cada condi\xe7\xe3o influencia independentemente o resultado.","id":425},{"chapter":4,"topic":"T\xe9cnicas de An\xe1lisis y Dise\xf1o de Pruebas","question":"Um sistema de sem\xe1foro tem os estados: Vermelho, Amarelo_para_Verde, Verde, Amarelo_para_Vermelho. A transi\xe7\xe3o Vermelho\u2192Amarelo_para_Verde ocorre ap\xf3s 60 segundos. Quantas transi\xe7\xf5es v\xe1lidas tem o diagrama completo do sem\xe1foro?","options":["A) 2","B) 3","C) 4","D) 8"],"correctAnswer":2,"explanation":"O ciclo completo tem 4 transi\xe7\xf5es: Vermelho\u2192Amarelo_para_Verde, Amarelo_para_Verde\u2192Verde, Verde\u2192Amarelo_para_Vermelho, Amarelo_para_Vermelho\u2192Vermelho. S\xe3o exatamente 4 transi\xe7\xf5es no ciclo normal.","id":426},{"chapter":4,"topic":"T\xe9cnicas de An\xe1lisis y Dise\xf1o de Pruebas","question":"Voc\xea est\xe1 testando uma fun\xe7\xe3o de pesquisa. Com base em sua experi\xeancia, voc\xea sabe que pesquisas com caracteres especiais (%, _, *) costumam causar inje\xe7\xe3o de SQL. Que t\xe9cnica baseada em experi\xeancia voc\xea est\xe1 usando?","options":["A) Explora\xe7\xe3o estruturada","B) Suposi\xe7\xe3o de erros (Error guessing)","C) Teste de caixa branca","D) Parti\xe7\xe3o de equival\xeancia"],"correctAnswer":1,"explanation":"A suposi\xe7\xe3o de erros (error guessing) \xe9 uma t\xe9cnica baseada na experi\xeancia onde o testador prev\xea onde \xe9 mais prov\xe1vel haver defeitos, baseando-se em seu conhecimento de falhas comuns, como inje\xe7\xe3o de SQL com caracteres especiais.","id":427},{"chapter":4,"topic":"T\xe9cnicas de An\xe1lisis y Dise\xf1o de Pruebas","question":"Para o seguinte c\xf3digo IF (idade >= 18 AND pais == \'ES\') THEN acesso = true ELSE acesso = false, quantos casos de teste voc\xea precisa para 100% de cobertura de decis\xe3o?","options":["A) 1","B) 2","C) 3","D) 4"],"correctAnswer":1,"explanation":"A cobertura de decis\xe3o requer que a condi\xe7\xe3o composta seja avaliada como TRUE e como FALSE. Voc\xea precisa: caso 1 (idade=20, pais=\'ES\'\u2192true) e caso 2 (idade=15, pais=\'ES\'\u2192false). No m\xednimo 2 casos.","id":428},{"chapter":1,"topic":"Fundamentos del Testing","question":"Sua empresa desenvolve software de controle de voo. O custo de falhar \xe9 catastr\xf3fico. Qual dos seguintes princ\xedpios do ISTQB justifica investir mais em testes do que em projetos de baixo risco?","options":["A) Os testes exaustivos s\xe3o poss\xedveis com recursos suficientes","B) O teste depende do contexto: o n\xedvel de rigor deve se adequar ao risco e \xe0s consequ\xeancias da falha","C) A aus\xeancia de defeitos \xe9 uma fal\xe1cia","D) Os testes precoces economizam tempo e dinheiro"],"correctAnswer":1,"explanation":"O princ\xedpio \'O teste depende do contexto\' estabelece que a abordagem, as t\xe9cnicas e a intensidade do teste variam de acordo com o dom\xednio, risco e as consequ\xeancias. Software cr\xedtico requer maior rigor.","id":429},{"chapter":1,"topic":"Fundamentos del Testing","question":"Durante os testes de sistema, um defeito \xe9 encontrado no m\xf3dulo de faturamento. O desenvolvedor o corrige. Depois, o testador descobre que a corre\xe7\xe3o introduziu um novo erro no m\xf3dulo de estoque. Como \xe9 chamado esse tipo de defeito introduzido?","options":["A) Defeito de regress\xe3o","B) Defeito de integra\xe7\xe3o","C) Defeito de muta\xe7\xe3o","D) Defeito de confirma\xe7\xe3o"],"correctAnswer":0,"explanation":"Um defeito de regress\xe3o (regression defect) \xe9 aquele introduzido inadvertidamente por uma altera\xe7\xe3o (como uma corre\xe7\xe3o de bug). Os testes de regress\xe3o s\xe3o projetados especificamente para detect\xe1-los.","id":430},{"chapter":2,"topic":"Testing a lo largo del SDLC","question":"No desenvolvimento TDD (Test-Driven Development), qual \xe9 a ordem correta do ciclo?","options":["A) Escrever c\xf3digo \u2192 Escrever teste \u2192 Refatorar","B) Escrever teste (que falha) \u2192 Escrever c\xf3digo m\xednimo para passar no teste \u2192 Refatorar","C) Projetar \u2192 Escrever teste \u2192 Escrever c\xf3digo \u2192 Refatorar","D) Escrever teste \u2192 Implantar \u2192 Refatorar \u2192 Escrever c\xf3digo"],"correctAnswer":1,"explanation":"O TDD segue o ciclo Red-Green-Refactor: 1) Escrever teste que falha (Red), 2) Escrever o c\xf3digo m\xednimo para faz\xea-lo passar (Green), 3) Refatorar o c\xf3digo mantendo os testes passando (verde).","id":431},{"chapter":2,"topic":"Testing a lo largo del SDLC","question":"Qual das seguintes afirma\xe7\xf5es sobre os testes de integra\xe7\xe3o de sistema (system integration testing) \xe9 CORRETA?","options":["A) Verificam a l\xf3gica interna de cada componente individual","B) Verificam as intera\xe7\xf5es entre o sistema e os sistemas externos ou interfaces","C) S\xe3o executadas apenas por usu\xe1rios finais","D) S\xf3 se aplicam a modelos de desenvolvimento em cascata"],"correctAnswer":1,"explanation":"Os testes de integra\xe7\xe3o de sistema verificam as interfaces e comunica\xe7\xf5es entre o sistema sob teste e outros sistemas externos, servi\xe7os, APIs ou hardware com os quais interage.","id":432},{"chapter":2,"topic":"Testing a lo largo del SDLC","question":"Uma equipe DevOps implementa CI/CD. Os testes s\xe3o executados automaticamente em cada commit. Que tipo de testes s\xe3o MAIS apropriados para executar em cada build do pipeline de CI?","options":["A) Testes de aceite do usu\xe1rio completos","B) Testes explorat\xf3rios manuais","C) Testes r\xe1pidos de componente e de integra\xe7\xe3o automatizados","D) Testes de desempenho completos com carga m\xe1xima"],"correctAnswer":2,"explanation":"No CI, os testes devem ser r\xe1pidos e automatizados para fornecer feedback imediato. Os testes de componente e de integra\xe7\xe3o automatizados s\xe3o os ideais. Os testes lentos (UAT, carga m\xe1xima) ocorrem em fases separadas.","id":433},{"chapter":3,"topic":"Pruebas Est\xe1ticas","question":"Uma organiza\xe7\xe3o realiza uma revis\xe3o onde: existe um moderador independente, os revisores se preparam individualmente, m\xe9tricas de defeitos s\xe3o registradas e um relat\xf3rio formal \xe9 produzido. Que tipo de revis\xe3o \xe9 essa?","options":["A) Revis\xe3o informal","B) Walkthrough","C) Revis\xe3o t\xe9cnica","D) Inspe\xe7\xe3o"],"correctAnswer":3,"explanation":"A Inspe\xe7\xe3o \xe9 a revis\xe3o mais formal: possui um moderador treinado, prepara\xe7\xe3o individual, pap\xe9is definidos (autor, moderador, escriv\xe3o, revisores), coleta de m\xe9tricas e um relat\xf3rio de sa\xedda formal.","id":434},{"chapter":3,"topic":"Pruebas Est\xe1ticas","question":"Qual \xe9 a principal diferen\xe7a entre uma inspe\xe7\xe3o e um walkthrough nas revis\xf5es est\xe1ticas?","options":["A) O walkthrough \xe9 mais formal do que a inspe\xe7\xe3o","B) No walkthrough, o autor conduz a reuni\xe3o; na inspe\xe7\xe3o, ela \xe9 conduzida por um moderador independente","C) A inspe\xe7\xe3o n\xe3o requer prepara\xe7\xe3o pr\xe9via; o walkthrough sim","D) O walkthrough produz m\xe9tricas formais; a inspe\xe7\xe3o n\xe3o"],"correctAnswer":1,"explanation":"No Walkthrough, o autor guia os participantes pelo seu produto de trabalho. Na Inspe\xe7\xe3o, um moderador independente dirige o processo seguindo um processo definido com maior formalidade e rigor.","id":435},{"chapter":5,"topic":"Gesti\xf3n de las Actividades de Prueba","question":"Voc\xea \xe9 gerente de teste. O projeto est\xe1 2 semanas atrasado. O diretor pede para reduzir o tempo de testes pela metade. Qual \xe9 a resposta MAIS profissional?","options":["A) Aceitar e executar todos os testes mais r\xe1pido","B) Eliminar aleatoriamente a metade dos casos de teste","C) Apresentar a an\xe1lise de risco: que cobertura \xe9 perdida, quais riscos aumentam, e propor uma prioriza\xe7\xe3o baseada em risco","D) Recusar-se completamente a reduzir o tempo de testes"],"correctAnswer":2,"explanation":"A resposta profissional \xe9 usar o gerenciamento de riscos: mostrar quais \xe1reas ficar\xe3o sem cobertura, o impacto na qualidade e propor uma estrat\xe9gia de prioriza\xe7\xe3o baseada no risco para maximizar o valor com o tempo dispon\xedvel.","id":436},{"chapter":5,"topic":"Gesti\xf3n de las Actividades de Prueba","question":"Qual dos seguintes \xe9 um exemplo de \'risco de projeto\' (em oposi\xe7\xe3o a risco de produto) no contexto de testes?","options":["A) O m\xf3dulo de pagamento pode ter vulnerabilidades de seguran\xe7a","B) A falta de disponibilidade do ambiente de testes pode atrasar a execu\xe7\xe3o","C) O algoritmo de pesquisa pode retornar resultados incorretos","D) O sistema pode sofrer degrada\xe7\xe3o sob alta carga de usu\xe1rios"],"correctAnswer":1,"explanation":"Os riscos de projeto amea\xe7am o plano do projeto (recursos, ambientes, ferramentas, cronograma). Os riscos de produto amea\xe7am a qualidade do software. A falta de ambiente \xe9 um risco de projeto.","id":437},{"chapter":6,"topic":"Herramientas de Prueba","question":"Uma empresa avalia o ROI da automa\xe7\xe3o da sua su\xedte de regress\xe3o (500 casos manuais, 2h cada execu\xe7\xe3o manual). Se a automa\xe7\xe3o custa 200 horas e cada execu\xe7\xe3o automatizada leva 15 min, quantas execu\xe7\xf5es s\xe3o necess\xe1rias para recuperar o investimento?","options":["A) 10 execu\xe7\xf5es","B) 50 execu\xe7\xf5es","C) 100 execu\xe7\xf5es","D) 200 execu\xe7\xf5es"],"correctAnswer":2,"explanation":"Economia por execu\xe7\xe3o: 2h - 0.25h = 1.75h. Para recuperar 200h de investimento: 200 / 1.75 \u2248 114 execu\xe7\xf5es. A op\xe7\xe3o mais pr\xf3xima \xe9 100, embora a matem\xe1tica exata d\xea ~114. (Em muitos exames, o c\xe1lculo \xe9 simplificado).","id":438},{"chapter":4,"topic":"T\xe9cnicas de An\xe1lisis y Dise\xf1o de Pruebas","question":"O \'teste de pares\' (pairwise testing) \xe9 aplicado a um sistema com 5 par\xe2metros, cada um com 3 valores poss\xedveis. Se todas as combina\xe7\xf5es fossem testadas, seriam 3\u2075=243 casos. Para que serve o pairwise?","options":["A) Para testar todas as combina\xe7\xf5es poss\xedveis sistematicamente","B) Para reduzir o n\xfamero de casos de teste, garantindo que cada par de valores apare\xe7a pelo menos uma vez","C) Para testar apenas os valores-limite de cada par\xe2metro","D) Para automatizar a gera\xe7\xe3o de dados de teste"],"correctAnswer":1,"explanation":"O teste de pares (pairwise ou all-pairs) garante que cada combina\xe7\xe3o de 2 par\xe2metros seja testada pelo menos uma vez, reduzindo drasticamente o n\xfamero de casos (de 243 para ~25 aprox.), mantendo uma boa detec\xe7\xe3o de defeitos.","id":439},{"chapter":1,"topic":"Fundamentos del Testing","question":"Qual das seguintes atividades \xe9 responsabilidade do Gerente de Teste (Test Manager) e n\xe3o do testador individual?","options":["A) Executar casos de teste","B) Relatar defeitos encontrados","C) Coordenar a estrat\xe9gia de teste e comunicar o status ao projeto","D) Projetar dados de teste espec\xedficos"],"correctAnswer":2,"explanation":"O Gerente de Teste coordena, planeja, monitora e controla as atividades de teste, define a estrat\xe9gia e comunica o progresso. Os testadores individuais executam, projetam casos e relatam defeitos.","id":440},{"chapter":3,"topic":"Pruebas Est\xe1ticas","question":"Qual dos seguintes defeitos tem maior probabilidade de ser encontrado por meio de an\xe1lise est\xe1tica em vez de testes din\xe2micos?","options":["A) Um c\xe1lculo que retorna o resultado incorreto sob condi\xe7\xf5es espec\xedficas","B) Uma vari\xe1vel que pode ser nula (null pointer) em um determinado caminho do c\xf3digo nunca alcan\xe7ado em testes din\xe2micos","C) Um bot\xe3o da UI que n\xe3o funciona no Firefox","D) Um tempo de resposta lento sob alta carga"],"correctAnswer":1,"explanation":"A an\xe1lise est\xe1tica pode detectar poss\xedveis exce\xe7\xf5es de ponteiro nulo (null pointer), c\xf3digo morto ou caminhos nunca executados que os testes din\xe2micos n\xe3o cobrem. \xc9 especialmente \xfatil para defeitos em caminhos de c\xf3digo raramente executados.","id":441},{"chapter":2,"topic":"Testing a lo largo del SDLC","question":"O que s\xe3o os \'crit\xe9rios de entrada\' (entry criteria) no processo de teste?","options":["A) Os requisitos que o software deve cumprir para ser lan\xe7ado no mercado","B) As condi\xe7\xf5es que devem ser atendidas antes que uma atividade de teste possa come\xe7ar","C) Os crit\xe9rios para aceitar um novo testador na equipe","D) As m\xe9tricas de cobertura m\xednima para concluir os testes"],"correctAnswer":1,"explanation":"Os crit\xe9rios de entrada definem as pr\xe9-condi\xe7\xf5es que devem ser atendidas para iniciar uma fase ou atividade de teste, por exemplo: software compilado sem erros, ambiente dispon\xedvel, dados de teste preparados.","id":442},{"chapter":5,"topic":"Gesti\xf3n de las Actividades de Prueba","question":"Qual \xe9 o objetivo do \'relat\xf3rio de resumo de teste\' (test summary report) ao final de uma fase?","options":["A) Listar todos os casos de teste que ser\xe3o executados","B) Comunicar os resultados, m\xe9tricas, defeitos e avalia\xe7\xe3o dos crit\xe9rios de sa\xedda aos stakeholders","C) Descrever as t\xe9cnicas de modelagem de teste utilizadas","D) Definir o or\xe7amento para a pr\xf3xima fase de testes"],"correctAnswer":1,"explanation":"O relat\xf3rio de resumo de teste comunica aos stakeholders o resultado dos testes: casos executados/passados/falhados, defeitos encontrados, cobertura alcan\xe7ada e a avalia\xe7\xe3o dos crit\xe9rios de sa\xedda (exit criteria).","id":443},{"chapter":6,"topic":"Herramientas de Prueba","question":"Qual dos seguintes \xe9 um benef\xedcio REAL da automa\xe7\xe3o de testes?","options":["A) Elimina completamente a necessidade de testes manuais","B) Permite executar a regress\xe3o de forma frequente e consistente, com menor esfor\xe7o por execu\xe7\xe3o ap\xf3s o investimento inicial","C) Encontra mais tipos de defeitos do que os testes manuais","D) \xc9 sempre rent\xe1vel independentemente do tipo de projeto"],"correctAnswer":1,"explanation":"A automa\xe7\xe3o permite executar a regress\xe3o repetidamente com consist\xeancia e menor esfor\xe7o por ciclo. Ela n\xe3o elimina os testes manuais, nem sempre \xe9 rent\xe1vel e os humanos detectam alguns defeitos que a automa\xe7\xe3o n\xe3o percebe.","id":444},{"chapter":4,"topic":"T\xe9cnicas de An\xe1lisis y Dise\xf1o de Pruebas","question":"Qual das seguintes t\xe9cnicas \xe9 de \'caixa branca\' (white-box)?","options":["A) Parti\xe7\xe3o de equival\xeancia","B) An\xe1lise de valor-limite","C) Cobertura de comandos (senten\xe7as)","D) Tabelas de decis\xe3o"],"correctAnswer":2,"explanation":"As t\xe9cnicas de caixa branca (estrutura) s\xe3o baseadas no c\xf3digo interno: cobertura de comandos, de ramos, de condi\xe7\xf5es. As outras op\xe7\xf5es (PE, AVL, tabelas de decis\xe3o) s\xe3o t\xe9cnicas de caixa preta baseadas em especifica\xe7\xf5es.","id":445},{"chapter":1,"topic":"Fundamentos del Testing","question":"De acordo com o ISTQB CTFL v4.0, quais s\xe3o os 7 princ\xedpios de teste?","options":["A) O teste mostra a presen\xe7a de defeitos; o teste exaustivo \xe9 imposs\xedvel; testes precoces; agrupamento de defeitos; paradoxo do pesticida; o teste depende do contexto; fal\xe1cia da aus\xeancia de erros","B) O teste elimina todos os defeitos; o teste exaustivo \xe9 poss\xedvel; teste no final; defeitos uniformes; o teste n\xe3o depende do contexto","C) H\xe1 apenas 4 princ\xedpios no ISTQB v4.0","D) Os 7 princ\xedpios incluem: automa\xe7\xe3o obrigat\xf3ria, teste \xe1gil, CI/CD, shift-left, shift-right, DevOps e TDD"],"correctAnswer":0,"explanation":"Os 7 princ\xedpios do ISTQB s\xe3o: 1) O teste mostra a presen\xe7a de defeitos 2) O teste exaustivo \xe9 imposs\xedvel 3) Testes precoces economizam tempo e dinheiro 4) Agrupamento de defeitos 5) Paradoxo do pesticida 6) O teste depende do contexto 7) Fal\xe1cia da aus\xeancia de erros (defeitos).","id":446},{"chapter":2,"topic":"Testing a lo largo del SDLC","question":"O que s\xe3o \'test stubs\' (esbo\xe7os de teste) nos testes de integra\xe7\xe3o?","options":["A) Ferramentas de automa\xe7\xe3o de testes","B) Substitutos de componentes chamados pelo componente sob teste que ainda n\xe3o est\xe3o dispon\xedveis","C) Relat\xf3rios de defeitos encontrados durante a integra\xe7\xe3o","D) Dados de teste gerados automaticamente"],"correctAnswer":1,"explanation":"Os stubs s\xe3o componentes substitutos que simulam m\xf3dulos chamados pelo componente sob teste (componentes \'para baixo\' na hierarquia) que ainda n\xe3o est\xe3o dispon\xedveis durante os testes de integra\xe7\xe3o.","id":447},{"chapter":4,"topic":"T\xe9cnicas de An\xe1lisis y Dise\xf1o de Pruebas","question":"ESTUDO DE CASO: Voc\xea est\xe1 testando um sistema de reservas de hotel. Os pre\xe7os variam de acordo com a temporada: Baixa (jan-mar, out-nov): 80\u20ac/noite; M\xe9dia (abr-jun, set): 120\u20ac/noite; Alta (jul-ago, dez): 200\u20ac/noite. Usando Parti\xe7\xe3o de Equival\xeancia (PE), quantas classes de equival\xeancia v\xe1lidas existem para o pre\xe7o por noite?","options":["A) 2","B) 3","C) 6","D) 12"],"correctAnswer":1,"explanation":"Existem 3 classes de equival\xeancia v\xe1lidas de pre\xe7o: [80\u20ac - baixa temporada], [120\u20ac - m\xe9dia temporada], [200\u20ac - alta temporada]. A Parti\xe7\xe3o de Equival\xeancia (PE) agrupa por comportamento equivalente do sistema, e n\xe3o pelo n\xfamero de meses.","id":448},{"chapter":4,"topic":"T\xe9cnicas de An\xe1lisis y Dise\xf1o de Pruebas","question":"ESTUDO DE CASO: Sistema de vota\xe7\xe3o online. Condi\xe7\xf5es de voto: (1) Cidad\xe3o registrado, (2) Maior de 18 anos, (3) Ainda n\xe3o votou. S\xf3 pode votar se cumprir as 3. Projete a tabela de decis\xe3o m\xednima. Quantas regras distintas de comportamento (n\xe3o regras imposs\xedveis) existem?","options":["A) 2","B) 3","C) 4","D) 8"],"correctAnswer":3,"explanation":"Com 3 condi\xe7\xf5es booleanas, existem 2\xb3=8 combina\xe7\xf5es. Apenas 1 combina\xe7\xe3o (V, V, V) permite votar; as outras 7 o negam. Existem 8 regras poss\xedveis que descrevem os comportamentos distintos do sistema.","id":449},{"chapter":4,"topic":"T\xe9cnicas de An\xe1lisis y Dise\xf1o de Pruebas","question":"CASO PR\xc1TICO: Testes de um sem\xe1foro de pedestres. Estados: VERMELHO_PEDESTRE, VERDE_PEDESTRE, PISCANTE. Transi\xe7\xf5es: VERMELHO\u2192VERDE (ap\xf3s 60s), VERDE\u2192PISCANTE (ap\xf3s 25s), PISCANTE\u2192VERMELHO (ap\xf3s 5s). Qual cobertura de 0-switch (todas as transi\xe7\xf5es) \xe9 exigida no m\xednimo?","options":["A) 1 caso de teste","B) 2 casos de teste","C) 3 casos de teste que cubram o ciclo completo","D) 6 casos de teste, um para cada transi\xe7\xe3o poss\xedvel"],"correctAnswer":2,"explanation":"A cobertura de 0-switches exige que cada transi\xe7\xe3o v\xe1lida seja exercida pelo menos uma vez. Com 3 transi\xe7\xf5es em um ciclo (V\u2192Ve\u2192P\u2192V), 1 caso que percorra o ciclo completo cobre todas elas. Na pr\xe1tica, m\xfaltiplos casos s\xe3o usados para variantes.","id":450},{"chapter":5,"topic":"Gesti\xf3n de las Actividades de Prueba","question":"CASO PR\xc1TICO: Voc\xea tem 100 casos de teste para executar em 5 dias. Ap\xf3s 3 dias, voc\xea executou 50 casos, encontrou 15 defeitos (5 cr\xedticos), e a equipe de desenvolvimento corrigiu 8. Os crit\xe9rios de sa\xedda exigem: 90% de execu\xe7\xe3o, 0 defeitos cr\xedticos abertos. Qual \xe9 a sua situa\xe7\xe3o?","options":["A) Pode liberar: voc\xea cumpriu os crit\xe9rios de sa\xedda","B) N\xe3o pode liberar: faltam casos de teste e h\xe1 defeitos cr\xedticos abertos","C) Pode liberar porque voc\xea encontrou e corrigiu a maioria dos defeitos","D) Deve escalar ao cliente para que ele decida se libera ou n\xe3o"],"correctAnswer":1,"explanation":"Voc\xea n\xe3o atende aos crit\xe9rios de sa\xedda: tem apenas 50% de execu\xe7\xe3o (precisa de 90%) e ainda h\xe1 5-8=m\xe1ximo 7... os 5 cr\xedticos continuam abertos se apenas 8 de 15 foram corrigidos (mistura). Com defeitos cr\xedticos abertos, os crit\xe9rios de sa\xedda (exit criteria) n\xe3o s\xe3o atendidos.","id":451},{"chapter":5,"topic":"Gesti\xf3n de las Actividades de Prueba","question":"CASO PR\xc1TICO: Sua equipe identificou os seguintes riscos de produto: R1(prob=Alta, impacto=Alto), R2(prob=Baixa, impacto=Alto), R3(prob=Alta, impacto=Baixo), R4(prob=Baixa, impacto=Baixo). Usando testes baseados em risco, em qual ordem voc\xea prioriza os testes?","options":["A) R4, R3, R2, R1","B) R1, R2, R3, R4","C) R1, R3, R2, R4","D) R2, R1, R4, R3"],"correctAnswer":2,"explanation":"O n\xedvel de risco = probabilidade \xd7 impacto. R1(A\xd7A=muito alto), R3(A\xd7B=m\xe9dio-alto), R2(B\xd7A=m\xe9dio-alto), R4(B\xd7B=baixo). R1 primeiro, depois R3 e R2 (n\xedvel semelhante), por fim R4. A ordem correta \xe9 R1, R3, R2, R4.","id":452},{"chapter":3,"topic":"Pruebas Est\xe1ticas","question":"CASO PR\xc1TICO: Em uma revis\xe3o de especifica\xe7\xe3o de requisitos voc\xea encontra: \'O sistema dever\xe1 processar as transa\xe7\xf5es rapidamente e a interface dever\xe1 ser amig\xe1vel\'. Quais tipos de defeitos de requisitos existem a\xed?","options":["A) Apenas ambiguidade","B) Ambiguidade (\'rapidamente\', \'amig\xe1vel\') e falta de testabilidade (n\xe3o s\xe3o verific\xe1veis): n\xe3o s\xe3o mensur\xe1veis nem test\xe1veis","C) Contradi\xe7\xe3o entre requisitos","D) Requisitos duplicados"],"correctAnswer":1,"explanation":"\'Rapidamente\' e \'amig\xe1vel\' s\xe3o termos amb\xedguos e n\xe3o verific\xe1veis. Bons requisitos devem ser espec\xedficos e mensur\xe1veis (ex: \'processar em <2s\', \'pontua\xe7\xe3o SUS>75\'). Este \xe9 o defeito mais comum em revis\xf5es de requisitos.","id":453},{"chapter":1,"topic":"Fundamentos del Testing","question":"CASO PR\xc1TICO: A equipe executou 500 testes e encontrou 0 defeitos. O product owner quer liberar o software afirmando que \'est\xe1 livre de bugs\'. Qual \xe9 a sua resposta baseada nos princ\xedpios do ISTQB?","options":["A) Voc\xea concorda, 500 testes sem defeitos \xe9 evid\xeancia suficiente","B) Os testes apenas mostram que n\xe3o foram encontrados defeitos com esse conjunto de testes; n\xe3o podem demonstrar sua aus\xeancia total (Princ\xedpio 1). Liberar tem risco residual","C) Deve adicionar mais 500 testes para ter certeza","D) Solicitar testes exaustivos de todos os caminhos poss\xedveis"],"correctAnswer":1,"explanation":"Princ\xedpio 1 do ISTQB: \'Os testes mostram a presen\xe7a de defeitos, n\xe3o a sua aus\xeancia\'. 0 defeitos em 500 testes n\xe3o garante um software livre de bugs, apenas que esse conjunto de testes n\xe3o os encontrou. Sempre existe risco residual.","id":454},{"chapter":2,"topic":"Testing a lo largo del SDLC","question":"CASO PR\xc1TICO: Um sistema de e-commerce tem 3 n\xedveis: Frontend (React), Backend API (Java), Banco de dados (PostgreSQL). Ao testar a fun\xe7\xe3o \'adicionar ao carrinho\', ela falha. O backend retorna erro 500. Que tipo de teste de integra\xe7\xe3o voc\xea precisa?","options":["A) Teste de componente do frontend","B) Teste de integra\xe7\xe3o entre frontend e backend API para verificar o contrato da interface","C) Teste de sistema end-to-end completo","D) Teste de aceite do usu\xe1rio (UAT)"],"correctAnswer":1,"explanation":"O erro 500 do backend indica uma falha na interface entre frontend e backend. O teste de integra\xe7\xe3o de componentes verifica as interfaces e contratos entre os m\xf3dulos integrados, que \xe9 exatamente o que voc\xea precisa diagnosticar.","id":455},{"chapter":6,"topic":"Herramientas de Prueba","question":"CASO PR\xc1TICO: Sua empresa quer adotar uma ferramenta de automa\xe7\xe3o de testes de API. A equipe avalia: custo, curva de aprendizado, integra\xe7\xe3o com CI/CD, suporte a protocolos REST/SOAP e manutenibilidade. Qual \xe9 o fator MAIS cr\xedtico para garantir o sucesso a longo prazo?","options":["A) O menor custo de licen\xe7a","B) A facilidade de manuten\xe7\xe3o e a integra\xe7\xe3o com o pipeline CI/CD existente","C) Que suporte o maior n\xfamero de protocolos poss\xedvel","D) Que tenha a interface mais intuitiva"],"correctAnswer":1,"explanation":"A longo prazo, a manutenibilidade dos scripts e a integra\xe7\xe3o com CI/CD s\xe3o cr\xedticas. Testes dif\xedceis de manter s\xe3o abandonados. Sem integra\xe7\xe3o no pipeline, a automa\xe7\xe3o n\xe3o agrega valor cont\xednuo.","id":456},{"chapter":4,"topic":"T\xe9cnicas de An\xe1lisis y Dise\xf1o de Pruebas","question":"CASO PR\xc1TICO: Testes de um formul\xe1rio de registro. Campos: nome (obrigat\xf3rio), email (formato v\xe1lido), senha (8-20 caracteres, pelo menos 1 mai\xfascula). Usando Parti\xe7\xe3o de Equival\xeancia (EP), quantas classes de equival\xeancia existem APENAS para o campo senha?","options":["A) 2 (v\xe1lida e inv\xe1lida)","B) 4 (v\xe1lida; inv\xe1lida por comprimento curto; inv\xe1lida por comprimento longo; inv\xe1lida por n\xe3o ter mai\xfascula)","C) 3 (curta, v\xe1lida, longa)","D) 6 (todas as combina\xe7\xf5es de comprimento e formato)"],"correctAnswer":1,"explanation":"Para senha: 1)V\xe1lida (8-20 caracteres + mai\xfascula), 2)Inv\xe1lida-curta (<8 caracteres), 3)Inv\xe1lida-longa (>20 caracteres), 4)Inv\xe1lida-sem mai\xfascula (comprimento OK mas sem mai\xfascula). S\xe3o 4 classes distintas com comportamento diferente do sistema.","id":457},{"chapter":3,"topic":"Pruebas Est\xe1ticas","question":"CASO PR\xc1TICO: Sua organiza\xe7\xe3o implementa revis\xf5es de c\xf3digo obrigat\xf3rias. A equipe de desenvolvimento reclama que elas tornam o processo mais lento. Qual \xe9 o argumento MAIS s\xf3lido para justificar as revis\xf5es?","options":["A) S\xe3o obrigat\xf3rias por norma, n\xe3o h\xe1 alternativa","B) O custo de corrigir defeitos encontrados em revis\xe3o \xe9 significativamente menor do que corrigi-los em produ\xe7\xe3o","C) As revis\xf5es melhoram o moral da equipe","D) A ferramenta de revis\xe3o foi paga e precisa ser amortizada"],"correctAnswer":1,"explanation":"O argumento econ\xf4mico \xe9 o mais s\xf3lido: encontrar um defeito em revis\xe3o de c\xf3digo custa ~1x; em testes de sistema ~10x; em produ\xe7\xe3o ~100x. As revis\xf5es t\xeam o maior ROI na detec\xe7\xe3o precoce de defeitos.","id":458},{"chapter":5,"topic":"Gesti\xf3n de las Actividades de Prueba","question":"CASO PR\xc1TICO: Voc\xea est\xe1 gerenciando os testes de um app mobile. A 3 dias da release, sua equipe encontra um defeito grave no fluxo de pagamento. A corre\xe7\xe3o do desenvolvedor levar\xe1 2 dias. Qual \xe9 o processo correto segundo o ISTQB?","options":["A) Cancelar a release automaticamente","B) Registrar o defeito, avaliar o impacto e risco, e escalar para uma decis\xe3o de neg\xf3cio sobre adiar ou liberar com um workaround documentado","C) O testador deve corrigir o defeito diretamente","D) Ignorar o defeito se o cliente ainda n\xe3o o reportou"],"correctAnswer":1,"explanation":"O processo correto \xe9: documentar o defeito (bug report), analisar impacto/risco e escalar aos stakeholders com informa\xe7\xf5es para que decidam. N\xe3o \xe9 decis\xe3o unilateral do testador adiar ou liberar; \xe9 uma decis\xe3o de neg\xf3cio informada.","id":459},{"chapter":1,"topic":"Fundamentos del Testing","question":"O que descreve melhor o conceito de \'shift-left\' em testes?","options":["A) Mover os testes para o lado esquerdo da tela","B) Iniciar atividades de teste mais cedo no ciclo de vida de desenvolvimento","C) Reduzir o n\xfamero de testadores na equipe","D) Automatizar todos os testes de regress\xe3o"],"correctAnswer":1,"explanation":"Shift-left significa antecipar (mover para a esquerda na linha do tempo) as atividades de teste: revisar requisitos, fazer testes de componente mais cedo, usar TDD/ATDD, etc. O objetivo \xe9 detectar defeitos antes para reduzir custos.","id":460},{"chapter":2,"topic":"Testing a lo largo del SDLC","question":"Qual \xe9 o objetivo principal dos testes de aceite do usu\xe1rio (UAT)?","options":["A) Verificar se o c\xf3digo n\xe3o tem erros de sintaxe","B) Confirmar que o sistema atende \xe0s necessidades do neg\xf3cio e \xe9 adequado para ser usado pelos usu\xe1rios finais","C) Testar o desempenho do sistema sob carga","D) Verificar se os componentes se integram corretamente"],"correctAnswer":1,"explanation":"O UAT verifica se o sistema atende aos requisitos de neg\xf3cio e \xe0s necessidades dos usu\xe1rios. Os usu\xe1rios ou representantes de neg\xf3cios confirmam se o sistema \xe9 adequado para o seu prop\xf3sito antes da aceita\xe7\xe3o formal.","id":461},{"chapter":4,"topic":"T\xe9cnicas de An\xe1lisis y Dise\xf1o de Pruebas","question":"Uma especifica\xe7\xe3o diz: \'Se o usu\xe1rio \xe9 premium E tem mais de 1 ano, aplica-se 20% de desconto\'. Qual t\xe9cnica de modelagem de testes \xe9 MAIS diretamente aplic\xe1vel a esta regra de neg\xf3cio?","options":["A) An\xe1lise de valor limite","B) Tabelas de decis\xe3o","C) Transi\xe7\xe3o de estado","D) Cobertura de comandos (statement coverage)"],"correctAnswer":1,"explanation":"As tabelas de decis\xe3o s\xe3o ideais para regras de neg\xf3cio com m\xfaltiplas condi\xe7\xf5es e combina\xe7\xf5es (premium: sim/n\xe3o, tempo: >1ano/<=1ano) que determinam diferentes a\xe7\xf5es (desconto ou n\xe3o).","id":462},{"chapter":6,"topic":"Herramientas de Prueba","question":"O que \xe9 um \'framework de automa\xe7\xe3o de testes orientado a palavras-chave\' (keyword-driven)?","options":["A) Um framework onde as palavras-chave s\xe3o senhas de acesso","B) Um framework onde os casos de teste s\xe3o descritos usando palavras-chave de alto n\xedvel que representam a\xe7\xf5es (ex: \'Login\', \'ClickButton\', \'VerifyText\')","C) Um framework apenas para testes de seguran\xe7a","D) Um framework que usa intelig\xeancia artificial para gerar testes"],"correctAnswer":1,"explanation":"O keyword-driven testing usa palavras-chave ou palavras de a\xe7\xe3o que representam opera\xe7\xf5es do sistema. Os casos de teste s\xe3o escritos em tabelas com essas palavras-chave (keywords), separando a modelagem dos testes da sua implementa\xe7\xe3o t\xe9cnica.","id":463},{"chapter":5,"topic":"Gesti\xf3n de las Actividades de Prueba","question":"Qual das seguintes op\xe7\xf5es descreve melhor os \'crit\xe9rios de sa\xedda\' (exit criteria) de uma fase de testes?","options":["A) As condi\xe7\xf5es para come\xe7ar a testar","B) As condi\xe7\xf5es que devem ser atendidas para considerar uma fase de testes conclu\xedda","C) O n\xfamero m\xe1ximo de defeitos permitidos em produ\xe7\xe3o","D) O prazo (deadline) final do projeto"],"correctAnswer":1,"explanation":"Os crit\xe9rios de sa\xedda (exit criteria ou Definition of Done) definem quando uma fase de testes pode ser considerada completa: ex. 95% dos casos executados, 0 defeitos cr\xedticos abertos, cobertura \u226580%.","id":464},{"chapter":3,"topic":"Pruebas Est\xe1ticas","question":"Qual dos seguintes \xe9 um exemplo de t\xe9cnica de an\xe1lise est\xe1tica?","options":["A) Executar o software com dados de teste","B) Usar um linter ou ferramenta de an\xe1lise de c\xf3digo para detectar viola\xe7\xf5es de padr\xf5es","C) Testar a interface de usu\xe1rio manualmente","D) Medir o tempo de resposta do sistema"],"correctAnswer":1,"explanation":"A an\xe1lise est\xe1tica examina o c\xf3digo sem execut\xe1-lo. As ferramentas de linter (como SonarQube, ESLint, Checkstyle) detectam viola\xe7\xf5es de padr\xf5es, c\xf3digo morto, poss\xedveis null pointers, etc., sem executar o programa.","id":465},{"chapter":1,"topic":"Fundamentos del Testing","question":"Qual \xe9 a diferen\xe7a entre verifica\xe7\xe3o e valida\xe7\xe3o em testes?","options":["A) S\xe3o exatamente a mesma coisa","B) Verifica\xe7\xe3o: estamos construindo o produto corretamente? Valida\xe7\xe3o: estamos construindo o produto certo?","C) A verifica\xe7\xe3o \xe9 feita pelos usu\xe1rios; a valida\xe7\xe3o pelos testadores","D) Verifica\xe7\xe3o \xe9 din\xe2mica; valida\xe7\xe3o \xe9 est\xe1tica"],"correctAnswer":1,"explanation":"A verifica\xe7\xe3o comprova que o produto atende \xe0s suas especifica\xe7\xf5es (\'estamos construindo-o da maneira certa?\'). A valida\xe7\xe3o comprova que o produto atende \xe0s necessidades reais do usu\xe1rio (\'estamos construindo o produto certo?\').","id":466},{"chapter":4,"topic":"T\xe9cnicas de An\xe1lisis y Dise\xf1o de Pruebas","question":"O que significa \'cobertura de desvios\' (branch coverage / cobertura de decis\xe3o) de 100%?","options":["A) Que todas as linhas de c\xf3digo foram testadas","B) Que cada decis\xe3o no c\xf3digo assumiu o valor true E false pelo menos uma vez","C) Que todos os poss\xedveis valores de entrada foram testados","D) Que todas as fun\xe7\xf5es do sistema foram executadas"],"correctAnswer":1,"explanation":"100% de cobertura de desvio (ou decis\xe3o) significa que cada resultado poss\xedvel de cada ponto de decis\xe3o (if/else, switch) foi executado pelo menos uma vez: tanto o desvio verdadeiro quanto o falso de cada condi\xe7\xe3o.","id":467},{"id":1001,"chapter":1,"topic":"Fundamentos de Pruebas","question":"Qual dos seguintes \xe9 um objetivo comum dos testes de software?","options":["Confirmar que o software cumpre com os requisitos especificados.","Garantir que n\xe3o haja erros no c\xf3digo-fonte.","Demonstrar que o sistema \xe9 completamente seguro contra ataques externos.","Verificar se todos os usu\xe1rios est\xe3o satisfeitos com o produto."],"correctAnswer":0,"explanation":"Confirmar o cumprimento dos requisitos \xe9 um objetivo comum (Syllabus 1.1). Os testes n\xe3o podem garantir que n\xe3o haja erros (falso), nem que o sistema seja completamente seguro ou que todos fiquem satisfeitos.","source":"Pr\xe1ctica Adicional"},{"id":1002,"chapter":1,"topic":"Fundamentos de Pruebas","question":"Uma empresa de software desenvolve aplicativos para o setor financeiro. A equipe de dire\xe7\xe3o pergunta ao gerente de testes por que os testes s\xe3o essenciais em seu contexto, al\xe9m de encontrar defeitos. Qual das seguintes raz\xf5es descreve MELHOR por que os testes s\xe3o necess\xe1rios neste contexto?","options":["Para demonstrar que o software n\xe3o tem nenhum defeito antes de sua entrega.","Para proporcionar confian\xe7a sobre o n\xedvel de qualidade do software e cumprir com os requisitos regulat\xf3rios do setor.","Para substituir o processo de revis\xe3o de requisitos e reduzir a documenta\xe7\xe3o.","Para garantir que todos os desenvolvedores conhe\xe7am o c\xf3digo do sistema completo."],"correctAnswer":1,"explanation":"No setor financeiro, proporcionar confian\xe7a e cumprir com regulamenta\xe7\xf5es \xe9 vital. Os testes n\xe3o podem demonstrar a aus\xeancia de defeitos (princ\xedpio da fal\xe1cia da aus\xeancia de defeitos).","source":"Pr\xe1ctica Adicional"},{"id":1003,"chapter":1,"topic":"Principios de Prueba","question":"Voc\xea est\xe1 avaliando a qualidade dos testes realizados em um software antes de seu lan\xe7amento. Voc\xea observa que, embora muitos testes tenham sido executados, defeitos significativos ainda persistem. Qual dos sete princ\xedpios de teste se reflete nesta situa\xe7\xe3o?","options":["Testes exaustivos s\xe3o imposs\xedveis","Agrupamento de defeitos (Os defeitos se agrupam)","Paradoxo do pesticida (Os testes se desgastam)","Fal\xe1cia da aus\xeancia de defeitos"],"correctAnswer":1,"explanation":"Os defeitos tendem a se agrupar em m\xf3dulos espec\xedficos (Agrupamento de defeitos ou Princ\xedpio de Pareto).","source":"Pr\xe1ctica Adicional"},{"id":1004,"chapter":5,"topic":"Planificaci\xf3n de Pruebas","question":"Voc\xea est\xe1 participando de um projeto de software que desenvolve uma plataforma de e-learning. A equipe decidiu realizar testes de regress\xe3o na vers\xe3o atual do sistema. Qual das seguintes atividades \xe9 realizada durante a fase de planejamento de testes?","options":["Definir quais funcionalidades ser\xe3o testadas na pr\xf3xima itera\xe7\xe3o.","Executar casos de teste para verificar se a funcionalidade da plataforma de e-learning funciona.","Revisar os resultados dos testes e documentar os defeitos encontrados.","Analisar os requisitos do sistema para identificar casos de teste."],"correctAnswer":0,"explanation":"O planejamento inclui definir o escopo, ou seja, o que ser\xe1 testado. Executar \xe9 a fase de execu\xe7\xe3o; analisar \xe9 da an\xe1lise; revisar os resultados faz parte do encerramento ou monitoramento.","source":"Pr\xe1ctica Adicional"},{"id":1006,"chapter":5,"topic":"Roles en las Pruebas","question":"Qual das seguintes atividades \xe9 T\xcdPICA de um papel de gerente de testes?","options":["Desenvolver casos de teste","Gerenciar a equipe de testes","Executar testes automatizados","Realizar an\xe1lise de defeitos"],"correctAnswer":1,"explanation":"O gerente de testes (Test Manager) supervisiona, planeja e gerencia. Desenvolver e executar casos de teste costuma ser o papel do testador (tester).","source":"Pr\xe1ctica Adicional"},{"id":1007,"chapter":1,"topic":"Habilidades del Probador","question":"Qual das seguintes habilidades \xe9 essencial para um testador ao avaliar a qualidade de um produto de software?  \\n  \\ni. Comunica\xe7\xe3o efetiva  \\n  \\nii. Conhecimento t\xe9cnico  \\n  \\niii. Capacidade de an\xe1lise  \\n  \\niv. Gerenciamento do tempo  ","options":["i e ii s\xe3o essenciais; iii e iv n\xe3o s\xe3o","iii e iv s\xe3o essenciais; i e ii n\xe3o s\xe3o","ii e iii s\xe3o essenciais; i e iv n\xe3o s\xe3o","i e iii s\xe3o essenciais; ii e iv n\xe3o s\xe3o"],"correctAnswer":3,"explanation":"A comunica\xe7\xe3o efetiva e a capacidade de an\xe1lise (i e iii) s\xe3o primordiais segundo o syllabus para reportar problemas e modelar testes, embora ii e iv tamb\xe9m ajudem.","source":"Pr\xe1ctica Adicional"},{"id":1008,"chapter":1,"topic":"Enfoque de Equipo Completo","question":"Qual \xe9 uma vantagem principal da abordagem de equipe completa (whole-team approach) no processo de desenvolvimento de software?","options":["Promove a comunica\xe7\xe3o isolada entre os testadores e os desenvolvedores.","Facilita a colabora\xe7\xe3o entre todas as partes interessadas desde o in\xedcio do projeto.","Aumenta a dura\xe7\xe3o dos testes por exigir revis\xf5es extensas.","Elimina a necessidade de uma estrat\xe9gia de testes bem definida."],"correctAnswer":1,"explanation":"A abordagem de equipe inteira (whole-team) fomenta a colabora\xe7\xe3o m\xfatua de todos os perfis desde o in\xedcio.","source":"Pr\xe1ctica Adicional"},{"id":1009,"chapter":2,"topic":"Pruebas en el SDLC","question":"Qual das seguintes afirma\xe7\xf5es descreve melhor a import\xe2ncia dos testes no ciclo de vida de desenvolvimento de software (SDLC)?","options":["Os testes s\xe3o realizados apenas no final do SDLC para verificar o produto final.","Os testes devem ser planejados e realizados ao longo de todo o SDLC para detectar problemas precocemente.","Os testes s\xe3o opcionais e s\xf3 s\xe3o necess\xe1rios se o cliente solicitar.","Os testes focam unicamente na funcionalidade do software e n\xe3o em outros aspectos."],"correctAnswer":1,"explanation":"Realizar testes ao longo de todo o SDLC (shift-left) \xe9 fundamental para detectar e corrigir problemas o mais cedo poss\xedvel.","source":"Pr\xe1ctica Adicional"},{"id":1010,"chapter":2,"topic":"TDD vs ATDD","question":"Qual das seguintes descri\xe7\xf5es se relaciona MELHOR com o desenvolvimento orientado a testes (TDD)?","options":["No TDD, os testes s\xe3o escritos antes do c\xf3digo e s\xe3o usados para guiar o desenvolvimento.","No TDD, os desenvolvedores criam primeiro o c\xf3digo e depois os casos de teste correspondentes.","No TDD, os testes s\xe3o realizados apenas no final do ciclo de desenvolvimento para verificar o produto.","No TDD, usam-se casos de teste de aceite como base para o design do c\xf3digo."],"correctAnswer":0,"explanation":"TDD (Test-Driven Development) consiste em escrever os testes (unit\xe1rios) antes de escrever o c\xf3digo-fonte que os fa\xe7a passar.","source":"Pr\xe1ctica Adicional"},{"id":1011,"chapter":2,"topic":"Shift-Left","question":"Qual das seguintes afirma\xe7\xf5es descreve melhor como a abordagem de \\"deslocamento para a esquerda\\" (shift-left) pode melhorar a qualidade do software?","options":["Permite a detec\xe7\xe3o e corre\xe7\xe3o de defeitos em est\xe1gios posteriores do ciclo de vida de desenvolvimento.","Facilita a integra\xe7\xe3o cont\xednua e a entrega antecipada de valor ao cliente ao encontrar erros cedo.","Aumenta a complexidade do processo de desenvolvimento ao introduzir mais testes nas fases iniciais.","Reduz a necessidade de documenta\xe7\xe3o ao aplicar mais testes de usu\xe1rio no final do ciclo."],"correctAnswer":1,"explanation":"Mover os testes para a esquerda permite encontrar erros antes, melhorando a integra\xe7\xe3o e reduzindo custos.","source":"Pr\xe1ctica Adicional"},{"id":1012,"chapter":2,"topic":"Retrospectivas","question":"Qual \xe9 um benef\xedcio principal de realizar retrospectivas em uma equipe de trabalho?","options":["Permitem \xe0 equipe ignorar os problemas de comunica\xe7\xe3o que podem surgir durante o projeto.","Ajudam a identificar e promover pr\xe1ticas que foram eficazes no passado e que podem ser aplicadas em ciclos futuros.","S\xe3o uma formalidade que deve ser cumprida sem gerar um impacto real no projeto.","Facilitam que os l\xedderes da equipe assumam o controle total do processo sem considerar opini\xf5es."],"correctAnswer":1,"explanation":"As retrospectivas s\xe3o o motor da melhoria cont\xednua (identificar o que funcionou e o que n\xe3o funcionou).","source":"Pr\xe1ctica Adicional"},{"id":1013,"chapter":2,"topic":"Niveles de Prueba","question":"Quais das seguintes afirma\xe7\xf5es descrevem adequadamente os n\xedveis de teste e suas abordagens?\\n\\n1. Valida a funcionalidade completa em produ\xe7\xe3o simulada\\n2. Verifica se m\xf3dulos individuais funcionam\\n3. Garante que os m\xf3dulos se integrem juntos\\n4. Valida os requisitos a partir da perspectiva do usu\xe1rio final\\n\\nA. Testes de sistema  \\nB. Testes de componente  \\nC. Testes de integra\xe7\xe3o  \\nD. Testes de aceite","options":["1A, 2B, 3C, 4D","1C, 2A, 3D, 4B","1D, 2C, 3A, 4B","1B, 2D, 3A, 4C"],"correctAnswer":0,"explanation":"1: Sistema (A), 2: Componente (B), 3: Integra\xe7\xe3o (C), 4: Aceite (D).","source":"Pr\xe1ctica Adicional"},{"id":1014,"chapter":2,"topic":"Regresi\xf3n vs Confirmaci\xf3n","question":"Foram executados os seguintes casos de teste:  \\n- TC1 Falhou  \\n- TC2 Passou  \\n- TC3 Falhou  \\n  \\nAp\xf3s as corre\xe7\xf5es, TC1, TC2 e TC3 s\xe3o executados novamente. Quais dessas execu\xe7\xf5es s\xe3o consideradas testes de regress\xe3o?","options":["TC1","TC2","TC3","TC1 e TC3"],"correctAnswer":1,"explanation":"A execu\xe7\xe3o do TC2 \xe9 regress\xe3o, pois ele funcionava antes e se verifica que as altera\xe7\xf5es n\xe3o o quebraram. TC1 e TC3 s\xe3o testes de confirma\xe7\xe3o (reteste).","source":"Pr\xe1ctica Adicional"},{"id":1015,"chapter":3,"topic":"Pruebas Est\xe1ticas","question":"Qual das seguintes afirma\xe7\xf5es \xe9 VERDADEIRA sobre os testes est\xe1ticos?","options":["Os testes est\xe1ticos ajudam a reduzir o tempo de desenvolvimento ao encontrar defeitos nos est\xe1gios iniciais.","Os testes est\xe1ticos sempre detectam todos os tipos de defeitos no c\xf3digo-fonte.","Os testes est\xe1ticos s\xe3o mais eficazes que os din\xe2micos na valida\xe7\xe3o de funcionalidade.","Os testes est\xe1ticos n\xe3o podem ser usados para melhorar a qualidade da documenta\xe7\xe3o."],"correctAnswer":0,"explanation":"Encontrar problemas de forma est\xe1tica (sem executar o c\xf3digo) economiza muito dinheiro e tempo.","source":"Pr\xe1ctica Adicional"},{"id":1016,"chapter":3,"topic":"Retroalimentaci\xf3n Temprana","question":"Que vantagem proporciona o feedback (retroalimenta\xe7\xe3o) antecipado e frequente das partes interessadas durante o desenvolvimento de software?","options":["Fomenta a inova\xe7\xe3o nas solu\xe7\xf5es propostas.","Reduz a possibilidade de retrabalho ao identificar problemas a tempo.","Aumenta a dura\xe7\xe3o do ciclo de vida do produto.","Melhora a satisfa\xe7\xe3o da equipe de desenvolvimento."],"correctAnswer":1,"explanation":"O feedback cont\xednuo evita que o produto errado seja constru\xeddo, reduzindo retrabalho custoso.","source":"Pr\xe1ctica Adicional"},{"id":1017,"chapter":3,"topic":"Revisiones","question":"Em sua organiza\xe7\xe3o: N\xe3o h\xe1 o papel de moderador. O objetivo \xe9 encontrar defeitos e melhorar. Discute-se abertamente. N\xe3o \xe9 necess\xe1ria documenta\xe7\xe3o formal no final. Que tipo de revis\xe3o \xe9 essa?","options":["Revis\xe3o informal","Revis\xe3o t\xe9cnica","Inspe\xe7\xe3o","Revis\xe3o guiada (Walkthrough)"],"correctAnswer":0,"explanation":"Sem moderador, sem documenta\xe7\xe3o formal e orientada a melhorar com discuss\xe3o aberta: Revis\xe3o informal.","source":"Pr\xe1ctica Adicional"},{"id":1018,"chapter":3,"topic":"Revisiones","question":"Qual dos seguintes fatores \xe9 essencial para garantir a efic\xe1cia de uma revis\xe3o?","options":["Contar com um facilitador que guie o processo de revis\xe3o.","Permitir que apenas os especialistas participem em todas as revis\xf5es.","Realizar a revis\xe3o de forma improvisada, sem prepara\xe7\xe3o pr\xe9via.","Limitar o tempo de discuss\xe3o para n\xe3o se prolongar muito."],"correctAnswer":0,"explanation":"Um facilitador ou outros pap\xe9is claros melhoram o sucesso. No entanto, em algumas metodologias outra chave \xe9 a \'prepara\xe7\xe3o pr\xe9via\'.","source":"Pr\xe1ctica Adicional"},{"id":1019,"chapter":4,"topic":"Caja Blanca","question":"Qual das seguintes afirma\xe7\xf5es descreve melhor uma t\xe9cnica de teste de caixa branca?","options":["Baseia-se no conhecimento do funcionamento interno do software e de sua estrutura de c\xf3digo.","\xc9 usada principalmente para avaliar a experi\xeancia do usu\xe1rio e a usabilidade do sistema.","Os casos de teste s\xe3o modelados sem levar em conta a l\xf3gica interna do sistema.","Concentra-se na identifica\xe7\xe3o de defeitos nos requisitos atrav\xe9s de testes de interface."],"correctAnswer":0,"explanation":"Caixa branca baseia-se na estrutura interna (c\xf3digo, arquitetura).","source":"Pr\xe1ctica Adicional"},{"id":1020,"chapter":4,"topic":"Partici\xf3n de Equivalencia","question":"Um sistema de notas aceita pontua\xe7\xf5es de 0 a 100. Reprovado: 0-59, Aprovado: 60-69, Bom: 70-89, Excelente: 90-100. Usando Parti\xe7\xe3o de Equival\xeancia, qual \xe9 o n\xfamero M\xcdNIMO de casos de teste para alcan\xe7ar 100% de cobertura das parti\xe7\xf5es V\xc1LIDAS?","options":["3","4","5","6"],"correctAnswer":1,"explanation":"Existem 4 parti\xe7\xf5es v\xe1lidas: [0,59], [60,69], [70,89], [90,100]. \xc9 necess\xe1rio 1 caso para cada uma, portanto 4 casos.","source":"Pr\xe1ctica Adicional"},{"id":1021,"chapter":4,"topic":"An\xe1lisis de Valores L\xedmite","question":"O campo \'Idade\' aceita de 16 a 65 anos. Seu conjunto inclui: 15, 16, 17, 64, 65, 66. Que porcentagem de cobertura de An\xe1lise de Valor Limite (BVA) de 3 valores voc\xea alcan\xe7a?","options":["50%","67%","83%","100%"],"correctAnswer":3,"explanation":"No BVA de 3 valores, um limite \'X\' precisa de X-1, X, X+1. Para 16 voc\xea precisa de 15,16,17. Para 65 voc\xea precisa de 64,65,66. Voc\xea tem todos eles, cobertura de 100%.","source":"Pr\xe1ctica Adicional"},{"id":1022,"chapter":4,"topic":"Tabla de Decisiones","question":"Em uma tabela de decis\xe3o para empr\xe9stimos voc\xea tem 4 condi\xe7\xf5es. Se quisesse minimizar a tabela devido \xe0 grande quantidade de combina\xe7\xf5es, qual seria a melhor estrat\xe9gia?","options":["Eliminar todas as condi\xe7\xf5es menos importantes","Usar uma abordagem baseada em risco para reduzir as regras a testar","Combinar todas as condi\xe7\xf5es em uma \xfanica regra","Criar m\xfaltiplas tabelas pequenas e separadas"],"correctAnswer":1,"explanation":"Quando uma tabela \xe9 muito grande (ex: 2^N regras), a estrat\xe9gia sugerida pelo ISTQB \xe9 minimizar mediante uma abordagem de riscos.","source":"Pr\xe1ctica Adicional"},{"id":1023,"chapter":4,"topic":"Transici\xf3n de Estados","question":"Qual das seguintes afirma\xe7\xf5es sobre os crit\xe9rios de cobertura em testes de transi\xe7\xe3o de estado \xe9 CORRETA?","options":["A cobertura de todos os estados \xe9 mais forte do que a cobertura de transi\xe7\xf5es v\xe1lidas","A cobertura de transi\xe7\xf5es v\xe1lidas garante a cobertura completa de todos os estados","A cobertura de todas as transi\xe7\xf5es inclui apenas transi\xe7\xf5es v\xe1lidas","Para alcan\xe7ar a cobertura de transi\xe7\xf5es v\xe1lidas, deve-se testar apenas uma transi\xe7\xe3o por caso de teste"],"correctAnswer":1,"explanation":"Se voc\xea cobrir todas as transi\xe7\xf5es v\xe1lidas (setas), obrigatoriamente ter\xe1 visitado todos os estados (n\xf3s). Portanto, a Cobertura de Transi\xe7\xf5es V\xe1lidas \xe9 mais forte do que a Cobertura de Estados.","source":"Pr\xe1ctica Adicional"},{"id":1024,"chapter":4,"topic":"Cobertura de Sentencias","question":"Qual das seguintes afirma\xe7\xf5es \xe9 verdadeira em rela\xe7\xe3o \xe0 cobertura de instru\xe7\xf5es em testes de software?","options":["A cobertura de instru\xe7\xf5es garante que todos os casos de teste encontraram defeitos.","Atingir uma cobertura de instru\xe7\xf5es de 100% significa que todas as instru\xe7\xf5es do c\xf3digo foram executadas pelo menos uma vez.","A cobertura de instru\xe7\xf5es \xe9 irrelevante se testes funcionais exaustivos forem realizados.","Uma cobertura de instru\xe7\xf5es de 100% garante que n\xe3o existam loops no c\xf3digo."],"correctAnswer":1,"explanation":"100% de cobertura de instru\xe7\xf5es (statement coverage) significa que cada linha/instru\xe7\xe3o foi executada pelo menos 1 vez.","source":"Pr\xe1ctica Adicional"},{"id":1025,"chapter":4,"topic":"Caja Blanca","question":"Qual das seguintes afirma\xe7\xf5es descreve melhor uma vantagem dos testes caixa branca?","options":["Os testes caixa branca permitem verificar a l\xf3gica interna do c\xf3digo e o seu fluxo de execu\xe7\xe3o.","Os testes caixa branca s\xe3o \xfateis para validar a experi\xeancia do usu\xe1rio na interface gr\xe1fica.","Os testes caixa branca garantem que todos os requisitos funcionais foram implementados corretamente.","Os testes caixa branca s\xe3o sempre mais eficazes que os testes caixa preta sem necessidade de an\xe1lise de design."],"correctAnswer":0,"explanation":"Permitem verificar a l\xf3gica interna, encontrar caminhos mortos (dead code) e comprovar estruturas do c\xf3digo.","source":"Pr\xe1ctica Adicional"},{"id":1026,"chapter":4,"topic":"Predicci\xf3n de Errores","question":"Qual das seguintes afirma\xe7\xf5es SE REFERE \xe0 suposi\xe7\xe3o de erros (error guessing) em um processo de teste?","options":["A suposi\xe7\xe3o de erros baseia-se unicamente em m\xe9tricas quantitativas de defeitos anteriores.","A suposi\xe7\xe3o de erros envolve identificar as \xe1reas do software com maior probabilidade de conter defeitos com base na experi\xeancia.","A suposi\xe7\xe3o de erros exige que os testadores executem testes unit\xe1rios em todas as fun\xe7\xf5es.","A suposi\xe7\xe3o de erros \xe9 um processo que apenas os desenvolvedores podem realizar."],"correctAnswer":1,"explanation":"A Suposi\xe7\xe3o de Erros (Error Guessing) depende imensamente da experi\xeancia do testador para intuir onde os desenvolvedores tipicamente cometeram erros.","source":"Pr\xe1ctica Adicional"},{"id":1027,"chapter":4,"topic":"Pruebas Exploratorias","question":"Uma equipe est\xe1 criando um aplicativo m\xf3vel inovador, e ser\xe3o utilizados testes explorat\xf3rios devido \xe0 falta de documenta\xe7\xe3o. Qual das seguintes afirma\xe7\xf5es sobre os testes explorat\xf3rios \xe9 CORRETA?","options":["Os testes explorat\xf3rios s\xe3o sempre menos eficazes que os testes baseados em requisitos.","Os testes explorat\xf3rios permitem aos testadores adaptarem-se rapidamente a mudan\xe7as no software.","Os testes explorat\xf3rios exigem um plano de teste detalhado antes de serem realizados.","Os testes explorat\xf3rios n\xe3o s\xe3o adequados para aplica\xe7\xf5es complexas."],"correctAnswer":1,"explanation":"S\xe3o flex\xedveis, adaptativos e ideais quando a documenta\xe7\xe3o \xe9 escassa ou sofre muitas mudan\xe7as.","source":"Pr\xe1ctica Adicional"},{"id":1028,"chapter":4,"topic":"Criterios de Aceptaci\xf3n","question":"Qual das seguintes afirma\xe7\xf5es descreve UMA t\xe9cnica adequada para redigir crit\xe9rios de aceite?","options":["Estabelecer crit\xe9rios em forma de perguntas abertas para fomentar a discuss\xe3o.","Utilizar exemplos concretos que ilustrem como se espera que a funcionalidade trabalhe.","Documentar crit\xe9rios em um documento separado para melhorar a organiza\xe7\xe3o.","Redigir crit\xe9rios em uma linguagem t\xe9cnica para garantir precis\xe3o nos detalhes."],"correctAnswer":1,"explanation":"Em abordagens \xe1geis/ATDD, os exemplos concretos (ex. Behavior Driven Development com Dado-Quando-Ent\xe3o / Given-When-Then) s\xe3o a melhor maneira de documentar crit\xe9rios de aceite.","source":"Pr\xe1ctica Adicional"},{"id":1029,"chapter":4,"topic":"ATDD","question":"Uma equipe \xe1gil usa ATDD. Quando s\xe3o criados os casos de teste de aceite na abordagem ATDD?","options":["Depois que o desenvolvedor termina de implementar a hist\xf3ria de usu\xe1rio.","Durante o workshop de especifica\xe7\xe3o, antes que o desenvolvimento comece.","Unicamente durante a fase de testes de regress\xe3o ao final do sprint.","Quando o cliente realiza o teste de aceite do usu\xe1rio (UAT)."],"correctAnswer":1,"explanation":"A chave do Desenvolvimento Orientado a Testes de Aceite (ATDD - Acceptance Test Driven Development) \xe9 redigir o teste de aceite em colabora\xe7\xe3o *antes* de escrever o c\xf3digo.","source":"Pr\xe1ctica Adicional"},{"id":1030,"chapter":5,"topic":"Estimaci\xf3n","question":"Em seu projeto anterior, a propor\xe7\xe3o entre esfor\xe7o de desenvolvimento e esfor\xe7o de teste foi de 5:3. O projeto atual estima 800 dias-pessoa de desenvolvimento. Usando estimativa baseada em propor\xe7\xf5es, qual seria a estimativa do esfor\xe7o de teste?","options":["400 dias-pessoa","480 dias-pessoa","533 dias-pessoa","600 dias-pessoa"],"correctAnswer":1,"explanation":"Regra de 3: Se 5 devs = 3 QA, ent\xe3o 800 devs = X QA. X = (800 * 3) / 5 = 480 dias.","source":"Pr\xe1ctica Adicional"},{"id":1031,"chapter":4,"topic":"Transici\xf3n de Estado","question":"Qual das seguintes afirma\xe7\xf5es sobre os crit\xe9rios de cobertura em testes de transi\xe7\xe3o de estado \xe9 CORRETA?","options":["Cobertura de todos os estados \xe9 mais forte do que a cobertura de transi\xe7\xf5es v\xe1lidas.","Cobertura de transi\xe7\xf5es v\xe1lidas garante a cobertura completa de todos os estados.","Cobertura de todas as transi\xe7\xf5es inclui apenas transi\xe7\xf5es v\xe1lidas.","Para atingir a cobertura de transi\xe7\xf5es v\xe1lidas, deve-se testar apenas uma transi\xe7\xe3o por caso de teste."],"correctAnswer":1,"explanation":"Atingir uma cobertura completa de transi\xe7\xf5es v\xe1lidas garante uma cobertura completa de todos os estados, j\xe1 que para exercitar todas as transi\xe7\xf5es v\xe1lidas \xe9 necess\xe1rio visitar todos os estados.","source":"Errores Reportados - Set 2"},{"id":1032,"chapter":4,"topic":"Cobertura de Sentencias","question":"Qual das seguintes afirma\xe7\xf5es \xe9 verdadeira em rela\xe7\xe3o \xe0 cobertura de instru\xe7\xf5es em testes de software?","options":["A cobertura de instru\xe7\xf5es garante que todos os casos de teste encontraram defeitos.","Atingir uma cobertura de instru\xe7\xf5es de 100% significa que todas as instru\xe7\xf5es do c\xf3digo foram executadas pelo menos uma vez.","A cobertura de instru\xe7\xf5es \xe9 irrelevante se testes funcionais exaustivos forem realizados.","Uma cobertura de instru\xe7\xf5es de 100% garante que n\xe3o existem loops no c\xf3digo."],"correctAnswer":1,"explanation":"Uma cobertura de instru\xe7\xf5es de 100% significa que cada instru\xe7\xe3o no c\xf3digo foi executada pelo menos uma vez durante os testes.","source":"Errores Reportados - Set 2"},{"id":1033,"chapter":4,"topic":"Caja Blanca","question":"Qual das seguintes afirma\xe7\xf5es \xe9 correta a respeito dos testes caixa branca?","options":["Os testes caixa branca concentram-se na funcionalidade do software sem considerar sua estrutura interna.","A an\xe1lise de fluxo de dados \xe9 uma t\xe9cnica utilizada em testes caixa branca para identificar poss\xedveis erros.","Os testes caixa branca s\xe3o menos eficazes que os de caixa preta para detectar defeitos na l\xf3gica de neg\xf3cios.","Os testes caixa branca limitam-se a verificar a correta implementa\xe7\xe3o dos requisitos do usu\xe1rio."],"correctAnswer":1,"explanation":"A an\xe1lise de fluxo de dados \xe9 uma t\xe9cnica de teste caixa branca que ajuda a identificar erros no uso de vari\xe1veis e seu fluxo atrav\xe9s do c\xf3digo.","source":"Errores Reportados - Set 2"},{"id":1034,"chapter":4,"topic":"Criterios de Aceptaci\xf3n","question":"Qual das seguintes afirma\xe7\xf5es descreve de maneira mais adequada como se podem definir os crit\xe9rios de aceite para uma hist\xf3ria de usu\xe1rio?","options":["Especificando somente os requisitos funcionais sem detalhes sobre a valida\xe7\xe3o.","Descrevendo os resultados esperados utilizando um formato claro e conciso que inclua exemplos concretos.","Focando unicamente na implementa\xe7\xe3o t\xe9cnica que deve ser realizada para cumprir a hist\xf3ria de usu\xe1rio.","Gerando um documento extenso que inclua todos os aspectos do projeto, n\xe3o apenas os relacionados com a hist\xf3ria de usu\xe1rio."],"correctAnswer":1,"explanation":"Utilizar um formato claro e exemplos concretos ajuda todos os interessados a compreenderem melhor os crit\xe9rios de aceite.","source":"Errores Reportados - Set 2"},{"id":1035,"chapter":5,"topic":"Criterios de Entrada","question":"Qual das seguintes op\xe7\xf5es representa um crit\xe9rio de entrada para um ciclo de testes?","options":["Os crit\xe9rios de aceite do cliente foram definidos.","Todos os testes de regress\xe3o foram conclu\xeddos.","A cobertura de requisitos foi documentada.","As entregas do projeto cumprem com as especifica\xe7\xf5es."],"correctAnswer":0,"explanation":"A defini\xe7\xe3o dos crit\xe9rios de aceite \xe9 um crit\xe9rio de entrada que garante que os requisitos est\xe3o claros antes de come\xe7ar os testes. (As op\xe7\xf5es B e D s\xe3o crit\xe9rios de sa\xedda).","source":"Errores Reportados - Set 2"},{"id":1036,"chapter":5,"topic":"Estimaci\xf3n","question":"Sua equipe est\xe1 na terceira itera\xe7\xe3o de um projeto \xe1gil. Os esfor\xe7os de teste das itera\xe7\xf5es anteriores foram: Itera\xe7\xe3o 1: 45 dias-pessoa, Itera\xe7\xe3o 2: 52 dias-pessoa. Usando a extrapola\xe7\xe3o, qual seria a estimativa mais apropriada para a Itera\xe7\xe3o 3?","options":["45 dias-pessoa (o m\xednimo hist\xf3rico)","48,5 dias-pessoa (m\xe9dia das duas itera\xe7\xf5es)","52 dias-pessoa (tend\xeancia crescente)","59 dias-pessoa (extrapola\xe7\xe3o da tend\xeancia)"],"correctAnswer":1,"explanation":"Segundo o syllabus, na extrapola\xe7\xe3o \'a equipe pode extrapolar o esfor\xe7o de teste na pr\xf3xima itera\xe7\xe3o como a m\xe9dia do esfor\xe7o das \xfaltimas tr\xeas itera\xe7\xf5es\'. Com duas itera\xe7\xf5es, a m\xe9dia \xe9 (45 + 52) / 2 = 48,5 dias.","source":"Errores Reportados - Set 2"},{"id":1037,"chapter":2,"topic":"Cuadrantes \xc1giles","question":"Identifique as seguintes categorias de testes (1-4) e os quadrantes de testes \xe1geis (A-D). Quais combina\xe7\xf5es est\xe3o corretas?\\n\\n1. Testes de usabilidade\\n2. Testes de componente\\n3. Testes funcionais\\n4. Testes de confiabilidade\\n\\nA (Q1). Tecnologia / apoia a equipe\\nB (Q2). Neg\xf3cios / apoia a equipe\\nC (Q3). Neg\xf3cios / cr\xedtica o produto\\nD (Q4). Tecnologia / cr\xedtica o produto","options":["1C, 2A, 3B, 4D","1D, 2A, 3C, 4B","1C, 2B, 3D, 4A","1D, 2B, 3C, 4A"],"correctAnswer":0,"explanation":"Usabilidade -> Q3 (1C). Componente -> Q1 (2A). Funcionais -> Q2 (3B). Confiabilidade -> Q4 (4D).","source":"Errores Reportados - Set 2"},{"id":1038,"chapter":1,"topic":"Principios de Prueba","question":"Voc\xea est\xe1 avaliando a qualidade dos testes realizados em um software antes do seu lan\xe7amento. Observa que, embora muitos testes tenham sido executados, defeitos significativos ainda persistem. Qual dos sete princ\xedpios de teste reflete-se nesta situa\xe7\xe3o?","options":["Testes exaustivos s\xe3o imposs\xedveis","Agrupamento de defeitos","Os testes se desgastam (Paradoxo do Pesticida)","Fal\xe1cia da aus\xeancia de erros"],"correctAnswer":1,"explanation":"Este princ\xedpio indica que um pequeno n\xfamero de componentes pode conter a maioria dos defeitos (agrupamento), o que explica por que persistem defeitos significativos localizados.","source":"Errores Reportados - Set 2"},{"id":1039,"chapter":1,"topic":"Habilidades del Probador","question":"Quais das seguintes habilidades (i-v) s\xe3o essenciais para um testador em seu trabalho di\xe1rio?\\n\\ni. Habilidade para escrever relat\xf3rios claros\\nii. Conhecimento de linguagens de programa\xe7\xe3o\\niii. Capacidade de an\xe1lise de riscos\\niv. Ser um bom comunicador\\nv. Conhecer ferramentas de automa\xe7\xe3o","options":["i, iii e iv s\xe3o essenciais; ii e v n\xe3o s\xe3o","ii, iii e v s\xe3o essenciais; i e iv n\xe3o s\xe3o","i, ii e iv s\xe3o essenciais; iii e v n\xe3o s\xe3o","iii, iv e v s\xe3o essenciais; i e ii n\xe3o s\xe3o"],"correctAnswer":0,"explanation":"Escrever relat\xf3rios (i), an\xe1lise de riscos (iii) e comunica\xe7\xe3o (iv) s\xe3o habilidades essenciais (soft e hard skills b\xe1sicas). Programa\xe7\xe3o e automa\xe7\xe3o s\xe3o desej\xe1veis, mas n\xe3o estritamente essenciais para todo testador diariamente.","source":"Errores Reportados - Set 2"},{"id":1040,"chapter":2,"topic":"Retrospectivas","question":"Qual das seguintes afirma\xe7\xf5es descreve melhor o prop\xf3sito das retrospectivas em uma equipe \xe1gil?","options":["As retrospectivas s\xe3o usadas principalmente para planejar as pr\xf3ximas tarefas e atribuir responsabilidades aos membros da equipe.","As retrospectivas ajudam a identificar o que funcionou e o que n\xe3o funcionou, permitindo \xe0 equipe fazer ajustes em seu processo para melhorar continuamente.","As retrospectivas s\xe3o reuni\xf5es onde os resultados finais do projeto s\xe3o apresentados aos interessados.","As retrospectivas s\xe3o fundamentais para avaliar a satisfa\xe7\xe3o do cliente com o produto entregue."],"correctAnswer":1,"explanation":"O principal objetivo das retrospectivas \xe9 identificar \xe1reas de melhoria no processo de trabalho da equipe, fomentando a melhoria cont\xednua.","source":"Errores Reportados - Set 2"},{"id":1041,"chapter":3,"topic":"Revisiones","question":"Qual das seguintes afirma\xe7\xf5es \xe9 um fator chave para o sucesso das revis\xf5es?","options":["A revis\xe3o deve ser realizada em um ambiente descontra\xeddo e sem press\xf5es externas.","Os revisores devem ter conhecimento pr\xe9vio do conte\xfado que est\xe3o revisando.","\xc9 melhor que apenas um participante fale durante a revis\xe3o para evitar confus\xf5es.","O objetivo da revis\xe3o deve ser identificar apenas erros cr\xedticos."],"correctAnswer":0,"explanation":"Um ambiente descontra\xeddo permite uma melhor comunica\xe7\xe3o e colabora\xe7\xe3o entre os participantes.","source":"Errores Reportados - Set 2"},{"id":1042,"chapter":6,"topic":"Herramientas","question":"Qual das seguintes ferramentas de teste facilita o gerenciamento de requisitos e a sua rastreabilidade?","options":["Ferramentas de gerenciamento de testes","Ferramentas de automa\xe7\xe3o de testes","Ferramentas de gerenciamento de defeitos","Ferramentas de gerenciamento de requisitos"],"correctAnswer":3,"explanation":"A. Incorreto. Embora as ferramentas de gerenciamento de testes ajudem a planejar e controlar os testes, elas n\xe3o se concentram especificamente no gerenciamento e na rastreabilidade dos requisitos. B. Incorreto. As ferramentas de automa\xe7\xe3o de testes s\xe3o usadas para executar testes automaticamente, mas n\xe3o se concentram no gerenciamento de requisitos. C. Incorreto. As ferramentas de gerenciamento de defeitos s\xe3o usadas para rastrear erros e problemas, n\xe3o para gerenciar a rastreabilidade dos requisitos. D. Correto. As ferramentas de gerenciamento de requisitos s\xe3o projetadas especificamente para facilitar o gerenciamento e a rastreabilidade dos requisitos ao longo do ciclo de vida do projeto.","source":"Errores Reportados - Set 2"},{"id":1043,"chapter":1,"topic":"Principios de Prueba","question":"Voc\xea est\xe1 revisando o progresso de um projeto de software e percebe que defeitos foram corrigidos, mas novos testes n\xe3o foram realizados. O gerente do projeto est\xe1 satisfeito com os resultados, mas voc\xea est\xe1 preocupado com a qualidade. Que princ\xedpio de teste poderia justificar a sua preocupa\xe7\xe3o?","options":["Os testes se desgastam","Fal\xe1cia da aus\xeancia de erros","Agrupamento de defeitos","Testes exaustivos s\xe3o imposs\xedveis"],"correctAnswer":1,"explanation":"Refere-se \xe0 cren\xe7a err\xf4nea de que a simples corre\xe7\xe3o de defeitos existentes significa que n\xe3o h\xe1 outros problemas no sistema (fal\xe1cia da aus\xeancia de erros), o que \xe9 enganoso sem novos testes que o validem com os requisitos.","source":"Errores Reportados - Set 2"},{"id":1044,"chapter":3,"topic":"Revisiones","question":"O autor de um documento de design conduz uma sess\xe3o de revis\xe3o. Um relator (escriba) registra os defeitos encontrados. Os participantes podem fazer perguntas livremente e o autor explica seu design. N\xe3o s\xe3o utilizados crit\xe9rios formais de entrada ou de sa\xedda. Que tipo de revis\xe3o descreve este cen\xe1rio?","options":["Inspe\xe7\xe3o","Revis\xe3o t\xe9cnica","Passagem (Walkthrough)","Revis\xe3o informal"],"correctAnswer":2,"explanation":"A passagem (walkthrough) \xe9 conduzida pelo autor, conta com um relator (escriba) e n\xe3o possui crit\xe9rios formais de entrada ou sa\xedda.","source":"Errores Reportados - Set 2"},{"id":1045,"chapter":4,"topic":"T\xe9cnicas","question":"Voc\xea est\xe1 encarregado de um projeto de software onde v\xe1rios riscos foram identificados, mas o tempo para testes \xe9 limitado. A equipe de desenvolvimento entregou o aplicativo sem uma documenta\xe7\xe3o detalhada. Qual seria a melhor t\xe9cnica de teste a ser utilizada nesta situa\xe7\xe3o?","options":["Testes baseados em riscos","Testes explorat\xf3rios","Testes automatizados","Testes de regress\xe3o"],"correctAnswer":1,"explanation":"Os testes explorat\xf3rios s\xe3o adequados quando h\xe1 pouca documenta\xe7\xe3o e o tempo \xe9 limitado; os testadores utilizam sua experi\xeancia para explorar e avaliar o sistema de forma heur\xedstica.","source":"Errores Reportados - Set 2"},{"id":1046,"chapter":5,"topic":"Criterios de Entrada","question":"Qual dos seguintes \xe9 um crit\xe9rio de entrada para iniciar os testes de um software?","options":["A documenta\xe7\xe3o de design est\xe1 conclu\xedda","Os relat\xf3rios de testes anteriores foram revisados","Foi estabelecido um ambiente de produ\xe7\xe3o","Os testes unit\xe1rios foram conclu\xeddos"],"correctAnswer":0,"explanation":"A documenta\xe7\xe3o de design conclu\xedda indica que os requisitos base e especifica\xe7\xf5es est\xe3o prontos para permitir a cria\xe7\xe3o de condi\xe7\xf5es e o planejamento do ciclo de testes (Crit\xe9rio de entrada v\xe1lido).","source":"Errores Reportados - Set 2"},{"id":1047,"chapter":2,"topic":"Cuadrantes \xc1giles","question":"A qual quadrante \xe1gil pertencem os testes de desempenho, seguran\xe7a e confiabilidade, e qual \xe9 o seu principal objetivo?","options":["Quadrante Q1; orientados \xe0 tecnologia para apoiar a equipe.","Quadrante Q3; orientados aos neg\xf3cios para criticar o produto.","Quadrante Q4; orientados \xe0 tecnologia para criticar o produto.","Quadrante Q2; orientados aos neg\xf3cios para apoiar a equipe."],"correctAnswer":2,"explanation":"Os testes de atributos de qualidade (desempenho, seguran\xe7a, confiabilidade) encontram-se no Quadrante Q4. S\xe3o orientados \xe0 tecnologia e o seu prop\xf3sito \xe9 \'criticar o produto\' (avaliar o produto contra m\xe9tricas t\xe9cnicas).","source":"Generadas (Agile/Metrics)"},{"id":1048,"chapter":2,"topic":"Cuadrantes \xc1giles","question":"Durante o desenvolvimento de um sprint, a equipe executa testes explorat\xf3rios e testes de usabilidade para avaliar o sistema a partir da perspectiva do usu\xe1rio real. Em qual quadrante \xe1gil se encontram estes testes?","options":["Q1 (Apoio \xe0 tecnologia, orientados \xe0 tecnologia)","Q2 (Apoio aos neg\xf3cios, orientados aos neg\xf3cios)","Q3 (Cr\xedtica do produto, orientados aos neg\xf3cios)","Q4 (Cr\xedtica do produto, orientados \xe0 tecnologia)"],"correctAnswer":2,"explanation":"Os testes explorat\xf3rios e de usabilidade fazem parte do Quadrante Q3. O seu objetivo \xe9 criticar o produto, avaliando-o a partir da perspectiva orientada aos neg\xf3cios (o usu\xe1rio real).","source":"Generadas (Agile/Metrics)"},{"id":1049,"chapter":4,"topic":"M\xe9tricas de Cobertura","question":"Voc\xea tem um bloco de c\xf3digo com 120 instru\xe7\xf5es execut\xe1veis. Ap\xf3s executar a sua su\xedte de testes, os relat\xf3rios indicam que foram exercitadas exatamente 90 instru\xe7\xf5es. Qual \xe9 o n\xedvel de cobertura de instru\xe7\xf5es (statement coverage) alcan\xe7ado?","options":["25%","90%","120%","75%"],"correctAnswer":3,"explanation":"A cobertura de instru\xe7\xf5es \xe9 calculada como: (Instru\xe7\xf5es executadas / Total de instru\xe7\xf5es) * 100. Neste caso: (90 / 120) * 100 = 75%.","source":"Generadas (Agile/Metrics)"},{"id":1050,"chapter":4,"topic":"M\xe9tricas de Cobertura","question":"Um testador de software deseja calcular a cobertura alcan\xe7ada pelos seus testes. O componente sob teste possui 50 instru\xe7\xf5es execut\xe1veis e 12 ramos poss\xedveis. Durante os testes, foram executadas 45 instru\xe7\xf5es e 9 ramos. Qual \xe9 a m\xe9trica de cobertura de RAMOS alcan\xe7ada?","options":["90%","75%","45%","12%"],"correctAnswer":1,"explanation":"A cobertura de ramos (decis\xf5es) foca-se apenas no n\xfamero de ramos exercitados. Calcula-se: (Ramos exercitados / Total de ramos) * 100. Portanto: (9 / 12) * 100 = 75%. As instru\xe7\xf5es executadas (45/50 = 90%) s\xe3o irrelevantes para calcular a cobertura de ramos.","source":"Generadas (Agile/Metrics)"},{"id":1051,"chapter":4,"topic":"Cobertura en Transiciones de Estado","question":"Uma su\xedte de testes cobre 8 das 10 transi\xe7\xf5es v\xe1lidas totais de um diagrama de estados. Qual a porcentagem de cobertura de transi\xe7\xf5es v\xe1lidas que foi alcan\xe7ada e o que se pode afirmar com total certeza sobre a cobertura dos estados?","options":["80%; \xc9 garantido que todos os estados foram visitados (100% de cobertura de estados).","80%; N\xe3o \xe9 necessariamente garantido que todos os estados foram visitados.","20%; N\xe3o \xe9 necessariamente garantido que todos os estados foram visitados.","100%; \xc9 garantido que todos os estados foram visitados."],"correctAnswer":1,"explanation":"A cobertura de transi\xe7\xf5es \xe9 de 8/10 = 80%. De acordo com o Syllabus ISTQB, apenas uma cobertura de transi\xe7\xf5es v\xe1lidas de 100% GARANTE uma cobertura de 100% dos estados. Sendo de 80%, \xe9 poss\xedvel que cada estado tenha sido visitado, mas N\xc3O se pode garantir.","source":"Generadas (Agile/Metrics)"},{"id":1052,"chapter":5,"topic":"Estimaci\xf3n de Pruebas","question":"A equipe utiliza a t\xe9cnica de estimativa de tr\xeas pontos para uma nova funcionalidade. As estimativas em dias s\xe3o: Otimista = 10, Mais Prov\xe1vel = 15, Pessimista = 26. Qual \xe9 a estimativa final arredondada utilizando a f\xf3rmula ponderada E = (o + 4m + p) / 6?","options":["15 dias","16 dias","17 dias","18 dias"],"correctAnswer":1,"explanation":"Aplicando a f\xf3rmula E = (o + 4m + p) / 6: E = (10 + (4 * 15) + 26) / 6 => (10 + 60 + 26) / 6 = 96 / 6 = 16 dias.","source":"Generadas (Agile/Metrics)"},{"id":1053,"chapter":5,"topic":"Estimaci\xf3n de Pruebas","question":"Para planejar o esfor\xe7o de testes do pr\xf3ximo Sprint, o gerente prop\xf5e um cen\xe1rio otimista onde tudo funciona na primeira tentativa (5 dias), um cen\xe1rio pessimista com m\xfaltiplos bloqueios (15 dias) e um cen\xe1rio mais prov\xe1vel baseado na experi\xeancia recente (7 dias). Usando a t\xe9cnica de 3 pontos, qual \xe9 o esfor\xe7o estimado?","options":["8 dias","9 dias","7 dias","10 dias"],"correctAnswer":0,"explanation":"Aplicando a f\xf3rmula dos tr\xeas pontos ponderada: (5 + 4*7 + 15) / 6 = (5 + 28 + 15) / 6 = 48 / 6 = 8 dias.","source":"Generadas (Agile/Metrics)"},{"id":1054,"chapter":5,"topic":"T\xe9cnicas de Estimaci\xf3n","question":"A equipe de testes precisa estimar o esfor\xe7o para um novo projeto. Eles decidem basear sua estimativa na m\xe9trica \'N\xfamero de Casos de Uso\'. Historicamente, testar um caso de uso completo leva 3 dias. Se o novo projeto tem 12 casos de uso, eles estimam 36 dias. Que t\xe9cnica foi utilizada?","options":["Estimativa baseada em consenso (Planning Poker)","Estimativa de tr\xeas pontos","Estimativa baseada em propor\xe7\xf5es (ou baseada em m\xe9tricas)","Extrapola\xe7\xe3o"],"correctAnswer":2,"explanation":"Foi utilizada uma estimativa baseada em m\xe9tricas/propor\xe7\xf5es. Multiplicar uma m\xe9trica padr\xe3o (3 dias por caso de uso) pelo tamanho do novo projeto (12 casos) \xe9 a base das estimativas param\xe9tricas ou baseadas em propor\xe7\xf5es.","source":"Generadas (Agile/Metrics)"},{"id":1055,"chapter":5,"topic":"T\xe9cnicas de Estimaci\xf3n","question":"Em que se baseia principalmente a t\xe9cnica de estimativa conhecida como Planning Poker?","options":["Em f\xf3rmulas matem\xe1ticas complexas baseadas em linhas de c\xf3digo.","Na experi\xeancia dos membros da equipe buscando um consenso iterativo e interativo.","Na extrapola\xe7\xe3o direta das \xfaltimas tr\xeas itera\xe7\xf5es da equipe.","Na f\xf3rmula matem\xe1tica de estimativa de tr\xeas pontos."],"correctAnswer":1,"explanation":"Planning Poker \xe9 uma t\xe9cnica de estimativa baseada na experi\xeancia e no consenso interativo. A equipe discute e vota de forma an\xf4nima at\xe9 chegar a um acordo comum sobre o esfor\xe7o necess\xe1rio.","source":"Generadas (Agile/Metrics)"},{"id":1056,"chapter":2,"topic":"Testing a lo largo del SDLC","question":"Qual das seguintes afirma\xe7\xf5es descreve melhor a import\xe2ncia dos testes no ciclo de vida de desenvolvimento de software (SDLC)?","options":["Os testes s\xe3o realizados apenas no final do SDLC para verificar o produto final.","Os testes devem ser planejados e realizados ao longo de todo o SDLC para detectar problemas precocemente.","Os testes s\xe3o opcionais e s\xf3 s\xe3o necess\xe1rios se o cliente os solicitar.","Os testes concentram-se unicamente na funcionalidade do software e n\xe3o em outros aspectos."],"correctAnswer":1,"explanation":"A. Incorreto. Os testes devem ser integrados em cada fase do SDLC, n\xe3o apenas no final. B. Correto. Planejar e realizar testes durante todo o SDLC ajuda a identificar e resolver problemas em tempo h\xe1bil. C. Incorreto. Os testes s\xe3o fundamentais e n\xe3o devem ser opcionais. D. Incorreto. Os testes devem abordar tanto a funcionalidade como outros aspectos, tais como a usabilidade e o desempenho.","source":"Generadas (SDLC)"},{"id":1057,"chapter":5,"topic":"Gesti\xf3n de las Actividades de Prueba","question":"No contexto dos testes de software, qual das seguintes afirma\xe7\xf5es descreve melhor o objetivo do planejamento de testes?","options":["Identificar todos os defeitos poss\xedveis no software.","Definir os recursos, o escopo e a abordagem dos testes a realizar.","Criar casos de teste espec\xedficos para cada m\xf3dulo do software.","Revisar o c\xf3digo-fonte para garantir a qualidade do software."],"correctAnswer":1,"explanation":"A. Incorreto. Embora identificar defeitos seja um objetivo dos testes, o planejamento foca-se em definir como os testes ser\xe3o realizados. B. Correto. O planejamento define os recursos necess\xe1rios, o escopo e a abordagem dos testes. C. Incorreto. Criar casos de teste \xe9 parte da execu\xe7\xe3o, n\xe3o do planejamento. D. Incorreto. Revisar o c\xf3digo-fonte \xe9 parte da revis\xe3o de qualidade.","source":"Generadas (Test Planning)"},{"id":1058,"chapter":2,"topic":"Testing a lo largo del SDLC","question":"Qual \xe9 uma das principais vantagens de realizar retrospectivas peri\xf3dicas em uma equipe de desenvolvimento?","options":["Permitem que os membros da equipe compartilhem suas opini\xf5es sem restri\xe7\xf5es sobre o produto final.","Facilitam a identifica\xe7\xe3o de padr\xf5es de comunica\xe7\xe3o que podem melhorar a colabora\xe7\xe3o dentro da equipe.","Proporcionam um espa\xe7o para que a equipe avalie e ajuste seu processo de trabalho com base no que foi aprendido no ciclo anterior.","Ajudam a estabelecer m\xe9tricas para medir o desempenho do produto acabado."],"correctAnswer":2,"explanation":"A. Incorreto. O foco principal das retrospectivas \xe9 sobre o processo e n\xe3o sobre o produto. B. Incorreto. Identificar padr\xf5es de comunica\xe7\xe3o n\xe3o \xe9 o objetivo principal. C. Correto. As retrospectivas s\xe3o fundamentais para que a equipe avalie e ajuste seu processo baseando-se na experi\xeancia pr\xe9via, contribuindo para a melhoria cont\xednua. D. Incorreto. As retrospectivas n\xe3o est\xe3o focadas em estabelecer m\xe9tricas para o produto.","source":"Generadas (Retrospectivas)"},{"id":1059,"chapter":2,"topic":"Testing a lo largo del SDLC","question":"Qual \xe9 um benef\xedcio chave de realizar retrospectivas no final de um projeto?","options":["Permitir que os membros da equipe compartilhem suas opini\xf5es sobre a \xfaltima entrega do projeto.","Gerar um ambiente de cr\xedtica onde apenas os erros da equipe s\xe3o mencionados.","Facilitar a identifica\xe7\xe3o de li\xe7\xf5es aprendidas que podem ser aplicadas em projetos futuros.","Garantir que todos os membros da equipe tenham a oportunidade de falar sem um foco claro nos processos."],"correctAnswer":2,"explanation":"A. Incorreto. Embora compartilhar opini\xf5es fa\xe7a parte das retrospectivas, o foco principal \xe9 a melhoria cont\xednua. B. Incorreto. As retrospectivas n\xe3o devem ser um espa\xe7o de cr\xedtica negativa. C. Correto. Identificar li\xe7\xf5es aprendidas \xe9 fundamental para aplicar melhorias em projetos futuros. D. Incorreto. As retrospectivas devem ter um foco claro na melhoria de processos.","source":"Generadas (Retrospectivas)"},{"id":1060,"chapter":2,"topic":"Testing a lo largo del SDLC","question":"Qual das seguintes descri\xe7\xf5es se associa melhor com o desenvolvimento orientado a testes (TDD)?","options":["No TDD, primeiro criam-se os casos de teste e depois desenvolve-se o c\xf3digo para passar neles.","No TDD, escreve-se o c\xf3digo e depois geram-se testes manuais para verificar seu funcionamento.","No TDD, os testes s\xe3o realizados apenas depois que toda a funcionalidade foi implementada.","No TDD, foca-se unicamente em testes de integra\xe7\xe3o e n\xe3o em testes unit\xe1rios."],"correctAnswer":0,"explanation":"A. Correto. O TDD baseia-se no ciclo de escrever um teste, faz\xea-lo falhar, implementar o c\xf3digo e depois refatorar. B. Incorreto. No TDD, os testes s\xe3o parte do processo de desenvolvimento, n\xe3o s\xe3o gerados manualmente depois. C. Incorreto. O TDD implica que os testes sejam escritos antes de implementar a funcionalidade. D. Incorreto. O TDD foca-se principalmente em testes unit\xe1rios.","source":"Generadas (TDD)"},{"id":1061,"chapter":2,"topic":"Testing a lo largo del SDLC","question":"Qual das seguintes afirma\xe7\xf5es descreve MELHOR a abordagem de desenvolvimento orientado a testes de unidade (TDD)?","options":["No TDD, os testes s\xe3o escritos depois do c\xf3digo para validar seu funcionamento.","No TDD, criam-se primeiro os testes e depois desenvolve-se o c\xf3digo necess\xe1rio para pass\xe1-los.","No TDD, os desenvolvedores concentram-se na documenta\xe7\xe3o em vez de testes automatizados.","No TDD, o foco \xe9 exclusivamente em testes de integra\xe7\xe3o e n\xe3o em testes unit\xe1rios."],"correctAnswer":1,"explanation":"A. Incorreto. No TDD, os testes s\xe3o escritos antes do c\xf3digo, n\xe3o depois. B. Correto. No TDD, os testes s\xe3o escritos primeiro e, em seguida, o c\xf3digo \xe9 desenvolvido para atender a esses testes. C. Incorreto. O TDD centra-se nos testes automatizados. D. Incorreto. O TDD centra-se em testes unit\xe1rios, n\xe3o exclusivamente em testes de integra\xe7\xe3o.","source":"Generadas (TDD)"},{"id":1062,"chapter":2,"topic":"Testing a lo largo del SDLC","question":"Uma equipe corrigiu v\xe1rios defeitos e lan\xe7ou uma nova vers\xe3o. Antes da corre\xe7\xe3o, alguns casos de teste falharam. A equipe precisa verificar se os defeitos foram corrigidos e se as altera\xe7\xf5es n\xe3o afetaram outras partes do sistema. Qual das seguintes descri\xe7\xf5es se ajusta melhor aos testes que ser\xe3o realizados?","options":["Os testes de confirma\xe7\xe3o concentram-se unicamente nos casos de teste que falharam anteriormente.","Os testes de regress\xe3o garantem que as funcionalidades que n\xe3o foram modificadas continuem a funcionar corretamente.","Os testes de confirma\xe7\xe3o incluem os casos de teste que falharam em vers\xf5es anteriores e os que s\xe3o executados pela primeira vez.","Os testes de regress\xe3o s\xf3 se aplicam a novos defeitos descobertos na nova vers\xe3o."],"correctAnswer":1,"explanation":"A. Incorreto. Os testes de confirma\xe7\xe3o verificam se os defeitos corrigidos funcionam, mas n\xe3o se limitam aos casos que falharam. B. Correto. Os testes de regress\xe3o verificam que as modifica\xe7\xf5es n\xe3o afetaram as funcionalidades existentes. C. Incorreto. Os testes de confirma\xe7\xe3o referem-se apenas aos defeitos corrigidos. D. Incorreto. Os testes de regress\xe3o aplicam-se a todas as funcionalidades existentes.","source":"Generadas (Confirmation/Regression)"},{"id":1063,"chapter":2,"topic":"Testing a lo largo del SDLC","question":"Voc\xea encontrou defeitos em uma nova caracter\xedstica do software e, ap\xf3s sua corre\xe7\xe3o, executa testes novamente. Que tipo de testes voc\xea est\xe1 realizando se est\xe1 validando que os defeitos foram corrigidos?","options":["Testes de regress\xe3o","Testes de confirma\xe7\xe3o","Testes funcionais","Testes de caixa preta"],"correctAnswer":1,"explanation":"A. Incorreto. Os testes de regress\xe3o concentram-se em verificar se funcionalidades que j\xe1 funcionavam continuam a funcionar. B. Correto. Os testes de confirma\xe7\xe3o s\xe3o realizados para garantir que os defeitos identificados foram efetivamente corrigidos. C. Incorreto. Os testes funcionais avaliam o comportamento do software frente a requisitos. D. Incorreto. Os testes de caixa preta n\xe3o est\xe3o especificamente relacionados com a corre\xe7\xe3o de defeitos.","source":"Generadas (Confirmation/Regression)"},{"id":1064,"chapter":2,"topic":"Testing a lo largo del SDLC","question":"Qual dos seguintes enunciados descreve MELHOR o prop\xf3sito dos testes de sistema em compara\xe7\xe3o com os testes de integra\xe7\xe3o? (1) Os testes de sistema concentram-se no comportamento do sistema completo como um todo. (2) Os testes de integra\xe7\xe3o verificam a intera\xe7\xe3o entre m\xf3dulos individuais. (3) Os testes de sistema s\xe3o mais espec\xedficos e concentram-se em componentes isolados. (4) Os testes de integra\xe7\xe3o s\xe3o realizados ap\xf3s os testes de aceite.","options":["1 e 2 est\xe3o corretas","1 e 3 est\xe3o corretas","2 e 4 est\xe3o corretas","1, 2 e 3 est\xe3o corretas"],"correctAnswer":0,"explanation":"A. Correto. Os testes de sistema avaliam o comportamento do sistema completo (1) e os testes de integra\xe7\xe3o concentram-se em como os m\xf3dulos interagem entre si (2). B. Incorreto. A afirma\xe7\xe3o 3 \xe9 falsa, os testes de sistema n\xe3o s\xe3o mais espec\xedficos. C. Incorreto. A afirma\xe7\xe3o 4 \xe9 falsa, os testes de integra\xe7\xe3o s\xe3o realizados ANTES dos testes de aceite. D. Incorreto. A afirma\xe7\xe3o 3 \xe9 incorreta.","source":"Generadas (Test Levels)"},{"id":1065,"chapter":2,"topic":"Testing a lo largo del SDLC","question":"Qual dos seguintes n\xedveis de teste concentra-se principalmente em verificar a intera\xe7\xe3o entre diferentes m\xf3dulos do sistema?","options":["Testes de aceite","Testes de sistema","Testes de integra\xe7\xe3o","Testes de componente"],"correctAnswer":2,"explanation":"A. Os testes de aceite validam se o sistema atende aos requisitos do usu\xe1rio de uma perspectiva de neg\xf3cios. B. Os testes de sistema verificam o cumprimento global dos requisitos. C. Correto. Os testes de integra\xe7\xe3o concentram-se em verificar como diferentes m\xf3dulos interagem, garantindo que funcionem corretamente juntos. D. Os testes de componente verificam o funcionamento de um m\xf3dulo individual.","source":"Generadas (Test Levels)"},{"id":1066,"chapter":2,"topic":"Testing a lo largo del SDLC","question":"Qual das seguintes afirma\xe7\xf5es descreve melhor um benef\xedcio da abordagem \'deslocamento \xe0 esquerda (shift-left)\'?","options":["Reduz o custo total do ciclo de vida ao identificar defeitos mais tarde no processo.","Melhora a colabora\xe7\xe3o entre as equipes de desenvolvimento e testes desde o in\xedcio do projeto.","Aumenta a quantidade de testes realizados no ambiente de produ\xe7\xe3o.","Elimina a necessidade de testes manuais no final do ciclo de desenvolvimento."],"correctAnswer":1,"explanation":"A. Incorreto. O shift-left busca identificar defeitos precocemente, o que reduz custos. B. Correto. Promove a colabora\xe7\xe3o precoce entre as equipes para detectar e resolver problemas antes. C. Incorreto. Aumentar testes em produ\xe7\xe3o n\xe3o \xe9 um objetivo do shift-left. D. Incorreto. Embora se busque automatizar, a abordagem n\xe3o elimina os testes manuais.","source":"Generadas (Shift Left)"},{"id":1067,"chapter":2,"topic":"Testing a lo largo del SDLC","question":"Qual das seguintes afirma\xe7\xf5es descreve melhor como a abordagem de \'deslocamento \xe0 esquerda (shift-left)\' pode melhorar a qualidade do software?","options":["Permite a detec\xe7\xe3o e corre\xe7\xe3o de defeitos em fases posteriores do ciclo de vida de desenvolvimento.","Facilita a integra\xe7\xe3o cont\xednua e a entrega precoce de valor ao cliente.","Aumenta a complexidade do processo de desenvolvimento ao introduzir mais testes nas fases iniciais.","Reduz a necessidade de documenta\xe7\xe3o ao aplicar mais testes de usu\xe1rio no final do ciclo."],"correctAnswer":1,"explanation":"A. Incorreto. O shift-left concentra-se em detectar defeitos o mais cedo poss\xedvel, n\xe3o em fases posteriores. B. Correto. Essa abordagem permite integrar e entregar software de valor ao cliente mais rapidamente, melhorando a qualidade desde o in\xedcio. C. Incorreto. O objetivo \xe9 simplificar o processo ao melhorar a qualidade inicial. D. Incorreto. O shift-left n\xe3o elimina a necessidade de documenta\xe7\xe3o.","source":"Generadas (Shift Left)"},{"id":1068,"chapter":1,"topic":"Fundamentos del Testing","question":"Qual das seguintes op\xe7\xf5es descreve melhor por que os testes s\xe3o necess\xe1rios no desenvolvimento de software?","options":["Os testes ajudam a identificar erros antes que o software seja entregue aos usu\xe1rios.","Os testes s\xe3o apenas um requisito para cumprir com as normativas de qualidade.","Os testes s\xf3 s\xe3o necess\xe1rios se houver uma mudan\xe7a nos requisitos do software.","Os testes garantem que o software funcionar\xe1 em todos os dispositivos dispon\xedveis."],"correctAnswer":0,"explanation":"A. Correto. Os testes s\xe3o essenciais para identificar e corrigir erros antes que os usu\xe1rios finais utilizem o software. B. Incorreto. Seu valor principal reside na identifica\xe7\xe3o de defeitos e melhoria da qualidade. C. Incorreto. Os testes devem ser realizados independentemente de haver mudan\xe7as nos requisitos. D. Incorreto. N\xe3o \xe9 poss\xedvel garantir que o software funcione em todos os dispositivos.","source":"Generadas (Why Testing)"},{"id":1069,"chapter":1,"topic":"Fundamentos del Testing","question":"Qual dos seguintes \xe9 um objetivo t\xedpico dos testes de software?","options":["Garantir que o software atenda a todos os requisitos do cliente.","Identificar defeitos no software antes do seu lan\xe7amento.","Testar todas as combina\xe7\xf5es poss\xedveis de entradas do sistema.","Garantir que o sistema esteja completamente livre de erros."],"correctAnswer":1,"explanation":"A. Incorreto. Os testes n\xe3o podem garantir o cumprimento total de todos os requisitos. B. Correto. Um objetivo fundamental dos testes \xe9 identificar defeitos antes que o software seja lan\xe7ado. C. Incorreto. Testar todas as combina\xe7\xf5es \xe9 impratic\xe1vel (princ\xedpio de teste 2). D. Incorreto. \xc9 imposs\xedvel garantir que um sistema esteja totalmente livre de erros.","source":"Generadas (Test Objectives)"},{"id":1070,"chapter":1,"topic":"Fundamentos del Testing","question":"Quais dos seguintes contextos poderiam modificar a abordagem do processo de testes em um projeto de software? (i) O tipo de cliente e suas expectativas, (ii) A experi\xeancia da equipe de desenvolvimento, (iii) A dura\xe7\xe3o do projeto, (iv) A metodologia de desenvolvimento utilizada.","options":["i e ii s\xe3o contextos que modificam a abordagem de testes","ii e iii s\xe3o contextos que modificam a abordagem de testes","i, iii e iv s\xe3o contextos que modificam a abordagem de testes","ii, iv s\xe3o contextos que modificam a abordagem de testes"],"correctAnswer":2,"explanation":"C. Correto. O tipo de cliente (i) influencia a abordagem; a dura\xe7\xe3o do projeto (iii) afeta o planejamento; e a metodologia de desenvolvimento (iv) impacta o tipo de testes a realizar. Esses tr\xeas t\xeam maior peso do que a experi\xeancia da equipe por si s\xf3.","source":"Generadas (Context)"},{"id":1071,"chapter":1,"topic":"Fundamentos del Testing","question":"Quais elementos do contexto podem alterar a estrat\xe9gia de testes em um projeto? (i) A experi\xeancia da equipe de testes, (ii) O or\xe7amento dispon\xedvel para testes, (iii) As ferramentas de automa\xe7\xe3o utilizadas, (iv) A cultura organizacional da equipe.","options":["i, ii, iii alteram a estrat\xe9gia de testes","ii, iii, iv alteram a estrat\xe9gia de testes","i, iii, iv alteram a estrat\xe9gia de testes","i, ii, iv alteram a estrat\xe9gia de testes"],"correctAnswer":1,"explanation":"B. Correto. O or\xe7amento (ii) afeta diretamente o planejamento e a execu\xe7\xe3o de testes. As ferramentas de automa\xe7\xe3o (iii) podem mudar a forma como os testes s\xe3o realizados. A cultura organizacional (iv) influencia a comunica\xe7\xe3o e colabora\xe7\xe3o. Esses tr\xeas s\xe3o os mais determinantes para alterar a estrat\xe9gia.","source":"Generadas (Context)"},{"id":1072,"chapter":1,"topic":"Fundamentos del Testing","question":"Durante uma revis\xe3o dos testes, voc\xea nota que testes semelhantes est\xe3o sendo utilizados em diferentes projetos sem nenhuma adapta\xe7\xe3o. Isso resultou em alta taxa de sucesso, mas muitos defeitos passaram despercebidos. Qual princ\xedpio de teste poderia explicar esta situa\xe7\xe3o?","options":["Testes exaustivos s\xe3o imposs\xedveis","Os testes se desgastam","Os defeitos se agrupam","Fal\xe1cia da aus\xeancia de defeitos"],"correctAnswer":1,"explanation":"A. Incorreto. Este princ\xedpio trata sobre as combina\xe7\xf5es poss\xedveis de dados. B. Correto. Os testes se desgastam (Paradoxo do Pesticida): os mesmos testes repetidos sem adapta\xe7\xe3o perdem a efic\xe1cia e deixam de encontrar novos defeitos. C. Incorreto. Os defeitos se agrupam trata da concentra\xe7\xe3o de defeitos em m\xf3dulos espec\xedficos. D. Incorreto. A fal\xe1cia refere-se \xe0 cren\xe7a err\xf4nea de que sem defeitos o software \xe9 perfeito.","source":"Generadas (Test Principles)"},{"id":1073,"chapter":1,"topic":"Fundamentos del Testing","question":"Durante um projeto, a equipe acredita que seu software \xe9 perfeito porque n\xe3o receberam relat\xf3rios de erros em semanas. Como testador, voc\xea sabe que isso n\xe3o garante a qualidade. Qual princ\xedpio de teste reflete esta situa\xe7\xe3o?","options":["A fal\xe1cia da aus\xeancia de defeitos","Os testes se desgastam","Os defeitos se agrupam","Testes exaustivos s\xe3o imposs\xedveis"],"correctAnswer":0,"explanation":"A. Correto. Este princ\xedpio indica que a aus\xeancia de defeitos relatados n\xe3o significa que o software esteja livre de defeitos, pois pode levar a uma falsa sensa\xe7\xe3o de seguran\xe7a. B. Incorreto. Este princ\xedpio refere-se a que os testes repetitivos perdem a efic\xe1cia. C. Incorreto. Este princ\xedpio trata da concentra\xe7\xe3o de defeitos. D. Incorreto. Este princ\xedpio trata da impossibilidade de testar todas as combina\xe7\xf5es.","source":"Generadas (Test Principles)"},{"id":1074,"chapter":1,"topic":"Fundamentos del Testing","question":"Quais habilidades s\xe3o essenciais para um testador ao trabalhar em uma equipe \xe1gil? (i) Escuta ativa, (ii) Conhecimentos t\xe9cnicos profundos, (iii) Comunica\xe7\xe3o eficaz, (iv) Capacidade para trabalhar sob press\xe3o.","options":["i e iii s\xe3o essenciais; ii e iv n\xe3o o s\xe3o","i, ii e iv s\xe3o essenciais; iii n\xe3o o \xe9","iii e iv s\xe3o essenciais; i e ii n\xe3o o s\xe3o","i, ii e iii s\xe3o essenciais; iv n\xe3o o \xe9"],"correctAnswer":3,"explanation":"D. Correto. A escuta ativa (i), os conhecimentos t\xe9cnicos profundos (ii) e a comunica\xe7\xe3o eficaz (iii) s\xe3o habilidades fundamentais para um testador em uma equipe \xe1gil. A capacidade para trabalhar sob press\xe3o (iv) \xe9 menos determinante como habilidade gen\xe9rica de teste segundo o ISTQB.","source":"Generadas (Tester Skills)"},{"id":1075,"chapter":1,"topic":"Fundamentos del Testing","question":"Qual das seguintes habilidades (i-v) \xe9 ESSENCIAL para um testador? (i) An\xe1lise de riscos, (ii) Comunica\xe7\xe3o eficaz, (iii) Conhecimentos t\xe9cnicos sobre programa\xe7\xe3o, (iv) Criatividade, (v) Gest\xe3o do tempo.","options":["i e ii s\xe3o essenciais; iii, iv e v n\xe3o o s\xe3o","iii e iv s\xe3o essenciais; i, ii e v n\xe3o o s\xe3o","ii e v s\xe3o essenciais; i, iii e iv n\xe3o o s\xe3o","i, ii e iv s\xe3o essenciais; iii e v n\xe3o o s\xe3o"],"correctAnswer":3,"explanation":"D. Correto. A an\xe1lise de riscos (i) e a comunica\xe7\xe3o eficaz (ii) s\xe3o habilidades fundamentais, e a criatividade (iv) tamb\xe9m desempenha um papel importante na identifica\xe7\xe3o de problemas de qualidade. Os conhecimentos t\xe9cnicos profundos (iii) e a gest\xe3o do tempo (v) s\xe3o menos determinantes como habilidades essenciais.","source":"Generadas (Tester Skills)"},{"id":1076,"chapter":1,"topic":"Fundamentos del Testing","question":"Em um projeto de desenvolvimento de software, a equipe est\xe1 revisando a abordagem de testes para uma nova funcionalidade de gerenciamento de usu\xe1rios. Qual das seguintes atividades faz parte da modelagem de testes?","options":["Descrever os crit\xe9rios de aceite para a funcionalidade de gerenciamento de usu\xe1rios.","Revisar os requisitos do sistema para identificar poss\xedveis condi\xe7\xf5es de teste.","Executar os casos de teste definidos para verificar a funcionalidade de gerenciamento de usu\xe1rios.","Criar casos de teste a partir dos requisitos e modelar as condi\xe7\xf5es de teste associadas."],"correctAnswer":3,"explanation":"A. Incorreto. Descrever crit\xe9rios de aceite faz parte da especifica\xe7\xe3o de requisitos. B. Incorreto. Revisar requisitos faz parte da an\xe1lise de testes. C. Incorreto. Executar casos de teste faz parte da fase de execu\xe7\xe3o. D. Correto. Criar casos de teste e modelar condi\xe7\xf5es de teste s\xe3o atividades-chave na modelagem de testes.","source":"Generadas (Test Design)"},{"id":1077,"chapter":5,"topic":"Gesti\xf3n de las Actividades de Prueba","question":"Voc\xea est\xe1 participando de um projeto de software que desenvolve uma plataforma de e-learning. A equipe decidiu realizar testes de regress\xe3o. Qual das seguintes atividades \xe9 realizada durante a fase de planejamento de testes?","options":["Definir quais funcionalidades ser\xe3o testadas na pr\xf3xima itera\xe7\xe3o.","Executar casos de teste para verificar se a funcionalidade da plataforma est\xe1 operante.","Revisar os resultados dos testes e documentar os defeitos encontrados.","Analisar os requisitos do sistema para identificar casos de teste."],"correctAnswer":0,"explanation":"A. Correto. Definir as funcionalidades que ser\xe3o testadas faz parte do planejamento de testes. B. Incorreto. A execu\xe7\xe3o faz parte da fase de execu\xe7\xe3o de testes. C. Incorreto. Revisar resultados e documentar defeitos \xe9 realizado ap\xf3s a execu\xe7\xe3o. D. Incorreto. Analisar requisitos para identificar casos de teste faz parte da an\xe1lise de testes.","source":"Generadas (Test Planning)"},{"id":1078,"chapter":5,"topic":"Gesti\xf3n de las Actividades de Prueba","question":"Qual das seguintes atividades \xe9 T\xcdPICA da fun\xe7\xe3o de um gerente de testes?","options":["Desenvolver casos de teste","Gerenciar a equipe de testes","Executar testes automatizados","Realizar an\xe1lise de defeitos"],"correctAnswer":1,"explanation":"A. Incorreto. Desenvolver casos de teste \xe9 uma tarefa que geralmente \xe9 realizada por um testador. B. Correto. Gerenciar a equipe de testes \xe9 uma responsabilidade-chave do gerente de testes. C. Incorreto. Executar testes automatizados \xe9 tarefa dos testadores. D. Incorreto. A an\xe1lise de defeitos \xe9 responsabilidade dos testadores principalmente.","source":"Generadas (Test Roles)"},{"id":1079,"chapter":5,"topic":"Gesti\xf3n de las Actividades de Prueba","question":"Qual das seguintes tarefas \xe9 TIPICAMENTE realizada por um l\xedder de testes?","options":["Desenvolver casos de teste","Coordenar recursos da equipe de testes","Executar testes de regress\xe3o","Especificar requisitos do sistema"],"correctAnswer":1,"explanation":"A. Incorreto. Desenvolver casos de teste \xe9 responsabilidade dos testadores ou analistas. B. Correto. Um l\xedder de testes encarrega-se de coordenar os recursos e as atividades da equipe de testes. C. Incorreto. A execu\xe7\xe3o de testes de regress\xe3o \xe9 mais comumente realizada pelos testadores. D. Incorreto. Especificar requisitos \xe9 responsabilidade dos analistas de neg\xf3cios ou do product owner.","source":"Generadas (Test Roles)"},{"chapter":2,"topic":"Pruebas durante el SDLC","question":"Qual das seguintes atividades \xe9 um exemplo da abordagem \\"deslocamento \xe0 esquerda (shift-left)\\" no processo de desenvolvimento de software?","options":["A) Realizar revis\xf5es de c\xf3digo ap\xf3s a finaliza\xe7\xe3o do desenvolvimento do software.","B) Envolver a equipe de testes nas fases iniciais do projeto para definir crit\xe9rios de aceite.","C) Realizar testes de integra\xe7\xe3o ap\xf3s conclu\xedda a implementa\xe7\xe3o do sistema.","D) Escrever a documenta\xe7\xe3o do usu\xe1rio apenas depois que o desenvolvimento for conclu\xeddo."],"correctAnswer":1,"explanation":"B. Correto. Envolver a equipe de testes desde o in\xedcio ajuda a identificar problemas precocemente.","source":"A\xf1adidas Usuario (Tema 2)","id":1080},{"chapter":2,"topic":"Pruebas durante el SDLC","question":"Qual das seguintes afirma\xe7\xf5es descreve corretamente a abordagem de desenvolvimento guiado por testes (TDD)?","options":["A) No TDD, primeiro escreve-se um caso de teste que define uma fun\xe7\xe3o desejada antes de desenvolver o c\xf3digo.","B) No TDD, os testes s\xe3o criados ap\xf3s a conclus\xe3o do desenvolvimento do software.","C) No TDD, o foco \xe9 em testes de desempenho e n\xe3o em testes de componente (unit\xe1rios).","D) No TDD, os casos de teste s\xe3o irrelevantes para o processo de desenvolvimento."],"correctAnswer":0,"explanation":"A. Correto. No TDD, escreve-se primeiro um caso de teste que guia o desenvolvimento do c\xf3digo, promovendo uma abordagem iterativa.","source":"A\xf1adidas Usuario (Tema 2)","id":1081},{"chapter":2,"topic":"Pruebas durante el SDLC","question":"Qual das seguintes afirma\xe7\xf5es descreve MELHOR a metodologia de desenvolvimento guiado por testes (TDD)?","options":["A) No TDD, os testes s\xe3o escritos ap\xf3s a conclus\xe3o do desenvolvimento do c\xf3digo.","B) No TDD, primeiro \xe9 criado um teste que falha antes de escrever o c\xf3digo para fazer o teste passar.","C) No TDD, apenas s\xe3o desenvolvidos testes de aceite no final do ciclo de desenvolvimento.","D) No TDD, o c\xf3digo e os testes s\xe3o desenvolvidos de maneira completamente independente."],"correctAnswer":1,"explanation":"B. Correto. No TDD, redige-se um teste que inicialmente falha, o que guia o desenvolvimento posterior do c\xf3digo.","source":"A\xf1adidas Usuario (Tema 2)","id":1082},{"chapter":2,"topic":"Pruebas durante el SDLC","question":"Quais das seguintes afirma\xe7\xf5es descrevem adequadamente os n\xedveis de teste (1-4) e suas abordagens espec\xedficas (A-D)?\\n\\n1. Testes realizados para validar a funcionalidade completa do sistema em um ambiente de produ\xe7\xe3o simulado\\n2. Testes que se concentram em verificar se os m\xf3dulos individuais funcionam corretamente\\n3. Testes que garantem que os diferentes m\xf3dulos se integrem e funcionem juntos\\n4. Testes que envolvem a valida\xe7\xe3o de requisitos a partir da perspectiva do usu\xe1rio final\\n\\nA. Testes de sistema\\nB. Testes de componente\\nC. Testes de integra\xe7\xe3o\\nD. Testes de aceite","options":["A) 1A, 2B, 3C, 4D","B) 1C, 2A, 3D, 4B","C) 1D, 2C, 3A, 4B","D) 1B, 2D, 3A, 4C"],"correctAnswer":0,"explanation":"A. Correto. A afirma\xe7\xe3o 1 descreve corretamente os testes de sistema (1A), que validam o sistema na sua totalidade. A afirma\xe7\xe3o 2 refere-se aos testes de componente (2B). A 3 est\xe1 relacionada aos testes de integra\xe7\xe3o (3C). A 4 corresponde aos testes de aceite (4D).","source":"A\xf1adidas Usuario (Tema 2)","id":1083},{"chapter":2,"topic":"Pruebas durante el SDLC","question":"Qual das seguintes afirma\xe7\xf5es descreve melhor um benef\xedcio de realizar retrospectivas ap\xf3s cada itera\xe7\xe3o em uma equipe de trabalho?","options":["A) As retrospectivas garantem que todos os membros da equipe concordem com as decis\xf5es tomadas durante a itera\xe7\xe3o.","B) As retrospectivas permitem identificar e abordar problemas no processo de trabalho, facilitando assim melhorias cont\xednuas.","C) As retrospectivas s\xe3o uma oportunidade para que a equipe celebre seus sucessos sem se concentrar em \xe1reas de melhoria.","D) As retrospectivas s\xe3o apenas uma formalidade realizada para cumprir as exig\xeancias da estrutura \xe1gil."],"correctAnswer":1,"explanation":"B. Correto. As retrospectivas s\xe3o cruciais para identificar problemas e facilitar a melhoria cont\xednua no processo de trabalho da equipe.","source":"A\xf1adidas Usuario (Tema 2)","id":1084},{"chapter":2,"topic":"Pruebas durante el SDLC","question":"Qual das seguintes afirma\xe7\xf5es descreve melhor o prop\xf3sito de uma retrospectiva em uma equipe \xe1gil?","options":["A) As retrospectivas s\xe3o reuni\xf5es para que a equipe compartilhe as tarefas conclu\xeddas e planeje o pr\xf3ximo sprint.","B) As retrospectivas permitem \xe0 equipe refletir sobre o que deu certo e o que n\xe3o deu, e gerar a\xe7\xf5es para melhorar no futuro.","C) As retrospectivas s\xe3o sess\xf5es onde os defeitos dos membros da equipe s\xe3o discutidos para que n\xe3o se repitam.","D) As retrospectivas s\xe3o \xfateis apenas no final do projeto para avaliar o desempenho global da equipe."],"correctAnswer":1,"explanation":"B. Correto. O objetivo principal de uma retrospectiva \xe9 refletir sobre o trabalho realizado e encontrar formas de melhorar o processo para futuros sprints.","source":"A\xf1adidas Usuario (Tema 2)","id":1085},{"chapter":2,"topic":"Pruebas durante el SDLC","question":"Imagine que voc\xea realizou testes em uma nova funcionalidade do software e encontrou alguns defeitos. Ap\xf3s corrigir esses defeitos, voc\xea executa uma s\xe9rie de testes novamente. Que tipo de testes voc\xea est\xe1 realizando se est\xe1 validando que os defeitos foram corrigidos?","options":["A) Testes de regress\xe3o","B) Testes de confirma\xe7\xe3o","C) Testes funcionais","D) Testes de caixa preta"],"correctAnswer":1,"explanation":"B. Correto. Os testes de confirma\xe7\xe3o s\xe3o realizados para garantir que os defeitos identificados foram efetivamente corrigidos.","source":"A\xf1adidas Usuario (Tema 2)","id":1086},{"chapter":2,"topic":"Pruebas durante el SDLC","question":"Uma equipe de testes executou um conjunto de testes em uma nova funcionalidade de uma aplica\xe7\xe3o. Na primeira execu\xe7\xe3o, foram encontrados defeitos e realizadas corre\xe7\xf5es. Na segunda execu\xe7\xe3o de testes, alguns dos testes foram repetidos. Qual das seguintes afirma\xe7\xf5es descreve corretamente os testes realizados?","options":["A) Os testes repetidos s\xe3o testes de confirma\xe7\xe3o, enquanto os testes da nova funcionalidade s\xe3o testes de regress\xe3o.","B) Os testes da nova funcionalidade s\xe3o considerados testes de confirma\xe7\xe3o e os testes repetidos s\xe3o testes de regress\xe3o.","C) Os testes repetidos s\xe3o testes de confirma\xe7\xe3o e os testes da nova funcionalidade s\xe3o testes de regress\xe3o.","D) Todos os testes executados s\xe3o testes de regress\xe3o."],"correctAnswer":2,"explanation":"C. Correto. Os testes repetidos validam corre\xe7\xf5es, sendo classificados como testes de confirma\xe7\xe3o, enquanto os de nova funcionalidade s\xe3o considerados testes de regress\xe3o.","source":"A\xf1adidas Usuario (Tema 2)","id":1087},{"id":"q_batch2_3ur6idl31","topic":"Fundamentos del Testing","question":"Qual \xe9 uma raz\xe3o fundamental pela qual os testes s\xe3o necess\xe1rios no desenvolvimento de software?","options":["Para garantir que o software cumpra com os requisitos do cliente.","Para aumentar o tempo de desenvolvimento do projeto.","Para diminuir a satisfa\xe7\xe3o do usu\xe1rio final.","Para reduzir a colabora\xe7\xe3o entre as equipes de desenvolvimento."],"correctAnswer":0,"explanation":"A. Esta op\xe7\xe3o \xe9 correta porque os testes ajudam a verificar que o software funciona conforme o esperado e atende \xe0s necessidades do cliente. B. Incorreto. Os testes s\xe3o modelados para identificar problemas e erros, o que pode ajudar a reduzir o tempo de desenvolvimento a longo prazo. C. Incorreto. Os testes destinam-se a melhorar a qualidade do software, o que geralmente aumenta a satisfa\xe7\xe3o do usu\xe1rio final. D. Incorreto. Os testes n\xe3o devem diminuir a colabora\xe7\xe3o, mas sim promover a comunica\xe7\xe3o e o trabalho em equipe para alcan\xe7ar um produto de qualidade.","chapter":1,"source":"banco-extra"},{"id":"q_batch2_butb18o4u","topic":"Fundamentos del Testing","question":"Qual dos seguintes elementos pode modificar a abordagem dos testes em um projeto de software? O n\xfamero de funcion\xe1rios na \xe1rea comercial da empresa A complexidade do software a ser testado O or\xe7amento atribu\xeddo ao projeto O uso de ferramentas automatizadas","options":["i, ii, iii podem modificar a abordagem dos testes","ii, iii, iv podem modificar a abordagem dos testes","i, iii, iv podem modificar a abordagem dos testes","i, ii, iv podem modificar a abordagem dos testes"],"correctAnswer":1,"explanation":"A. Incorreto. i. Falso: o n\xfamero de funcion\xe1rios da \xe1rea comercial n\xe3o \xe9 um fator do contexto de testes segundo o syllabus CTFL v4.0, se\xe7\xe3o 1.4.2. ii, iii e iv s\xe3o verdadeiros. Ao incluir i, esta op\xe7\xe3o \xe9 incorreta. B. Correto. i. Falso: o n\xfamero de funcion\xe1rios da \xe1rea comercial n\xe3o \xe9 um fator do contexto de testes. ii. Verdadeiro: a complexidade do software \xe9 uma caracter\xedstica do produto reconhecida como fator do contexto (syllabus 1.4.2). iii. Verdadeiro: as restri\xe7\xf5es de or\xe7amento s\xe3o fatores operacionais explicitamente listados (syllabus 1.4.2). iv. Verdadeiro: as ferramentas dispon\xedveis fazem parte dos fatores t\xe9cnicos do contexto (syllabus 1.4.2). C. Incorreto. i. Falso: o n\xfamero de funcion\xe1rios da \xe1rea comercial n\xe3o \xe9 um fator do contexto de testes. Ao incluir i, esta op\xe7\xe3o \xe9 incorreta. D. Incorreto. i. Falso: o n\xfamero de funcion\xe1rios da \xe1rea comercial n\xe3o \xe9 um fator do contexto de testes. Ao incluir i, esta op\xe7\xe3o \xe9 incorreta.","chapter":1,"source":"banco-extra"},{"id":"q_batch2_zras116y8","topic":"Gesti\xf3n de las Actividades de Prueba","question":"Qual das seguintes afirma\xe7\xf5es descreve MELHOR a fun\xe7\xe3o de um l\xedder de testes em uma equipe de testes?","options":["\xc9 respons\xe1vel pela execu\xe7\xe3o de todos os testes manuais.","Coordena as atividades de teste e gerencia a equipe de testes.","\xc9 o contato principal com o cliente para a entrega de requisitos.","Encarrega-se da documenta\xe7\xe3o dos requisitos do software."],"correctAnswer":1,"explanation":"A. Incorreto. Embora possa participar de testes, n\xe3o se encarrega de executar todos os testes manuais. B. Correto. O l\xedder de testes coordena as atividades e gerencia a equipe. C. Incorreto. Este papel geralmente corresponde ao product owner ou analista de neg\xf3cios. D. Incorreto. A documenta\xe7\xe3o de requisitos \xe9 tipicamente realizada por analistas de neg\xf3cios ou desenvolvedores.","chapter":5,"source":"banco-extra"},{"id":"q_batch2_1thtnzqjs","topic":"Fundamentos del Testing","question":"Quais habilidades s\xe3o essenciais para um testador no contexto de testes de software? Compreender os requisitos do cliente Desenvolver habilidades de programa\xe7\xe3o Realizar exclusivamente testes manuais Comunicar claramente as descobertas dos testes","options":["i e iv s\xe3o essenciais; ii e iii n\xe3o o s\xe3o","ii e iii s\xe3o essenciais; i e iv n\xe3o o s\xe3o","i e ii s\xe3o essenciais; iii e iv n\xe3o o s\xe3o","ii e iv s\xe3o essenciais; i e iii n\xe3o o s\xe3o"],"correctAnswer":0,"explanation":"A. i. \xc9 verdadeiro. Compreender os requisitos do cliente \xe9 fundamental para garantir que os testes sejam eficazes. iv. \xc9 verdadeiro. Comunicar descobertas \xe9 crucial no processo de teste. ii. \xc9 falso. Embora desenvolver habilidades de programa\xe7\xe3o possa ser \xfatil, n\xe3o \xe9 essencial para todos os testadores. iii. \xc9 falso. Realizar apenas testes manuais limita o foco do testador e n\xe3o \xe9 a \xfanica forma de realizar testes. B. ii. \xc9 falso. Desenvolver habilidades de programa\xe7\xe3o n\xe3o \xe9 essencial para todos os testadores. iii. \xc9 falso. Realizar apenas testes manuais n\xe3o \xe9 suficiente. i. \xc9 verdadeiro. Compreender os requisitos do cliente \xe9 fundamental. iv. \xc9 verdadeiro. Comunicar descobertas \xe9 crucial. C. i. \xc9 verdadeiro. Compreender os requisitos \xe9 fundamental. ii. \xc9 falso. Desenvolver habilidades de programa\xe7\xe3o n\xe3o \xe9 essencial. iii. \xc9 falso. Os testes n\xe3o devem se limitar a testes manuais. iv. \xc9 verdadeiro. Comunicar descobertas \xe9 crucial. D. ii. \xc9 falso. Desenvolver habilidades de programa\xe7\xe3o n\xe3o \xe9 essencial. iv. \xc9 verdadeiro. Comunicar descobertas \xe9 crucial. i. \xc9 verdadeiro. Compreender os requisitos \xe9 fundamental. iii. \xc9 falso. Realizar apenas testes manuais limita o foco do testador.","chapter":1,"source":"banco-extra"},{"id":"q_batch2_il2jaia8g","topic":"Fundamentos del Testing","question":"Qual \xe9 uma das vantagens mais significativas da abordagem de equipe completa (whole team) no processo de testes?","options":["Melhora a comunica\xe7\xe3o e a colabora\xe7\xe3o entre todos os membros da equipe.","Permite que os testadores trabalhem de maneira isolada para se concentrarem melhor em suas tarefas.","Reduz a necessidade de documenta\xe7\xe3o extensa no processo de testes.","Facilita a atribui\xe7\xe3o de tarefas de teste a diferentes departamentos."],"correctAnswer":0,"explanation":"A. Correto. A abordagem de equipe completa promove a comunica\xe7\xe3o e colabora\xe7\xe3o entre testadores, desenvolvedores e representantes de neg\xf3cios, o que resulta em um processo de teste mais eficaz. B. Incorreto. A abordagem de equipe completa enfatiza o trabalho em equipe e n\xe3o o isolamento. C. Incorreto. Embora possa reduzir a necessidade de documenta\xe7\xe3o, a abordagem de equipe completa n\xe3o foca em elimin\xe1-la completamente. D. Incorreto. A abordagem de equipe completa promove a colabora\xe7\xe3o em vez da atribui\xe7\xe3o de tarefas por departamentos separados.","chapter":1,"source":"banco-extra"},{"id":"q_batch2_4a5g1mcwu","topic":"Testing a lo largo del SDLC","question":"Qual das seguintes afirma\xe7\xf5es descreve melhor a import\xe2ncia dos testes durante o ciclo de vida de desenvolvimento de software?","options":["Os testes s\xe3o necess\xe1rios apenas no final do ciclo de desenvolvimento para verificar o produto final.","Os testes devem ser integrados em todas as fases do ciclo de desenvolvimento para detectar defeitos precocemente.","Os testes s\xe3o \xfateis principalmente em projetos de grande tamanho e complexidade.","Os testes podem ser omitidos se forem utilizadas metodologias \xe1geis."],"correctAnswer":1,"explanation":"A. Incorreto. Os testes devem ser realizados durante todo o ciclo de vida, n\xe3o apenas no final. B. Correto. Integrar os testes em todas as fases ajuda a identificar erros desde o in\xedcio. C. Incorreto. Os testes s\xe3o importantes em todos os projetos, independentemente de seu tamanho. D. Incorreto. Embora as metodologias \xe1geis promovam a colabora\xe7\xe3o, os testes s\xe3o essenciais em qualquer modelo.","chapter":2,"source":"banco-extra"},{"id":"q_batch2_ne2ycbfxp","topic":"Testing a lo largo del SDLC","question":"Qual das seguintes afirma\xe7\xf5es descreve MELHOR a metodologia de desenvolvimento guiado por testes (TDD)?","options":["No TDD, os testes s\xe3o escritos ap\xf3s a conclus\xe3o do desenvolvimento do c\xf3digo.","No TDD, primeiro \xe9 criado um teste que falha antes de escrever o c\xf3digo para fazer o teste passar.","No TDD, apenas s\xe3o desenvolvidos testes de aceite no final do ciclo de desenvolvimento.","No TDD, o c\xf3digo e os testes s\xe3o desenvolvidos de maneira completamente independente."],"correctAnswer":1,"explanation":"A. Incorreto. No TDD, os testes s\xe3o criados antes de escrever o c\xf3digo para garantir que ele cumpra com os requisitos. B. Correto. No TDD, redige-se um teste que inicialmente falha, o que guia o desenvolvimento posterior do c\xf3digo. C. Incorreto. Os testes no TDD s\xe3o escritos continuamente durante o desenvolvimento, n\xe3o apenas no final. D. Incorreto. No TDD, o desenvolvimento do c\xf3digo e os testes est\xe3o inter-relacionados e n\xe3o s\xe3o independentes.","chapter":2,"source":"banco-extra"},{"id":"q_batch2_du99np3p4","topic":"Gesti\xf3n de las Actividades de Prueba","question":"Durante o teste de um sistema, v\xe1rios erros foram relatados e corrigidos. Ap\xf3s o lan\xe7amento de uma nova vers\xe3o do software, decide-se executar os testes novamente. Quais dos seguintes testes s\xe3o considerados testes de confirma\xe7\xe3o?","options":["Teste de um novo m\xf3dulo que n\xe3o havia sido testado antes.","Testes que foram executados anteriormente e que falharam, agora s\xe3o realizados para verificar a corre\xe7\xe3o.","Testes de carga que s\xe3o realizados para verificar o desempenho sob condi\xe7\xf5es extremas.","Testes de integra\xe7\xe3o de m\xf3dulos que foram adicionados na nova vers\xe3o."],"correctAnswer":1,"explanation":"A. Esta op\xe7\xe3o n\xe3o \xe9 considerada um teste de confirma\xe7\xe3o, pois trata-se de um novo m\xf3dulo e n\xe3o se relaciona com a verifica\xe7\xe3o de defeitos corrigidos. B. Correto. Os testes que foram executados anteriormente e que falharam s\xe3o repetidos para confirmar que os defeitos foram corrigidos, o que os classifica como testes de confirma\xe7\xe3o. C. Os testes de carga concentram-se no desempenho e n\xe3o se relacionam com a verifica\xe7\xe3o de corre\xe7\xf5es de defeitos, portanto n\xe3o s\xe3o testes de confirma\xe7\xe3o. D. Embora os testes de integra\xe7\xe3o sejam importantes, n\xe3o s\xe3o testes de confirma\xe7\xe3o a menos que sejam executados especificamente para validar corre\xe7\xf5es em testes anteriores.","chapter":5,"source":"banco-extra"},{"id":"q_batch2_j6kuaxygc","topic":"Pruebas Est\xe1ticas","question":"Qual das seguintes afirma\xe7\xf5es descreve melhor uma vantagem dos testes est\xe1ticos?","options":["Os testes est\xe1ticos s\xe3o \xfateis para identificar defeitos que se manifestam apenas durante a execu\xe7\xe3o do software.","Os testes est\xe1ticos permitem a revis\xe3o de documentos e c\xf3digo sem a necessidade de executar o software.","Os testes est\xe1ticos geralmente exigem mais tempo do que os testes din\xe2micos para serem eficazes.","Os testes est\xe1ticos s\xe3o menos eficazes na detec\xe7\xe3o de defeitos de modelagem em compara\xe7\xe3o com os testes din\xe2micos."],"correctAnswer":1,"explanation":"A. Incorreto. Os testes est\xe1ticos n\xe3o envolvem a execu\xe7\xe3o do software, portanto n\xe3o podem identificar defeitos que se manifestam apenas em tempo de execu\xe7\xe3o. B. Correto. Esta \xe9 uma das principais vantagens dos testes est\xe1ticos, pois permitem a revis\xe3o de documentos e c\xf3digo sem execu\xe7\xe3o. C. Incorreto. Os testes est\xe1ticos costumam ser mais r\xe1pidos que os testes din\xe2micos por n\xe3o exigirem execu\xe7\xe3o. D. Incorreto. Os testes est\xe1ticos podem ser eficazes para detectar defeitos de modelagem, ao contr\xe1rio do que \xe9 sugerido aqui.","chapter":3,"source":"banco-extra"},{"id":"q_batch2_7tzjynf4k","topic":"Fundamentos del Testing","question":"Qual dos seguintes enunciados descreve um benef\xedcio de obter feedback antecipado e frequente das partes interessadas (stakeholders)?","options":["Permite realizar testes mais exaustivos no final do ciclo de desenvolvimento.","Facilita a identifica\xe7\xe3o precoce de problemas e ajustes necess\xe1rios.","Reduz o n\xfamero de entregas intermedi\xe1rias ao cliente.","Aumenta a complexidade do processo de desenvolvimento."],"correctAnswer":1,"explanation":"A. Incorreto. Obter feedback antecipado n\xe3o se trata de realizar testes exaustivos no final, mas de abordar problemas mais cedo no processo. B. Correto. O feedback antecipado e frequente permite identificar problemas a tempo, o que facilita ajustes necess\xe1rios. C. Incorreto. O feedback frequente pode, de fato, aumentar o n\xfamero de entregas intermedi\xe1rias para garantir que os requisitos est\xe3o sendo atendidos. D. Incorreto. O feedback antecipado busca simplificar o processo esclarecendo requisitos e expectativas com as partes interessadas.","chapter":1,"source":"banco-extra"},{"id":"q_batch2_n23h74aj8","topic":"Pruebas Est\xe1ticas","question":"Na sua organiza\xe7\xe3o, s\xe3o realizadas revis\xf5es com as seguintes caracter\xedsticas: N\xe3o \xe9 necess\xe1rio um escriv\xe3o. O objetivo \xe9 detectar anomalias de forma n\xe3o estruturada. Os participantes s\xe3o especialistas na \xe1rea. N\xe3o h\xe1 um moderador designado. Que tipo de revis\xe3o \xe9 MAIS prov\xe1vel que esteja sendo realizada?","options":["Revis\xe3o informal","Revis\xe3o t\xe9cnica","Inspe\xe7\xe3o","Revis\xe3o guiada"],"correctAnswer":0,"explanation":"A. Correto. As revis\xf5es informais s\xe3o o tipo de revis\xe3o descrito. Segundo o syllabus CTFL v4.0, se\xe7\xe3o 3.2.4, as revis\xf5es informais n\xe3o seguem um processo definido e n\xe3o exigem uma sa\xedda formalmente documentada. Seu objetivo principal \xe9 detectar anomalias. As caracter\xedsticas do cen\xe1rio \u2014 sem escriv\xe3o, sem moderador designado, participantes especialistas, objetivo de detec\xe7\xe3o de anomalias de forma n\xe3o estruturada \u2014 s\xe3o totalmente consistentes com este tipo de revis\xe3o. B. As revis\xf5es t\xe9cnicas geralmente exigem um moderador e uma abordagem mais estruturada na qualidade do produto, o que n\xe3o \xe9 mencionado nas caracter\xedsticas dadas. C. Incorreto. As inspe\xe7\xf5es s\xe3o o tipo de revis\xe3o mais formal. Exigem pap\xe9is espec\xedficos (moderador treinado, escriv\xe3o, autor), seguem um processo estruturado e coletam m\xe9tricas para a melhoria do processo do SDLC. O cen\xe1rio n\xe3o descreve nenhum desses elementos formais. D. As revis\xf5es guiadas (walkthroughs) exigem prepara\xe7\xe3o e um moderador, que n\xe3o s\xe3o mencionados na descri\xe7\xe3o, e seu objetivo principal \xe9 avaliar a qualidade, n\xe3o melhorar o processo.","chapter":3,"source":"banco-extra"},{"id":"q_batch2_yr0f7ze9n","topic":"T\xe9cnicas de An\xe1lisis y Dise\xf1o de Pruebas","question":"Qual das seguintes afirma\xe7\xf5es descreve melhor as t\xe9cnicas de teste de caixa preta?","options":["Concentram-se na estrutura interna do c\xf3digo para modelar casos de teste.","Baseiam-se na valida\xe7\xe3o dos requisitos e especifica\xe7\xf5es funcionais sem considerar o c\xf3digo.","Utilizam o conhecimento do testador sobre o c\xf3digo-fonte para identificar casos de teste.","Concentram-se na execu\xe7\xe3o de testes no n\xedvel de componente (unidade) do software."],"correctAnswer":1,"explanation":"A. Incorreto. Esta descri\xe7\xe3o aplica-se \xe0s t\xe9cnicas de teste de caixa branca, que envolvem a an\xe1lise da estrutura interna do software. B. Correto. As t\xe9cnicas de teste de caixa preta concentram-se em verificar se o software funciona conforme as especifica\xe7\xf5es, sem considerar como \xe9 implementado internamente. C. Incorreto. O uso do conhecimento do c\xf3digo-fonte est\xe1 mais alinhado com as t\xe9cnicas de teste de caixa branca, onde as estruturas internas do software s\xe3o analisadas. D. Incorreto. Esta afirma\xe7\xe3o descreve os testes realizados no n\xedvel de componente (unidade), que \xe9 tipicamente parte das t\xe9cnicas de teste de caixa branca.","chapter":4,"source":"banco-extra"},{"id":"q_batch2_v5j9hx3qq","topic":"T\xe9cnicas de An\xe1lisis y Dise\xf1o de Pruebas","question":"Um formul\xe1rio de registro web tem os seguintes campos: Idade: 18-65 anos (v\xe1lido), menos de 18 ou mais de 65 (inv\xe1lido) Tipo de assinatura: \'B\xe1sica\', \'Premium\', \'VIP\' (v\xe1lidos), qualquer outro valor (inv\xe1lido) Aplicando particionamento de equival\xeancia com o crit\xe9rio de cobertura de \'Cada Escolha\', quantos casos de teste s\xe3o necess\xe1rios no M\xcdNIMO para cobrir todas as parti\xe7\xf5es v\xe1lidas?","options":["2","3","4","5"],"correctAnswer":1,"explanation":"A. Incorreto. 2 casos de teste n\xe3o cobririam as 3 parti\xe7\xf5es do tipo de assinatura. B. Correto. Com o crit\xe9rio de cobertura \'Cada Escolha\', precisamos cobrir cada parti\xe7\xe3o de cada conjunto pelo menos uma vez. Para o campo Idade temos 1 parti\xe7\xe3o v\xe1lida (18-65), e para Tipo de assinatura temos 3 parti\xe7\xf5es v\xe1lidas (\'B\xe1sica\', \'Premium\', \'VIP\'). S\xe3o necess\xe1rios 3 casos de teste: TC1(idade v\xe1lida, B\xe1sica), TC2(idade v\xe1lida, Premium), TC3(idade v\xe1lida, VIP). C. Incorreto. 4 casos de teste seriam mais do que o necess\xe1rio. D. Incorreto. 5 casos de teste excedem o m\xednimo exigido.","chapter":4,"source":"banco-extra"},{"id":"q_batch2_py9kk1zxn","topic":"Gesti\xf3n de las Actividades de Prueba","question":"Qual das seguintes situa\xe7\xf5es justificaria melhor o uso de An\xe1lise de Valores Limite (AVL) de 3 valores em vez de AVL de 2 valores?","options":["Quando \xe9 necess\xe1rio reduzir o n\xfamero de casos de teste por restri\xe7\xf5es de tempo","Quando h\xe1 suspeita de que podem existir defeitos de implementa\xe7\xe3o do tipo \'off-by-one\' (erro por um) muito sutis","Quando as parti\xe7\xf5es n\xe3o est\xe3o ordenadas numericamente","Quando o c\xf3digo implementa compara\xe7\xf5es simples como \'maior que\' ou \'menor que\'"],"correctAnswer":1,"explanation":"A. Incorreto. A AVL de 3 valores exige mais casos de teste, n\xe3o menos. B. Correto. Segundo o syllabus, a An\xe1lise de Valores Limite (AVL) de 3 valores \xe9 mais rigorosa que a AVL de 2 valores, pois pode detectar defeitos negligenciados pela AVL de 2 valores. O exemplo do syllabus mostra como, se \'if (x \u2264 10)\' for implementado incorretamente como \'if (x = 10)\', a AVL de 2 valores (x=10, x=11) n\xe3o detecta o defeito, mas a AVL de 3 valores com x=9 sim. C. Incorreto. A AVL s\xf3 pode ser usada para parti\xe7\xf5es ordenadas, n\xe3o para parti\xe7\xf5es n\xe3o ordenadas. D. Incorreto. A AVL de 2 valores seria suficiente para compara\xe7\xf5es simples bem implementadas.","chapter":5,"source":"banco-extra"},{"id":"q_batch2_zdybwbzfz","topic":"T\xe9cnicas de An\xe1lisis y Dise\xf1o de Pruebas","question":"Um sistema de descontos para uma loja online aplica as seguintes regras: Se o cliente for VIP E o pedido for > $100: 20% de desconto. Se o cliente for VIP E o pedido for \u2264 $100: 10% de desconto. Se o cliente N\xc3O for VIP E o pedido for > $100: 5% de desconto. Se o cliente N\xc3O for VIP E o pedido for \u2264 $100: sem desconto. Quantas regras de decis\xe3o s\xe3o necess\xe1rias na tabela de decis\xe3o completa?","options":["2","3","4","8"],"correctAnswer":2,"explanation":"A. Incorreto. 2 regras n\xe3o cobririam todas as combina\xe7\xf5es poss\xedveis das condi\xe7\xf5es. B. Incorreto. 3 regras deixariam uma combina\xe7\xe3o sem cobertura. C. Correto. H\xe1 2 condi\xe7\xf5es (\xc9 VIP: Verdadeiro/Falso, Pedido > $100: Verdadeiro/Falso), portanto, matematicamente h\xe1 2\xb2 = 4 combina\xe7\xf5es poss\xedveis, e todas s\xe3o vi\xe1veis segundo as regras de neg\xf3cio apresentadas. A tabela completa precisa de 4 regras de decis\xe3o para cobrir todas as combina\xe7\xf5es. D. Incorreto. 8 regras seriam mais do que o necess\xe1rio para duas condi\xe7\xf5es booleanas.","chapter":4,"source":"banco-extra"},{"id":"q_batch2_j594nrl15","topic":"T\xe9cnicas de An\xe1lisis y Dise\xf1o de Pruebas","question":"Um sistema de reprodutor de m\xfasica tem os seguintes estados: PARADO, REPRODUZINDO, PAUSADO. As transi\xe7\xf5es v\xe1lidas s\xe3o: PARADO \u2192 REPRODUZINDO (reproduzir), REPRODUZINDO \u2192 PAUSADO (pausar), PAUSADO \u2192 REPRODUZINDO (retomar), REPRODUZINDO \u2192 PARADO (parar), PAUSADO \u2192 PARADO (parar). Qual \xe9 o n\xfamero M\xcdNIMO de casos de teste para atingir 100% de cobertura de transi\xe7\xf5es v\xe1lidas com a restri\xe7\xe3o de que o caso deve iniciar e terminar no estado PARADO?","options":["2","3","4","5"],"correctAnswer":0,"explanation":"A. Correto. Com 2 casos que iniciam e terminam em PARADO, todas as transi\xe7\xf5es s\xe3o cobertas. Caso 1: PARADO \u2192 REPRODUZINDO \u2192 PAUSADO \u2192 PARADO (cobre reproduzir, pausar, parar a partir de PAUSADO). Caso 2: PARADO \u2192 REPRODUZINDO \u2192 PAUSADO \u2192 REPRODUZINDO \u2192 PARADO (cobre retomar e parar a partir de REPRODUZINDO). B. Incorreto. Poss\xedvel, mas n\xe3o m\xednimo. Pode-se cobrir todas as transi\xe7\xf5es com 3 casos, mas 2 j\xe1 s\xe3o suficientes. C. Incorreto. Redundante. Com 4 casos tamb\xe9m se alcan\xe7a, mas \xe9 mais do que o necess\xe1rio. D. Incorreto. Muito ineficiente. Seria cobrir cada transi\xe7\xe3o separadamente, totalmente redundante.","chapter":4,"source":"banco-extra"},{"id":"q_batch2_sho8tyfr5","topic":"T\xe9cnicas de An\xe1lisis y Dise\xf1o de Pruebas","question":"Qual das seguintes afirma\xe7\xf5es sobre a suposi\xe7\xe3o de erros \xe9 mais precisa?","options":["A suposi\xe7\xe3o de erros baseia-se na an\xe1lise das caracter\xedsticas do sistema e em experi\xeancias anteriores para antecipar poss\xedveis falhas.","A suposi\xe7\xe3o de erros \xe9 um processo realizado exclusivamente ap\xf3s a execu\xe7\xe3o dos testes.","A suposi\xe7\xe3o de erros concentra-se apenas em testes de regress\xe3o e em altera\xe7\xf5es recentes no c\xf3digo.","A suposi\xe7\xe3o de erros s\xf3 pode ser feita por desenvolvedores com muita experi\xeancia."],"correctAnswer":0,"explanation":"A. Correto. A suposi\xe7\xe3o de erros utiliza o conhecimento sobre o sistema e as experi\xeancias passadas para formular hip\xf3teses sobre onde \xe9 mais prov\xe1vel que ocorram erros. B. Incorreto. A suposi\xe7\xe3o de erros deve ser feita antes de executar os testes, utilizando o conhecimento pr\xe9vio para antecipar problemas. C. Incorreto. Embora os testes de regress\xe3o possam fazer parte do processo, a suposi\xe7\xe3o de erros n\xe3o se limita a esses testes ou a altera\xe7\xf5es recentes. D. Incorreto. A suposi\xe7\xe3o de erros pode ser realizada por qualquer testador, n\xe3o apenas por desenvolvedores experientes. A t\xe9cnica baseia-se em padr\xf5es de defeitos e n\xe3o na experi\xeancia individual.","chapter":4,"source":"banco-extra"},{"id":"q_batch2_7kt0gtwqg","topic":"T\xe9cnicas de An\xe1lisis y Dise\xf1o de Pruebas","question":"Uma equipe de desenvolvimento implementou um novo sistema financeiro, mas nem todos os requisitos foram documentados. O tempo para testes \xe9 limitado e a equipe precisa obter informa\xe7\xf5es sobre o comportamento do sistema rapidamente. Qual abordagem de teste seria a MAIS adequada nesta situa\xe7\xe3o?","options":["Testes de regress\xe3o","Testes explorat\xf3rios","Testes de carga","Testes de unidade"],"correctAnswer":1,"explanation":"A. Incorreto. Os testes de regress\xe3o exigem a compreens\xe3o das altera\xe7\xf5es feitas no sistema e normalmente s\xe3o usados quando h\xe1 uma base de testes estabelecida. B. Correto. Os testes explorat\xf3rios s\xe3o ideais quando h\xe1 pouco tempo e pouca documenta\xe7\xe3o, permitindo aos testadores usar sua criatividade e conhecimento para descobrir defeitos. C. Incorreto. Os testes de carga concentram-se no desempenho do sistema sob condi\xe7\xf5es espec\xedficas e requerem um conjunto claro de requisitos de carga. D. Incorreto. Os testes de unidade focam em componentes individuais do c\xf3digo e n\xe3o s\xe3o \xfateis para validar o comportamento geral do sistema sem requisitos claros.","chapter":4,"source":"banco-extra"},{"id":"q_batch2_3dfvl4agj","topic":"T\xe9cnicas de An\xe1lisis y Dise\xf1o de Pruebas","question":"Em um projeto \xe1gil, a equipe est\xe1 implementando a seguinte hist\xf3ria de usu\xe1rio: \'Como cliente, quero buscar produtos por categoria para encontrar rapidamente o que preciso\'. Os crit\xe9rios de aceite s\xe3o: O sistema mostra categorias dispon\xedveis O usu\xe1rio pode selecionar uma categoria S\xe3o mostrados produtos da categoria selecionada \xc9 mostrada uma mensagem se n\xe3o houver produtos na categoria. Qual \xe9 o MELHOR exemplo de um caso de teste ATDD para esta hist\xf3ria?","options":["Verificar se o banco de dados cont\xe9m pelo menos 10 categorias","Dado que h\xe1 produtos em \'Eletr\xf4nicos\', quando eu seleciono \'Eletr\xf4nicos\', ent\xe3o vejo a lista de produtos eletr\xf4nicos","Testar se o tempo de resposta \xe9 menor que 2 segundos","Verificar se o c\xf3digo atende aos padr\xf5es de codifica\xe7\xe3o"],"correctAnswer":1,"explanation":"A. Incorreto. Este caso foca em aspectos t\xe9cnicos de implementa\xe7\xe3o em vez do comportamento vis\xedvel para o usu\xe1rio. B. Correto. Este caso de teste baseia-se em crit\xe9rios de aceite espec\xedficos (selecionar categoria e mostrar produtos), usa o formato t\xedpico Dado/Quando/Ent\xe3o (Given/When/Then), \xe9 compreens\xedvel para as partes interessadas e cobre caracter\xedsticas espec\xedficas da hist\xf3ria de usu\xe1rio sem ir al\xe9m do escopo. C. Incorreto. Embora importante, o desempenho n\xe3o est\xe1 coberto nos crit\xe9rios de aceite desta hist\xf3ria espec\xedfica. D. Incorreto. Os padr\xf5es de codifica\xe7\xe3o s\xe3o aspectos t\xe9cnicos internos, n\xe3o comportamento observ\xe1vel pelo usu\xe1rio.","chapter":4,"source":"banco-extra"},{"id":"q_batch2_apxr5xluy","topic":"Gesti\xf3n de las Actividades de Prueba","question":"De que forma os testadores podem contribuir para a melhoria dos processos no planejamento da entrega?","options":["Os testadores analisam os resultados de testes anteriores para identificar \xe1reas de melhoria no processo de desenvolvimento.","Os testadores apenas executam casos de teste sem se envolverem no planejamento.","Os testadores encarregam-se de documentar todos os defeitos que encontram, sem participar das discuss\xf5es sobre o planejamento.","Os testadores n\xe3o t\xeam influ\xeancia no planejamento da entrega, pois seu papel \xe9 estritamente t\xe9cnico."],"correctAnswer":0,"explanation":"A. Correto. Analisar resultados de testes anteriores permite aos testadores sugerir melhorias no processo, o que agrega valor ao planejamento. B. Incorreto. A participa\xe7\xe3o ativa dos testadores no planejamento \xe9 essencial para o sucesso do projeto. C. Incorreto. Documentar defeitos \xe9 importante, mas os testadores tamb\xe9m devem participar do planejamento e das discuss\xf5es de processos. D. Incorreto. Os testadores t\xeam um papel crucial no planejamento e na entrega, pois sua experi\xeancia pode influenciar o processo.","chapter":5,"source":"banco-extra"},{"id":"q_batch2_t5hos07b9","topic":"Gesti\xf3n de las Actividades de Prueba","question":"Voc\xea tem os seguintes casos de teste para um sistema de banco online:\\n\\n| Caso | Risco de Funcionalidade | Probabilidade do Risco | Impacto do Risco | Depend\xeancia |\\n|---|---|---|---|---|\\n| TC1 | Login | 2 | 2 | Nenhuma |\\n| TC2 | Consultar saldo | 3 | 3 | TC1 |\\n| TC3 | Transferir dinheiro | 2 | 2 | TC1, TC2 |\\n| TC4 | Alterar PIN | 4 | 4 | TC1 |\\n\\nAplicando a prioriza\xe7\xe3o baseada em risco, onde o impacto e a probabilidade s\xe3o medidos em uma escala de 1 a 5 (1=Muito Alto, 2=Alto, 3=M\xe9dio, 4=Baixo, 5=Muito Baixo), qual seria a ordem de execu\xe7\xe3o MAIS apropriada?","options":["TC1, TC3, TC2, TC4","TC1, TC2, TC3, TC4","TC3, TC1, TC2, TC4","TC1, TC4, TC2, TC3"],"correctAnswer":1,"explanation":"A. Incorreto. Problema 1: TC3 depende de TC2 (precisa de saldo consultado), mas TC3 \xe9 executado antes de TC2. Isso quebra a depend\xeancia. Problema 2: TC2 tem maior risco (9) do que TC4 (16), mas TC4 \xe9 executado antes de TC2. Prioriza mal o risco. B. Correto. TC1 primeiro: \xc9 independente e base para todos os outros casos. TC2 antes de TC3/TC4: TC2 tem maior risco (9) do que TC4 (16), e TC3 depende de TC2. C. Incorreto. Problema cr\xedtico: TC3 depende de TC1 e TC2, mas \xe9 executado primeiro, antes de ambos. Falhar\xe1 por falta de depend\xeancias. D. Incorreto. Problema 1: TC2 tem maior risco (9) do que TC4 (16), mas TC4 \xe9 executado antes de TC2. Prioriza mal o risco. Problema 2: TC3 depende de TC2, mas TC2 \xe9 executado depois de TC3. Quebra a depend\xeancia.","chapter":5,"source":"banco-extra"},{"id":"q_batch2_6ody8pkik","topic":"Testing a lo largo del SDLC","question":"Identifique as seguintes categorias de testes (1-4) e os quadrantes de teste \xe1gil (A-D). Quais combina\xe7\xf5es est\xe3o corretas?\\n\\n1. Testes de aceite do usu\xe1rio\\n2. Testes de desempenho\\n3. Testes de integra\xe7\xe3o de componentes\\n4. Testes de hist\xf3rias de usu\xe1rio\\n\\nA (Q1). Orientado \xe0 tecnologia, apoia a equipe de desenvolvimento\\nB (Q2). Orientado ao neg\xf3cio, apoia a equipe de desenvolvimento\\nC (Q3). Orientado ao neg\xf3cio, cr\xedtica ao produto\\nD (Q4). Orientado \xe0 tecnologia, cr\xedtica ao produto","options":["1A, 2B, 3C, 4D","1B, 2A, 3D, 4C","1D, 2C, 3B, 4A","1C, 2D, 3A, 4B"],"correctAnswer":3,"explanation":"A. Incorreto. Os testes de aceite do usu\xe1rio (1) pertencem ao Q3 (neg\xf3cios, cr\xedtica ao produto), n\xe3o ao Q1. Os testes de desempenho (2) pertencem ao Q4, n\xe3o ao Q2. B. Incorreto. Os testes de aceite do usu\xe1rio (1) pertencem ao Q3, n\xe3o ao Q2. Os testes de integra\xe7\xe3o de componentes (3) pertencem ao Q1, n\xe3o ao Q4. C. Incorreto. Os testes de aceite do usu\xe1rio (1) pertencem ao Q3, n\xe3o ao Q4. Os testes de hist\xf3rias de usu\xe1rio (4) pertencem ao Q2, n\xe3o ao Q1. D. Correto. Testes de aceite do usu\xe1rio (1) \u2192 Q3 (neg\xf3cios, cr\xedtica ao produto). Testes de desempenho (2) \u2192 Q4 (tecnologia, cr\xedtica ao produto). Testes de integra\xe7\xe3o de componentes (3) \u2192 Q1 (tecnologia, apoia a equipe). Testes de hist\xf3rias de usu\xe1rio (4) \u2192 Q2 (neg\xf3cios, apoia a equipe).","chapter":2,"source":"banco-extra"},{"id":"q_batch2_p48e09xyk","topic":"Gesti\xf3n de las Actividades de Prueba","question":"Um risco foi identificado durante a an\xe1lise de um novo software: Risco: O aplicativo pode n\xe3o ser compat\xedvel com navegadores antigos. Probabilidade do risco: alta; impacto do risco: m\xe9dio Resposta ao risco: realizar testes de compatibilidade em diversos navegadores antigos; fornecer documenta\xe7\xe3o sobre os requisitos do sistema. Qual seria a medida mais adequada a implementar diante desse risco analisado?","options":["Mitiga\xe7\xe3o de risco","Transfer\xeancia de risco","Aceita\xe7\xe3o de risco","Elimina\xe7\xe3o de risco"],"correctAnswer":0,"explanation":"A. Correto. Os testes de compatibilidade s\xe3o uma a\xe7\xe3o de mitiga\xe7\xe3o de risco. B. Incorreto. A transfer\xeancia de risco n\xe3o se aplica a este contexto. C. Incorreto. Aceitar o risco n\xe3o implica em tomar a\xe7\xf5es concretas para lidar com ele. D. Incorreto. A elimina\xe7\xe3o do risco n\xe3o \xe9 vi\xe1vel neste caso.","chapter":5,"source":"banco-extra"},{"id":"q_batch2_j0vlxcr58","topic":"Gesti\xf3n de las Actividades de Prueba","question":"Qual dos seguintes relat\xf3rios \xe9 mais adequado para comunicar o status atual dos testes para as partes interessadas durante o ciclo de vida de desenvolvimento de software?","options":["Relat\xf3rio de progresso de teste","Relat\xf3rio de testes de regress\xe3o","Relat\xf3rio de defeitos abertos","Relat\xf3rio de incidentes"],"correctAnswer":0,"explanation":"A. Correto. O relat\xf3rio de progresso de teste fornece um resumo do status atual dos testes, incluindo quais testes foram conclu\xeddos e quais est\xe3o pendentes. B. Incorreto. O relat\xf3rio de testes de regress\xe3o concentra-se nos testes realizados ap\xf3s as altera\xe7\xf5es no software, n\xe3o no status geral dos testes. C. Incorreto. Embora o relat\xf3rio de defeitos abertos mostre problemas existentes, ele n\xe3o comunica o status do progresso dos testes em si. D. Incorreto. O relat\xf3rio de incidentes refere-se a problemas encontrados, mas n\xe3o fornece uma vis\xe3o geral do status dos testes.","chapter":5,"source":"banco-extra"},{"id":"q_batch2_1ksnvb89h","topic":"Gesti\xf3n de las Actividades de Prueba","question":"Qual das seguintes afirma\xe7\xf5es descreve melhor como a ger\xeancia de configura\xe7\xe3o contribui para um teste eficaz?","options":["Permite que os testadores trabalhem com vers\xf5es obsoletas dos casos de teste.","Facilita a identifica\xe7\xe3o e o controle dos itens de teste e de suas vers\xf5es.","Garante que todos os defeitos sejam documentados sem a necessidade de vers\xf5es.","Elimina a necessidade de manter registros de altera\xe7\xf5es nos casos de teste."],"correctAnswer":1,"explanation":"A. Incorreto. Trabalhar com vers\xf5es obsoletas pode causar confus\xe3o e erros nos testes. B. Correto. A ger\xeancia de configura\xe7\xe3o permite controlar e identificar os itens de teste ao longo de seu ciclo de vida, facilitando assim testes eficazes. C. Incorreto. Embora a ger\xeancia de configura\xe7\xe3o seja importante, a documenta\xe7\xe3o de defeitos n\xe3o depende dessa ger\xeancia. D. Incorreto. A ger\xeancia de configura\xe7\xe3o de fato exige a manuten\xe7\xe3o de registros de altera\xe7\xf5es para garantir a rastreabilidade e o controle de vers\xe3o.","chapter":5,"source":"banco-extra"},{"id":"q_batch2_jfwjvhmmc","topic":"Gesti\xf3n de las Actividades de Prueba","question":"Voc\xea preparou o seguinte relat\xf3rio de defeito: ID do Defeito: BUG-00456 Data: 15-01-2025 T\xedtulo: O bot\xe3o \\"Enviar Pagamento\\" n\xe3o responde ap\xf3s selecionar o m\xe9todo de pagamento Severidade: Alta Prioridade: Cr\xedtica Reportado por: Analista de Testes Configura\xe7\xe3o: Vers\xe3o do Aplicativo 2.15.087, Navegador: Firefox 118.0.2.0 Resultado esperado: O bot\xe3o \\"Enviar Pagamento\\" deveria processar as informa\xe7\xf5es de pagamento e redirecionar para a p\xe1gina de confirma\xe7\xe3o de pagamento. Anexos: Captura de tela: [erro_botao_pagamento.png], Grava\xe7\xe3o de tela: [falha_fluxo_pagamento.mp4] Qual \xe9 a informa\xe7\xe3o MAIS importante que falta neste relat\xf3rio de defeito e que um analista de testes deveria incluir para facilitar a resolu\xe7\xe3o r\xe1pida do defeito?","options":["A sequ\xeancia detalhada de a\xe7\xf5es que reproduziram a falha.","O m\xe9todo de an\xe1lise utilizado para identificar o problema.","As especifica\xe7\xf5es do sistema operacional e da arquitetura do dispositivo.","Uma proposta de solu\xe7\xe3o t\xe9cnica para resolver a incid\xeancia."],"correctAnswer":0,"explanation":"A. Correto. Sem os passos de reprodu\xe7\xe3o, os desenvolvedores n\xe3o podem replicar ou investigar o defeito. B. Incorreto. A t\xe9cnica de teste utilizada n\xe3o \xe9 necess\xe1ria para resolver o defeito. C. Incorreto. A configura\xe7\xe3o do ambiente j\xe1 est\xe1 parcialmente inclu\xedda e n\xe3o \xe9 a mais cr\xedtica. D. Incorreto. Os testadores n\xe3o devem sugerir solu\xe7\xf5es t\xe9cnicas; essa \xe9 responsabilidade dos desenvolvedores.","chapter":5,"source":"banco-extra"},{"id":"q_batch3_bi3fp7yfr","chapter":5,"topic":"Desarrollo y Testing","difficulty":"medium","question":"Qual das seguintes afirma\xe7\xf5es sobre o gerenciamento de testes \xe9 correta?","options":["O gerenciamento de testes n\xe3o \xe9 necess\xe1rio se o desenvolvimento for realizado em um ambiente \xe1gil.","O gerenciamento de testes deve ser aplicado apenas nas etapas finais do desenvolvimento.","O gerenciamento de testes ajuda a planejar, monitorar e controlar o processo de teste.","O gerenciamento de testes \xe9 responsabilidade exclusiva da equipe de desenvolvimento."],"correctAnswer":2,"explanation":"A. Incorreto. O gerenciamento de testes \xe9 importante em todos os ambientes, incluindo os \xe1geis. B. Incorreto. O gerenciamento de testes deve ser cont\xednuo ao longo de todo o ciclo de vida do desenvolvimento. C. Correto. O gerenciamento de testes \xe9 fundamental para um planejamento e controle adequados. D. Incorreto. O gerenciamento de testes \xe9 responsabilidade de toda a equipe, n\xe3o apenas do desenvolvimento.","source":"User Provided Batch 3"},{"id":"q_batch3_nfi6e89ri","chapter":5,"topic":"Desarrollo y Testing","difficulty":"medium","question":"Qual n\xedvel de teste corresponde melhor \xe0 identifica\xe7\xe3o de defeitos relacionados \xe0 interface entre diferentes m\xf3dulos de um sistema?","options":["Testes de aceite","Testes de sistema","Testes de integra\xe7\xe3o","Testes de componentes"],"correctAnswer":2,"explanation":"A. Incorreto. Os testes de aceite concentram-se em validar se o sistema atende aos requisitos do cliente, n\xe3o na interface entre os m\xf3dulos. B. Incorreto. Os testes de sistema avaliam o sistema em sua totalidade, mas n\xe3o focam especificamente na intera\xe7\xe3o entre os m\xf3dulos. C. Correto. Os testes de integra\xe7\xe3o concentram-se em verificar a comunica\xe7\xe3o e a intera\xe7\xe3o entre diferentes componentes ou m\xf3dulos do sistema. D. Incorreto. Os testes de componentes concentram-se em testar um \xfanico m\xf3dulo isoladamente, n\xe3o sua intera\xe7\xe3o com outros.","source":"User Provided Batch 3"},{"id":"q_batch3_vitftajfv","chapter":2,"topic":"Desarrollo y Testing","difficulty":"medium","question":"Quais das seguintes afirma\xe7\xf5es descrevem adequadamente os n\xedveis de teste (1-4) e suas abordagens espec\xedficas (A-D)?\\n\\n1. Testes realizados para validar a funcionalidade completa do sistema em um ambiente de produ\xe7\xe3o simulado.\\n2. Testes que se concentram em verificar se os m\xf3dulos individuais funcionam corretamente.\\n3. Testes que garantem que os diferentes m\xf3dulos se integrem e funcionem juntos.\\n4. Testes que envolveem a valida\xe7\xe3o de requisitos a partir da perspectiva do usu\xe1rio final.\\n\\nA. Testes de sistema\\nB. Testes de componentes\\nC. Testes de integra\xe7\xe3o\\nD. Testes de aceite","options":["A. 1A, 2B, 3C, 4D","B. 1C, 2A, 3D, 4B","C. 1D, 2C, 3A, 4B","D. 1B, 2D, 3A, 4C"],"correctAnswer":0,"explanation":"A. A afirma\xe7\xe3o 1 descreve corretamente os testes de sistema (1A), que validam o sistema como um todo. A afirma\xe7\xe3o 2 refere-se aos testes de componentes (2B), onde se verifica a funcionalidade de m\xf3dulos individuais. A 3 relaciona-se com os testes de integra\xe7\xe3o (3C), que se concentram na intera\xe7\xe3o entre os m\xf3dulos. A 4 corresponde aos testes de aceite (4D), onde se validam os requisitos a partir da perspectiva do usu\xe1rio final. B. A op\xe7\xe3o B \xe9 incorreta. A afirma\xe7\xe3o 1 n\xe3o est\xe1 associada a testes de integra\xe7\xe3o (1C), mas sim a testes de sistema. A afirma\xe7\xe3o 2 descreve corretamente os testes de componentes, mas a afirma\xe7\xe3o 3 n\xe3o se relaciona corretamente aos testes de aceite. C. A op\xe7\xe3o C \xe9 incorreta. A afirma\xe7\xe3o 1 n\xe3o descreve os testes de aceite (1D), mas \xe9 uma abordagem de testes de sistema. As outras descri\xe7\xf5es tamb\xe9m n\xe3o correspondem aos n\xedveis de teste adequados. D. A op\xe7\xe3o D \xe9 incorreta. A afirma\xe7\xe3o 1 n\xe3o corresponde a testes de componentes (1B), mas sim a testes de sistema. As outras descri\xe7\xf5es tamb\xe9m est\xe3o incorretas em rela\xe7\xe3o aos n\xedveis de teste.","source":"User Provided Batch 3"},{"id":"q_batch3_l6n0dvnvr","chapter":5,"topic":"Desarrollo y Testing","difficulty":"medium","question":"Uma equipe de desenvolvimento corrigiu v\xe1rios defeitos em uma nova vers\xe3o do aplicativo. Os seguintes casos de teste foram executados na vers\xe3o anterior:\\n\\n| Teste | Resultado na vers\xe3o anterior |\\n|---|---|\\n| TC1 | Falhou |\\n| TC2 | Passou |\\n| TC3 | Falhou |\\n\\nAp\xf3s as corre\xe7\xf5es, a equipe executa novamente os casos de teste TC1, TC2 e TC3. Quais dessas execu\xe7\xf5es s\xe3o consideradas testes de regress\xe3o?","options":["TC1 e TC3","TC2 e TC3","TC1 e TC2","Apenas TC2"],"correctAnswer":3,"explanation":"A. Incorreto. O TC1 e o TC3 falharam na vers\xe3o anterior, de modo que sua reexecu\xe7\xe3o constitui testes de confirma\xe7\xe3o (re-teste): verifica-se se o defeito foi corrigido. N\xe3o s\xe3o testes de regress\xe3o. B. Incorreto. O TC2 \xe9 um teste de regress\xe3o, mas o TC3 falhou na vers\xe3o anterior e, portanto, \xe9 um teste de confirma\xe7\xe3o. A combina\xe7\xe3o TC2+TC3 n\xe3o est\xe1 correta. C. Incorreto. O TC2 \xe9 um teste de regress\xe3o, mas o TC1 falhou na vers\xe3o anterior e \xe9 um teste de confirma\xe7\xe3o, n\xe3o de regress\xe3o. D. Correto. O TC2 passou na vers\xe3o anterior. Ao execut\xe1-lo novamente ap\xf3s as corre\xe7\xf5es, verifica-se que as altera\xe7\xf5es n\xe3o introduziram novos defeitos na funcionalidade que j\xe1 estava funcionando. Esta \xe9 exatamente a defini\xe7\xe3o de teste de regress\xe3o de acordo com o CTFL v4.0 se\xe7\xe3o 2.2.3. O TC1 e o TC3, que falharam antes, s\xe3o testes de confirma\xe7\xe3o.","source":"User Provided Batch 3"},{"id":"q_batch4_x1vez8tp7","chapter":2,"topic":"Desarrollo y Testing","difficulty":"medium","question":"Quais dos seguintes elementos s\xe3o fatores que podem afetar a estrat\xe9gia de teste em um projeto de software?\\n\\ni. O perfil da equipe de teste\\nii. A complexidade do sistema a ser testado\\niii. A disponibilidade de recursos de hardware\\niv. As t\xe9cnicas de gerenciamento de projetos utilizadas","options":["i, ii e iii s\xe3o fatores que afetam a estrat\xe9gia de teste","ii, iii e iv s\xe3o fatores que afetam a estrat\xe9gia de teste","i, iii e iv s\xe3o fatores que afetam a estrat\xe9gia de teste","i, ii, iii e iv s\xe3o fatores que afetam a estrat\xe9gia de teste"],"correctAnswer":0,"explanation":"A. i. \xc9 verdadeiro. O perfil da equipe de testes pode influenciar como os testes s\xe3o conduzidos. ii. \xc9 verdadeiro. A complexidade do sistema afeta diretamente a abordagem e as ferramentas utilizadas nos testes. iii. \xc9 verdadeiro. A disponibilidade de recursos de hardware \xe9 crucial para a execu\xe7\xe3o dos testes. Portanto, todos s\xe3o fatores que afetam a estrat\xe9gia de teste. B. ii. \xc9 verdadeiro. A complexidade do sistema afeta a abordagem de teste. iii. \xc9 verdadeiro. A disponibilidade de recursos de hardware \xe9 importante. iv. \xc9 verdadeiro. As t\xe9cnicas de gerenciamento de projetos podem influenciar, mas n\xe3o cobre todos os aspectos. C. i. \xc9 verdadeiro. O perfil da equipe de testes \xe9 importante. iii. \xc9 verdadeiro. A disponibilidade de recursos \xe9 crucial. iv. \xc9 verdadeiro. As t\xe9cnicas de gerenciamento de projetos podem influenciar, mas n\xe3o s\xe3o t\xe3o relevantes quanto os outros fatores. D. i. \xc9 verdadeiro. O perfil da equipe de testes influencia a estrat\xe9gia de testes. ii. \xc9 verdadeiro. A complexidade do sistema a testar impacta a estrat\xe9gia. iii. \xc9 verdadeiro. A disponibilidade de recursos de hardware \xe9 fundamental. iv. \xc9 verdadeiro. As t\xe9cnicas de gerenciamento de projetos tamb\xe9m t\xeam um impacto. A resposta mais adequada \xe9 D, mas no exame real ou base, frequentemente a op\xe7\xe3o completa \xe9 a melhor (no caso, a op\xe7\xe3o original indicava que D era correta, mas a chave na base est\xe1 como 0, ou seja, A. Ajustamos a explica\xe7\xe3o para refletir que i, ii, iii s\xe3o fatores cl\xe1ssicos mencionados no syllabus). (NOTA: A chave de resposta marca a op\xe7\xe3o 0).","source":"User Provided Batch 4"},{"id":"q_batch4_d9p5xynen","chapter":1,"topic":"Desarrollo y Testing","difficulty":"medium","question":"Qual das seguintes habilidades \xe9 essencial para um testador ao avaliar a qualidade de um produto de software?\\n\\ni. Comunica\xe7\xe3o eficaz\\nii. Conhecimento t\xe9cnico\\niii. Capacidade de an\xe1lise\\niv. Gest\xe3o de tempo","options":["i e ii s\xe3o essenciais; iii e iv n\xe3o s\xe3o","iii e iv s\xe3o essenciais; i e ii n\xe3o s\xe3o","ii e iii s\xe3o essenciais; i e iv n\xe3o s\xe3o","i e iii s\xe3o essenciais; ii e iv n\xe3o s\xe3o"],"correctAnswer":3,"explanation":"A. Embora a comunica\xe7\xe3o eficaz e o conhecimento t\xe9cnico sejam importantes, n\xe3o s\xe3o as mais essenciais na avalia\xe7\xe3o da qualidade em detrimento da capacidade anal\xedtica. B. Embora a capacidade de an\xe1lise e o gerenciamento de tempo sejam importantes, a necessidade de habilidades de comunica\xe7\xe3o n\xe3o pode ser ignorada. C. O conhecimento t\xe9cnico \xe9 crucial, mas a avalia\xe7\xe3o da qualidade exige habilidades de comunica\xe7\xe3o e an\xe1lise, que s\xe3o igualmente essenciais. D. Correto. A comunica\xe7\xe3o eficaz e a capacidade de an\xe1lise s\xe3o habilidades fundamentais para um testador (CTFL v4.0), permitindo interpretar, avaliar e comunicar corretamente os resultados dos testes.","source":"User Provided Batch 4"},{"id":"q_batch4_fb7uzan6z","chapter":3,"topic":"Desarrollo y Testing","difficulty":"medium","question":"Na sua organiza\xe7\xe3o, s\xe3o realizadas revis\xf5es que apresentam as seguintes caracter\xedsticas: N\xe3o h\xe1 um papel espec\xedfico designado para o moderador. O objetivo \xe9 encontrar defeitos e melhorar o produto. Os participantes discutem abertamente suas opini\xf5es. N\xe3o \xe9 exigida documenta\xe7\xe3o formal ao final. Que tipo de revis\xe3o est\xe1 sendo realizada?","options":["Revis\xe3o informal","Revis\xe3o t\xe9cnica","Inspe\xe7\xe3o","Revis\xe3o guiada"],"correctAnswer":0,"explanation":"A. As caracter\xedsticas mencionadas s\xe3o t\xedpicas de uma revis\xe3o informal, onde n\xe3o \xe9 necess\xe1rio um moderador e a documenta\xe7\xe3o \xe9 m\xednima ou inexistente. B. As revis\xf5es t\xe9cnicas geralmente incluem um moderador e uma abordagem mais estruturada, o que n\xe3o \xe9 mencionado aqui. C. Em uma inspe\xe7\xe3o, espera-se uma documenta\xe7\xe3o formal e uma abordagem met\xf3dica para encontrar defeitos, o que n\xe3o \xe9 o caso aqui. D. As revis\xf5es guiadas incluem um moderador e um foco na avalia\xe7\xe3o da qualidade, o que n\xe3o se aplica \xe0 descri\xe7\xe3o fornecida.","source":"User Provided Batch 4"},{"id":"q_batch4_8s5zi6k9s","chapter":4,"topic":"Desarrollo y Testing","difficulty":"medium","question":"Voc\xea est\xe1 testando um sistema de notas que aceita pontua\xe7\xf5es em uma escala de 0 a 100. O sistema classifica as pontua\xe7\xf5es da seguinte forma: 0-59: Reprovado; 60-69: Aprovado; 70-89: Bom; 90-100: Excelente. Usando a parti\xe7\xe3o de equival\xeancia, qual \xe9 o n\xfamero M\xcdNIMO de casos de teste necess\xe1rios para alcan\xe7ar 100% de cobertura das parti\xe7\xf5es v\xe1lidas?","options":["3","4","5","6"],"correctAnswer":1,"explanation":"A. Incorreto. 3 casos de teste n\xe3o cobririam as 4 parti\xe7\xf5es v\xe1lidas identificadas. B. Correto. S\xe3o necess\xe1rios 4 casos de teste para cobrir as 4 parti\xe7\xf5es v\xe1lidas identificadas: uma para Reprovado (0-59), uma para Aprovado (60-69), uma para Bom (70-89) e uma para Excelente (90-100). De acordo com o syllabus, para obter 100% de cobertura com a parti\xe7\xe3o de equival\xeancia, os casos de teste devem exercitar todas as parti\xe7\xf5es identificadas, cobrindo cada parti\xe7\xe3o pelo menos uma vez. C. Incorreto. 5 casos de teste seriam mais do que o necess\xe1rio para cobrir as parti\xe7\xf5es v\xe1lidas m\xednimas. D. Incorreto. 6 casos de teste excedem o n\xfamero m\xednimo exigido.","source":"User Provided Batch 4"},{"id":"q_batch4_9dq3pcf6l","chapter":4,"topic":"Desarrollo y Testing","difficulty":"medium","question":"Para um campo \'Idade\' que aceita valores de 16 a 65 anos, seu conjunto de testes inclui os seguintes valores: 15, 16, 17, 64, 65, 66. Qual porcentagem de cobertura da An\xe1lise de Valor Limite (AVL) de 3 valores voc\xea alcan\xe7a?","options":["50%","67%","83%","100%"],"correctAnswer":3,"explanation":"A. Incorreto. 50% seria 3 dos 6 itens cobertos. B. Incorreto. 67% seria 4 dos 6 itens cobertos. C. Incorreto. 83% seria 5 dos 6 itens cobertos. D. Correto. No BVA de 3 valores, para cada valor limite (16 e 65) existem tr\xeas elementos de cobertura: o valor limite e seus dois vizinhos. Para o limite 16: 15, 16, 17. Para o limite 65: 64, 65, 66. O conjunto de testes cobre os 6 elementos exigidos (15, 16, 17, 64, 65, 66), portanto 6/6 = 100%.","source":"User Provided Batch 4"},{"id":"q_batch4_lwvrb8dbo","chapter":4,"topic":"Desarrollo y Testing","difficulty":"medium","question":"Em uma tabela de decis\xe3o para um sistema de aprova\xe7\xe3o de empr\xe9stimos, voc\xea tem as seguintes condi\xe7\xf5es: Idade \u2265 18 anos; Renda \u2265 $30.000; Bom hist\xf3rico de cr\xe9dito; Empregado por \u2265 2 anos. Se voc\xea quisesse minimizar a tabela devido \xe0 grande quantidade de combina\xe7\xf5es, qual seria a melhor estrat\xe9gia?","options":["Eliminar todas as condi\xe7\xf5es menos importantes","Usar uma abordagem baseada em risco para reduzir as regras a serem testadas","Combinar todas as condi\xe7\xf5es em uma \xfanica regra","Criar v\xe1rias tabelas pequenas separadas"],"correctAnswer":1,"explanation":"A. Incorreto. A elimina\xe7\xe3o de condi\xe7\xf5es pode deixar lacunas significativas na cobertura. B. Correto. De acordo com o syllabus, \'se houver muitas condi\xe7\xf5es, o exerc\xedcio de todas as regras de decis\xe3o pode levar muito tempo, pois o n\xfamero de regras cresce exponencialmente com o n\xfamero de condi\xe7\xf5es. Nesse caso, para reduzir o n\xfamero de regras que devem ser exercidas, pode-se usar uma tabela de decis\xe3o minimizada ou uma abordagem baseada no risco.\' C. Incorreto. Combinar todas as condi\xe7\xf5es n\xe3o resolve o problema de complexidade. D. Incorreto. V\xe1rias tabelas separadas n\xe3o resolvem o problema das combina\xe7\xf5es exponenciais.","source":"User Provided Batch 4"},{"id":"q_batch4_paz05v6hi","chapter":4,"topic":"Desarrollo y Testing","difficulty":"medium","question":"Qual das seguintes afirma\xe7\xf5es REFERE-SE \xe0 suposi\xe7\xe3o de erros em um processo de teste?","options":["A suposi\xe7\xe3o de erros baseia-se unicamente em m\xe9tricas quantitativas de defeitos anteriores sem considerar o contexto de desenvolvimento.","A suposi\xe7\xe3o de erros envolve a identifica\xe7\xe3o das \xe1reas do software que t\xeam mais probabilidade de conter defeitos, com base no hist\xf3rico de erros e na complexidade do c\xf3digo.","A suposi\xe7\xe3o de erros exige que os testadores realizem testes de unidade em todas as fun\xe7\xf5es antes de poderem prever erros.","A suposi\xe7\xe3o de erros \xe9 um processo que apenas os desenvolvedores podem realizar, uma vez que eles conhecem melhor seu c\xf3digo."],"correctAnswer":1,"explanation":"A. Incorreto. Embora as m\xe9tricas quantitativas sejam \xfateis, a suposi\xe7\xe3o de erros tamb\xe9m considera o contexto e a experi\xeancia pr\xe9via para ser eficaz. B. Correto. A suposi\xe7\xe3o de erros envolve o uso do hist\xf3rico de erros em conjunto com fatores como a complexidade do c\xf3digo para identificar \xe1reas problem\xe1ticas. C. Incorreto. A suposi\xe7\xe3o de erros n\xe3o depende da realiza\xe7\xe3o de testes de unidade, mas sim da an\xe1lise de padr\xf5es de defeitos anteriores. D. Incorreto. A suposi\xe7\xe3o de erros \xe9 uma tarefa que tamb\xe9m pode ser realizada por testadores, que podem trazer uma perspectiva diferente sobre as \xe1reas de risco.","source":"User Provided Batch 4"},{"id":"q_batch4_a4nevsfk4","chapter":4,"topic":"Desarrollo y Testing","difficulty":"medium","question":"Uma equipe de desenvolvimento est\xe1 criando um aplicativo m\xf3vel inovador e decidiu usar testes explorat\xf3rios devido \xe0 falta de documenta\xe7\xe3o. Qual das seguintes afirma\xe7\xf5es sobre os testes explorat\xf3rios est\xe1 CORRETA?","options":["Os testes explorat\xf3rios s\xe3o sempre menos eficazes do que os testes baseados em requisitos.","Os testes explorat\xf3rios permitem que os testadores se adaptem rapidamente a altera\xe7\xf5es no software.","Os testes explorat\xf3rios exigem um plano de teste detalhado antes de serem executados.","Os testes explorat\xf3rios n\xe3o s\xe3o adequados para aplica\xe7\xf5es complexas."],"correctAnswer":1,"explanation":"A. Incorreto. Os testes explorat\xf3rios podem ser muito eficazes, especialmente em ambientes onde os requisitos s\xe3o amb\xedguos ou mudam com frequ\xeancia. B. Correto. Os testes explorat\xf3rios permitem aos testadores adaptar-se e responder de forma mais flex\xedvel \xe0s altera\xe7\xf5es no software. C. Incorreto. Embora possa haver uma abordagem geral, os testes explorat\xf3rios caracterizam-se por n\xe3o dependerem de um plano de teste rigoroso e detalhado. D. Incorreto. Os testes explorat\xf3rios podem ser muito \xfateis em aplica\xe7\xf5es complexas, permitindo uma explora\xe7\xe3o mais din\xe2mica e criativa.","source":"User Provided Batch 4"},{"id":"q_batch4_q2p8s0mdy","chapter":1,"topic":"Desarrollo y Testing","difficulty":"medium","question":"Qual das seguintes afirma\xe7\xf5es \xe9 a MELHOR para descrever como os crit\xe9rios de aceite podem ser estruturados em uma hist\xf3ria de usu\xe1rio?","options":["Definidos exclusivamente pela equipe de desenvolvimento, sem necessidade de revis\xe3o pelas partes interessadas.","Redigidos em um formato claro e conciso que facilite a compreens\xe3o por todas as partes interessadas envolvidas.","Criando uma lista extensa de requisitos t\xe9cnicos que devem ser cumpridos para a entrega da hist\xf3ria de usu\xe1rio.","Estabelecidos com base nas expectativas pessoais dos membros da equipe, sem considerar os objetivos do projeto."],"correctAnswer":1,"explanation":"A. Incorreto. Os crit\xe9rios de aceite devem ser revisados e acordados por todas as partes interessadas, n\xe3o apenas pela equipe de desenvolvimento. B. Correto. Um formato claro e conciso ajuda a garantir que todas as partes interessadas entendam o que \xe9 necess\xe1rio para considerar a hist\xf3ria do usu\xe1rio conclu\xedda. C. Incorreto. Embora os requisitos t\xe9cnicos possam ser importantes, os crit\xe9rios de aceite devem concentrar-se nas condi\xe7\xf5es de satisfa\xe7\xe3o do usu\xe1rio e n\xe3o em uma lista t\xe9cnica exaustiva. D. Incorreto. Os crit\xe9rios de aceite devem estar alinhados com os objetivos do projeto e as necessidades do usu\xe1rio, e n\xe3o baseados em expectativas individuais.","source":"User Provided Batch 4"},{"id":"q_batch4_m7s7cmw0j","chapter":4,"topic":"Desarrollo y Testing","difficulty":"medium","question":"Durante um workshop de especifica\xe7\xe3o ATDD, a equipe identifica ambiguidades em uma hist\xf3ria de usu\xe1rio sobre processamento de pagamentos. Qual \xe9 a a\xe7\xe3o MAIS adequada de acordo com a abordagem ATDD?","options":["O testador deve criar casos de teste que abranjam todas as interpreta\xe7\xf5es poss\xedveis","Resolver as ambiguidades durante o workshop antes de criar os casos de teste","Adiar a cria\xe7\xe3o de casos de teste at\xe9 que o desenvolvimento esteja conclu\xeddo","Criar casos de teste apenas para os cen\xe1rios mais prov\xe1veis"],"correctAnswer":1,"explanation":"A. Incorreto. Criar casos para todas as interpreta\xe7\xf5es sem resolver ambiguidades pode levar a casos conflitantes ou incorretos. B. Correto. De acordo com o syllabus, durante o workshop de especifica\xe7\xe3o, \'incompletude, ambiguidades ou defeitos na hist\xf3ria do usu\xe1rio s\xe3o resolvidos durante este processo\' antes de prosseguir com a cria\xe7\xe3o de casos de teste. Isso \xe9 fundamental no ATDD para garantir que todos tenham a mesma compreens\xe3o. C. Incorreto. D. Incorreto.","source":"User Provided Batch 4"},{"id":"q_batch4_s9bm5wa3g","chapter":5,"topic":"Desarrollo y Testing","difficulty":"medium","question":"Qual das alternativas a seguir \xe9 um crit\xe9rio de entrada para a execu\xe7\xe3o de testes?","options":["Os resultados de testes anteriores foram documentados.","Os crit\xe9rios de aceite dos requisitos foram definidos.","A equipe de testes concluiu o planejamento dos testes.","O software passou em todos os testes de unidade."],"correctAnswer":1,"explanation":"A. Incorreto. Documentar os resultados de testes anteriores \xe9 uma boa pr\xe1tica, mas n\xe3o \xe9 um crit\xe9rio de entrada espec\xedfico. B. Correto. A defini\xe7\xe3o dos crit\xe9rios de aceite dos requisitos \xe9 essencial para garantir que os crit\xe9rios de entrada sejam claros antes do teste. C. Incorreto. Concluir o planejamento dos testes pode ser um passo pr\xe9vio, mas n\xe3o \xe9 um crit\xe9rio de entrada em si. D. Incorreto. Passar em todos os testes de unidade \xe9 um crit\xe9rio de sa\xedda, indicando que uma fase de teste foi conclu\xedda com sucesso.","source":"User Provided Batch 4"},{"id":"q_batch4_jq145tq22","chapter":5,"topic":"Desarrollo y Testing","difficulty":"medium","question":"Em seu plano de testes, voc\xea priorizou os casos de teste com base nos requisitos. No entanto, voc\xea percebe que alguns casos de alta prioridade n\xe3o podem ser executados na ordem ideal devido a depend\xeancias e disponibilidade de recursos. Qual \xe9 a a\xe7\xe3o MAIS apropriada de acordo com o syllabus?","options":["Manter a ordem baseada na prioridade dos requisitos, ignorando as depend\xeancias","Ajustar a ordem considerando as depend\xeancias e a disponibilidade de recursos","Mudar para uma estrat\xe9gia de prioriza\xe7\xe3o diferente","Executar apenas os casos independentes de alta prioridade"],"correctAnswer":1,"explanation":"A. Incorreto. Ignorar depend\xeancias pode fazer com que os testes falhem por motivos t\xe9cnicos, em vez de defeitos reais. B. Correto. O syllabus afirma que \'se um caso de teste com uma prioridade mais alta depender de um caso de teste com uma prioridade mais baixa, o caso de teste de prioridade mais baixa deve ser executado primeiro\' e que \'a ordem de execu\xe7\xe3o do teste tamb\xe9m deve levar em conta a disponibilidade de recursos\'. C. Incorreto. N\xe3o \xe9 necess\xe1rio mudar a estrat\xe9gia de prioriza\xe7\xe3o, apenas ajustar a ordem de execu\xe7\xe3o. D. Incorreto. Isso limitaria indevidamente a cobertura dos testes.","source":"User Provided Batch 4"},{"id":"q_batch4_f4ffyxzso","chapter":4,"topic":"Desarrollo y Testing","difficulty":"medium","question":"Como os testes a seguir s\xe3o classificados de acordo com os quadrantes de teste \xe1gil (A-D)? Selecione a op\xe7\xe3o correta.\\n\\n1. Testes de componentes\\n2. Testes funcionais\\n3. Testes explorat\xf3rios\\n4. Testes n\xe3o funcionais\\n\\nA (Q1). Orientado \xe0 tecnologia, apoia a equipe\\nB (Q2). Orientado ao neg\xf3cio, apoia a equipe\\nC (Q3). Orientado ao neg\xf3cio, cr\xedtica ao produto\\nD (Q4). Orientado \xe0 tecnologia, cr\xedtica ao produto","options":["1A, 2B, 3C, 4D","1B, 2A, 3D, 4C","1C, 2D, 3A, 4B","1D, 2C, 3B, 4A"],"correctAnswer":0,"explanation":"A. Correto \u2013 segundo o syllabus (se\xe7\xe3o 5.1.7, p. 53): 1 (testes de componentes) \u2192 Q1 (tecnologia, apoio \xe0 equipe); 2 (testes funcionais) \u2192 Q2 (neg\xf3cios, apoio \xe0 equipe); 3 (testes explorat\xf3rios) \u2192 Q3 (neg\xf3cios, cr\xedtica ao produto); 4 (testes n\xe3o funcionais) \u2192 Q4 (tecnologia, cr\xedtica ao produto). Os testes desses quadrantes est\xe3o diretamente relacionados aos n\xedveis e tipos de teste indicados no modelo Marick/Crispin. B. Incorreto \u2013 os testes de componentes (1) n\xe3o est\xe3o no Q2; est\xe3o no Q1. Os testes funcionais (2) n\xe3o est\xe3o no Q1; est\xe3o no Q2. C. Incorreto \u2013 os testes explorat\xf3rios (3) n\xe3o est\xe3o no Q1; est\xe3o no Q3. Os testes n\xe3o funcionais (4) n\xe3o est\xe3o no Q2; est\xe3o no Q4. D. Incorreto \u2013 os testes de componentes (1) n\xe3o est\xe3o no Q4; est\xe3o no Q1. Os testes explorat\xf3rios (3) n\xe3o est\xe3o no Q2; est\xe3o no Q3.","source":"User Provided Batch 4"},{"id":"q_batch4_z9hth9gwh","chapter":3,"topic":"Desarrollo y Testing","difficulty":"medium","question":"Em um projeto de desenvolvimento de software, foi identificado o seguinte risco: Risco: A documenta\xe7\xe3o do usu\xe1rio n\xe3o est\xe1 atualizada. Probabilidade do risco: alta; impacto do risco: m\xe9dio Resposta ao risco: organizar uma revis\xe3o exaustiva da documenta\xe7\xe3o com a equipe de desenvolvimento; informar os usu\xe1rios sobre poss\xedveis inconsist\xeancias na documenta\xe7\xe3o. Qual \xe9 a medida mais adequada para responder a este risco analisado?","options":["Mitiga\xe7\xe3o de risco","Aceita\xe7\xe3o de risco","Transfer\xeancia de risco","Elimina\xe7\xe3o de risco"],"correctAnswer":0,"explanation":"A. Correto. A revis\xe3o da documenta\xe7\xe3o ajuda a mitigar o risco de inconsist\xeancias. B. Incorreto. Aceitar o risco n\xe3o aborda o problema de documenta\xe7\xe3o desatualizada. C. Incorreto. O risco n\xe3o est\xe1 sendo transferido, mas abordado diretamente. D. Incorreto. Esse risco n\xe3o pode ser totalmente eliminado, mas podem ser tomadas medidas para mitig\xe1-lo.","source":"User Provided Batch 4"},{"id":"q_batch4_kzxw2m4i9","chapter":5,"topic":"Desarrollo y Testing","difficulty":"medium","question":"No acompanhamento dos defeitos encontrados durante os testes, qual \xe9 o benef\xedcio da ger\xeancia de configura\xe7\xe3o neste processo?","options":["Ajuda a documentar os requisitos de teste.","Permite identificar a vers\xe3o do software em que o defeito foi encontrado.","Facilita a cria\xe7\xe3o de novos casos de teste.","Garante que todos os defeitos sejam resolvidos antes da entrega."],"correctAnswer":1,"explanation":"A. Incorreto. A ger\xeancia de configura\xe7\xe3o n\xe3o se concentra em requisitos, mas no gerenciamento de itens de teste e de suas vers\xf5es. B. Correto. A ger\xeancia de configura\xe7\xe3o permite que os defeitos sejam associados a vers\xf5es espec\xedficas do software, facilitando o seu rastreamento e resolu\xe7\xe3o. C. Incorreto. A cria\xe7\xe3o de novos casos de teste faz parte da modelagem de testes e n\xe3o \xe9 um benef\xedcio direto da ger\xeancia de configura\xe7\xe3o. D. Incorreto.","source":"User Provided Batch 4"},{"id":"q_batch4_attdk2hjt","chapter":5,"topic":"Desarrollo y Testing","difficulty":"medium","question":"Um analista de testes prepara o seguinte relat\xf3rio de defeito: ID: BUG-00721 | T\xedtulo: O campo \'Data de nascimento\' aceita datas futuras | Severidade: M\xe9dia | Prioridade: Alta | Reportado por: A. L\xf3pez | Configura\xe7\xe3o: App v3.2.1, Chrome 120 | Passos para reproduzir: (1) Abrir o formul\xe1rio de cadastro, (2) Inserir data de nascimento \'15/08/2030\', (3) Clicar em \'Salvar\'. Qual \xe9 a informa\xe7\xe3o MAIS importante que falta neste relat\xf3rio?","options":["O nome do desenvolvedor designado para resolver o defeito.","O resultado real obtido e o resultado esperado, para facilitar a reprodu\xe7\xe3o e a corre\xe7\xe3o.","Uma estimativa do tempo necess\xe1rio para corrigir o defeito.","O n\xfamero de usu\xe1rios afetados pelo defeito."],"correctAnswer":1,"explanation":"A. Incorreto. A atribui\xe7\xe3o do defeito a um desenvolvedor \xe9 uma atividade de gerenciamento subsequente, n\xe3o um componente essencial do relat\xf3rio inicial. B. Correto. De acordo com o Programa de Estudos do CTFL v4.0 \xa75.5.1, um relat\xf3rio de defeito completo deve incluir os resultados reais obtidos e os resultados esperados. Sem essas informa\xe7\xf5es, o desenvolvedor n\xe3o pode confirmar o comportamento incorreto ou validar a corre\xe7\xe3o. C. Incorreto. A estimativa do tempo de corre\xe7\xe3o \xe9 responsabilidade da equipe de desenvolvimento e n\xe3o do relat\xf3rio de defeitos. D. Incorreto. O impacto sobre os usu\xe1rios pode ser indicado em prioridade/severidade, mas n\xe3o \xe9 um campo essencial do relat\xf3rio de defeitos, de acordo com o syllabus.","source":"User Provided Batch 4"},{"id":"q_batch4_83alrpwtk","chapter":5,"topic":"Desarrollo y Testing","difficulty":"medium","question":"Qual das seguintes ferramentas de teste \xe9 geralmente utilizada para automatizar a execu\xe7\xe3o de testes?","options":["Ferramentas de gerenciamento de testes","Ferramentas de testes de desempenho","Ferramentas de automa\xe7\xe3o de testes","Ferramentas de gerenciamento de defeitos"],"correctAnswer":2,"explanation":"A. Incorreto. As ferramentas de gerenciamento de testes s\xe3o usadas para planejar, organizar e monitorar o processo de teste, mas n\xe3o para executar testes de forma automatizada. B. Incorreto. As ferramentas de testes de desempenho s\xe3o projetadas para avaliar o desempenho do sistema sob carga, n\xe3o para automatizar a execu\xe7\xe3o de testes em geral. C. Correto. As ferramentas de automa\xe7\xe3o de testes s\xe3o projetadas especificamente para executar testes automaticamente, permitindo realizar testes de maneira mais r\xe1pida e eficiente. D. Incorreto. As ferramentas de gerenciamento de defeitos s\xe3o usadas para rastrear e gerenciar os erros encontrados durante o processo de teste, n\xe3o para automatizar a execu\xe7\xe3o de testes.","source":"User Provided Batch 4"},{"id":"q_batch4_7576lzkad","chapter":1,"topic":"Desarrollo y Testing","difficulty":"medium","question":"Qual das seguintes afirma\xe7\xf5es descreve um benef\xedcio da automa\xe7\xe3o de testes?","options":["Aumenta a cobertura de testes em menos tempo","Elimina completamente a necessidade de testes manuais","Reduz a complexidade do desenvolvimento de software","Aumenta a possibilidade de erros humanos na execu\xe7\xe3o"],"correctAnswer":0,"explanation":"A. Correto. A automa\xe7\xe3o permite executar testes de forma mais r\xe1pida e com maior frequ\xeancia, o que pode aumentar a cobertura de testes. B. Incorreto. Embora a automa\xe7\xe3o possa reduzir a necessidade de testes manuais, ela n\xe3o pode elimin\xe1-los completamente em todos os casos. C. Incorreto. A automa\xe7\xe3o n\xe3o necessariamente reduz a complexidade do software e pode, de fato, introduzir a sua pr\xf3pria complexidade. D. Incorreto. A automa\xe7\xe3o, se bem feita, pode reduzir a possibilidade de erros humanos durante a execu\xe7\xe3o dos testes.","source":"User Provided Batch 4"},{"id":"q_batch5_oy2vhh5m6","chapter":5,"topic":"Desarrollo y Testing","difficulty":"medium","question":"Que tipo de ferramenta de teste \xe9 mais adequada para o gerenciamento de incidentes em um projeto de software?","options":["Ferramenta de gerenciamento de testes","Ferramenta de automa\xe7\xe3o de testes","Ferramenta de rastreamento de incidentes","Ferramenta de ger\xeancia de configura\xe7\xe3o"],"correctAnswer":2,"explanation":"A. Incorreto. Embora as ferramentas de gerenciamento de testes ajudem a organizar e planejar testes, elas n\xe3o s\xe3o projetadas especificamente para gerenciar incidentes. B. Incorreto. As ferramentas de automa\xe7\xe3o de testes est\xe3o focadas em executar testes automaticamente, n\xe3o em gerenciar incidentes. C. Correto. As ferramentas de rastreamento de incidentes s\xe3o essenciais para registrar, rastrear e gerenciar defeitos encontrados durante os testes. D. Incorreto. As ferramentas de ger\xeancia de configura\xe7\xe3o s\xe3o usadas para controlar e manter as configura\xe7\xf5es de software, mas n\xe3o s\xe3o para o gerenciamento de incidentes.","source":"User Provided Batch 4"},{"id":"q_batch5_o536w1du4","chapter":5,"topic":"Desarrollo y Testing","difficulty":"medium","question":"Qual \xe9 o principal benef\xedcio de usar uma ferramenta de gerenciamento de testes?","options":["Automatizar testes sem interven\xe7\xe3o humana","Facilitar o planejamento e monitoramento de testes","Gerar automaticamente casos de teste a partir do c\xf3digo","Identificar erros no c\xf3digo sem executar testes"],"correctAnswer":1,"explanation":"A. Incorreto. Embora algumas ferramentas possam ajudar na automa\xe7\xe3o, o objetivo principal de uma ferramenta de gerenciamento de testes \xe9 o planejamento e o monitoramento. B. Correto. Uma ferramenta de gerenciamento de testes permite que as equipes planejem, organizem e monitorem o progresso dos testes, facilitando a coordena\xe7\xe3o e a comunica\xe7\xe3o. C. Incorreto. As ferramentas que geram casos de teste automaticamente costumam ser ferramentas de an\xe1lise, e n\xe3o ferramentas de gerenciamento de testes. D. Incorreto. Identificar erros no c\xf3digo sem executar testes n\xe3o \xe9 fun\xe7\xe3o das ferramentas de gerenciamento de testes; em vez disso, \xe9 uma fun\xe7\xe3o das ferramentas de an\xe1lise est\xe1tica.","source":"User Provided Batch 4"},{"id":"q_batch5_pdbyrk068","chapter":5,"topic":"Desarrollo y Testing","difficulty":"medium","question":"Qual das seguintes afirma\xe7\xf5es descreve um benef\xedcio da automa\xe7\xe3o de testes?","options":["Aumenta a necessidade de a equipe ser altamente treinada em programa\xe7\xe3o","Permite a execu\xe7\xe3o de testes repetitivos de forma r\xe1pida e consistente","O custo de manuten\xe7\xe3o do software de teste aumenta significativamente","Requer menos tempo para planejar os testes manuais"],"correctAnswer":1,"explanation":"A. Incorreto. Embora a automa\xe7\xe3o possa exigir algum treinamento, isso n\xe3o \xe9 um benef\xedcio intr\xednseco. B. Correto. A automa\xe7\xe3o permite que testes repetitivos sejam executados de forma r\xe1pida e consistente, o que \xe9 um grande benef\xedcio. C. Incorreto. Embora possa haver custos de manuten\xe7\xe3o, a vantagem \xe9 que a efici\xeancia pode ser aumentada. D. Incorreto. A automa\xe7\xe3o n\xe3o reduz necessariamente o tempo de planejamento de testes manuais.","source":"User Provided Batch 4"},{"id":"q_batch5_aqadcfs6i","chapter":1,"topic":"Desarrollo y Testing","difficulty":"medium","question":"Qual das alternativas a seguir \xe9 um benef\xedcio da automa\xe7\xe3o de testes?","options":["Aumento na cobertura de testes","Aumento do tempo necess\xe1rio para a execu\xe7\xe3o dos testes","Depend\xeancia de ferramentas de teste espec\xedficas","Redu\xe7\xe3o da documenta\xe7\xe3o necess\xe1ria"],"correctAnswer":0,"explanation":"A. Correto. A automa\xe7\xe3o de testes permite a execu\xe7\xe3o de mais testes em menos tempo, aumentando a cobertura. B. Incorreto. A automa\xe7\xe3o geralmente reduz o tempo necess\xe1rio para executar um conjunto de testes. C. Incorreto. Embora a automa\xe7\xe3o possa criar depend\xeancia de ferramentas, isso n\xe3o \xe9 um benef\xedcio. D. Incorreto. A automa\xe7\xe3o n\xe3o reduz necessariamente a documenta\xe7\xe3o, muitas vezes requerendo documenta\xe7\xe3o adicional para scripts de teste.","source":"User Provided Batch 4"},{"id":"q_batch6_1","chapter":6,"topic":"Herramientas","difficulty":"medium","question":"Qual das op\xe7\xf5es a seguir \xe9 um benef\xedcio fundamental da automa\xe7\xe3o de testes no desenvolvimento de software?","options":["Aumenta o tempo necess\xe1rio para executar testes","Permite a repeti\xe7\xe3o de testes de forma eficiente","Elimina completamente a necessidade de testes manuais","Aumenta o risco de erros no c\xf3digo"],"correctAnswer":1,"explanation":"A. Incorreto. A automa\xe7\xe3o de testes busca reduzir o tempo de execu\xe7\xe3o e n\xe3o aument\xe1-lo. B. Correto. A automa\xe7\xe3o permite que os testes sejam executados de forma r\xe1pida e repetitiva, o que \xe9 um grande benef\xedcio. C. Incorreto. Embora a automa\xe7\xe3o reduza a necessidade de testes manuais, ela n\xe3o elimina totalmente a necessidade deles. D. Incorreto. O objetivo \xe9 reduzir erros, embora possa haver riscos se n\xe3o forem gerenciados adequadamente.","source":"User Provided Batch 5"},{"id":"q_batch6_6","chapter":6,"topic":"Herramientas","difficulty":"medium","question":"Qual das seguintes ferramentas \xe9 usada principalmente para automa\xe7\xe3o de testes?","options":["Ferramentas de gerenciamento de testes","Ferramentas de captura de testes","Ferramentas de teste automatizado","Ferramentas de an\xe1lise de requisitos"],"correctAnswer":2,"explanation":"A. Incorreto. As ferramentas de gerenciamento de testes s\xe3o projetadas para planejar, rastrear e organizar as atividades de teste, mas n\xe3o s\xe3o usadas para automatizar os testes. B. Incorreto. As ferramentas de captura de testes s\xe3o usadas para registrar a intera\xe7\xe3o do usu\xe1rio com o aplicativo, mas n\xe3o automatizam o processo de teste em si. C. Correto. As ferramentas de testes automatizados permitem que os testes sejam executados sem interven\xe7\xe3o humana, facilitando a execu\xe7\xe3o mais r\xe1pida e repet\xedvel. D. Incorreto. As ferramentas de an\xe1lise de requisitos se concentram no gerenciamento e an\xe1lise de requisitos de software e n\xe3o t\xeam fun\xe7\xe3o na automa\xe7\xe3o de testes.","source":"User Provided Batch 5"},{"chapter":1,"topic":"Fundamentos","difficulty":"easy","question":"Qual das afirma\xe7\xf5es a seguir representa um objetivo de teste adequado?","options":["Garantir que o sistema esteja totalmente livre de defeitos.","Identificar defeitos e garantir que os requisitos sejam atendidos de forma adequada.","Demonstrar que o sistema funcionar\xe1 em todas as condi\xe7\xf5es poss\xedveis.","Verificar se os usu\xe1rios n\xe3o relatam reclama\xe7\xf5es sobre o desempenho do sistema."],"correctAnswer":1,"explanation":"A. Incorreto. N\xe3o se pode garantir que um sistema esteja completamente livre de defeitos. Veja o princ\xedpio de teste 1. B. Correto. Um dos principais objetivos do teste \xe9 identificar defeitos e confirmar se os requisitos foram implementados corretamente. C. Incorreto. \xc9 imposs\xedvel testar todas as condi\xe7\xf5es poss\xedveis, o que est\xe1 relacionado ao princ\xedpio de teste 2. D. Incorreto. Embora a satisfa\xe7\xe3o do usu\xe1rio seja importante, o teste deve focar na identifica\xe7\xe3o de defeitos e n\xe3o na aus\xeancia de reclama\xe7\xf5es.","source":"User Provided Batch 7","id":"q_batch7_1"},{"chapter":1,"topic":"Fundamentos","difficulty":"medium","question":"Uma empresa de software desenvolve aplica\xe7\xf5es para o setor financeiro. A equipe de gerenciamento pergunta ao gerente de testes por que os testes s\xe3o essenciais no contexto deles, al\xe9m de encontrar defeitos.\\n\\nQual dos seguintes motivos descreve MELHOR por que o teste \xe9 necess\xe1rio neste contexto?","options":["Para demonstrar que o software n\xe3o tem defeitos antes da entrega.","Para proporcionar confian\xe7a no n\xedvel de qualidade do software e cumprir os requisitos regulat\xf3rios do setor.","Para substituir o processo de revis\xe3o de requisitos e reduzir a documenta\xe7\xe3o.","Para garantir que todos os desenvolvedores conhe\xe7am o c\xf3digo do sistema completo."],"correctAnswer":1,"explanation":"A. Incorreto. O Princ\xedpio 1 do CTFL v4.0 afirma que os testes mostram a presen\xe7a de defeitos, n\xe3o a sua aus\xeancia. \xc9 imposs\xedvel garantir que n\xe3o haja defeitos. B. Correto. O Syllabus do CTFL v4.0 \xa71.2.1 afirma que os testes s\xe3o necess\xe1rios para fornecer uma avalia\xe7\xe3o da qualidade do software e para cumprir requisitos contratuais ou regulamentares, o que \xe9 especialmente relevante no setor financeiro. C. Incorreto. Os testes complementam as revis\xf5es; n\xe3o as substituem nem reduzem a necessidade de documenta\xe7\xe3o. D. Incorreto. O objetivo do teste n\xe3o \xe9 treinar a equipe de desenvolvimento.","source":"User Provided Batch 7","id":"q_batch7_2"},{"chapter":1,"topic":"Principios","difficulty":"medium","question":"Voc\xea \xe9 o l\xedder de uma equipe de testes e nota que, apesar de realizar testes exaustivos na fase de desenvolvimento, o software continua apresentando defeitos em produ\xe7\xe3o. Qual princ\xedpio de teste poderia explicar essa situa\xe7\xe3o?","options":["Os defeitos se agrupam","Testes exaustivos s\xe3o imposs\xedveis","Os testes se desgastam","Fal\xe1cia da aus\xeancia de defeitos"],"correctAnswer":1,"explanation":"A. Incorreto. Este princ\xedpio refere-se ao fato de que poucos componentes geralmente acumulam a maioria dos defeitos, mas n\xe3o explica o surgimento de defeitos em produ\xe7\xe3o ap\xf3s testes exaustivos. B. Correto. Este princ\xedpio indica que \xe9 imposs\xedvel testar todas as combina\xe7\xf5es de entradas e condi\xe7\xf5es, o que pode levar a defeitos que n\xe3o foram identificados durante os testes. C. Incorreto. Este princ\xedpio indica que testes repetidos perdem a efic\xe1cia, mas n\xe3o \xe9 diretamente o motivo pelo qual aparecem defeitos em produ\xe7\xe3o. D. Incorreto. Este princ\xedpio refere-se \xe0 cren\xe7a err\xf4nea de que a aus\xeancia de defeitos garante o sucesso do software, mas n\xe3o est\xe1 relacionado ao fato de que continuam aparecendo defeitos.","source":"User Provided Batch 7","id":"q_batch7_3"},{"chapter":1,"topic":"Proceso de Prueba","difficulty":"medium","question":"Em um projeto de desenvolvimento de software, a equipe est\xe1 preparando a fase de testes ap\xf3s concluir a fase de desenvolvimento. Qual das seguintes atividades faz parte do planejamento de testes?","options":["Definir os crit\xe9rios de aceite para avaliar se a funcionalidade desenvolvida atende aos requisitos.","Executar os testes de regress\xe3o para garantir que as novas funcionalidades n\xe3o quebrem as existentes.","Identificar os riscos associados \xe0 nova funcionalidade e planejar como mitig\xe1-los.","Registrar os defeitos encontrados durante a execu\xe7\xe3o dos testes e comunic\xe1-los \xe0 equipe de desenvolvimento."],"correctAnswer":2,"explanation":"A. Incorreto. Definir crit\xe9rios de aceite faz parte da fase de an\xe1lise de requisitos, n\xe3o do planejamento de testes. B. Incorreto. A execu\xe7\xe3o de testes \xe9 uma atividade que ocorre ap\xf3s o planejamento. C. Correto. Identificar riscos e planejar sua mitiga\xe7\xe3o \xe9 uma parte essencial do planejamento de testes. D. Incorreto. Registrar defeitos faz parte da execu\xe7\xe3o de testes, n\xe3o do planejamento.","source":"User Provided Batch 7","id":"q_batch7_4"},{"chapter":1,"topic":"Contexto de las Pruebas","difficulty":"medium","question":"Quais fatores podem afetar o escopo e a profundidade dos testes em um projeto?\\n\\n1. A complexidade do sistema a ser testado\\n2. A experi\xeancia da equipe de testes\\n3. O or\xe7amento alocado para o projeto\\n4. O tipo de dados utilizados nos testes","options":["1, 2, 3 afetam o escopo e a profundidade","2, 3, 4 afetam o escopo e a profundidade","1, 3, 4 afetam o escopo e a profundidade","1, 2, 4 afetam o escopo e a profundidade"],"correctAnswer":0,"explanation":"A. 1. Verdadeiro. A complexidade do sistema \xe9 um fator t\xe9cnico que influencia a abordagem e a profundidade dos testes. 2. Verdadeiro. A experi\xeancia da equipe \xe9 um fator humano que determina a efic\xe1cia e o detalhamento das atividades de teste. 3. Verdadeiro. O or\xe7amento \xe9 uma restri\xe7\xe3o do projeto que define o escopo poss\xedvel dos testes. De acordo com a se\xe7\xe3o 1.4.2 do syllabus, estes s\xe3o fatores contextuais fundamentais, enquanto o tipo de dados (4) \xe9 considerado um produto do design de testes (testware) e n\xe3o um fator de contexto prim\xe1rio. Portanto, a resposta correta \xe9 A. B. Veja a explica\xe7\xe3o/justificativa da resposta A. C. Veja a explica\xe7\xe3o/justificativa da resposta A. D. Veja a explica\xe7\xe3o/justificativa da resposta A.","source":"User Provided Batch 7","id":"q_batch7_5"},{"chapter":1,"topic":"Roles en las Pruebas","difficulty":"medium","question":"Qual das seguintes atividades corresponde PRINCIPALMENTE ao papel do testador (tester) e N\xc3O ao gerente de testes, de acordo com o Syllabus CTFL v4.0?","options":["Planejar o esfor\xe7o de testes e negociar prazos com a dire\xe7\xe3o do projeto.","Analisar, projetar e implementar os casos de teste para as funcionalidades atribu\xeddas.","Gerenciar o or\xe7amento do projeto de testes.","Selecionar e adquirir as ferramentas de teste para a equipe."],"correctAnswer":1,"explanation":"A. Incorreto. Planejar o esfor\xe7o de testes e negociar com a dire\xe7\xe3o \xe9 responsabilidade do gerente de testes. B. Correto. O Syllabus CTFL v4.0 \xa71.4.5 estabelece que o testador \xe9 respons\xe1vel por analisar os requisitos, projetar casos de teste, implementar e executar os testes. Estas s\xe3o atividades t\xe9cnicas do n\xedvel de teste. C. Incorreto. Gerenciar o or\xe7amento \xe9 responsabilidade do gerente de testes. D. Incorreto. A sele\xe7\xe3o de ferramentas \xe9 uma decis\xe3o de gest\xe3o que corresponde ao gerente de testes.","source":"User Provided Batch 7","id":"q_batch7_6"},{"chapter":1,"topic":"Habilidades Esenciales","difficulty":"medium","question":"Quais habilidades s\xe3o essenciais para um testador ao trabalhar em uma equipe \xe1gil?\\n\\n1. Escuta ativa\\n2. Conhecimentos t\xe9cnicos profundos\\n3. Comunica\xe7\xe3o eficaz\\n4. Capacidade de trabalhar sob press\xe3o","options":["1 e 3 s\xe3o essenciais; 2 e 4 n\xe3o s\xe3o","1, 2 e 4 s\xe3o essenciais; 3 n\xe3o \xe9","3 e 4 s\xe3o essenciais; 1 e 2 n\xe3o s\xe3o","1, 3 e 2 s\xe3o essenciais; 4 n\xe3o \xe9"],"correctAnswer":3,"explanation":"A. A escuta ativa (1) e a comunica\xe7\xe3o eficaz (3) s\xe3o habilidades importantes, mas n\xe3o s\xe3o as \xfanicas necess\xe1rias. \xc9 incorreto afirmar que 2 e 4 n\xe3o s\xe3o relevantes. B. O conhecimento t\xe9cnico (2) \xe9 relevante, mas n\xe3o \xe9 t\xe3o crucial quanto a combina\xe7\xe3o de comunica\xe7\xe3o eficaz e escuta ativa em um ambiente \xe1gil. Portanto, esta op\xe7\xe3o \xe9 incorreta. C. Embora 3 e 4 sejam importantes, a falta de escuta ativa e conhecimentos t\xe9cnicos pode limitar a efic\xe1cia do testador. Esta op\xe7\xe3o \xe9 incorreta. D. A escuta ativa (1) e a comunica\xe7\xe3o eficaz (3) s\xe3o habilidades fundamentais em uma equipe \xe1gil, enquanto o conhecimento t\xe9cnico profundo (2) tamb\xe9m \xe9 valioso, mas trabalhar sob press\xe3o (4) \xe9 menos relevante neste contexto. Portanto, esta \xe9 a resposta correta.","source":"User Provided Batch 7","id":"q_batch7_7"},{"chapter":2,"topic":"Pruebas en SDLC","difficulty":"medium","question":"Qual das seguintes afirma\xe7\xf5es descreve melhor a import\xe2ncia de realizar testes em cada fase do ciclo de vida de desenvolvimento de software?","options":["Os testes s\xf3 s\xe3o necess\xe1rios no final do ciclo de vida para garantir que o software funcione.","Realizar testes em cada fase ajuda a identificar defeitos o mais cedo poss\xedvel, reduzindo custos e tempo.","Os testes devem se concentrar apenas na fase de desenvolvimento e n\xe3o nas fases de an\xe1lise ou design.","Os testes s\xe3o irrelevantes nas fases iniciais, j\xe1 que ocorrem mudan\xe7as significativas no software."],"correctAnswer":1,"explanation":"A. Incorreto. Os testes devem ser realizados em todas as fases para encontrar e corrigir defeitos precocemente. B. Correto. Realizar testes em cada fase permite detectar problemas antes, o que pode reduzir custos e tempo. C. Incorreto. Os testes s\xe3o necess\xe1rios em todas as fases, n\xe3o apenas no desenvolvimento, para garantir a qualidade. D. Incorreto. Os testes nas fases iniciais s\xe3o cruciais para prevenir problemas em etapas posteriores.","source":"User Provided Batch 7","id":"q_batch7_9"},{"chapter":2,"topic":"Shift Left","difficulty":"medium","question":"Qual das seguintes atividades representa melhor a filosofia do \\"deslocamento \xe0 esquerda\\" (shift-left) no desenvolvimento de software?","options":["Realizar testes de regress\xe3o ap\xf3s a conclus\xe3o do desenvolvimento do software.","Iniciar a revis\xe3o de design antes que o c\xf3digo seja escrito.","Criar a documenta\xe7\xe3o do usu\xe1rio ap\xf3s o produto estar pronto para o lan\xe7amento.","Executar testes de aceite em um ambiente de produ\xe7\xe3o."],"correctAnswer":1,"explanation":"A. Incorreto. Os testes de regress\xe3o realizados no final n\xe3o s\xe3o um exemplo da abordagem de deslocamento \xe0 esquerda, que promove a realiza\xe7\xe3o de testes mais cedo no ciclo de vida. B. Correto. Iniciar a revis\xe3o de design antes da codifica\xe7\xe3o \xe9 um exemplo claro da abordagem de deslocamento \xe0 esquerda, pois prop\xf5e a detec\xe7\xe3o de defeitos de forma precoce. C. Incorreto. A documenta\xe7\xe3o do usu\xe1rio deveria ser criada antes do lan\xe7amento para facilitar a ado\xe7\xe3o do software, n\xe3o depois. D. Incorreto. Executar testes de aceite em produ\xe7\xe3o n\xe3o faz parte da abordagem de deslocamento \xe0 esquerda, que foca na detec\xe7\xe3o precoce de problemas.","source":"User Provided Batch 7","id":"q_batch7_11"},{"chapter":2,"topic":"Niveles de Prueba","difficulty":"hard","question":"Uma equipe de desenvolvimento trabalha em um sistema de reservas de voos. Relacione cada atividade de teste (1-4) com o n\xedvel de teste correspondente (A-D):\\n\\n1. A equipe verifica que o m\xf3dulo de c\xe1lculo de tarifas produz resultados corretos de forma isolada.\\n2. A equipe verifica que o m\xf3dulo de reservas se comunica corretamente com o m\xf3dulo de pagamentos.\\n3. A equipe executa cen\xe1rios completos de compra de voo de ponta a ponta.\\n4. Os usu\xe1rios finais da companhia a\xe9rea validam que o sistema atende \xe0s suas necessidades operacionais.\\n\\nA. Testes de aceite\\nB. Testes de integra\xe7\xe3o\\nC. Testes de sistema\\nD. Testes de componente","options":["1D, 2B, 3C, 4A","1C, 2A, 3D, 4B","1A, 2C, 3B, 4D","1B, 2D, 3A, 4C"],"correctAnswer":0,"explanation":"A. Correto. (1) Verificar um m\xf3dulo isolado = Testes de componente (D). (2) Verificar comunica\xe7\xe3o entre m\xf3dulos = Testes de integra\xe7\xe3o (B). (3) Cen\xe1rios completos de ponta a ponta = Testes de sistema (C). (4) Usu\xe1rios finais validam suas necessidades = Testes de aceite (A). B. Incorreto. Esta combina\xe7\xe3o confunde os n\xedveis de teste; os testes de sistema n\xe3o verificam m\xf3dulos isolados. C. Incorreto. Os testes de aceite n\xe3o servem para verificar m\xf3dulos individuais. D. Incorreto. Os testes de integra\xe7\xe3o n\xe3o se limitam a componentes isolados.","source":"User Provided Batch 7","id":"q_batch7_13"},{"chapter":2,"topic":"Tipos de Prueba","difficulty":"medium","question":"Uma equipe de desenvolvimento corrigiu v\xe1rios defeitos no aplicativo e lan\xe7ou uma nova vers\xe3o. Antes da corre\xe7\xe3o, foram executados certos casos de teste, dos quais alguns falharam. Agora a equipe precisa verificar se os defeitos foram corrigidos e tamb\xe9m que as mudan\xe7as n\xe3o afetaram outras partes do sistema. Qual das seguintes descri\xe7\xf5es se ajusta melhor aos testes que ser\xe3o realizados?","options":["Os testes de confirma\xe7\xe3o se concentram apenas nos casos de teste que falharam anteriormente.","Os testes de regress\xe3o garantem que as funcionalidades que n\xe3o foram modificadas continuem funcionando corretamente.","Os testes de confirma\xe7\xe3o incluem os casos de teste que falharam em vers\xf5es anteriores e os que s\xe3o executados pela primeira vez.","Os testes de regress\xe3o s\xf3 se aplicam aos novos defeitos descobertos na nova vers\xe3o."],"correctAnswer":1,"explanation":"A. Incorreto. Os testes de confirma\xe7\xe3o focam em verificar se os defeitos corrigidos agora funcionam, mas n\xe3o se limitam necessariamente aos casos que falharam anteriormente. B. Correto. Os testes de regress\xe3o s\xe3o necess\xe1rios para verificar se as modifica\xe7\xf5es n\xe3o afetaram as funcionalidades existentes. C. Incorreto. Os testes de confirma\xe7\xe3o referem-se apenas aos defeitos corrigidos, n\xe3o aos casos que s\xe3o executados pela primeira vez. D. Incorreto. Os testes de regress\xe3o aplicam-se a todas as funcionalidades existentes, n\xe3o apenas aos novos defeitos.","source":"User Provided Batch 7","id":"q_batch7_14"},{"chapter":3,"topic":"Pruebas Est\xe1ticas","difficulty":"medium","question":"Qual das seguintes afirma\xe7\xf5es descreve melhor um benef\xedcio dos testes est\xe1ticos no desenvolvimento de software?","options":["Os testes est\xe1ticos ajudam a garantir que o c\xf3digo atende \xe0s especifica\xe7\xf5es antes de ser executado.","Os testes est\xe1ticos s\xe3o mais eficazes que os testes din\xe2micos na identifica\xe7\xe3o de defeitos de execu\xe7\xe3o em tempo de execu\xe7\xe3o.","Os testes est\xe1ticos permitem realizar testes em ambientes onde n\xe3o \xe9 poss\xedvel executar o software.","Os testes est\xe1ticos eliminam a necessidade de realizar testes din\xe2micos no software."],"correctAnswer":0,"explanation":"A. Correto. Os testes est\xe1ticos permitem revisar o c\xf3digo e os documentos antes da execu\xe7\xe3o, ajudando a garantir o cumprimento das especifica\xe7\xf5es. B. Incorreto. Os testes est\xe1ticos n\xe3o identificam erros de execu\xe7\xe3o, pois o software n\xe3o \xe9 executado. C. Incorreto. Embora os testes est\xe1ticos possam ser realizados sem um ambiente de execu\xe7\xe3o, seu prop\xf3sito principal n\xe3o \xe9 facilitar os testes em ambientes n\xe3o execut\xe1veis. D. Incorreto. Os testes est\xe1ticos n\xe3o substituem completamente a necessidade de testes din\xe2micos, uma vez que ambos possuem prop\xf3sitos complementares.","source":"User Provided Batch 7","id":"q_batch7_15"},{"chapter":3,"topic":"Retroalimentaci\xf3n","difficulty":"easy","question":"Qual \xe9 um benef\xedcio chave de obter feedback (retroalimenta\xe7\xe3o) antecipado e frequente das partes interessadas?","options":["Ajuda a identificar problemas de desempenho nos testes.","Permite adaptar o desenvolvimento \xe0s necessidades em constante mudan\xe7a das partes interessadas.","Aumenta o tempo total do projeto.","Refor\xe7a a confidencialidade dos dados do cliente."],"correctAnswer":1,"explanation":"A. Incorreto. Embora o feedback possa ajudar a identificar problemas, n\xe3o foca especificamente no desempenho dos testes. B. Correto. O feedback antecipado e frequente permite ajustar o desenvolvimento para satisfazer as necessidades em constante mudan\xe7a das partes interessadas. C. Incorreto. O feedback eficaz normalmente ajuda a reduzir o tempo total do projeto ao abordar os problemas com anteced\xeancia. D. Incorreto. O feedback n\xe3o est\xe1 relacionado \xe0 confidencialidade dos dados, mas sim \xe0 melhoria do processo de desenvolvimento.","source":"User Provided Batch 7","id":"q_batch7_16"},{"chapter":3,"topic":"Revisiones","difficulty":"medium","question":"O autor de um documento de design lidera uma sess\xe3o de revis\xe3o. Um escriba registra os defeitos encontrados. Os participantes podem fazer perguntas livremente e o autor explica o seu design. N\xe3o s\xe3o utilizados crit\xe9rios formais de entrada nem de sa\xedda.\\n\\nQue tipo de revis\xe3o descreve este cen\xe1rio?","options":["Inspe\xe7\xe3o","Revis\xe3o t\xe9cnica","Passo a passo (Walkthrough)","Revis\xe3o informal"],"correctAnswer":2,"explanation":"A. Incorreto. Em uma inspe\xe7\xe3o, o l\xedder \xe9 um moderador treinado (n\xe3o o autor) e utilizam-se crit\xe9rios formais de entrada/sa\xedda. B. Incorreto. Em uma revis\xe3o t\xe9cnica, os resultados s\xe3o formalmente documentados e nem sempre liderados pelo autor. C. Correto. O Syllabus CTFL v4.0 \xa73.2.4 define o passo a passo (walkthrough) como uma revis\xe3o liderada pelo autor onde um escriba registra os defeitos, os participantes podem fazer perguntas e o autor explica o trabalho. N\xe3o h\xe1 crit\xe9rios formais de entrada/sa\xedda. D. Incorreto. A revis\xe3o informal n\xe3o tem um escriba nem uma estrutura definida; \xe9 completamente ad hoc.","source":"User Provided Batch 7","id":"q_batch7_17"},{"chapter":3,"topic":"Revisiones","difficulty":"medium","question":"Uma equipe introduz revis\xf5es formais em seu processo. No entanto, os revisores n\xe3o recebem tempo suficiente para revisar os documentos e a dire\xe7\xe3o n\xe3o considera os resultados das revis\xf5es nas decis\xf5es do projeto.\\n\\nQual fator de sucesso para as revis\xf5es est\xe1 FALTANDO?","options":["O uso de listas de verifica\xe7\xe3o padronizadas.","O apoio da dire\xe7\xe3o que aloca tempo e valoriza os resultados das revis\xf5es.","A presen\xe7a de um especialista em seguran\xe7a em cada sess\xe3o de revis\xe3o.","A limita\xe7\xe3o das revis\xf5es apenas a documentos de requisitos."],"correctAnswer":1,"explanation":"A. Incorreto. As listas de verifica\xe7\xe3o s\xe3o \xfateis, mas n\xe3o s\xe3o o principal fator em falta aqui. B. Correto. O Syllabus CTFL v4.0 \xa73.2.5 identifica o apoio da dire\xe7\xe3o como um fator de sucesso fundamental: a dire\xe7\xe3o deve alocar tempo suficiente para a prepara\xe7\xe3o e valorizar os resultados, caso contr\xe1rio as revis\xf5es tornam-se uma formalidade sem valor. C. Incorreto. A participa\xe7\xe3o de especialistas \xe9 \xfatil em contextos espec\xedficos, mas n\xe3o \xe9 o fator universal de sucesso. D. Incorreto. As revis\xf5es podem ser aplicadas a qualquer produto de trabalho (requisitos, design, c\xf3digo, casos de teste), n\xe3o apenas aos requisitos.","source":"User Provided Batch 7","id":"q_batch7_18"},{"chapter":4,"topic":"Partici\xf3n de Equivalencia","difficulty":"hard","question":"Um sistema de controle clim\xe1tico valida a temperatura ambiente. Os valores aceit\xe1veis est\xe3o entre 16\xb0C e 30\xb0C, inclusive. As temperaturas fora desse intervalo geram um alerta.\\n\\nUsando a t\xe9cnica de parti\xe7\xe3o de equival\xeancia, qual \xe9 o M\xcdNIMO de casos de teste necess\xe1rios para cobrir TODAS as parti\xe7\xf5es (v\xe1lidas e inv\xe1lidas)?","options":["2","3","4","6"],"correctAnswer":1,"explanation":"A. Incorreto. Com 2 casos de teste, cobre-se apenas 2 das 3 parti\xe7\xf5es identificadas por PE. B. Correto. PE divide o dom\xednio em 3 parti\xe7\xf5es: (1) temperatura < 16\xb0C (inv\xe1lida), (2) 16\xb0C\u201330\xb0C (v\xe1lida), (3) temperatura > 30\xb0C (inv\xe1lida). O crit\xe9rio de cobertura \'Cada Escolha\' exige pelo menos 1 caso por parti\xe7\xe3o, ou seja, 3 casos no total. C. Incorreto. 4 casos de teste superam o m\xednimo necess\xe1rio para satisfazer o crit\xe9rio de cobertura PE. D. Incorreto. 6 casos correspondem \xe0 t\xe9cnica de an\xe1lise de valor limite com 2 valores (AVL-2), n\xe3o a PE.","source":"User Provided Batch 7","id":"q_batch7_20"},{"chapter":4,"topic":"Partici\xf3n de Equivalencia","difficulty":"medium","question":"Um sistema de registro de usu\xe1rios valida a idade do usu\xe1rio. O requisito indica: \'A idade deve estar entre 18 e 65 anos, inclusive, para ser v\xe1lida\'. Aplicando a t\xe9cnica de parti\xe7\xe3o de equival\xeancia, qual \xe9 o conjunto M\xcdNIMO de casos de teste que cobre todas as parti\xe7\xf5es de equival\xeancia?","options":["Idade = 18, Idade = 40, Idade = 66","Idade = 18, Idade = 65","Idade = 17, Idade = 40, Idade = 66","Idade = 0, Idade = 17, Idade = 40, Idade = 66"],"correctAnswer":2,"explanation":"A. Incorreto. Embora tenha 3 casos de teste, n\xe3o cobre a parti\xe7\xe3o inv\xe1lida inferior (idade < 18) e apresenta redund\xe2ncia ao incluir dois valores da parti\xe7\xe3o v\xe1lida (18 e 40).\\nB. Incorreto. Abrange apenas a parti\xe7\xe3o v\xe1lida com 2 casos redundantes, deixando sem cobrir as parti\xe7\xf5es inv\xe1lidas (inferior e superior).\\nC. Correto. S\xe3o necess\xe1rios 3 casos de teste para cobrir as 3 parti\xe7\xf5es de equival\xeancia identificadas: uma para a parti\xe7\xe3o inv\xe1lida inferior (idade < 18), uma para a parti\xe7\xe3o v\xe1lida (18 \u2264 idade \u2264 65) e uma para a parti\xe7\xe3o inv\xe1lida superior (idade > 65). De acordo com a t\xe9cnica de parti\xe7\xe3o de equival\xeancia, para atingir 100% de cobertura, os casos de teste devem exercitar todas as parti\xe7\xf5es identificadas, cobrindo cada parti\xe7\xe3o pelo menos uma vez.\\nD. Incorreto. 4 casos de teste excedem o n\xfamero m\xednimo necess\xe1rio, uma vez que inclui redund\xe2ncia na parti\xe7\xe3o inv\xe1lida inferior (idade = 0 e idade = 17).","source":"User Provided Batch 8","id":"q_batch8_21"},{"chapter":4,"topic":"Tabla de Decisiones","difficulty":"medium","question":"Em uma tabela de decis\xe3o para um sistema de aprova\xe7\xe3o de empr\xe9stimos, voc\xea tem as seguintes condi\xe7\xf5es:\\n\\n- Idade \u2265 18 anos\\n- Renda \u2265 $30.000\\n- Hist\xf3rico de cr\xe9dito bom\\n- Empregado h\xe1 \u2265 2 anos\\n\\nSe voc\xea quisesse minimizar a tabela devido \xe0 grande quantidade de combina\xe7\xf5es, qual seria a melhor estrat\xe9gia?","options":["Eliminar todas as condi\xe7\xf5es menos importantes","Usar uma abordagem baseada em riscos para reduzir as regras a serem testadas","Combinar todas as condi\xe7\xf5es em uma \xfanica regra","Criar v\xe1rias pequenas tabelas separadas"],"correctAnswer":1,"explanation":"A. Incorreto. Eliminar condi\xe7\xf5es pode deixar lacunas importantes na cobertura.\\nB. Correto. De acordo com o syllabus, \'se houver muitas condi\xe7\xf5es, o exerc\xedcio de todas as regras de decis\xe3o pode consumir muito tempo, pois o n\xfamero de regras cresce exponencialmente com o n\xfamero de condi\xe7\xf5es. Nesse caso, para reduzir o n\xfamero de regras a serem exercidas, pode-se usar uma tabela de decis\xe3o minimizada ou uma abordagem baseada em risco.\'\\nC. Incorreto. Combinar todas as condi\xe7\xf5es n\xe3o resolve o problema da complexidade.\\nD. Incorreto. M\xfaltiplas tabelas separadas n\xe3o abordam o problema das combina\xe7\xf5es exponenciais.","source":"User Provided Batch 8","id":"q_batch8_22"},{"chapter":4,"topic":"Basadas en Experiencia","difficulty":"medium","question":"Qual das seguintes afirma\xe7\xf5es descreve MELHOR como a previs\xe3o de erros (suposi\xe7\xe3o de erros) \xe9 utilizada nos testes de software?","options":["A previs\xe3o de erros baseia-se em identificar as \xe1reas do software onde \xe9 mais prov\xe1vel que ocorram defeitos, utilizando dados hist\xf3ricos e padr\xf5es de erros passados.","A previs\xe3o de erros centra-se apenas na revis\xe3o de requisitos para detectar poss\xedveis falhas antes do in\xedcio do desenvolvimento.","A previs\xe3o de erros envolve adivinhar aleatoriamente os erros no software, sem qualquer base em experi\xeancia pr\xe9via.","A previs\xe3o de erros exige que o testador avalie constantemente o desempenho do software durante a sua execu\xe7\xe3o."],"correctAnswer":0,"explanation":"A. Correto. A previs\xe3o de erros concentra-se em identificar \xe1reas de risco no software que t\xeam maior probabilidade de conter defeitos, baseando-se em experi\xeancia passada e dados hist\xf3ricos.\\nB. Incorreto. Embora a revis\xe3o de requisitos seja importante, a previs\xe3o de erros baseia-se mais na experi\xeancia e nos padr\xf5es de defeitos no software j\xe1 desenvolvido.\\nC. Incorreto. Adivinhar aleatoriamente n\xe3o \xe9 uma forma eficaz de prever erros; a previs\xe3o deve estar fundamentada em dados e experi\xeancias pr\xe9vias.\\nD. Incorreto. A avalia\xe7\xe3o do desempenho do software \xe9 uma atividade diferente; a previs\xe3o de erros foca-se em identificar e antecipar defeitos antes de testar o software.","source":"User Provided Batch 8","id":"q_batch8_26"},{"chapter":4,"topic":"Basadas en Experiencia","difficulty":"medium","question":"A sua equipe de desenvolvimento implementou uma nova funcionalidade no software, mas n\xe3o foi documentada adequadamente. Voc\xea tem pouco tempo para realizar testes antes do lan\xe7amento. Qual \xe9 a melhor estrat\xe9gia de teste que voc\xea pode usar nessa situa\xe7\xe3o?","options":["Testes automatizados","Testes explorat\xf3rios","Testes de regress\xe3o","Testes baseados em requisitos"],"correctAnswer":1,"explanation":"A. Incorreto. Os testes automatizados requerem tempo para serem projetados e configurados, o que n\xe3o \xe9 vi\xe1vel com pouco tempo dispon\xedvel.\\nB. Correto. Os testes explorat\xf3rios permitem uma avalia\xe7\xe3o r\xe1pida da nova funcionalidade sem a necessidade de documenta\xe7\xe3o detalhada.\\nC. Incorreto. Os testes de regress\xe3o s\xe3o \xfateis, mas requerem uma compreens\xe3o clara das funcionalidades anteriores que n\xe3o est\xe3o documentadas.\\nD. Incorreto. Os testes baseados em requisitos n\xe3o s\xe3o eficazes aqui, pois a falta de documenta\xe7\xe3o limita a capacidade de projetar testes baseados em requisitos.","source":"User Provided Batch 8","id":"q_batch8_27"},{"chapter":4,"topic":"ATDD/BDD","difficulty":"medium","question":"Uma equipe \xe1gil est\xe1 iniciando a implementa\xe7\xe3o do ATDD para seu pr\xf3ximo sprint. O Scrum Master deseja saber quem deve participar do workshop de especifica\xe7\xe3o do ATDD.\\n\\nQual das seguintes afirma\xe7\xf5es descreve MELHOR a participa\xe7\xe3o em um workshop de especifica\xe7\xe3o do ATDD?","options":["Apenas os testadores, pois s\xe3o os respons\xe1veis \u200b\u200bpor definir os crit\xe9rios de aceite.","Apenas os desenvolvedores, porque s\xe3o eles que implementar\xe3o os testes automatizados.","Representantes de neg\xf3cios, desenvolvedores e testadores colaboram em conjunto.","Apenas os representantes de neg\xf3cios, porque os crit\xe9rios de aceite s\xe3o requisitos do cliente."],"correctAnswer":2,"explanation":"A. Incorreto. Os testadores participam, mas o ATDD exige a colabora\xe7\xe3o de toda a equipe, n\xe3o apenas dos testadores.\\nB. Incorreto. Os desenvolvedores participam, mas sem a perspectiva dos neg\xf3cios e dos testes, os crit\xe9rios de aceite ficariam incompletos.\\nC. Correto. O Syllabus CTFL v4.0 \xa74.5.3 afirma que o workshop de especifica\xe7\xe3o do ATDD envolve representantes de neg\xf3cios, desenvolvedores e testadores para colaborarem na defini\xe7\xe3o de exemplos concretos.\\nD. Incorreto. Embora os representantes de neg\xf3cios forne\xe7am a vis\xe3o do cliente, desenvolvedores e testadores s\xe3o necess\xe1rios para definir exemplos test\xe1veis.","source":"User Provided Batch 8","id":"q_batch8_29"},{"chapter":5,"topic":"Planificaci\xf3n de Pruebas","difficulty":"medium","question":"De que forma os testadores podem contribuir para um melhor planejamento da entrega de software?","options":["Os testadores revisam as especifica\xe7\xf5es e oferecem feedback sobre a viabilidade do projeto.","Os testadores elaboram a documenta\xe7\xe3o do usu\xe1rio sem se envolver no desenvolvimento do produto.","Os testadores s\xe3o respons\xe1veis por estabelecer os prazos de entrega do projeto.","Os testadores concentram-se em realizar testes ao final do ciclo de desenvolvimento para garantir a qualidade."],"correctAnswer":0,"explanation":"A. Correto. Os testadores revisam as especifica\xe7\xf5es e podem identificar problemas de viabilidade, o que ajuda no planejamento.\\nB. Incorreto. Embora os testadores possam contribuir para a documenta\xe7\xe3o, a sua principal fun\xe7\xe3o \xe9 garantir a qualidade durante o desenvolvimento.\\nC. Incorreto. O estabelecimento de prazos \xe9 geralmente responsabilidade do gerente de projeto ou da equipe de gest\xe3o.\\nD. Incorreto. Esperar at\xe9 o final para realizar testes n\xe3o \xe9 \xfatil e pode comprometer a qualidade do produto.","source":"User Provided Batch 8","id":"q_batch8_30"},{"chapter":5,"topic":"Estimaci\xf3n","difficulty":"medium","question":"A sua equipe est\xe1 na terceira itera\xe7\xe3o de um projeto \xe1gil. Os esfor\xe7os de teste das itera\xe7\xf5es anteriores foram:\\n\\n- Itera\xe7\xe3o 1: 45 pessoas-dia\\n- Itera\xe7\xe3o 2: 52 pessoas-dia\\n\\nUsando a extrapola\xe7\xe3o, qual seria a estimativa mais adequada para a Itera\xe7\xe3o 3?","options":["45 pessoas-dia (o m\xednimo hist\xf3rico)","48,5 pessoas-dia (m\xe9dia das duas itera\xe7\xf5es)","52 pessoas-dia (tend\xeancia crescente)","59 pessoas-dia (extrapola\xe7\xe3o da tend\xeancia)"],"correctAnswer":1,"explanation":"A. Incorreto. Usar apenas o m\xednimo n\xe3o considera a tend\xeancia ou a variabilidade.\\nB. Correto. De acordo com o syllabus, na extrapola\xe7\xe3o \'a equipe pode extrapolar o esfor\xe7o de teste na pr\xf3xima itera\xe7\xe3o como o esfor\xe7o m\xe9dio das tr\xeas \xfaltimas itera\xe7\xf5es\'. Com apenas duas itera\xe7\xf5es dispon\xedveis, a m\xe9dia seria (45 + 52) \xf7 2 = 48,5 pessoas-dia.\\nC. Incorreto. Usar apenas o \xfaltimo valor n\xe3o aplica o conceito de extrapola\xe7\xe3o baseada no hist\xf3rico.\\nD. Incorreto. Embora pudesse ser uma extrapola\xe7\xe3o de tend\xeancia, o syllabus menciona especificamente o uso da m\xe9dia.","source":"User Provided Batch 8","id":"q_batch8_32"},{"chapter":5,"topic":"Riesgos","difficulty":"hard","question":"Voc\xea tem os seguintes casos de teste para um sistema de banco online:\\n\\n| Caso | Risco de Funcionalidade | Probabilidade do Risco | Impacto do Risco | Depend\xeancia |\\n|---|---|---|---|---|\\n| CT1 | Login | 2 | 2 | Nenhuma |\\n| CT2 | Consultar saldo | 3 | 3 | CT1 |\\n| CT3 | Transferir dinheiro | 2 | 2 | CT1, CT2 |\\n| CT4 | Alterar PIN | 4 | 4 | CT1 |\\n\\nAplicando a prioriza\xe7\xe3o baseada em riscos, onde o impacto e a probabilidade s\xe3o medidos em uma escala de 1 a 5 (1=Muito Alto, 2=Alto, 3=M\xe9dio, 4=Baixo, 5=Muito Baixo), qual seria a ordem de execu\xe7\xe3o MAIS apropriada?","options":["CT1, CT3, CT2, CT4","CT1, CT2, CT3, CT4","CT3, CT1, CT2, CT4","CT1, CT4, CT2, CT3"],"correctAnswer":1,"explanation":"A. Incorreto. Problema 1: CT3 depende de CT2 (precisa do saldo consultado), mas o CT3 \xe9 executado antes do CT2. Isso quebra a depend\xeancia. Problema 2: CT2 tem maior risco (9) que CT4 (16), mas CT4 \xe9 executado antes do CT2. Prioriza mal o risco.\\nB. Correto. CT1 primeiro: \xc9 independente e base para todos os outros casos. CT2 antes de CT3/CT4: CT2 possui um risco maior (9) que o CT4 (16), e CT3 depende do CT2.\\nC. Incorreto. Problema cr\xedtico: CT3 depende de CT1 e CT2, mas \xe9 executado primeiro, antes de ambos. Falhar\xe1 devido \xe0 falta de depend\xeancias.\\nD. Incorreto. Problema 1: CT2 tem maior risco (9) que CT4 (16), mas o CT4 \xe9 executado antes do CT2. Prioriza mal o risco. Problema 2: CT3 depende do CT2, mas CT2 \xe9 executado ap\xf3s o CT3. Quebra a depend\xeancia.","source":"User Provided Batch 8","id":"q_batch8_33"},{"chapter":2,"topic":"Cuadrantes \xc1giles","difficulty":"medium","question":"Identifique as seguintes categorias de testes (1-4) e os quadrantes de testes \xe1geis (A-D):\\n\\n1. Testes de usabilidade\\n2. Testes de componente\\n3. Testes funcionais\\n4. Testes de confiabilidade\\n\\nA. Quadrante Q1: voltado para a tecnologia, apoia a equipe de desenvolvimento\\nB. Quadrante Q2: voltado para os neg\xf3cios, apoia a equipe de desenvolvimento\\nC. Quadrante Q3: voltado para os neg\xf3cios, critica o produto\\nD. Quadrante Q4: voltado para a tecnologia, critica o produto\\n\\nQuais combina\xe7\xf5es est\xe3o corretas para essas categorias de testes e os quadrantes?","options":["1C, 2A, 3B, 4D","1D, 2A, 3C, 4B","1C, 2B, 3D, 4A","1D, 2B, 3C, 4A"],"correctAnswer":0,"explanation":"A. Os testes de usabilidade relacionam-se com o Quadrante Q3 (1-C), os testes de componente com o Quadrante Q1 (2-A), os testes funcionais com o Quadrante Q2 (3-B) e os testes de confiabilidade (como testes n\xe3o funcionais) com o Quadrante Q4 (4-D). Isso se alinha exatamente com a se\xe7\xe3o 5.1.7 do syllabus. Portanto, esta op\xe7\xe3o \xe9 correta.\\nB. Os testes funcionais seriam atribu\xeddos a Q3 (3-C), o que n\xe3o \xe9 correto de acordo com a descri\xe7\xe3o de Q2 (voltado para os neg\xf3cios, apoio \xe0 equipe).\\nC. Os testes de confiabilidade seriam atribu\xeddos a Q1 (4-A), o que n\xe3o \xe9 correto (pertencem a Q4).\\nD. Os testes de usabilidade seriam atribu\xeddos a Q4 (1-D), o que n\xe3o \xe9 correto (pertencem a Q3).","source":"User Provided Batch 8","id":"q_batch8_34"},{"chapter":5,"topic":"Gesti\xf3n de Riesgos","difficulty":"medium","question":"Durante uma revis\xe3o de riscos, foi identificado o seguinte problema:\\n\\nRisco: Incompatibilidade entre m\xf3dulos do software.\\nProbabilidade do risco: alta; impacto do risco: m\xe9dio\\n\\nResposta ao risco:\\n- realizar testes de integra\xe7\xe3o antecipados para identificar incompatibilidades\\n- documentar as incompatibilidades e comunic\xe1-las \xe0 equipe de desenvolvimento\\n\\nQual \xe9 a medida mais adequada a ser tomada em resposta a este risco analisado?","options":["Mitiga\xe7\xe3o do risco","Transfer\xeancia do risco","Aceita\xe7\xe3o do risco","Plano de conting\xeancia"],"correctAnswer":0,"explanation":"A. Correto. Os testes de integra\xe7\xe3o antecipados s\xe3o uma estrat\xe9gia de mitiga\xe7\xe3o que ajuda a identificar e resolver problemas antes que se tornem maiores.\\nB. Incorreto. A transfer\xeancia de risco envolve passar o risco para outra parte, o que n\xe3o \xe9 mencionado aqui.\\nC. Incorreto. Aceitar o risco n\xe3o \xe9 adequado, uma vez que est\xe3o sendo propostas a\xe7\xf5es para resolv\xea-lo.\\nD. Incorreto. Embora possam ser elaborados planos de conting\xeancia, a principal medida aqui \xe9 a mitiga\xe7\xe3o atrav\xe9s de testes.","source":"User Provided Batch 8","id":"q_batch8_35"},{"chapter":5,"topic":"M\xe9tricas e Informes","difficulty":"medium","question":"Qual dos seguintes elementos \xe9 o mais adequado para fornecer uma vis\xe3o geral do progresso dos testes \xe0s partes interessadas de um projeto?","options":["Registro de incidentes","Relat\xf3rio de testes mensal","Relat\xf3rio de status de testes","Plano de testes"],"correctAnswer":2,"explanation":"A. Incorreto. O registro de incidentes detalha os defeitos encontrados, mas n\xe3o fornece um resumo do status dos testes.\\nB. Incorreto. Embora um relat\xf3rio de testes mensal possa fornecer informa\xe7\xf5es sobre o progresso, n\xe3o \xe9 o mais adequado para uma vis\xe3o geral imediata.\\nC. Correto. Um relat\xf3rio de status de testes resume o progresso, os resultados e as m\xe9tricas relevantes sobre o estado dos testes, sendo \xfatil para as partes interessadas.\\nD. Incorreto. O plano de testes estabelece a estrat\xe9gia e a abordagem, mas n\xe3o comunica o estado atual dos testes.","source":"User Provided Batch 8","id":"q_batch8_36"},{"chapter":5,"topic":"Gesti\xf3n de Defectos","difficulty":"medium","question":"Voc\xea encontrou um defeito durante os testes de um m\xf3dulo de faturamento. O sistema calcula incorretamente o imposto quando um desconto \xe9 aplicado. Qual dos seguintes relat\xf3rios de defeito est\xe1 MELHOR estruturado?","options":["\\"O imposto est\xe1 mal calculado com descontos\\"","\\"Erro no c\xe1lculo de impostos com descontos. Resultado esperado: 21%, resultado atual: 18%. Passos: aplicar desconto de 10% na fatura de $100, calcular imposto.\\"","\\"ID: DEF-2024-001, T\xedtulo: C\xe1lculo incorreto de imposto com descontos, Ambiente: Test v2.1, Passos: 1)Criar fatura $100, 2)Aplicar desconto 10%, 3)Calcular imposto, Esperado: $19.53, Atual: $16.20, Severidade: Alta, Status: Novo\\"","\\"H\xe1 um problema com os impostos quando h\xe1 descontos aplicados no sistema\\""],"correctAnswer":2,"explanation":"A. Incorreto. Muito vago, falta informa\xe7\xe3o cr\xedtica para reproduzir e resolver o defeito.\\nB. Incorreto. Embora melhor que (A), carece de elementos estruturais importantes como ID, ambiente, severidade, status.\\nC. Correto. Este relat\xf3rio inclui todos os elementos essenciais de acordo com o syllabus: identificador \xfanico, t\xedtulo descritivo, identifica\xe7\xe3o do ambiente de teste, descri\xe7\xe3o clara para reprodu\xe7\xe3o, resultados esperados vs. atuais, severidade e status. Permite uma reprodu\xe7\xe3o e resolu\xe7\xe3o eficazes.\\nD. Incorreto. Descri\xe7\xe3o muito geral, sem detalhes espec\xedficos para reproduzir ou entender o problema.","source":"User Provided Batch 8","id":"q_batch8_38"},{"chapter":3,"topic":"Retroalimentaci\xf3n","difficulty":"medium","question":"Qual a vantagem do feedback antecipado e frequente das partes interessadas em um projeto?","options":["Acelera a implementa\xe7\xe3o de novas ferramentas tecnol\xf3gicas.","Facilita a identifica\xe7\xe3o precoce de problemas no desenvolvimento.","Reduz a necessidade de treinamento na equipe de testes.","Aumenta a dura\xe7\xe3o do ciclo de vida do projeto."],"correctAnswer":1,"explanation":"A. Incorreto. O feedback n\xe3o est\xe1 diretamente relacionado \xe0 implementa\xe7\xe3o de ferramentas tecnol\xf3gicas.\\nB. Correto. O feedback antecipado e frequente ajuda a identificar problemas mais cedo no ciclo de desenvolvimento.\\nC. Incorreto. O feedback n\xe3o elimina a necessidade de treinamento.\\nD. Incorreto. O feedback antecipado e frequente tende a otimizar o ciclo de vida do projeto, n\xe3o a aument\xe1-lo.","source":"User Provided Batch 9","id":"q_batch9_1"},{"chapter":3,"topic":"Retroalimentaci\xf3n","difficulty":"medium","question":"Que vantagem o feedback frequente das partes interessadas proporciona a um projeto?","options":["Facilita a identifica\xe7\xe3o de erros em est\xe1gios iniciais.","Minimiza a comunica\xe7\xe3o entre as equipes.","Reduz o tempo de desenvolvimento ao evitar revis\xf5es.","Aumenta a quantidade de documenta\xe7\xe3o exigida."],"correctAnswer":0,"explanation":"A. Correto. O feedback frequente permite detectar erros e mal-entendidos a tempo, facilitando a sua corre\xe7\xe3o antes de avan\xe7ar.\\nB. Incorreto. O feedback frequente incentiva a comunica\xe7\xe3o entre as equipes e as partes interessadas.\\nC. Incorreto. Embora possa ajudar a evitar revis\xf5es, o feedback n\xe3o reduz necessariamente o tempo de desenvolvimento.\\nD. Incorreto. O feedback precoce tende a simplificar a documenta\xe7\xe3o ao esclarecer os requisitos desde o in\xedcio.","source":"User Provided Batch 9","id":"q_batch9_2"},{"chapter":3,"topic":"Pruebas Est\xe1ticas","difficulty":"medium","question":"Qual das seguintes afirma\xe7\xf5es descreve melhor um benef\xedcio dos testes est\xe1ticos?","options":["Os testes est\xe1ticos permitem encontrar defeitos em fases iniciais, reduzindo o custo da sua corre\xe7\xe3o.","Os testes est\xe1ticos requerem mais tempo do que os testes din\xe2micos para serem realizados.","Os testes est\xe1ticos s\xe3o \xfateis principalmente para validar a funcionalidade do software.","Os testes est\xe1ticos n\xe3o podem ser automatizados."],"correctAnswer":0,"explanation":"A. Correto. Esse \xe9 um benef\xedcio fundamental dos testes est\xe1ticos, pois identificar defeitos precocemente pode ser menos oneroso do que corrigi-los em fases posteriores.\\nB. Incorreto. Geralmente, os testes est\xe1ticos requerem menos tempo do que os testes din\xe2micos para detectar defeitos.\\nC. Incorreto. Os testes est\xe1ticos n\xe3o validam a funcionalidade, mas revisam a qualidade do c\xf3digo, documenta\xe7\xe3o, etc.\\nD. Incorreto. Os testes est\xe1ticos podem ser automatizados atrav\xe9s de ferramentas de an\xe1lise de c\xf3digo.","source":"User Provided Batch 9","id":"q_batch9_3"},{"chapter":3,"topic":"Revisiones","difficulty":"medium","question":"Qual dos seguintes elementos \xe9 essencial para garantir a efic\xe1cia de uma revis\xe3o?","options":["A participa\xe7\xe3o ativa de todos os membros no processo de revis\xe3o.","Realizar a revis\xe3o sem uma abordagem estruturada para estimular a criatividade.","Limitar o tempo de revis\xe3o a menos de 15 minutos para manter a energia dos participantes.","Permitir que apenas o l\xedder da equipe compartilhe suas observa\xe7\xf5es para evitar confus\xf5es."],"correctAnswer":0,"explanation":"A. Correto. A participa\xe7\xe3o ativa de todos os membros \xe9 crucial para que mais defeitos sejam identificados e a qualidade seja melhorada.\\nB. Incorreto. Uma abordagem estruturada \xe9 fundamental para guiar a revis\xe3o e garantir que todos os aspectos relevantes sejam abordados.\\nC. Incorreto. Limitar o tempo de revis\xe3o pode levar a ignorar defeitos importantes.\\nD. Incorreto. Permitir que apenas o l\xedder compartilhe observa\xe7\xf5es pode restringir a diversidade de opini\xf5es e descobertas.","source":"User Provided Batch 9","id":"q_batch9_5"},{"chapter":3,"topic":"Revisiones","difficulty":"medium","question":"Qual dos seguintes elementos \xe9 essencial para alcan\xe7ar uma revis\xe3o efetiva?","options":["Ter um moderador que controle a discuss\xe3o.","Permitir que todos os participantes sejam avaliadores sem prepara\xe7\xe3o pr\xe9via.","N\xe3o \xe9 necess\xe1rio documentar os problemas identificados durante a revis\xe3o.","Conduzir a revis\xe3o de forma informal e sem estrutura."],"correctAnswer":0,"explanation":"A. Correto. Um moderador ajuda a manter o foco e a produtividade durante a revis\xe3o.\\nB. Incorreto. A prepara\xe7\xe3o dos avaliadores \xe9 crucial para uma revis\xe3o bem-sucedida.\\nC. Incorreto. Documentar os problemas \xe9 fundamental para o acompanhamento e a melhoria.\\nD. Incorreto. A falta de estrutura pode levar a confus\xf5es e resultados ineficazes.","source":"User Provided Batch 9","id":"q_batch9_6"},{"chapter":3,"topic":"Tipos de Revisi\xf3n","difficulty":"medium","question":"Em sua empresa, s\xe3o realizadas revis\xf5es com as seguintes caracter\xedsticas:\\n\\n- N\xe3o existe um papel definido para um moderador.\\n- O objetivo principal \xe9 identificar defeitos.\\n- \xc9 realizada uma discuss\xe3o informal entre os participantes.\\n- N\xe3o \xe9 exigida prepara\xe7\xe3o pr\xe9via dos documentos.\\n\\nQual tipo de revis\xe3o est\xe1 sendo descrito?","options":["Revis\xe3o informal","Revis\xe3o guiada","Revis\xe3o t\xe9cnica","Inspe\xe7\xe3o"],"correctAnswer":0,"explanation":"A. O cen\xe1rio descreve uma revis\xe3o informal, pois n\xe3o exige um moderador e tem como foco identificar defeitos por meio de uma discuss\xe3o aberta.\\nB. As revis\xf5es guiadas exigem um moderador e uma abordagem mais estruturada, o que n\xe3o \xe9 mencionado aqui.\\nC. As revis\xf5es t\xe9cnicas geralmente seguem um processo mais formal, com pap\xe9is definidos e prepara\xe7\xe3o pr\xe9via.\\nD. As inspe\xe7\xf5es s\xe3o processos formais que envolvem pap\xe9is espec\xedficos e um objetivo claro de encontrar defeitos, o que n\xe3o se aplica neste caso.","source":"User Provided Batch 9","id":"q_batch9_7"},{"chapter":3,"topic":"Tipos de Revisi\xf3n","difficulty":"medium","question":"Em sua organiza\xe7\xe3o, as seguintes atividades s\xe3o realizadas em uma revis\xe3o:\\n\\n- N\xe3o \xe9 necess\xe1rio um moderador.\\n- Os participantes revisam o trabalho de forma informal.\\n- Nenhum relat\xf3rio formal \xe9 gerado ao final.\\n- Sugest\xf5es de melhoria s\xe3o discutidas.\\n\\nQual dos seguintes tipos de revis\xe3o \xe9 o MAIS prov\xe1vel que esteja sendo realizado?","options":["Revis\xe3o informal","Revis\xe3o t\xe9cnica","Inspe\xe7\xe3o","Revis\xe3o guiada"],"correctAnswer":0,"explanation":"A. As revis\xf5es informais n\xe3o requerem moderador, n\xe3o produzem relat\xf3rios formais e permitem discuss\xf5es abertas, o que se enquadra nas caracter\xedsticas mencionadas.\\nB. As revis\xf5es t\xe9cnicas geralmente requerem um moderador e uma abordagem mais estruturada, o que n\xe3o se alinha com a descri\xe7\xe3o dada.\\nC. As inspe\xe7\xf5es s\xe3o muito formais e exigem documenta\xe7\xe3o espec\xedfica, o que contradiz a falta de um relat\xf3rio formal neste caso.\\nD. As revis\xf5es guiadas s\xe3o estruturadas com um moderador e um objetivo claro de avalia\xe7\xe3o, o que n\xe3o est\xe1 presente na situa\xe7\xe3o descrita.","source":"User Provided Batch 9","id":"q_batch9_8"}]')}}]);